const { app, BrowserWindow, ipcMain } = require('electron');
const path = require('node:path');
const fs = require('node:fs');
const http = require('node:http');
const { spawn } = require('node:child_process');

let serverProcess = null;

function isServerHealthy(url) {
  return new Promise((resolve) => {
    const req = http.get(url, (res) => {
      res.resume();
      resolve(res.statusCode >= 200 && res.statusCode < 500);
    });
    req.on('error', () => resolve(false));
    req.setTimeout(900, () => {
      req.destroy();
      resolve(false);
    });
  });
}

async function waitForServer(healthUrl, timeoutMs = 15000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (await isServerHealthy(healthUrl)) return true;
    await new Promise((r) => setTimeout(r, 250));
  }
  return false;
}

async function ensureLocalServerRunning() {
  if (process.env.SKM_APP_URL) {
    return process.env.SKM_APP_URL;
  }

  const port = Number(process.env.PORT || 3000);
  const baseUrl = `http://127.0.0.1:${port}`;
  const healthUrl = `${baseUrl}/api/health`;

  if (await isServerHealthy(healthUrl)) {
    return baseUrl;
  }

  const appRoot = path.resolve(__dirname, '..');
  const distDir = path.join(appRoot, 'dist');
  const hasDist = fs.existsSync(path.join(distDir, 'index.html'));
  const tsxCli = path.join(appRoot, 'node_modules', 'tsx', 'dist', 'cli.mjs');
  const serverEntry = path.join(appRoot, 'server.ts');

  const dataDir = path.join(app.getPath('userData'), 'skm-data');
  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true });
  }

  const childEnv = {
    ...process.env,
    ELECTRON_RUN_AS_NODE: '1',
    PORT: String(port),
    NODE_ENV: app.isPackaged || hasDist ? 'production' : 'development',
    DISABLE_HMR: 'true',
    SKM_ALLOW_OFFLINE_LOCAL_LOGIN: process.env.SKM_ALLOW_OFFLINE_LOCAL_LOGIN || 'true',
    SKM_DATA_DIR: process.env.SKM_DATA_DIR || dataDir,
  };

  const args = fs.existsSync(tsxCli) ? [tsxCli, serverEntry] : [serverEntry];
  serverProcess = spawn(process.execPath, args, {
    cwd: appRoot,
    env: childEnv,
    stdio: 'pipe',
    windowsHide: true,
  });

  serverProcess.stdout?.on('data', (chunk) => {
    console.log(`[SKM Server] ${String(chunk).trimEnd()}`);
  });
  serverProcess.stderr?.on('data', (chunk) => {
    console.error(`[SKM Server ERR] ${String(chunk).trimEnd()}`);
  });

  await waitForServer(healthUrl, 15000);
  return baseUrl;
}

function createWindow(targetUrl) {
  const win = new BrowserWindow({
    width: 1366,
    height: 860,
    minWidth: 1024,
    minHeight: 700,
    title: 'সৈয়দপুর কুদ্দুসিয়া মাদ্রাসা — Saidpur kudduchiyya madrasah Membership System',
    icon: path.join(__dirname, '..', 'public', 'assets', 'madrasa-logo.png'),
    webPreferences: {
      preload: path.join(__dirname, 'preload.cjs'),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  win.loadURL(targetUrl);
}

// Native Windows Drive (D:\, E:\, USB) detection & encrypted backup write
ipcMain.handle('skm:list-drives', async () => {
  const letters = ['C', 'D', 'E', 'F', 'G', 'H'];
  const available = [];
  for (const letter of letters) {
    const driveRoot = `${letter}:\\`;
    try {
      if (fs.existsSync(driveRoot)) {
        available.push(letter);
      }
    } catch {
      // ignore inaccessible drive
    }
  }
  return available;
});

ipcMain.handle('skm:save-backup', async (_event, { driveLetter, filename, content }) => {
  try {
    const cleanDrive = String(driveLetter || 'D').replace(/[^A-Za-z]/g, '').slice(0, 1).toUpperCase();
    const targetDir = path.join(`${cleanDrive}:\\`, 'SKM_Madrasa_Backups');
    if (!fs.existsSync(`${cleanDrive}:\\`)) {
      return { ok: false, error: `Drive ${cleanDrive}:\\ is not attached or accessible.` };
    }
    if (!fs.existsSync(targetDir)) {
      fs.mkdirSync(targetDir, { recursive: true });
    }
    const safeName = path.basename(String(filename));
    const fullPath = path.join(targetDir, safeName);
    fs.writeFileSync(fullPath, String(content), 'utf8');
    return { ok: true, path: fullPath };
  } catch (err) {
    return { ok: false, error: err.message };
  }
});

// Native OS Printer Dialog pre-configured for A6 Receipt printing
ipcMain.handle('skm:print-a6', async (event) => {
  return new Promise((resolve) => {
    try {
      event.sender.print(
        {
          silent: false,
          printBackground: true,
          pageSize: { width: 101600, height: 152400 },
        },
        (success, failureReason) => {
          resolve({ ok: success, error: success ? undefined : failureReason || 'Print cancelled' });
        }
      );
    } catch (err) {
      resolve({ ok: false, error: err.message });
    }
  });
});

app.whenReady().then(async () => {
  const targetUrl = await ensureLocalServerRunning();
  createWindow(targetUrl);
  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow(targetUrl);
  });
});

app.on('will-quit', () => {
  if (serverProcess && !serverProcess.killed) {
    serverProcess.kill();
    serverProcess = null;
  }
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});

const { contextBridge, ipcRenderer } = require('electron');

contextBridge.exposeInMainWorld('skmDesktop', {
  isElectron: true,
  listAvailableDrives: () => ipcRenderer.invoke('skm:list-drives'),
  saveBackupToDrive: (driveLetter, filename, content) =>
    ipcRenderer.invoke('skm:save-backup', { driveLetter, filename, content }),
  printA6: () => ipcRenderer.invoke('skm:print-a6'),
});

