import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const ROOT_DIR = process.cwd();
const PUBLIC_DOWNLOADS = path.join(ROOT_DIR, 'public', 'downloads');
const DIST_DOWNLOADS = path.join(ROOT_DIR, 'dist', 'downloads');

fs.mkdirSync(PUBLIC_DOWNLOADS, { recursive: true });

// 1. Sync Replication Formula markdown
const formulaSrc = path.join(ROOT_DIR, 'docs', 'REPLICATION_FORMULA.md');
const formulaDest = path.join(PUBLIC_DOWNLOADS, 'SKM_REPLICATION_FORMULA.md');
if (fs.existsSync(formulaSrc)) {
  fs.copyFileSync(formulaSrc, formulaDest);
}

// 2. Generate clean A-to-Z Source Code Bundle JSON
const skipDirs = new Set([
  'node_modules',
  '.git',
  'dist',
  'dev-dist',
  'data',
  '.playwright-cli',
  'downloads',
  '.aistudio',
]);
const allowedExt = new Set([
  '.ts',
  '.tsx',
  '.js',
  '.mjs',
  '.cjs',
  '.css',
  '.html',
  '.json',
  '.bat',
  '.md',
  '.txt',
  '.rules',
]);
const excludedFileNames = new Set([
  'package-lock.json',
  'bun.lock',
  'skm-source-bundle.json',
  '.env',
  '.env.local',
  '.env.production',
]);

const bundleFiles = [];
function walkSource(dirPath) {
  const entries = fs.readdirSync(dirPath, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.name.startsWith('.env') && entry.name !== '.env.example') continue;
    if (excludedFileNames.has(entry.name)) continue;
    if (/firebase-adminsdk|service-account|\.pem$|\.key$/i.test(entry.name)) continue;

    const absPath = path.join(dirPath, entry.name);
    const relPath = path.relative(ROOT_DIR, absPath).replace(/\\/g, '/');

    if (entry.isDirectory()) {
      if (skipDirs.has(entry.name)) continue;
      walkSource(absPath);
    } else if (entry.isFile()) {
      const ext = path.extname(entry.name).toLowerCase();
      if (entry.name !== '.env.example' && !allowedExt.has(ext)) continue;
      const stat = fs.statSync(absPath);
      if (stat.size > 512 * 1024) continue;
      bundleFiles.push({
        path: relPath,
        sizeBytes: stat.size,
        content: fs.readFileSync(absPath, 'utf8'),
      });
    }
  }
}

walkSource(ROOT_DIR);
bundleFiles.sort((a, b) => a.path.localeCompare(b.path));

const bundleJsonPath = path.join(PUBLIC_DOWNLOADS, 'skm-source-bundle.json');
fs.writeFileSync(
  bundleJsonPath,
  JSON.stringify(
    {
      generatedAt: new Date().toISOString(),
      totalFiles: bundleFiles.length,
      files: bundleFiles,
    },
    null,
    2
  ),
  'utf8'
);
console.log(`Generated ${bundleJsonPath} (${bundleFiles.length} clean files)`);

// 3. Render ONLINE_OFFLINE_GUIDELINE.html -> PDF using Chromium headless if available
const guidelineHtml = path.join(ROOT_DIR, 'docs', 'ONLINE_OFFLINE_GUIDELINE.html');
const guidelinePdf = path.join(PUBLIC_DOWNLOADS, 'SKM_Online_Offline_Guideline.pdf');
const chromePath = '/ms-playwright/chrome-headless-shell-linux64/chrome-headless-shell';
if (fs.existsSync(chromePath) && fs.existsSync(guidelineHtml)) {
  try {
    execFileSync(
      chromePath,
      [
        '--headless',
        '--disable-gpu',
        '--no-sandbox',
        '--no-pdf-header-footer',
        '--allow-file-access-from-files',
        `--print-to-pdf=${guidelinePdf}`,
        `file://${guidelineHtml}`,
      ],
      { stdio: 'pipe', timeout: 30000 }
    );
    console.log(`Rendered ${guidelinePdf}`);
  } catch (err) {
    console.warn('Skipped headless PDF re-render:', err instanceof Error ? err.message : err);
  }
}

// 4. Build Vite PWA + Production UI bundle
console.log('Running npm run build...');
execFileSync('npm', ['run', 'build'], { stdio: 'inherit', cwd: ROOT_DIR });

// 5. Assemble standalone Windows/Web/PWA offline .zip installer cleanly via python3
const zipOutPath = path.join(PUBLIC_DOWNLOADS, 'syedpur-kuddusia-madrasa-software.zip');
const pyScript = `
import os, re, zipfile

root = ${JSON.stringify(ROOT_DIR)}
out_zip = ${JSON.stringify(zipOutPath)}
tmp_zip = out_zip + '.tmp'

skip_dirs = {'node_modules', '.git', 'data', '.playwright-cli', '.aistudio', 'dev-dist'}
secret_re = re.compile(r'firebase-adminsdk|service-account|\\.pem$|\\.key$', re.I)

with zipfile.ZipFile(tmp_zip, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=6) as zf:
    for dirpath, dirnames, filenames in os.walk(root):
        rel_dir = os.path.relpath(dirpath, root).replace('\\\\', '/')
        if rel_dir == '.':
            rel_dir = ''
        dirnames[:] = sorted(
            d for d in dirnames
            if d not in skip_dirs and not (rel_dir in ('public', 'dist') and d == 'downloads')
        )
        for fname in sorted(filenames):
            if fname.startswith('.env') and fname != '.env.example':
                continue
            if fname in ('bun.lock', 'package-lock.json') or fname.endswith('.zip') or fname.endswith('.tmp'):
                continue
            if secret_re.search(fname):
                continue
            abs_file = os.path.join(dirpath, fname)
            rel_file = (rel_dir + '/' + fname) if rel_dir else fname
            zf.write(abs_file, rel_file)

    # Include generated clean downloads (excluding the zip itself)
    pub_dl = os.path.join(root, 'public', 'downloads')
    if os.path.isdir(pub_dl):
        for fname in sorted(os.listdir(pub_dl)):
            if fname.endswith('.zip') or fname.endswith('.tmp'):
                continue
            abs_file = os.path.join(pub_dl, fname)
            if os.path.isfile(abs_file):
                zf.write(abs_file, 'public/downloads/' + fname)

os.replace(tmp_zip, out_zip)
print('Packaged ZIP:', out_zip, os.path.getsize(out_zip))
`;

execFileSync('python3', ['-c', pyScript], { stdio: 'inherit', cwd: ROOT_DIR });

// Ensure dist/downloads has the generated packages as well
fs.mkdirSync(DIST_DOWNLOADS, { recursive: true });
for (const fname of [
  'syedpur-kuddusia-madrasa-software.zip',
  'SKM_Online_Offline_Guideline.pdf',
  'SKM_REPLICATION_FORMULA.md',
  'skm-source-bundle.json',
]) {
  const srcFile = path.join(PUBLIC_DOWNLOADS, fname);
  if (fs.existsSync(srcFile)) {
    fs.copyFileSync(srcFile, path.join(DIST_DOWNLOADS, fname));
  }
}

// Verify zip integrity
execFileSync('unzip', ['-t', zipOutPath], { stdio: 'pipe' });
console.log('ZIP integrity test passed!');

import 'dotenv/config';
import express from 'express';
import http from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { apiRouter } from './src/server/routes.ts';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

async function startServer() {
  const app = express();
  const httpServer = http.createServer(app);
  const PORT = Number(process.env.PORT || 3000);

  app.use(express.json({ limit: '25mb' }));
  const downloadHeaders = (res: express.Response, filePath: string) => {
    const ext = path.extname(filePath).toLowerCase();
    const baseName = path.basename(filePath);
    if (ext === '.zip') res.setHeader('Content-Type', 'application/zip');
    else if (ext === '.pdf') res.setHeader('Content-Type', 'application/pdf');
    else if (ext === '.md') res.setHeader('Content-Type', 'text/markdown; charset=utf-8');
    else if (ext === '.json') res.setHeader('Content-Type', 'application/json; charset=utf-8');
    res.setHeader('Content-Disposition', `attachment; filename="${baseName}"`);
  };
  app.use(
    '/downloads',
    express.static(path.join(__dirname, 'public', 'downloads'), { setHeaders: downloadHeaders })
  );
  app.use(
    '/downloads',
    express.static(path.join(__dirname, 'dist', 'downloads'), { setHeaders: downloadHeaders })
  );
  app.use('/downloads', (_req, res) => {
    res.status(404).json({ error: 'Downloadable package file not found.' });
  });
  app.use('/api', apiRouter);

  if (process.env.NODE_ENV === 'production') {
    const distDir = path.join(__dirname, 'dist');
    app.use(express.static(distDir));
    app.get('*', (_req, res) => {
      res.sendFile(path.join(distDir, 'index.html'));
    });
  } else {
    const { createServer: createViteServer } = await import('vite');
    const hmrDisabled = process.env.DISABLE_HMR === 'true';
    const vite = await createViteServer({
      server: {
        middlewareMode: true,
        hmr: hmrDisabled ? false : { server: httpServer },
        ws: hmrDisabled ? false : undefined,
      },
      appType: 'spa',
    });

    if (hmrDisabled) {
      app.get('/@vite/client', async (_req, res, next) => {
        try {
          const transformed = await vite.transformRequest('/@vite/client');
          if (!transformed?.code) {
            return next();
          }
          const patched = transformed.code
            .replace('ws.send(JSON.stringify(data));', 'if (ws && ws.readyState === 1) ws.send(JSON.stringify(data));')
            .replace(/throw new SendBeforeConnectError\([^)]*\);?/g, 'return;')
            .replace('transport.connect(createHMRHandler(handleMessage));', '/* HMR WebSocket disabled */')
            .replace('setupForwardConsoleHandler(transport, forwardConsole);', '/* Console forwarding disabled */');
          res.setHeader('Content-Type', 'application/javascript; charset=utf-8');
          res.send(patched);
        } catch (err) {
          next(err);
        }
      });
    }

    app.use(vite.middlewares);
  }

  httpServer.listen(PORT, '0.0.0.0', () => {
    console.log(`Saidpur kudduchiyya madrasah Membership Server listening on http://localhost:${PORT}`);
  });
}

startServer().catch((err) => {
  console.error('Fatal server startup error:', err);
  process.exit(1);
});

