import { useEffect, useState } from 'react';
import {
  AlertCircle,
  BarChart3,
  CloudOff,
  CloudUpload,
  Code2,
  DatabaseBackup,
  Download,
  Globe,
  LayoutDashboard,
  LogOut,
  Megaphone,
  Menu,
  Share2,
  Shield,
  Users,
  Wallet,
  X,
} from 'lucide-react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { auth, testFirestoreConnection } from './lib/firebase';
import { apiFetch, getAuthToken, setAuthToken } from './services/api';
import { downloadPackageAsset } from './services/packageDownload';
import {
  cacheMembersSnapshot,
  clearOfflineAutoResume,
  getAdminOfflineQueue,
  getLastOfflineProfile,
  saveOfflineSnapshot,
  updateOfflineItemStatus,
} from './services/offlineDb';
import { sortQueueChronological } from './services/offlineOverlay';
import { useOnlineStatus } from './hooks/useOnlineStatus';
import { t } from './i18n/translations';
import { START_YEAR } from './domain/membershipRules';
import { PWAInstallButton } from './components/PWAInstallButton';
import { ShareInstallModal } from './components/ShareInstallModal';
import { LoginView } from './components/LoginView';
import { DashboardView } from './components/DashboardView';
import { MembersView } from './components/MembersView';
import { MemberProfileModal } from './components/MemberProfileModal';
import { PaymentsView } from './components/PaymentsView';
import { ReceiptModal } from './components/ReceiptModal';
import { CorrectionModal } from './components/CorrectionModal';
import { PendingDuesView } from './components/PendingDuesView';
import { OfflineSyncView } from './components/OfflineSyncView';
import { ReportsView } from './components/ReportsView';
import { BackupView } from './components/BackupView';
import { StaffView } from './components/StaffView';
import { NoticePostsView } from './components/NoticePostsView';
import { CodeVaultView } from './components/CodeVaultView';
import type { AuthUser, Language, PaymentItem, SystemSettings } from './types/app';

type NavTab =
  | 'dashboard'
  | 'members'
  | 'payments'
  | 'pending'
  | 'reports'
  | 'notices'
  | 'offline'
  | 'backups'
  | 'staff'
  | 'codevault';

export default function App() {
  const [lang, setLang] = useState<Language>('bn');
  const [user, setUser] = useState<AuthUser | null>(null);
  const [settings, setSettings] = useState<SystemSettings>({
    allowPartialPayments: 'true',
    autoBackupEnabled: 'true',
    autoBackupIntervalHours: '24',
    currentActiveYear: String(START_YEAR),
  });
  const [initializing, setInitializing] = useState(
    () => typeof navigator !== 'undefined' && !navigator.onLine
  );

  const [activeTab, setActiveTab] = useState<NavTab>('dashboard');
  const [selectedYear, setSelectedYear] = useState<number>(START_YEAR);
  const [mobileDrawerOpen, setMobileDrawerOpen] = useState(false);

  // Modals & Cross-view shortcuts
  const [profileMemberId, setProfileMemberId] = useState<number | null>(null);
  const [preselectedPayMemberId, setPreselectedPayMemberId] = useState<number | null>(null);
  const [receiptNumber, setReceiptNumber] = useState<string | null>(null);
  const [receiptAutoPrint, setReceiptAutoPrint] = useState(false);
  const [correctingPayment, setCorrectingPayment] = useState<PaymentItem | null>(null);
  const [refreshTick, setRefreshTick] = useState(0);
  const [showShareModal, setShowShareModal] = useState(false);

  const openReceiptModal = (num: string, autoPrint = false) => {
    setReceiptAutoPrint(autoPrint);
    setReceiptNumber(num);
  };

  // Network + Admin offline mode
  const browserOnline = useOnlineStatus();
  const [adminSimulatedOffline, setAdminSimulatedOffline] = useState(false);
  const [unsyncedCount, setUnsyncedCount] = useState(0);
  const isOfflineMode =
    user?.roleName === 'ADMIN' ? !browserOnline || adminSimulatedOffline || !getAuthToken() : false;

  const refreshOfflineCount = async () => {
    try {
      const items = await getAdminOfflineQueue();
      setUnsyncedCount(items.filter((i) => i.syncStatus === 'UNSYNCED').length);
    } catch {
      // ignore IndexedDB unavailable
    }
  };

  useEffect(() => {
    document.documentElement.lang = lang === 'bn' ? 'bn' : 'en';
  }, [lang]);

  useEffect(() => {
    if (browserOnline && auth.currentUser) {
      testFirestoreConnection().catch(() => {});
    }
  }, [browserOnline, user]);

  // Pre-warm offline IndexedDB snapshots whenever Admin is connected online so turning off internet works seamlessly
  const warmOfflineCaches = async (refYear: number) => {
    try {
      const [dashRes, memsRes, paysRes, pendRes, adminNoticesRes, publicNoticesRes, bundleRes] =
        await Promise.allSettled([
          apiFetch(`/api/dashboard?year=${refYear}`),
          apiFetch<{ members: Parameters<typeof cacheMembersSnapshot>[0] }>(`/api/members?year=${refYear}`),
          apiFetch<{ payments: unknown[] }>(`/api/payments?year=${refYear}`),
          apiFetch(`/api/pending?year=${refYear}`),
          apiFetch<{ items: unknown[] }>('/api/admin/notices'),
          apiFetch<{ items: unknown[] }>('/api/public/notices'),
          apiFetch('/api/admin/source-bundle'),
        ]);

      const saves: Promise<void>[] = [];
      if (dashRes.status === 'fulfilled') {
        saves.push(
          saveOfflineSnapshot(`dashboard:${refYear}`, dashRes.value),
          saveOfflineSnapshot('dashboard:latest', dashRes.value)
        );
      }
      if (memsRes.status === 'fulfilled') {
        saves.push(cacheMembersSnapshot(memsRes.value.members));
      }
      if (paysRes.status === 'fulfilled') {
        saves.push(
          saveOfflineSnapshot(`payments:year:${refYear}`, paysRes.value.payments),
          saveOfflineSnapshot('payments:latest', paysRes.value.payments)
        );
      }
      if (pendRes.status === 'fulfilled') {
        saves.push(
          saveOfflineSnapshot(`pending:${refYear}`, pendRes.value),
          saveOfflineSnapshot('pending:latest', pendRes.value)
        );
      }
      if (adminNoticesRes.status === 'fulfilled') {
        saves.push(saveOfflineSnapshot('admin:notices', adminNoticesRes.value.items || []));
      }
      if (publicNoticesRes.status === 'fulfilled') {
        saves.push(saveOfflineSnapshot('public:notices', publicNoticesRes.value.items || []));
      }
      if (bundleRes.status === 'fulfilled') {
        saves.push(saveOfflineSnapshot('admin:source-bundle', bundleRes.value));
      }
      await Promise.allSettled(saves);
    } catch {
      // non-fatal background warm
    }
  };

  // Restore Firebase or Offline Trusted Session if PWA is reopened offline
  useEffect(() => {
    let active = true;
    const safetyTimer = setTimeout(() => {
      if (active) setInitializing(false);
    }, 1500);

    if (typeof navigator !== 'undefined' && !navigator.onLine) {
      getLastOfflineProfile()
        .then((offlineProf) => {
          if (active && offlineProf) {
            setUser(offlineProf.user);
            setSettings(offlineProf.settings);
            setSelectedYear(
              Math.max(START_YEAR, Number(offlineProf.settings.currentActiveYear || START_YEAR))
            );
          }
        })
        .finally(() => {
          if (active) setInitializing(false);
        });
    }

    const unsub = onAuthStateChanged(auth, async (fbUser) => {
      if (fbUser && !user && (typeof navigator === 'undefined' || navigator.onLine)) {
        try {
          const token = await fbUser.getIdToken();
          setAuthToken(token);
          const res = await apiFetch<{ user: AuthUser; settings: SystemSettings }>('/api/auth/me');
          if (active) {
            setUser(res.user);
            setSettings(res.settings);
            setSelectedYear(Math.max(START_YEAR, Number(res.settings.currentActiveYear || START_YEAR)));
          }
        } catch {
          setAuthToken(null);
        }
      }
      if (active) setInitializing(false);
    });
    return () => {
      active = false;
      clearTimeout(safetyTimer);
      unsub();
    };
  }, []);

  // Auto-synchronize Admin offline queue chronologically whenever internet returns
  useEffect(() => {
    if (!user || user.roleName !== 'ADMIN') return;
    void refreshOfflineCount();

    if (browserOnline && !adminSimulatedOffline && getAuthToken() && activeTab !== 'offline') {
      getAdminOfflineQueue().then(async (items) => {
        const pending = sortQueueChronological(items.filter((i) => i.syncStatus === 'UNSYNCED'));
        if (pending.length === 0) return;
        try {
          const res = await apiFetch<{
            results: Array<{ clientTxId: string; status: string; message: string }>;
          }>('/api/sync/offline', {
            method: 'POST',
            body: JSON.stringify({ items: pending }),
          });
          for (const r of res.results) {
            await updateOfflineItemStatus(
              r.clientTxId,
              r.status === 'SYNCED' || r.status === 'DUPLICATE_SKIPPED' ? 'SYNCED' : 'CONFLICT',
              r.message
            );
          }
          await refreshOfflineCount();
          setRefreshTick((t) => t + 1);
          void warmOfflineCaches(selectedYear);
        } catch {
          // Will retry when connection stabilizes
        }
      });
    }
  }, [user, browserOnline, adminSimulatedOffline]);

  const handleAuthenticated = (
    authUser: AuthUser,
    sysSettings: SystemSettings,
    offlineLogin = false
  ) => {
    const refYear = Math.max(START_YEAR, Number(sysSettings.currentActiveYear || START_YEAR));
    setUser(authUser);
    setSettings(sysSettings);
    setSelectedYear(refYear);
    setActiveTab('dashboard');
    if (!offlineLogin && browserOnline) {
      void warmOfflineCaches(refYear);
    }
  };

  const handleLogout = async () => {
    setAuthToken(null);
    setUser(null);
    setAdminSimulatedOffline(false);
    await clearOfflineAutoResume();
    try {
      await signOut(auth);
    } catch {
      // ignore if signed in via username/password
    }
  };

  const toggleLanguage = () => setLang((prev) => (prev === 'en' ? 'bn' : 'en'));

  if (initializing) {
    return (
      <div className="min-h-screen bg-[#F6F8F7] flex items-center justify-center p-6">
        <div className="flex flex-col items-center gap-4">
          <img
            src="/assets/madrasa-logo.png"
            alt="Saidpur kudduchiyya madrasah"
            className="h-20 w-20 object-contain aspect-square"
          />
          <p className="text-sm font-semibold text-[#0B5D2E]">{t(lang, 'loading')}</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return (
      <LoginView
        lang={lang}
        onToggleLang={toggleLanguage}
        onAuthenticated={handleAuthenticated}
      />
    );
  }

  const hasPerm = (perm: string) =>
    user.roleName === 'ADMIN' || user.permissions.includes(perm);

  const rawNavItems: Array<{
    id: NavTab;
    label: string;
    icon: typeof LayoutDashboard;
    visible: boolean;
    badge?: number;
  }> = [
    { id: 'dashboard', label: t(lang, 'dashboard'), icon: LayoutDashboard, visible: true },
    { id: 'members', label: t(lang, 'members'), icon: Users, visible: hasPerm('members:view') },
    { id: 'payments', label: t(lang, 'payments'), icon: Wallet, visible: hasPerm('payments:view') },
    {
      id: 'pending',
      label: t(lang, 'pendingDues'),
      icon: AlertCircle,
      visible: hasPerm('payments:view'),
    },
    { id: 'reports', label: t(lang, 'reports'), icon: BarChart3, visible: hasPerm('reports:view') },
    {
      id: 'notices',
      label: lang === 'bn' ? 'নোটিশ ও পোস্ট' : 'Notices & Posts',
      icon: Megaphone,
      visible: user.roleName === 'ADMIN',
    },
    {
      id: 'offline',
      label: t(lang, 'offlineSync'),
      icon: CloudUpload,
      visible: user.roleName === 'ADMIN',
      badge: unsyncedCount,
    },
    {
      id: 'backups',
      label: t(lang, 'backups'),
      icon: DatabaseBackup,
      visible: hasPerm('backup:manage'),
    },
    {
      id: 'staff',
      label: t(lang, 'staffAdmin'),
      icon: Shield,
      visible: user.roleName === 'ADMIN',
    },
    {
      id: 'codevault',
      label: lang === 'bn' ? 'কোড ও AI গাইড' : 'Source & AI Guide',
      icon: Code2,
      visible: user.roleName === 'ADMIN',
    },
  ];
  const navItems = rawNavItems.filter((item) => item.visible);

  const mobilePrimaryTabs = navItems.slice(0, 4);

  return (
    <div className="min-h-screen bg-[#F6F8F7] text-slate-900 flex">
      {/* Desktop Sidebar */}
      <aside className="hidden lg:flex lg:flex-col lg:w-64 lg:fixed lg:inset-y-0 bg-[#0B5D2E] text-white border-r border-[#084722] z-30">
        <div className="p-5 border-b border-white/15 flex items-center gap-3">
          <img
            src="/assets/madrasa-logo.png"
            alt="Saidpur kudduchiyya madrasah"
            className="h-12 w-12 object-contain aspect-square shrink-0"
          />
          <div className="min-w-0">
            <div className="text-[13px] font-bold leading-tight">
              {t(lang, 'orgName')}
            </div>
            <div className="text-[11px] text-[#F4D06F] font-medium mt-0.5">
              Saidpur, Taki · 2026+
            </div>
          </div>
        </div>

        <nav aria-label="Primary navigation" className="flex-1 p-3 space-y-1 overflow-y-auto">
          {navItems.map((item) => {
            const Icon = item.icon;
            const active = activeTab === item.id;
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => setActiveTab(item.id)}
                className={`w-full flex items-center justify-between px-3.5 py-3 rounded-xl text-sm font-semibold transition-colors ${
                  active
                    ? 'bg-white text-[#0B5D2E] shadow-xs'
                    : 'text-emerald-50 hover:bg-white/10'
                }`}
              >
                <span className="flex items-center gap-3 min-w-0">
                  <Icon className="h-4 w-4 shrink-0" />
                  <span className="truncate">{item.label}</span>
                </span>
                {item.badge !== undefined && item.badge > 0 && (
                  <span className="font-mono-num text-xs font-bold px-1.5 py-0.5 rounded bg-amber-500 text-white">
                    {item.badge}
                  </span>
                )}
              </button>
            );
          })}
        </nav>

        <div className="p-4 border-t border-white/15 space-y-2.5">
          <div className="text-xs">
            <div className="font-bold text-white truncate">{user.fullName}</div>
            <div className="text-emerald-200/80 font-mono-num">
              {user.roleName} · {user.username}
            </div>
          </div>
          <button
            type="button"
            onClick={() => setShowShareModal(true)}
            className="w-full h-9 rounded-xl bg-emerald-600/40 hover:bg-emerald-600/60 border border-white/15 text-white text-xs font-semibold flex items-center justify-center gap-2 transition-colors"
          >
            <Share2 className="h-3.5 w-3.5 text-[#F4D06F]" />
            <span>
              {lang === 'bn' ? 'শেয়ার ও অফলাইন ইনস্টল' : 'Share & Offline Profile'}
            </span>
          </button>
          <button
            type="button"
            onClick={() => void downloadPackageAsset('guideline')}
            className="w-full h-9 rounded-xl bg-white/10 hover:bg-white/20 text-[#F4D06F] text-xs font-semibold flex items-center justify-center gap-2 transition-colors"
          >
            <Download className="h-3.5 w-3.5" />
            <span>
              {lang === 'bn' ? 'অনলাইন ও অফলাইন গাইড (PDF)' : 'Online/Offline Guide (PDF)'}
            </span>
          </button>
          <button
            type="button"
            onClick={handleLogout}
            className="w-full h-10 rounded-xl bg-white/10 hover:bg-white/20 text-white text-xs font-semibold flex items-center justify-center gap-2 transition-colors"
          >
            <LogOut className="h-4 w-4" />
            <span>{t(lang, 'logout')}</span>
          </button>
        </div>
      </aside>

      {/* Main Content Shell */}
      <div className="flex-1 lg:pl-64 flex flex-col min-h-screen w-full">
        {/* Top Bar (compact on mobile <= 52px, clean on desktop) */}
        <header className="sticky top-0 z-20 bg-white border-b border-slate-200 h-13 lg:h-16 px-4 sm:px-6 flex items-center justify-between gap-4">
          <div className="flex items-center gap-2.5 min-w-0">
            <img
              src="/assets/madrasa-logo.png"
              alt="Logo"
              className="h-8 w-8 object-contain aspect-square lg:hidden shrink-0"
            />
            <span className="text-sm font-bold text-[#0B5D2E] truncate lg:hidden">
              {t(lang, 'orgName')}
            </span>
            <span className="hidden lg:inline text-sm font-semibold text-slate-700 truncate">
              {t(lang, 'systemTitle')}
            </span>
          </div>

          <div className="flex items-center gap-2 shrink-0">
            {isOfflineMode ? (
              <button
                type="button"
                onClick={() => setActiveTab('offline')}
                className="inline-flex items-center gap-1.5 rounded-lg bg-amber-100 text-amber-900 px-2.5 py-1.5 text-xs font-semibold whitespace-nowrap"
              >
                <CloudOff className="h-3.5 w-3.5" />
                <span className="hidden sm:inline">{t(lang, 'offlineMode')}</span>
                {unsyncedCount > 0 && <span className="font-mono-num">({unsyncedCount})</span>}
              </button>
            ) : (
              <span className="hidden md:inline-flex items-center gap-1.5 text-xs font-medium text-[#16A34A] whitespace-nowrap">
                {t(lang, 'onlineMode')}
              </span>
            )}

            <button
              type="button"
              onClick={() => setShowShareModal(true)}
              className="inline-flex items-center gap-1.5 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-semibold text-[#0B5D2E] hover:bg-emerald-100 whitespace-nowrap"
            >
              <Share2 className="h-3.5 w-3.5" />
              <span className="hidden sm:inline">
                {lang === 'bn' ? 'শেয়ার ও প্যাক' : 'Share & Pack'}
              </span>
            </button>

            <PWAInstallButton lang={lang} />

            <button
              type="button"
              onClick={toggleLanguage}
              className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700 hover:bg-slate-50 whitespace-nowrap"
            >
              <Globe className="h-3.5 w-3.5 text-[#0B5D2E]" />
              <span>{t(lang, 'languageLabel')}</span>
            </button>

            <button
              type="button"
              aria-label="Open menu"
              onClick={() => setMobileDrawerOpen(true)}
              className="lg:hidden p-2 rounded-lg border border-slate-200 text-slate-700"
            >
              <Menu className="h-4 w-4" />
            </button>
          </div>
        </header>

        {/* Offline status strip for Admin & Staff */}
        {!browserOnline && user.roleName !== 'ADMIN' && (
          <div className="bg-[#DC2626] text-white text-xs font-semibold px-4 py-2 text-center">
            {lang === 'bn'
              ? 'ইন্টারনেট সংযোগ বিচ্ছিন্ন। পূর্বের সংরক্ষিত তথ্য দেখা যাচ্ছে — নতুন এন্ট্রির জন্য ইন্টারনেট বা অ্যাডমিন ডিভাইস প্রয়োজন।'
              : 'Internet disconnected. Viewing cached records — new entries require online connection or the Admin device.'}
          </div>
        )}
        {!browserOnline && user.roleName === 'ADMIN' && (
          <div className="bg-amber-600 text-white text-xs font-semibold px-4 py-2 text-center">
            {lang === 'bn'
              ? 'অফলাইন মোড চালু (ইন্টারনেট বন্ধ) — আপনি নতুন সদস্য, চাঁদা গ্রহণ এবং 4"×6" রসিদ প্রিন্ট করতে পারবেন; ইন্টারনেট ফিরলে স্বয়ংক্রিয় সিঙ্ক হবে।'
              : 'Offline Mode Active — Admin can view cached ledgers, add members, collect fees, and print receipts offline; auto-syncs when online.'}
          </div>
        )}

        {/* Active Page Viewport */}
        <main className="flex-1 p-4 sm:p-6 lg:p-8 pb-24 lg:pb-10 max-w-7xl w-full mx-auto">
          {activeTab === 'dashboard' && (
            <DashboardView
              lang={lang}
              user={user}
              selectedYear={selectedYear}
              isOfflineMode={isOfflineMode}
              onSelectYear={setSelectedYear}
              onOpenReceipt={(num) => setReceiptNumber(num)}
              onNavigate={(tab) => setActiveTab(tab as NavTab)}
            />
          )}

          {activeTab === 'members' && (
            <MembersView
              lang={lang}
              user={user}
              selectedYear={selectedYear}
              isOfflineMode={isOfflineMode}
              onRefreshOfflineCount={refreshOfflineCount}
              onViewProfile={(id) => setProfileMemberId(id)}
              onOpenReceipt={(num) => setReceiptNumber(num)}
              onQuickCollect={(id) => {
                setPreselectedPayMemberId(id);
                setActiveTab('payments');
              }}
            />
          )}

          {activeTab === 'payments' && (
            <PaymentsView
              lang={lang}
              user={user}
              selectedYear={selectedYear}
              settings={settings}
              isOfflineMode={isOfflineMode}
              preselectedMemberId={preselectedPayMemberId}
              onClearPreselected={() => setPreselectedPayMemberId(null)}
              onRefreshOfflineCount={refreshOfflineCount}
              onOpenReceipt={(num, autoPrint) => openReceiptModal(num, Boolean(autoPrint))}
              onOpenCorrection={(p) => setCorrectingPayment(p)}
              refreshTick={refreshTick}
            />
          )}

          {activeTab === 'pending' && (
            <PendingDuesView
              lang={lang}
              user={user}
              selectedYear={selectedYear}
              isOfflineMode={isOfflineMode}
              onOpenReceipt={(num) => setReceiptNumber(num)}
              onQuickCollect={(id) => {
                setPreselectedPayMemberId(id);
                setActiveTab('payments');
              }}
            />
          )}

          {activeTab === 'reports' && (
            <ReportsView
              lang={lang}
              selectedYear={selectedYear}
              onOpenReceipt={(num) => setReceiptNumber(num)}
            />
          )}

          {activeTab === 'offline' && (
            <OfflineSyncView
              lang={lang}
              user={user}
              isOfflineMode={isOfflineMode}
              onToggleOfflineMode={() => setAdminSimulatedOffline((prev) => !prev)}
              onRefreshOfflineCount={refreshOfflineCount}
            />
          )}

          {activeTab === 'backups' && (
            <BackupView
              lang={lang}
              user={user}
              settings={settings}
              onSettingsUpdated={setSettings}
            />
          )}

          {activeTab === 'staff' && (
            <StaffView
              lang={lang}
              user={user}
              settings={settings}
              onSettingsUpdated={setSettings}
            />
          )}

          {activeTab === 'notices' && user.roleName === 'ADMIN' && (
            <NoticePostsView
              lang={lang}
              user={user}
              isOfflineMode={isOfflineMode}
              onRefreshOfflineCount={refreshOfflineCount}
              refreshTick={refreshTick}
            />
          )}

          {activeTab === 'codevault' && user.roleName === 'ADMIN' && (
            <CodeVaultView lang={lang} isOfflineMode={isOfflineMode} />
