        <nav
          aria-label="Mobile navigation"
          className="lg:hidden fixed bottom-0 left-0 right-0 z-30 h-16 bg-white/95 backdrop-blur-md border-t border-slate-200 grid grid-cols-4 items-center"
        >
          {mobilePrimaryTabs.map((item) => {
            const Icon = item.icon;
            const active = activeTab === item.id;
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => setActiveTab(item.id)}
                className={`flex flex-col items-center justify-center h-full px-1 ${
                  active ? 'text-[#0B5D2E] font-bold' : 'text-slate-500 font-medium'
                }`}
              >
                <Icon className="h-5 w-5" />
                <span className="text-[10px] mt-1 truncate max-w-full">{item.label}</span>
              </button>
            );
          })}
        </nav>
      </div>

      {/* Mobile Full Menu Drawer */}
      {mobileDrawerOpen && (
        <div className="lg:hidden fixed inset-0 z-50 flex justify-end bg-black/50">
          <div className="w-72 bg-[#0B5D2E] text-white h-full p-5 flex flex-col">
            <div className="flex items-center justify-between border-b border-white/15 pb-4">
              <div className="flex items-center gap-2.5">
                <img
                  src="/assets/madrasa-logo.png"
                  alt="Logo"
                  className="h-9 w-9 object-contain aspect-square"
                />
                <span className="text-sm font-bold">{user.fullName}</span>
              </div>
              <button
                type="button"
                aria-label="Close menu"
                onClick={() => setMobileDrawerOpen(false)}
                className="p-2 text-white/80"
              >
                <X className="h-5 w-5" />
              </button>
            </div>
            <div className="flex-1 py-4 space-y-1 overflow-y-auto">
              {navItems.map((item) => {
                const Icon = item.icon;
                return (
                  <button
                    key={item.id}
                    type="button"
                    onClick={() => {
                      setActiveTab(item.id);
                      setMobileDrawerOpen(false);
                    }}
                    className={`w-full flex items-center justify-between px-3 py-3 rounded-xl text-sm font-semibold ${
                      activeTab === item.id ? 'bg-white text-[#0B5D2E]' : 'text-emerald-50'
                    }`}
                  >
                    <span className="flex items-center gap-3">
                      <Icon className="h-4 w-4" />
                      <span>{item.label}</span>
                    </span>
                    {item.badge !== undefined && item.badge > 0 && (
                      <span className="font-mono-num text-xs bg-amber-500 text-white px-1.5 py-0.5 rounded">
                        {item.badge}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
            <div className="space-y-2 pt-2">
              <button
                type="button"
                onClick={() => {
                  setMobileDrawerOpen(false);
                  setShowShareModal(true);
                }}
                className="w-full h-10 rounded-xl bg-emerald-600/50 text-white text-xs font-semibold flex items-center justify-center gap-2"
              >
                <Share2 className="h-4 w-4 text-[#F4D06F]" />
                <span>
                  {lang === 'bn' ? 'শেয়ার ও অফলাইন প্যাক' : 'Share & Offline Profile'}
                </span>
              </button>
              <a
                href="/api/package/download-guideline"
                download="SKM_Online_Offline_Guideline.pdf"
                className="w-full h-10 rounded-xl bg-white/10 text-[#F4D06F] text-xs font-semibold flex items-center justify-center gap-2"
              >
                <Download className="h-4 w-4" />
                <span>
                  {lang === 'bn' ? 'অনলাইন ও অফলাইন গাইড (PDF)' : 'Online/Offline Guide (PDF)'}
                </span>
              </a>
              <button
                type="button"
                onClick={handleLogout}
                className="w-full h-11 rounded-xl bg-white/15 text-white text-sm font-semibold flex items-center justify-center gap-2"
              >
                <LogOut className="h-4 w-4" />
                <span>{t(lang, 'logout')}</span>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Global Modals */}
      {showShareModal && (
        <ShareInstallModal lang={lang} onClose={() => setShowShareModal(false)} />
      )}

      {profileMemberId !== null && (
        <MemberProfileModal
          lang={lang}
          memberId={profileMemberId}
          onClose={() => setProfileMemberId(null)}
          onOpenReceipt={(num) => setReceiptNumber(num)}
        />
      )}

      {receiptNumber && (
        <ReceiptModal
          lang={lang}
          receiptNumber={receiptNumber}
          autoPrint={receiptAutoPrint}
          onClose={() => {
            setReceiptNumber(null);
            setReceiptAutoPrint(false);
          }}
        />
      )}

      {correctingPayment && (
        <CorrectionModal
          lang={lang}
          payment={correctingPayment}
          onClose={() => setCorrectingPayment(null)}
          onSuccess={() => {
            setCorrectingPayment(null);
            setRefreshTick((t) => t + 1);
          }}
        />
      )}
    </div>
  );
}

import { useEffect, useState, type ChangeEvent } from 'react';
import {
  CheckCircle2,
  Cloud,
  CloudUpload,
  DatabaseBackup,
  Download,
  HardDrive,
  ShieldCheck,
  Trash2,
  Upload,
  Usb,
} from 'lucide-react';
import { onAuthStateChanged, signInWithPopup, type User as FirebaseUser } from 'firebase/auth';
import {
  collection,
  deleteDoc,
  doc,
  limit,
  onSnapshot,
  orderBy,
  query,
  serverTimestamp,
  setDoc,
} from 'firebase/firestore';
import {
  OperationType,
  auth,
  firestoreDb,
  googleAuthProvider,
  handleFirestoreError,
} from '../lib/firebase';
import { apiFetch } from '../services/api';
import { t } from '../i18n/translations';
import type { AuthUser, Language, SystemSettings } from '../types/app';

interface BackupHistoryRow {
  id: number;
  backupType: string;
  targetLocation: string;
  encryptionAlg: string;
  checksumSha256: string;
  recordCount: number;
  fileSizeBytes: number;
  status: string;
  createdAt: string;
  createdByName: string | null;
}

interface CloudVaultEntry {
  id: string;
  checksumSha256: string;
  recordCount: number;
  encryptionAlg: string;
  targetLocation: string;
  envelopeJson: string;
  createdByEmail?: string;
  createdAtText: string;
}

export function BackupView({
  lang,
  user,
  settings,
  onSettingsUpdated,
}: {
  lang: Language;
  user: AuthUser;
  settings: SystemSettings;
  onSettingsUpdated: (s: SystemSettings) => void;
}) {
  const [history, setHistory] = useState<BackupHistoryRow[]>([]);
  const [passphrase, setPassphrase] = useState('');
  const [creating, setCreating] = useState(false);
  const [restorePreview, setRestorePreview] = useState<{
    envelope: unknown;
    counts: { members: number; obligations: number; payments: number; corrections: number };
    exportedAt: string;
    sourceLabel?: string;
  } | null>(null);
  const [restoring, setRestoring] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Firebase Firestore Online Cloud Vault state
  const [fbUser, setFbUser] = useState<FirebaseUser | null>(auth.currentUser);
  const [cloudBackups, setCloudBackups] = useState<CloudVaultEntry[]>([]);
  const [cloudBusy, setCloudBusy] = useState(false);

  const loadHistory = async () => {
    try {
      const res = await apiFetch<{ history: BackupHistoryRow[] }>('/api/backups');
      setHistory(res.history);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load backup history.');
    }
  };

  useEffect(() => {
    loadHistory();
  }, []);

  useEffect(() => {
    const unsub = onAuthStateChanged(auth, (u) => {
      setFbUser(u);
    });
    return () => unsub();
  }, []);

  useEffect(() => {
    if (!fbUser || !fbUser.emailVerified) {
      setCloudBackups([]);
      return;
    }
    const vaultPath = `users/${fbUser.uid}/backups`;
    const q = query(
      collection(firestoreDb, vaultPath),
      orderBy('createdAt', 'desc'),
      limit(25)
    );
    const unsub = onSnapshot(
      q,
      (snap) => {
        const rows: CloudVaultEntry[] = snap.docs.map((d) => {
          const data = d.data() as Record<string, unknown>;
          const ts = data.createdAt as { toDate?: () => Date } | undefined;
          return {
            id: d.id,
            checksumSha256: String(data.checksumSha256 || ''),
            recordCount: Number(data.recordCount || 0),
            encryptionAlg: String(data.encryptionAlg || 'AES-256-GCM'),
            targetLocation: String(data.targetLocation || 'Firestore Cloud Vault'),
            envelopeJson: String(data.envelopeJson || ''),
            createdByEmail: data.createdByEmail ? String(data.createdByEmail) : undefined,
            createdAtText: ts?.toDate ? ts.toDate().toLocaleString() : 'Just now',
          };
        });
        setCloudBackups(rows);
      },
      (err) => {
        try {
          handleFirestoreError(err, OperationType.LIST, vaultPath);
        } catch {
          // Graceful UI feedback if user lacks cloud permissions or is offline
        }
      }
    );
    return () => unsub();
  }, [fbUser]);

  const triggerDownload = (filename: string, content: string) => {
    const blob = new Blob([content], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  const handleCreateBackup = async (
    backupType: 'MANUAL' | 'AUTO_CLOUD' | 'LOCAL_DRIVE' | 'USB',
    targetLocation: string,
    driveLetter?: string
  ) => {
    setCreating(true);
    setError(null);
    setMessage(null);
    try {
      const res = await apiFetch<{
        backupRecord: BackupHistoryRow;
        encryptedEnvelope: Record<string, unknown>;
      }>('/api/backups/create', {
        method: 'POST',
        body: JSON.stringify({ backupType, targetLocation, passphrase }),
      });

      const filename = `SKM-Backup-${new Date().toISOString().slice(0, 10)}.skmbak`;
      const serialized = JSON.stringify(res.encryptedEnvelope, null, 2);

      // If running inside Windows Electron desktop app and targeting D/E/USB drive
      if (driveLetter && window.skmDesktop?.saveBackupToDrive) {
        const result = await window.skmDesktop.saveBackupToDrive(driveLetter, filename, serialized);
        if (!result.ok) {
          throw new Error(result.error || `Drive ${driveLetter}:\\ not writable.`);
        }
        setMessage(`Encrypted backup saved directly to ${result.path}`);
      } else if (backupType === 'LOCAL_DRIVE' || backupType === 'USB') {
        const picker = (
          window as unknown as { showDirectoryPicker?: () => Promise<FileSystemDirectoryHandle> }
        ).showDirectoryPicker;
        if (picker) {
          try {
            const dir = await picker();
            const handle = await dir.getFileHandle(filename, { create: true });
            const writable = await handle.createWritable();
            await writable.write(serialized);
            await writable.close();
            setMessage(`Encrypted backup written to selected folder (${targetLocation}): ${filename}`);
          } catch {
            triggerDownload(filename, serialized);
            setMessage(`Encrypted backup downloaded: ${filename}`);
          }
        } else {
          triggerDownload(filename, serialized);
          setMessage(`Encrypted backup downloaded: ${filename}`);
        }
      } else {
        triggerDownload(filename, serialized);
        setMessage(
          `Encrypted AES-256-GCM backup created & verified (${res.backupRecord.recordCount} records).`
        );
      }

      await loadHistory();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Backup creation failed.');
    } finally {
      setCreating(false);
    }
  };

  const handleConnectGoogleCloud = async () => {
    setError(null);
    setCloudBusy(true);
    try {
      await signInWithPopup(auth, googleAuthProvider);
      setMessage(
        lang === 'bn'
          ? 'ক্লাউড ভল্টের সাথে গুগল অ্যাকাউন্ট সংযুক্ত হয়েছে।'
          : 'Google account connected for Cloud Backup Vault.'
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Google connection failed.');
    } finally {
      setCloudBusy(false);
    }
  };

  const handleSaveToCloudVault = async () => {
    if (!fbUser) {
      await handleConnectGoogleCloud();
      return;
    }
    setCloudBusy(true);
    setError(null);
    setMessage(null);
    try {
      const res = await apiFetch<{
        backupRecord: BackupHistoryRow;
        encryptedEnvelope: Record<string, unknown>;
      }>('/api/backups/create', {
        method: 'POST',
        body: JSON.stringify({
          backupType: 'AUTO_CLOUD',
          targetLocation: `Firebase Cloud Vault (${fbUser.email || fbUser.uid})`,
          passphrase,
        }),
      });

      const serialized = JSON.stringify(res.encryptedEnvelope);
      if (serialized.length > 940_000) {
        throw new Error(
          'Encrypted backup exceeds single Cloud Vault snapshot size limit; use local .skmbak file download instead.'
        );
      }

      const backupId = `skmbak_${Date.now()}`;
      const docPath = `users/${fbUser.uid}/backups/${backupId}`;
      try {
        await setDoc(doc(firestoreDb, 'users', fbUser.uid, 'backups', backupId), {
          ownerId: fbUser.uid,
          checksumSha256: String(res.encryptedEnvelope.checksumSha256 || res.backupRecord.checksumSha256),
          recordCount: Number(res.backupRecord.recordCount),
          encryptionAlg: String(res.backupRecord.encryptionAlg || 'AES-256-GCM'),
          targetLocation: 'Firebase Cloud Vault',
          envelopeJson: serialized,
          createdByEmail: fbUser.email || '',
          createdAt: serverTimestamp(),
        });
      } catch (err) {
        handleFirestoreError(err, OperationType.CREATE, docPath);
      }

      setMessage(
        lang === 'bn'
          ? `অনলাইন ক্লাউড ভল্টে এনক্রিপ্টেড ব্যাকআপ সংরক্ষিত হয়েছে (${res.backupRecord.recordCount} রেকর্ড)!`
          : `Saved encrypted snapshot to Online Cloud Vault (${res.backupRecord.recordCount} records).`
      );
      await loadHistory();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Cloud vault backup failed.');
    } finally {
      setCloudBusy(false);
    }
  };

  const handleVerifyCloudEntry = async (entry: CloudVaultEntry) => {
    setError(null);
    setMessage(null);
    try {
      const envelope = JSON.parse(entry.envelopeJson);
      const res = await apiFetch<{
        verified: boolean;
        exportedAt: string;
        counts: { members: number; obligations: number; payments: number; corrections: number };
      }>('/api/backups/verify-restore', {
        method: 'POST',
        body: JSON.stringify({ envelope, passphrase, confirmRestore: false }),
      });
      setRestorePreview({
        envelope,
        counts: res.counts,
        exportedAt: res.exportedAt,
        sourceLabel: `Cloud Vault (${entry.createdAtText})`,
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Cloud backup verification failed.');
    }
  };

  const handleDeleteCloudEntry = async (entry: CloudVaultEntry) => {
    if (!fbUser) return;
    setError(null);
    const docPath = `users/${fbUser.uid}/backups/${entry.id}`;
    try {
      await deleteDoc(doc(firestoreDb, 'users', fbUser.uid, 'backups', entry.id));
    } catch (err) {
      handleFirestoreError(err, OperationType.DELETE, docPath);
    }
  };

  const handleSelectRestoreFile = async (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setError(null);
    setMessage(null);
    try {
      const text = await file.text();
      const envelope = JSON.parse(text);
      const res = await apiFetch<{
        verified: boolean;
        exportedAt: string;
        counts: { members: number; obligations: number; payments: number; corrections: number };
      }>('/api/backups/verify-restore', {
        method: 'POST',
        body: JSON.stringify({ envelope, passphrase, confirmRestore: false }),
      });
      setRestorePreview({
        envelope,
        counts: res.counts,
        exportedAt: res.exportedAt,
        sourceLabel: file.name,
      });
    } catch (err) {
      setRestorePreview(null);
      setError(err instanceof Error ? err.message : 'Backup verification failed.');
    }
  };

  const handleConfirmRestore = async () => {
    if (!restorePreview) return;
    setRestoring(true);
    setError(null);
    try {
      await apiFetch('/api/backups/verify-restore', {
        method: 'POST',
        body: JSON.stringify({
          envelope: restorePreview.envelope,
          passphrase,
          confirmRestore: true,
        }),
      });
      setMessage(
        lang === 'bn'
          ? 'ব্যাকআপ যাচাই ও ডাটাবেসে সফলভাবে রিস্টোর হয়েছে।'
          : 'Backup verified and restored successfully to the active database.'
      );
      setRestorePreview(null);
      await loadHistory();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Restore failed.');
    } finally {
      setRestoring(false);
    }
  };

  const toggleAutoBackup = async () => {
    const nextVal = settings.autoBackupEnabled === 'true' ? 'false' : 'true';
    try {
      const res = await apiFetch<{ settings: SystemSettings }>('/api/settings', {
        method: 'PUT',
        body: JSON.stringify({ autoBackupEnabled: nextVal }),
      });
      onSettingsUpdated(res.settings);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update backup schedule.');
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-slate-900">{t(lang, 'backups')}</h1>
          <p className="text-sm text-slate-500 mt-0.5">
            {lang === 'bn'
              ? 'AES-256-GCM এনক্রিপ্টেড ক্লাউড ভল্ট, লোকাল ড্রাইভ (D:/E:) ও USB ব্যাকআপ এবং যাচাইকৃত রিস্টোর'
              : 'AES-256-GCM Encrypted Backups · Online Cloud Vault, Windows D:/E: Drives, USB & Verified Restore'}
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2 shrink-0">
          <a
            href="/api/package/download-guideline"
            download="SKM_Online_Offline_Guideline.pdf"
            className="inline-flex items-center justify-center gap-2 rounded-xl border border-amber-200 bg-amber-50 hover:bg-amber-100 text-amber-900 px-3.5 h-10 text-xs font-semibold whitespace-nowrap"
          >
            <Download className="h-4 w-4" />
            <span>
              {lang === 'bn' ? 'অনলাইন-অফলাইন গাইড (PDF)' : 'Online/Offline Guide (PDF)'}
            </span>
          </a>
          <a
            href="/api/package/download-zip"
            download="syedpur-kuddusia-madrasa-software.zip"
            className="inline-flex items-center justify-center gap-2 rounded-xl border border-emerald-200 bg-emerald-50 hover:bg-emerald-100 text-[#0B5D2E] px-4 h-10 text-xs font-semibold whitespace-nowrap"
          >
            <Download className="h-4 w-4" />
            <span>
              {lang === 'bn' ? 'অফলাইন সফটওয়্যার (.zip) ডাউনলোড' : 'Download Full Software (.zip)'}
            </span>
          </a>
          <a
            href="/api/package/download-bat"
            download="setup-and-run-windows.bat"
            className="inline-flex items-center justify-center gap-2 rounded-xl border border-blue-200 bg-blue-50 hover:bg-blue-100 text-[#0A3D91] px-3.5 h-10 text-xs font-semibold whitespace-nowrap"
          >
            <Download className="h-4 w-4" />
            <span>
              {lang === 'bn' ? 'উইন্ডোজ ইন্সটলার (.bat)' : 'Windows Installer (.bat)'}
            </span>
          </a>
        </div>
      </div>

      {message && (
        <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-[#0B5D2E]">
          {message}
        </div>
      )}
      {error && (
        <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-[#DC2626]">
          {error}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Create Encrypted Backup Card */}
        <section className="lg:col-span-7 rounded-xl bg-white border border-slate-200 p-6 space-y-4">
          <div className="flex items-center justify-between gap-2">
            <h2 className="text-base font-bold text-slate-900 flex items-center gap-2">
              <DatabaseBackup className="h-5 w-5 text-[#0B5D2E]" />
              <span>{t(lang, 'createBackup')}</span>
            </h2>
            {user.roleName === 'ADMIN' && (
              <button
                type="button"
                onClick={toggleAutoBackup}
                className={`px-3 py-1.5 rounded-lg text-xs font-semibold border ${
                  settings.autoBackupEnabled === 'true'
                    ? 'bg-emerald-50 border-emerald-200 text-[#0B5D2E]'
                    : 'bg-slate-100 border-slate-200 text-slate-600'
                }`}
              >
                {lang === 'bn' ? 'স্বয়ংক্রিয় ব্যাকআপ: ' : 'Auto Backup: '}
                {settings.autoBackupEnabled === 'true' ? 'ON (24h)' : 'OFF'}
              </button>
            )}
          </div>

          <div>
            <label htmlFor="bak-pass" className="block text-xs font-semibold text-slate-700 mb-1">
              {lang === 'bn'
                ? 'ঐচ্ছিক এনক্রিপশন পাসওয়ার্ড (খালি রাখলে সিস্টেম কী ব্যবহৃত হবে)'
                : 'Optional Encryption Passphrase (leave blank for managed AES-256-GCM key)'}
            </label>
            <input
              id="bak-pass"
              type="password"
              value={passphrase}
