function categorizeFile(filePath: string): CategoryFilter {
  const lower = filePath.toLowerCase();
  if (
    lower.includes('offlinedb') ||
    lower.includes('offlineoverlay') ||
    lower.includes('offlinesync') ||
    lower.includes('useonline') ||
    lower.includes('usepwa') ||
    lower.includes('pwainstall') ||
    lower.startsWith('electron/') ||
    lower.endsWith('.bat') ||
    lower.includes('capacitor')
  ) {
    return 'OFFLINE_PWA';
  }
  if (lower.startsWith('src/server/') || lower.startsWith('src/db/') || lower === 'server.ts') {
    return 'BACKEND';
  }
  if (
    lower.startsWith('src/components/') ||
    lower.startsWith('src/services/') ||
    lower.startsWith('src/domain/') ||
    lower.startsWith('src/i18n/') ||
    lower.startsWith('src/hooks/') ||
    lower.startsWith('src/types/') ||
    lower.startsWith('src/lib/') ||
    lower === 'src/app.tsx' ||
    lower === 'src/main.tsx' ||
    lower === 'src/index.css' ||
    lower === 'index.html'
  ) {
    return 'FRONTEND';
  }
  return 'CONFIG_DOCS';
}

export function CodeVaultView({ lang, isOfflineMode }: CodeVaultViewProps) {
  const [bundle, setBundle] = useState<SourceBundlePayload | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sourceOrigin, setSourceOrigin] = useState<'LIVE_SERVER' | 'OFFLINE_CACHE' | 'STATIC_BUNDLE'>(
    'LIVE_SERVER'
  );

  const [searchQuery, setSearchQuery] = useState('');
  const [category, setCategory] = useState<CategoryFilter>('ALL');
  const [selectedPath, setSelectedPath] = useState<string>('src/App.tsx');

  const [copiedCode, setCopiedCode] = useState(false);
  const [copiedPrompt, setCopiedPrompt] = useState(false);

  const loadBundle = async () => {
    setLoading(true);
    setError(null);
    const loadFromOfflineFallback = async () => {
      const cached = await getOfflineSnapshot<SourceBundlePayload>(SOURCE_BUNDLE_CACHE_KEY);
      if (cached && cached.files?.length > 0) {
        setBundle(cached);
        setSourceOrigin('OFFLINE_CACHE');
        return true;
      }
      try {
        const staticRes = await fetch('/downloads/skm-source-bundle.json');
        if (staticRes.ok) {
          const parsed = (await staticRes.json()) as SourceBundlePayload;
          if (parsed && parsed.files?.length > 0) {
            setBundle(parsed);
            setSourceOrigin('STATIC_BUNDLE');
            await saveOfflineSnapshot(SOURCE_BUNDLE_CACHE_KEY, parsed);
            return true;
          }
        }
      } catch {
        // ignore fallback fetch error
      }
      return false;
    };

    try {
      if (isOfflineMode || (typeof navigator !== 'undefined' && !navigator.onLine)) {
        const ok = await loadFromOfflineFallback();
        if (!ok) {
          setError(
            lang === 'bn'
              ? 'অফলাইন সোর্স কোড বান্ডেল পাওয়া যায়নি। অনলাইনে একবার সিঙ্ক করে নিন।'
              : 'Offline source code bundle not cached yet. Connect once online to sync it.'
          );
        }
        return;
      }

      const data = await apiFetch<SourceBundlePayload>('/api/admin/source-bundle');
      setBundle(data);
      setSourceOrigin('LIVE_SERVER');
      await saveOfflineSnapshot(SOURCE_BUNDLE_CACHE_KEY, data);
    } catch (err) {
      const ok = await loadFromOfflineFallback();
      if (!ok) {
        setError(err instanceof Error ? err.message : 'Failed to load A-to-Z project source code.');
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadBundle();
  }, [isOfflineMode]);

  const filteredFiles = useMemo(() => {
    if (!bundle) return [];
    const q = searchQuery.trim().toLowerCase();
    return bundle.files.filter((file) => {
      if (category !== 'ALL' && categorizeFile(file.path) !== category) {
        return false;
      }
      if (!q) return true;
      return file.path.toLowerCase().includes(q) || file.content.toLowerCase().includes(q);
    });
  }, [bundle, searchQuery, category]);

  useEffect(() => {
    if (filteredFiles.length === 0) return;
    if (!filteredFiles.some((f) => f.path === selectedPath)) {
      const preferred =
        filteredFiles.find((f) => f.path === 'src/App.tsx') || filteredFiles[0];
      setSelectedPath(preferred.path);
    }
  }, [filteredFiles, selectedPath]);

  const selectedFile = useMemo(
    () => filteredFiles.find((f) => f.path === selectedPath) || filteredFiles[0] || null,
    [filteredFiles, selectedPath]
  );

  const copyText = async (text: string, onDone: () => void) => {
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      ta.remove();
    }
    onDone();
  };

  const triggerTextDownload = (filename: string, content: string, mime = 'text/plain;charset=utf-8') => {
    const blob = new Blob([content], { type: mime });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      a.remove();
      URL.revokeObjectURL(url);
    }, 30_000);
  };

  const totalSizeKb = useMemo(() => {
    if (!bundle) return 0;
    const bytes = bundle.files.reduce((sum, f) => sum + f.sizeBytes, 0);
    return Math.round(bytes / 1024);
  }, [bundle]);

  const categories: Array<{ id: CategoryFilter; label: string }> = [
    { id: 'ALL', label: lang === 'bn' ? 'সকল ফাইল' : 'All Files' },
    { id: 'FRONTEND', label: lang === 'bn' ? 'ফ্রন্টএন্ড ও UI' : 'Frontend & UI' },
    { id: 'BACKEND', label: lang === 'bn' ? 'ব্যাকএন্ড ও DB' : 'Backend & DB' },
    { id: 'OFFLINE_PWA', label: lang === 'bn' ? 'অফলাইন ও উইন্ডোজ' : 'Offline & PWA' },
    { id: 'CONFIG_DOCS', label: lang === 'bn' ? 'কনফিগ ও গাইড' : 'Config & Docs' },
  ];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 flex items-center gap-2.5">
            <Code2 className="h-6 w-6 text-[#0B5D2E]" />
            <span>
              {lang === 'bn'
                ? 'এ টু জেড সোর্স কোড ভল্ট ও Google AI Studio অটো-আপডেট গাইড'
                : 'A-to-Z Source Code Vault & Multi-Gmail AI Studio Auto-Update Guide'}
            </span>
          </h1>
