import { useState, type FormEvent } from 'react';
import { AlertTriangle, X } from 'lucide-react';
import { apiFetch } from '../services/api';
import { formatCurrency, t } from '../i18n/translations';
import type { Language, PaymentItem } from '../types/app';

interface CorrectionModalProps {
  lang: Language;
  payment: PaymentItem;
  onClose: () => void;
  onSuccess: () => void;
}

export function CorrectionModal({ lang, payment, onClose, onSuccess }: CorrectionModalProps) {
  const [newPaidAmount, setNewPaidAmount] = useState(String(payment.paidAmount));
  const [newPaymentMethod, setNewPaymentMethod] = useState(payment.paymentMethod);
  const [newNotes, setNewNotes] = useState(payment.notes || '');
  const [reason, setReason] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError(null);
    if (reason.trim().length < 5) {
      setError(
        lang === 'bn'
          ? 'সংশোধনের সুস্পষ্ট কারণ (কমপক্ষে ৫ অক্ষর) লিখুন।'
          : 'Please provide a clear reason (minimum 5 characters) for this audit trail.'
      );
      return;
    }

    setSaving(true);
    try {
      await apiFetch(`/api/payments/${payment.id}/correct`, {
        method: 'POST',
        body: JSON.stringify({
          newPaidAmount: Number(newPaidAmount),
          newPaymentMethod,
          newNotes,
          reason: reason.trim(),
        }),
      });
      onSuccess();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to apply correction.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-start sm:items-center justify-center bg-black/50 p-4 overflow-y-auto">
      <div className="w-full max-w-lg rounded-2xl bg-white border border-slate-200 shadow-2xl p-6 my-8">
        <div className="flex items-center justify-between border-b border-slate-100 pb-3">
          <div className="flex items-center gap-2 text-[#DC2626]">
            <AlertTriangle className="h-5 w-5" />
            <h2 className="text-lg font-bold text-slate-900">{t(lang, 'correctPayment')}</h2>
          </div>
          <button
            type="button"
            aria-label="Close correction modal"
            onClick={onClose}
            className="p-2 text-slate-500 hover:text-slate-800"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        <div className="mt-3 rounded-xl bg-slate-50 border border-slate-200 p-3 text-xs space-y-1">
          <div>
            <span className="text-slate-500">{t(lang, 'receiptNo')}: </span>
            <strong className="font-mono-num text-[#0A3D91]">{payment.receiptNumber}</strong>
          </div>
          <div>
            <span className="text-slate-500">{t(lang, 'memberName')}: </span>
            <strong>
              {payment.memberName} ({payment.memberCode})
            </strong>
          </div>
          <div>
            <span className="text-slate-500">Original Paid: </span>
            <strong className="font-mono-num">{formatCurrency(payment.paidAmount)}</strong>
            <span className="mx-2">·</span>
            <span className="text-slate-500">Expected Fee: </span>
            <strong className="font-mono-num">{formatCurrency(payment.expectedFee)}</strong>
          </div>
        </div>

        {error && (
          <div className="mt-3 rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-xs font-medium text-[#DC2626]">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="mt-4 space-y-3.5">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label htmlFor="corr-amount" className="block text-xs font-semibold text-slate-700 mb-1">
                {lang === 'bn' ? 'সংশোধিত টাকার পরিমাণ (₹)' : 'Updated Paid Amount (₹)'}
              </label>
              <input
                id="corr-amount"
                type="number"
                min="0"
                step="0.01"
                required
                value={newPaidAmount}
                onChange={(e) => setNewPaidAmount(e.target.value)}
                className="w-full h-11 px-3 rounded-xl border border-slate-300 text-sm font-mono-num font-bold"
              />
            </div>
            <div>
              <label htmlFor="corr-method" className="block text-xs font-semibold text-slate-700 mb-1">
                {t(lang, 'paymentMethod')}
              </label>
              <select
                id="corr-method"
