                  : 'e.g., Cashier entered 500 instead of 800 on handwritten slip'
              }
              className="w-full p-3 rounded-xl border border-slate-300 text-sm focus:ring-2 focus:ring-[#DC2626] focus:outline-none"
            />
          </div>

          <p className="text-xs text-slate-500">
            {lang === 'bn'
              ? 'সতর্কতা: পূর্বের মান স্থায়ীভাবে অডিট লগে সংরক্ষিত থাকবে এবং মুছে ফেলা যাবে না।'
              : 'Immutable Audit Rule: Original values, updated values, reason, user, and timestamp are permanently logged.'}
          </p>

          <div className="pt-2 flex items-center justify-end gap-3">
            <button
              type="button"
              onClick={onClose}
              className="px-4 h-11 rounded-xl border border-slate-300 text-sm font-semibold text-slate-700"
            >
              {t(lang, 'cancel')}
            </button>
            <button
              type="submit"
              disabled={saving}
              className="px-5 h-11 rounded-xl bg-[#DC2626] hover:bg-red-700 text-white text-sm font-semibold disabled:opacity-60"
            >
              {saving ? '...' : t(lang, 'save')}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import {
  ArrowUpRight,
  Banknote,
  Calendar,
  CheckCircle2,
  Clock,
  Download,
  Receipt,
