  UserCheck,
  Users,
  UserX,
} from 'lucide-react';
import { apiFetch } from '../services/api';
import { fetchAndDownloadReceiptPdf } from '../services/exportUtils';
import {
  getAdminOfflineQueue,
  getCachedMembersSnapshot,
  getOfflineSnapshot,
  saveOfflineSnapshot,
} from '../services/offlineDb';
import {
  mergeDashboardWithOfflineQueue,
  mergeMembersWithOfflineQueue,
} from '../services/offlineOverlay';
import { formatCurrency, t } from '../i18n/translations';
import { START_YEAR } from '../domain/membershipRules';
import type { AuthUser, DashboardData, Language } from '../types/app';

interface DashboardViewProps {
  lang: Language;
  user?: AuthUser;
  selectedYear: number;
  isOfflineMode?: boolean;
  onSelectYear: (y: number) => void;
  onOpenReceipt: (receiptNumber: string) => void;
  onNavigate: (tab: string) => void;
}

export function DashboardView({
  lang,
  user,
  selectedYear,
  isOfflineMode = false,
  onSelectYear,
  onOpenReceipt,
  onNavigate,
}: DashboardViewProps) {
  const [data, setData] = useState<DashboardData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadFromOfflineCache = async (year: number): Promise<DashboardData | null> => {
    const cached =
      (await getOfflineSnapshot<DashboardData>(`dashboard:${year}`)) ||
      (await getOfflineSnapshot<DashboardData>('dashboard:latest'));
    if (!cached) return null;

    const [cachedMembers, queue] = await Promise.all([
      getCachedMembersSnapshot(),
      getAdminOfflineQueue(),
    ]);
    const mergedMembers = mergeMembersWithOfflineQueue(
      cachedMembers,
      queue,
      cached.referenceYear,
      user?.fullName
    );
    return mergeDashboardWithOfflineQueue(cached, mergedMembers, queue, user);
  };

  const loadDashboard = async (year: number) => {
    setLoading(true);
    setError(null);
    if (isOfflineMode) {
      const offlineDash = await loadFromOfflineCache(year);
      if (offlineDash) {
        setData(offlineDash);
        setLoading(false);
        return;
      }
    }

    try {
      const res = await apiFetch<DashboardData>(`/api/dashboard?year=${year}`);
      setData(res);
      await Promise.all([
        saveOfflineSnapshot(`dashboard:${year}`, res),
        saveOfflineSnapshot('dashboard:latest', res),
      ]);
    } catch (err) {
      const offlineDash = await loadFromOfflineCache(year);
      if (offlineDash) {
        setData(offlineDash);
      } else {
        setError(err instanceof Error ? err.message : 'Failed to load dashboard.');
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadDashboard(selectedYear);
  }, [selectedYear, isOfflineMode]);

  const yearOptions = Array.from({ length: 30 }, (_, idx) => START_YEAR + idx);

  if (loading && !data) {
    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="h-28 rounded-xl bg-white border border-slate-200 animate-pulse p-5" />
          ))}
        </div>
        <div className="h-72 rounded-xl bg-white border border-slate-200 animate-pulse" />
      </div>
    );
  }

  if (error && !data) {
    return (
      <div className="rounded-xl border border-red-200 bg-red-50 p-6 text-sm text-[#DC2626] flex items-center justify-between gap-4">
        <span>{error}</span>
        <button
          type="button"
          onClick={() => void loadDashboard(selectedYear)}
          className="px-4 py-2 rounded-lg bg-[#DC2626] text-white font-semibold text-xs whitespace-nowrap shrink-0"
        >
          Retry
        </button>
      </div>
    );
  }

  if (!data) return null;

  const maxChartAmount = Math.max(1000, ...data.yearlyChart.map((c) => c.amount));

  return (
    <div className="space-y-6">
      {/* Header Row */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-slate-900">
            {t(lang, 'dashboard')}
          </h1>
          <p className="text-sm text-slate-500 mt-0.5">
            {isOfflineMode
              ? lang === 'bn'
                ? 'সৈয়দপুর কুদ্দুসিয়া মাদ্রাসা · অফলাইন ক্যাশ ও স্থানীয় কিউ পরিসংখ্যান'
                : 'Saidpur kudduchiyya madrasah · Offline Cache & Local Queue Ledger'
              : lang === 'bn'
                ? 'সৈয়দপুর কুদ্দুসিয়া মাদ্রাসা · লাইভ ডেটাবেস পরিসংখ্যান'
                : 'Saidpur kudduchiyya madrasah · Live Database Ledger'}
          </p>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 bg-white border border-slate-200 rounded-xl px-3 h-11">
            <Calendar className="h-4 w-4 text-[#0B5D2E]" />
            <label htmlFor="dash-year" className="text-xs font-semibold text-slate-600 whitespace-nowrap">
              {t(lang, 'activeYear')}:
            </label>
            <select
              id="dash-year"
              value={selectedYear}
              onChange={(e) => onSelectYear(Number(e.target.value))}
              className="text-sm font-bold text-slate-900 bg-transparent focus:outline-none font-mono-num"
            >
              {yearOptions.map((y) => (
                <option key={y} value={y}>
                  {y}
                </option>
              ))}
            </select>
          </div>

          <button
            type="button"
            onClick={() => void loadDashboard(selectedYear)}
            aria-label="Refresh dashboard"
            className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 h-11 text-xs font-semibold text-slate-700 hover:bg-slate-50 whitespace-nowrap shrink-0"
          >
            <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
            <span className="hidden sm:inline">{lang === 'bn' ? 'রিফ্রেশ' : 'Refresh'}</span>
          </button>
        </div>
      </div>

      {/* Primary KPI Grid (7 requested live metrics) */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="rounded-xl bg-white border border-slate-200 p-5">
          <div className="flex items-center justify-between text-slate-500 text-xs font-semibold">
            <span>{t(lang, 'totalMembers')}</span>
            <Users className="h-4 w-4 text-[#0B5D2E]" />
          </div>
          <p className="mt-2 text-2xl font-bold text-slate-900 font-mono-num">
            {data.stats.totalMembers}
          </p>
          <div className="mt-2 flex items-center gap-3 text-xs text-slate-500">
            <span className="inline-flex items-center gap-1 text-[#16A34A] font-medium">
              <UserCheck className="h-3.5 w-3.5" />
              {data.stats.activeMembers} {t(lang, 'active')}
            </span>
            <span aria-hidden="true">·</span>
            <span className="inline-flex items-center gap-1 text-slate-500">
              <UserX className="h-3.5 w-3.5" />
              {data.stats.inactiveMembers} {t(lang, 'inactive')}
            </span>
          </div>
        </div>

        <div className="rounded-xl bg-white border border-slate-200 p-5">
          <div className="flex items-center justify-between text-slate-500 text-xs font-semibold">
            <span>{t(lang, 'totalCollection')}</span>
            <Banknote className="h-4 w-4 text-[#16A34A]" />
          </div>
          <p className="mt-2 text-2xl font-bold text-[#0B5D2E] font-mono-num">
            {formatCurrency(data.stats.totalCollection)}
          </p>
          <p className="mt-2 text-xs text-slate-500">
            {lang === 'bn' ? '২০২৬ সাল থেকে সর্বমোট আদায়' : 'Cumulative since 2026'}
          </p>
        </div>

        <div className="rounded-xl bg-white border border-slate-200 p-5">
          <div className="flex items-center justify-between text-slate-500 text-xs font-semibold">
            <span>
              {t(lang, 'currentYearCollection')} ({data.referenceYear})
            </span>
            <Receipt className="h-4 w-4 text-[#0A3D91]" />
          </div>
          <p className="mt-2 text-2xl font-bold text-[#0A3D91] font-mono-num">
