              {t(lang, 'paidMembers')} / {t(lang, 'pendingMembers')}
            </span>
            <Clock className="h-4 w-4 text-[#DC2626]" />
          </div>
          <div className="mt-2 flex items-baseline gap-3 font-mono-num">
            <span className="text-2xl font-bold text-[#16A34A]">{data.stats.paidMembers}</span>
            <span className="text-slate-300">/</span>
            <span className="text-2xl font-bold text-[#DC2626]">{data.stats.pendingMembers}</span>
          </div>
          <button
            type="button"
            onClick={() => onNavigate('pending')}
            className="mt-2 inline-flex items-center gap-1 text-xs font-semibold text-[#DC2626] hover:underline"
          >
            <CheckCircle2 className="h-3.5 w-3.5" />
            <span>
              {lang === 'bn' ? 'বকেয়া তালিকা দেখুন' : 'Review Pending Dues'}
            </span>
          </button>
        </div>
      </div>

      {/* Yearly Collection Chart + Recent Activities */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <section className="lg:col-span-7 rounded-xl bg-white border border-slate-200 p-5 sm:p-6">
          <div className="flex items-center justify-between mb-5">
            <h2 className="text-base font-bold text-slate-900">{t(lang, 'yearlyChartTitle')}</h2>
            <span className="text-xs font-medium text-slate-500 font-mono-num">
              {START_YEAR}–{data.yearlyChart[data.yearlyChart.length - 1]?.year ?? START_YEAR}
            </span>
          </div>

          <div className="space-y-3">
            {data.yearlyChart.map((item) => {
              const pct = Math.max(2, Math.round((item.amount / maxChartAmount) * 100));
              const isSelected = item.year === data.referenceYear;
              return (
                <div key={item.year} className="grid grid-cols-12 items-center gap-3">
                  <div className="col-span-2 text-xs font-bold text-slate-700 font-mono-num">
