                        >
                          <Receipt className="h-3.5 w-3.5 text-[#0B5D2E]" />
                          <span>{lang === 'bn' ? 'দেখুন' : 'Receipt'}</span>
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            fetchAndDownloadReceiptPdf(p.receiptNumber).catch(() => {});
                          }}
                          aria-label={`Download PDF receipt ${p.receiptNumber}`}
                          className="inline-flex items-center gap-1 rounded-lg border border-blue-200 bg-blue-50 px-2.5 py-1.5 text-xs font-semibold text-[#0A3D91] hover:bg-blue-100 whitespace-nowrap"
                        >
                          <Download className="h-3.5 w-3.5" />
                          <span>PDF</span>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
}

