                      d="M23.745 12.27c0-.7-.06-1.4-.19-2.07H12v4.51h6.6c-.29 1.52-1.14 2.82-2.4 3.68v3.05h3.88c2.27-2.09 3.665-5.17 3.665-9.17Z"
                    />
                    <path
                      fill="#34A853"
                      d="M12 24c3.24 0 5.95-1.08 7.93-2.91l-3.88-3.05c-1.08.72-2.45 1.16-4.05 1.16-3.12 0-5.77-2.11-6.72-4.96H1.29v3.14C3.26 21.3 7.31 24 12 24Z"
                    />
                    <path
                      fill="#FBBC05"
                      d="M5.28 14.24c-.24-.72-.38-1.49-.38-2.24s.14-1.52.38-2.24V6.62H1.29C.47 8.24 0 10.06 0 12s.47 3.76 1.29 5.38l3.99-3.14Z"
                    />
                    <path
                      fill="#EA4335"
                      d="M12 4.75c1.77 0 3.35.61 4.6 1.8l3.42-3.42C17.95 1.19 15.24 0 12 0 7.31 0 3.26 2.7 1.29 6.62l3.99 3.14c.95-2.85 3.6-4.96 6.72-4.96Z"
                    />
                  </svg>
                  <span>{t(lang, 'signInGoogle')}</span>
                </button>
              </>
            )}

            {/* STEP 1B: VERIFY GMAIL LOGIN OTP (ADMIN & STAFF) */}
            {step === 'OTP_VERIFY' && otpChallenge && (
              <form onSubmit={handleVerifyLoginOtp} className="space-y-4">
                {renderOtpDestinationBanner(otpChallenge)}
                <div>
                  <label
                    htmlFor="login-otp-code"
                    className="block text-sm font-semibold text-slate-700 mb-1.5"
                  >
                    {lang === 'bn' ? '৬ সংখ্যার OTP কোড লিখুন *' : 'Enter 6-Digit OTP Code *'}
                  </label>
                  <input
                    id="login-otp-code"
                    type="text"
                    inputMode="numeric"
                    maxLength={6}
                    required
                    value={otpCode}
                    onChange={(e) => setOtpCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                    placeholder="••••••"
                    className="w-full h-12 px-4 rounded-xl border border-slate-300 text-center text-lg font-mono-num font-bold tracking-[0.4em] text-slate-900 focus:outline-none focus:ring-2 focus:ring-[#0B5D2E]"
                  />
                </div>
                <button
                  type="submit"
                  disabled={loading}
                  className="w-full h-12 rounded-xl bg-[#0B5D2E] hover:bg-[#094A25] text-white font-semibold text-sm transition-colors disabled:opacity-60"
                >
                  {loading
                    ? t(lang, 'signingIn')
                    : lang === 'bn'
                      ? 'OTP যাচাই করে প্রবেশ করুন'
                      : 'Verify OTP & Enter Dashboard'}
                </button>
              </form>
            )}

            {/* STEP 2A: FORGOT PASSWORD OTP REQUEST */}
            {step === 'FORGOT_REQUEST' && (
              <form onSubmit={handleRequestForgotOtp} className="mt-5 space-y-4">
                <div>
                  <label
                    htmlFor="forgot-id"
                    className="block text-sm font-semibold text-slate-700 mb-1.5"
                  >
                    {lang === 'bn'
                      ? 'নিবন্ধিত মোবাইল নম্বর, জিমেইল অথবা User ID *'
                      : 'Registered Mobile Number, Gmail, or User ID *'}
                  </label>
                  <div className="relative">
                    <KeyRound className="h-4 w-4 text-slate-400 absolute left-3.5 top-1/2 -translate-y-1/2" />
                    <input
                      id="forgot-id"
                      type="text"
                      required
                      value={otpIdentifier}
                      onChange={(e) => setOtpIdentifier(e.target.value)}
                      placeholder="User ID / Gmail / Mobile"
                      className="w-full h-11 pl-10 pr-4 rounded-xl border border-slate-300 bg-white text-sm text-slate-900 focus:outline-none focus:ring-2 focus:ring-[#0B5D2E]"
                    />
                  </div>
                </div>
                  <button
                    type="submit"
                    disabled={loading}
                    className="w-full h-12 rounded-xl bg-[#0A3D91] hover:bg-[#083073] text-white font-semibold text-sm transition-colors disabled:opacity-60"
                  >
                    {loading
                      ? t(lang, 'signingIn')
                      : !browserOnline
                        ? lang === 'bn'
                          ? 'অফলাইনে সরাসরি সফটওয়্যারে প্রবেশ করুন'
                          : 'Enter Software Offline Directly'
                        : lang === 'bn'
                          ? 'মোবাইল / জিমেইলে রিসেট OTP পাঠান'
                          : 'Send Reset OTP to Mobile / Gmail'}
                  </button>
                </form>
              )}

            {/* STEP 3B: FORGOT PASSWORD VERIFY OTP & SET NEW PASSWORD */}
            {step === 'FORGOT_RESET' && otpChallenge && (
              <form onSubmit={handleCompleteForgotReset} className="space-y-4">
                {renderOtpDestinationBanner(otpChallenge)}

                {otpChallenge.accountUsername && (
                  <div className="text-xs text-slate-600 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2">
                    {lang === 'bn' ? 'অ্যাকাউন্ট:' : 'Account:'}{' '}
                    <strong className="font-mono-num text-[#0B5D2E]">
                      @{otpChallenge.accountUsername}
                    </strong>{' '}
                    ({otpChallenge.accountName})
                  </div>
                )}

                <div>
                  <label
                    htmlFor="forgot-otp-code"
                    className="block text-xs font-semibold text-slate-700 mb-1"
                  >
                    {lang === 'bn' ? '৬ সংখ্যার OTP কোড *' : '6-Digit OTP Code *'}
                  </label>
                  <input
                    id="forgot-otp-code"
                    type="text"
                    inputMode="numeric"
                    maxLength={6}
                    required
                    value={otpCode}
                    onChange={(e) => setOtpCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                    placeholder="••••••"
                    className="w-full h-11 px-4 rounded-xl border border-slate-300 text-center text-base font-mono-num font-bold tracking-[0.35em]"
                  />
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label
                      htmlFor="forgot-new-pass"
                      className="block text-xs font-semibold text-slate-700 mb-1"
                    >
                      {lang === 'bn' ? 'নতুন পাসওয়ার্ড (কমপক্ষে ৬ অক্ষর) *' : 'New Password (min 6) *'}
                    </label>
                    <div className="relative">
                      <input
                        id="forgot-new-pass"
                        type={showNewPass ? 'text' : 'password'}
                        required
                        minLength={6}
                        value={newPassword}
                        onChange={(e) => setNewPassword(e.target.value)}
                        className="w-full h-11 pl-3 pr-10 rounded-xl border border-slate-300 text-sm"
                      />
                      <button
                        type="button"
                        onClick={() => setShowNewPass((prev) => !prev)}
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 text-slate-500"
                      >
                        {showNewPass ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                      </button>
                    </div>
                  </div>
                  <div>
                    <label
                      htmlFor="forgot-confirm-pass"
                      className="block text-xs font-semibold text-slate-700 mb-1"
                    >
                      {lang === 'bn' ? 'পাসওয়ার্ড নিশ্চিত করুন *' : 'Confirm Password *'}
                    </label>
                    <input
                      id="forgot-confirm-pass"
                      type={showNewPass ? 'text' : 'password'}
                      required
                      minLength={6}
                      value={confirmPassword}
                      onChange={(e) => setConfirmPassword(e.target.value)}
                      className="w-full h-11 px-3 rounded-xl border border-slate-300 text-sm"
                    />
                  </div>
                </div>

                <button
                  type="submit"
                  disabled={loading}
                  className="w-full h-12 rounded-xl bg-[#0A3D91] hover:bg-[#083073] text-white font-semibold text-sm transition-colors disabled:opacity-60"
                >
                  {loading
                    ? t(lang, 'signingIn')
                    : lang === 'bn'
                      ? 'OTP যাচাই করে নতুন পাসওয়ার্ড সেভ করুন'
                      : 'Verify OTP & Save New Password'}
                </button>
              </form>
            )}
          </div>
        </div>
      </main>

      <footer className="py-5 text-center text-xs text-slate-500 px-4">
        <span>
          © {new Date().getFullYear()} {t(lang, 'orgName')} · Saidpur, Taki · {t(lang, 'systemTitle')}
        </span>
      </footer>

      <div id="skm-recaptcha-container" className="sr-only" />
    </div>
  );
}

import { useEffect, useState } from 'react';
import { CalendarRange, Download, MapPin, Phone, Printer, Receipt, User, X } from 'lucide-react';
import { apiFetch } from '../services/api';
import { fetchAndDownloadReceiptPdf } from '../services/exportUtils';
import {
  getCachedMembersSnapshot,
  getOfflineSnapshot,
  saveOfflineSnapshot,
} from '../services/offlineDb';
import { printMemberPaymentHistory, printReceiptByNumber } from '../services/printReceipt';
import { formatCurrency, t } from '../i18n/translations';
import { START_YEAR } from '../domain/membershipRules';
import type { Language, MemberProfileData } from '../types/app';

interface MemberProfileModalProps {
  lang: Language;
  memberId: number;
  onClose: () => void;
  onOpenReceipt: (receiptNumber: string) => void;
}

export function MemberProfileModal({
  lang,
  memberId,
  onClose,
  onOpenReceipt,
}: MemberProfileModalProps) {
  const [profile, setProfile] = useState<MemberProfileData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [yearScope, setYearScope] = useState<'NEAR' | 'ALL_2055'>('NEAR');

  useEffect(() => {
    let active = true;
    const loadProfile = async () => {
      setLoading(true);
      setError(null);
      const cached = await getOfflineSnapshot<MemberProfileData>(`member_profile:${memberId}`);
      if (typeof navigator !== 'undefined' && !navigator.onLine && cached) {
        if (active) {
          setProfile(cached);
          setLoading(false);
        }
        return;
      }

      try {
        const res = await apiFetch<MemberProfileData>(`/api/members/${memberId}`);
        await saveOfflineSnapshot(`member_profile:${memberId}`, res);
        if (active) setProfile(res);
      } catch (err) {
        if (cached) {
          if (active) setProfile(cached);
        } else {
          const allCachedMembers = await getCachedMembersSnapshot();
          const m = allCachedMembers.find((item) => item.id === memberId);
          if (m && active) {
            setProfile({
              member: {
                id: m.id,
                memberCode: m.memberCode,
                name: m.name,
                guardianName: m.guardianName,
                mobile: m.mobile,
                address: m.address,
                joiningDate: m.joiningDate,
                defaultAnnualFee: m.defaultAnnualFee,
                status: m.status,
                registrationDate: m.registrationDate,
                createdByName: m.createdByName,
              },
              schedules: [],
              yearlyLedger: [
                {
                  year: START_YEAR,
                  frozenAnnualFee: m.currentYearExpected || m.defaultAnnualFee,
                  paidTotal: m.currentYearPaid,
                  dueAmount: Math.max(0, (m.currentYearExpected || m.defaultAnnualFee) - m.currentYearPaid),
                  status: m.currentYearStatus,
                  isFutureYear: false,
                  isPersisted: true,
                },
              ],
              payments: [],
              pendingSummary: {
                currentYearPending: Math.max(
                  0,
                  (m.currentYearExpected || m.defaultAnnualFee) - m.currentYearPaid
                ),
                previousYearsPending: 0,
                totalOutstanding: m.totalOutstanding,
                overdueYears: m.totalOutstanding > 0 ? [START_YEAR] : [],
              },
              referenceYear: START_YEAR,
            });
          } else if (active) {
            setError(err instanceof Error ? err.message : 'Failed to load profile');
          }
        }
      } finally {
        if (active) setLoading(false);
      }
    };
    void loadProfile();
    return () => {
      active = false;
    };
  }, [memberId]);

  const displayedLedger = profile
    ? yearScope === 'NEAR'
      ? profile.yearlyLedger.filter((y) => y.year <= profile.referenceYear + 4)
      : profile.yearlyLedger
    : [];

  return (
    <div className="fixed inset-0 z-50 flex items-start sm:items-center justify-center bg-black/50 p-4 overflow-y-auto">
      <div className="w-full max-w-4xl rounded-2xl bg-white border border-slate-200 shadow-2xl overflow-hidden my-6 max-h-[90vh] flex flex-col">
        <div className="bg-[#0B5D2E] text-white px-6 py-4 flex items-center justify-between shrink-0">
          <div>
            <h2 className="text-lg font-bold">
              {profile ? profile.member.name : t(lang, 'loading')}
            </h2>
            {profile && (
              <p className="text-xs text-emerald-100 font-mono-num">
                {profile.member.memberCode} · {profile.member.status}
              </p>
            )}
          </div>
          <button
            type="button"
            aria-label="Close member profile"
            onClick={onClose}
            className="p-2 rounded-lg text-white/80 hover:text-white hover:bg-white/10"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        <div className="p-6 overflow-y-auto space-y-6">
          {loading ? (
            <p className="text-sm text-slate-500 py-8 text-center">{t(lang, 'loading')}</p>
          ) : error ? (
            <p className="text-sm text-[#DC2626] py-8 text-center">{error}</p>
          ) : profile ? (
            <>
              {/* Profile Details + Pending Summary */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="md:col-span-2 rounded-xl border border-slate-200 p-4 space-y-2 text-sm">
                  <div className="flex items-center gap-2 text-slate-700">
                    <User className="h-4 w-4 text-[#0B5D2E]" />
                    <span className="font-semibold">{t(lang, 'guardianName')}:</span>
                    <span>{profile.member.guardianName}</span>
                  </div>
                  <div className="flex items-center gap-2 text-slate-700">
                    <Phone className="h-4 w-4 text-[#0B5D2E]" />
                    <span className="font-semibold">{t(lang, 'mobile')}:</span>
                    <span className="font-mono-num">{profile.member.mobile}</span>
                  </div>
                  <div className="flex items-center gap-2 text-slate-700">
                    <MapPin className="h-4 w-4 text-[#0B5D2E]" />
                    <span className="font-semibold">{t(lang, 'address')}:</span>
                    <span>{profile.member.address}</span>
                  </div>
                  <div className="flex items-center gap-4 text-xs text-slate-500 pt-1">
                    <span>
                      {t(lang, 'joiningDate')}: <strong className="font-mono-num">{profile.member.joiningDate}</strong>
                    </span>
                    <span aria-hidden="true">·</span>
                    <span>
                      {t(lang, 'annualFee')}: <strong className="font-mono-num text-[#0B5D2E]">{formatCurrency(profile.member.defaultAnnualFee)}</strong>
                    </span>
                  </div>
                </div>

                <div className="rounded-xl border border-slate-200 bg-slate-50 p-4 flex flex-col justify-center">
                  <span className="text-xs font-semibold text-slate-500">
                    {t(lang, 'totalOutstanding')} ({lang === 'bn' ? 'বর্তমান পর্যন্ত' : `Up to ${profile.referenceYear}`})
                  </span>
                  <span className="mt-1 text-2xl font-bold text-[#DC2626] font-mono-num">
                    {formatCurrency(profile.pendingSummary.totalOutstanding)}
                  </span>
                  <div className="mt-2 text-xs text-slate-600 space-y-0.5 font-mono-num">
                    <div>
                      {t(lang, 'currentYearPending')}: {formatCurrency(profile.pendingSummary.currentYearPending)}
                    </div>
                    <div>
                      {t(lang, 'previousYearsPending')}: {formatCurrency(profile.pendingSummary.previousYearsPending)}
                    </div>
                  </div>
                </div>
              </div>

              {/* Automatic Multi-Year Ledger (2026 - 2055+) */}
              <div>
                <div className="flex items-center justify-between mb-3">
                  <h3 className="text-sm font-bold text-slate-900 flex items-center gap-2">
                    <CalendarRange className="h-4 w-4 text-[#0B5D2E]" />
                    <span>
                      {lang === 'bn'
                        ? 'স্বয়ংক্রিয় বাৎসরিক খতিয়ান (২০২৬ - ২০৫৫+)'
                        : 'Automatic Yearly Membership Ledger (2026 – 2055+)'}
                    </span>
                  </h3>
                  <div className="flex items-center gap-1 bg-slate-100 p-1 rounded-lg">
                    <button
                      type="button"
                      onClick={() => setYearScope('NEAR')}
                      className={`px-2.5 py-1 text-xs font-semibold rounded ${
                        yearScope === 'NEAR' ? 'bg-white text-slate-900 shadow-xs' : 'text-slate-600'
                      }`}
                    >
                      {profile.yearlyLedger[0]?.year}–{profile.referenceYear + 4}
                    </button>
                    <button
                      type="button"
                      onClick={() => setYearScope('ALL_2055')}
                      className={`px-2.5 py-1 text-xs font-semibold rounded ${
                        yearScope === 'ALL_2055' ? 'bg-white text-slate-900 shadow-xs' : 'text-slate-600'
                      }`}
                    >
                      2026–2055
                    </button>
                  </div>
                </div>

                <div className="overflow-x-auto border border-slate-200 rounded-xl">
                  <table className="w-full text-left border-collapse text-xs">
                    <thead>
                      <tr className="bg-slate-50 border-b border-slate-200 text-slate-600 font-semibold">
                        <th className="py-2.5 px-3">{t(lang, 'paymentYear')}</th>
                        <th className="py-2.5 px-3 text-right">{t(lang, 'expectedFee')}</th>
                        <th className="py-2.5 px-3 text-right">{t(lang, 'paidAmount')}</th>
                        <th className="py-2.5 px-3 text-right">{t(lang, 'dueAmount')}</th>
                        <th className="py-2.5 px-3">{t(lang, 'status')}</th>
                        <th className="py-2.5 px-3 text-right">{lang === 'bn' ? 'রসিদ' : 'Receipt'}</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {displayedLedger.map((row) => {
                        const yearPayment = profile.payments.find(
                          (p) => !p.isVoided && p.paymentYear === row.year
                        );
                        return (
                          <tr key={row.year} className="hover:bg-slate-50">
                            <td className="py-2.5 px-3 font-mono-num font-bold text-slate-900">
                              {row.year}
                              {row.isFutureYear && (
                                <span className="ml-2 text-[11px] font-normal text-slate-400">
                                  ({lang === 'bn' ? 'ভবিষ্যৎ' : 'Upcoming'})
                                </span>
                              )}
                            </td>
                            <td className="py-2.5 px-3 text-right font-mono-num">
                              {formatCurrency(row.frozenAnnualFee)}
                            </td>
                            <td className="py-2.5 px-3 text-right font-mono-num text-[#16A34A] font-semibold">
                              {formatCurrency(row.paidTotal)}
                            </td>
                            <td className="py-2.5 px-3 text-right font-mono-num font-semibold">
                              {formatCurrency(row.dueAmount)}
                            </td>
                            <td className="py-2.5 px-3">
                              <span
                                className={`font-bold ${
                                  row.status === 'PAID'
                                    ? 'text-[#16A34A]'
                                    : row.status === 'PARTIAL'
                                      ? 'text-amber-700'
                                      : row.isFutureYear
                                        ? 'text-slate-400'
                                        : 'text-[#DC2626]'
                                }`}
                              >
                                {row.status === 'PAID'
                                  ? t(lang, 'paid')
                                  : row.status === 'PARTIAL'
                                    ? t(lang, 'partial')
                                    : row.isFutureYear
                                      ? lang === 'bn'
                                        ? 'নির্ধারিত'
                                        : 'Scheduled'
                                      : t(lang, 'unpaid')}
                              </span>
                            </td>
                            <td className="py-2.5 px-3 text-right">
                              {yearPayment ? (
                                <div className="inline-flex items-center gap-1">
                                  <button
                                    type="button"
                                    onClick={() => onOpenReceipt(yearPayment.receiptNumber)}
                                    className="inline-flex items-center gap-1 rounded border border-emerald-200 bg-emerald-50 px-2 py-1 font-semibold text-[#0B5D2E] hover:bg-emerald-100"
                                  >
                                    <Receipt className="h-3 w-3" />
                                    <span>{lang === 'bn' ? 'রসিদ' : 'View'}</span>
                                  </button>
                                  <button
                                    type="button"
                                    onClick={() => {
                                      void printReceiptByNumber(yearPayment.receiptNumber, lang).catch((err) =>
                                        setError(err instanceof Error ? err.message : 'Print failed.')
                                      );
                                    }}
                                    className="inline-flex items-center gap-1 rounded border border-emerald-200 bg-white px-2 py-1 font-semibold text-[#0B5D2E] hover:bg-emerald-50"
                                  >
                                    <Printer className="h-3 w-3" />
                                    <span>{lang === 'bn' ? 'প্রিন্ট' : 'Print'}</span>
                                  </button>
                                  <button
                                    type="button"
                                    onClick={() => {
                                      fetchAndDownloadReceiptPdf(yearPayment.receiptNumber).catch((err) =>
                                        setError(err instanceof Error ? err.message : 'PDF download failed.')
                                      );
                                    }}
                                    className="inline-flex items-center gap-1 rounded border border-blue-200 bg-blue-50 px-2 py-1 font-semibold text-[#0A3D91] hover:bg-blue-100"
                                  >
                                    <Download className="h-3 w-3" />
                                    <span>PDF</span>
                                  </button>
                                </div>
                              ) : (
                                <span className="text-slate-300">—</span>
                              )}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Payment History */}
              <div>
                <div className="flex flex-wrap items-center justify-between gap-2 mb-3">
                  <h3 className="text-sm font-bold text-slate-900">
                    {lang === 'bn' ? 'সম্পূর্ণ পেমেন্ট ইতিহাস' : 'Complete Payment History'}
                  </h3>
                  <button
                    type="button"
                    onClick={() => {
                      if (profile) {
                        void printMemberPaymentHistory(profile, lang).catch((err) =>
                          setError(err instanceof Error ? err.message : 'Failed to print history.')
                        );
                      }
                    }}
                    className="inline-flex items-center gap-1.5 rounded-lg bg-[#0B5D2E] hover:bg-[#094A25] text-white px-3 py-1.5 text-xs font-semibold"
                  >
                    <Printer className="h-3.5 w-3.5" />
                    <span>{lang === 'bn' ? 'সম্পূর্ণ হিস্ট্রি প্রিন্ট করুন' : 'Print Payment History'}</span>
                  </button>
                </div>
                {profile.payments.length === 0 ? (
                  <p className="text-sm text-slate-500">{t(lang, 'noRecords')}</p>
                ) : (
                  <div className="overflow-x-auto border border-slate-200 rounded-xl">
                    <table className="w-full text-left border-collapse text-xs">
                      <thead>
                        <tr className="bg-slate-50 border-b border-slate-200 text-slate-600 font-semibold">
                          <th className="py-2.5 px-3">{t(lang, 'receiptNo')}</th>
                          <th className="py-2.5 px-3">{t(lang, 'paymentYear')}</th>
                          <th className="py-2.5 px-3">{lang === 'bn' ? 'তারিখ ও সময়' : 'Date & Time'}</th>
                          <th className="py-2.5 px-3">{t(lang, 'paymentMethod')}</th>
                          <th className="py-2.5 px-3 text-right">{t(lang, 'paidAmount')}</th>
                          <th className="py-2.5 px-3 text-right">{t(lang, 'dueAmount')}</th>
                          <th className="py-2.5 px-3 text-right">{lang === 'bn' ? 'রসিদ ও প্রিন্ট' : 'Receipt & Print'}</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {profile.payments.map((p) => (
                          <tr key={p.id}>
                            <td className="py-2.5 px-3 font-mono-num font-semibold text-[#0A3D91]">
                              {p.receiptNumber}
                            </td>
                            <td className="py-2.5 px-3 font-mono-num">{p.paymentYear}</td>
                            <td className="py-2.5 px-3 font-mono-num">
                              {p.paymentDate} {p.paymentTime}
                            </td>
                            <td className="py-2.5 px-3">{p.paymentMethod}</td>
                            <td className="py-2.5 px-3 text-right font-mono-num font-bold text-[#16A34A]">
                              {formatCurrency(p.paidAmount)}
                            </td>
                            <td className="py-2.5 px-3 text-right font-mono-num">
                              {formatCurrency(p.dueAfterPayment)}
                            </td>
                            <td className="py-2.5 px-3 text-right">
                              <div className="inline-flex items-center gap-1">
                                <button
                                  type="button"
                                  onClick={() => onOpenReceipt(p.receiptNumber)}
                                  className="inline-flex items-center gap-1 rounded border border-slate-200 px-2 py-1 font-semibold text-slate-700 hover:bg-slate-100"
                                >
                                  <Receipt className="h-3.5 w-3.5 text-[#0B5D2E]" />
                                  <span>{lang === 'bn' ? 'রসিদ' : 'View'}</span>
                                </button>
                                <button
                                  type="button"
                                  onClick={() => {
                                    void printReceiptByNumber(p.receiptNumber, lang).catch((err) =>
                                      setError(err instanceof Error ? err.message : 'Print failed.')
                                    );
                                  }}
                                  className="inline-flex items-center gap-1 rounded border border-emerald-200 bg-emerald-50 px-2 py-1 font-semibold text-[#0B5D2E] hover:bg-emerald-100"
                                >
                                  <Printer className="h-3.5 w-3.5" />
                                  <span>{lang === 'bn' ? 'প্রিন্ট' : 'Print'}</span>
                                </button>
                                <button
                                  type="button"
                                  onClick={() => {
                                    fetchAndDownloadReceiptPdf(p.receiptNumber).catch((err) =>
                                      setError(err instanceof Error ? err.message : 'PDF download failed.')
                                    );
                                  }}
                                  className="inline-flex items-center gap-1 rounded border border-blue-200 bg-blue-50 px-2 py-1 font-semibold text-[#0A3D91] hover:bg-blue-100"
                                >
                                  <Download className="h-3.5 w-3.5" />
                                  <span>PDF</span>
                                </button>
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            </>
          ) : null}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState, type FormEvent } from 'react';
import {
  AlertTriangle,
  Download,
  Edit3,
  Eye,
  Plus,
  Receipt,
  Search,
  Trash2,
  UserPlus,
  Wallet,
  X,
} from 'lucide-react';
import { apiFetch } from '../services/api';
import { fetchAndDownloadReceiptPdf } from '../services/exportUtils';
import {
  cacheMembersSnapshot,
  enqueueAdminOfflineItem,
  getAdminOfflineQueue,
  getCachedMembersSnapshot,
} from '../services/offlineDb';
import { mergeMembersWithOfflineQueue } from '../services/offlineOverlay';
import { formatCurrency, t } from '../i18n/translations';
import { START_YEAR } from '../domain/membershipRules';
import type { AuthUser, Language, MemberListItem } from '../types/app';

interface MembersViewProps {
  lang: Language;
  user: AuthUser;
  selectedYear: number;
  isOfflineMode: boolean;
  onRefreshOfflineCount: () => void;
  onViewProfile: (memberId: number) => void;
  onOpenReceipt: (receiptNumber: string) => void;
  onQuickCollect: (memberId: number) => void;
}

export function MembersView({
  lang,
  user,
  selectedYear,
  isOfflineMode,
  onRefreshOfflineCount,
  onViewProfile,
  onOpenReceipt,
  onQuickCollect,
}: MembersViewProps) {
  const [membersList, setMembersList] = useState<MemberListItem[]>([]);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<'ALL' | 'ACTIVE' | 'INACTIVE'>('ALL');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const [showAddModal, setShowAddModal] = useState(false);
  const [editingMember, setEditingMember] = useState<MemberListItem | null>(null);
  const [deletingMember, setDeletingMember] = useState<MemberListItem | null>(null);
  const [deleting, setDeleting] = useState(false);

  // Form states
  const [formName, setFormName] = useState('');
  const [formGuardian, setFormGuardian] = useState('');
  const [formMobile, setFormMobile] = useState('');
  const [formAddress, setFormAddress] = useState('');
  const [formJoiningDate, setFormJoiningDate] = useState('2026-01-01');
  const [formAnnualFee, setFormAnnualFee] = useState('1200');
  const [formStatus, setFormStatus] = useState<'ACTIVE' | 'INACTIVE'>('ACTIVE');
  const [formEffYear, setFormEffYear] = useState(String(selectedYear));
  const [saving, setSaving] = useState(false);

  const canCreate = user.roleName === 'ADMIN';
  const canEdit = user.roleName === 'ADMIN' || user.permissions.includes('members:edit');
  const canDelete = user.roleName === 'ADMIN';
  const canPay = user.roleName === 'ADMIN' || user.permissions.includes('payments:create');

  const adjustAnnualFee = (delta: number) => {
    const current = Number(formAnnualFee) || 0;
    const next = Math.max(1, Math.round((current + delta) * 100) / 100);
    setFormAnnualFee(String(next));
  };

  const applyCachedWithQueue = async () => {
    const [cached, queue] = await Promise.all([
      getCachedMembersSnapshot(),
      getAdminOfflineQueue(),
    ]);
    const merged = mergeMembersWithOfflineQueue(cached, queue, selectedYear, user.fullName);
    const q = search.toLowerCase();
    return merged.filter((m) => {
      const matchesQ =
        !q ||
        m.memberCode.toLowerCase().includes(q) ||
        m.name.toLowerCase().includes(q) ||
        m.mobile.includes(q);
      const matchesStatus = statusFilter === 'ALL' || m.status === statusFilter;
      return matchesQ && matchesStatus;
    });
  };

  const loadMembers = async () => {
    setLoading(true);
    setError(null);
    if (isOfflineMode) {
      const offlineRows = await applyCachedWithQueue();
      setMembersList(offlineRows);
      setLoading(false);
      return;
    }

    try {
      const res = await apiFetch<{ members: MemberListItem[] }>(
        `/api/members?q=${encodeURIComponent(search)}&status=${statusFilter}&year=${selectedYear}`
      );
      setMembersList(res.members);
      if (!search && statusFilter === 'ALL') {
        await cacheMembersSnapshot(res.members);
      }
    } catch (err) {
      // Fallback to cached snapshot if offline or unreachable
      const offlineRows = await applyCachedWithQueue();
      if (offlineRows.length > 0 || user.roleName === 'ADMIN') {
        setMembersList(offlineRows);
      } else {
        setError(err instanceof Error ? err.message : 'Failed to load members.');
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const timer = setTimeout(() => {
      loadMembers();
    }, 150);
    return () => clearTimeout(timer);
  }, [search, statusFilter, selectedYear]);

  const openAdd = () => {
    setFormName('');
    setFormGuardian('');
    setFormMobile('');
    setFormAddress('');
    setFormJoiningDate(`${Math.max(START_YEAR, selectedYear)}-01-01`);
    setFormAnnualFee('1200');
    setFormStatus('ACTIVE');
    setShowAddModal(true);
  };

  const openEdit = (m: MemberListItem) => {
    setEditingMember(m);
    setFormName(m.name);
    setFormGuardian(m.guardianName);
    setFormMobile(m.mobile);
    setFormAddress(m.address);
    setFormAnnualFee(String(m.defaultAnnualFee));
    setFormStatus(m.status);
    setFormEffYear(String(Math.max(START_YEAR, selectedYear)));
  };

  const handleCreateSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setError(null);
    setNotice(null);

    const payload = {
      name: formName.trim(),
      guardianName: formGuardian.trim(),
      mobile: formMobile.trim(),
      address: formAddress.trim(),
      joiningDate: formJoiningDate,
      defaultAnnualFee: Number(formAnnualFee),
      status: formStatus,
      clientOfflineId: `offline-mem-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    };

    const shouldEnqueueOffline = () => isOfflineMode || (typeof navigator !== 'undefined' && !navigator.onLine);
    const isNetworkErr = (err: unknown) =>
      err instanceof TypeError ||
      (err instanceof Error && /failed to fetch|networkerror|load failed/i.test(err.message));

    const queueMemberCreate = async () => {
      if (user.roleName !== 'ADMIN') {
        throw new Error('Only Admin devices may create offline entries.');
      }
      await enqueueAdminOfflineItem({
        clientTxId: payload.clientOfflineId,
        operationType: 'CREATE_MEMBER',
        payload,
        summary: `Register Member: ${payload.name} (Fee ₹${payload.defaultAnnualFee})`,
        createdOfflineAt: new Date().toISOString(),
        syncStatus: 'UNSYNCED',
      });
      onRefreshOfflineCount();
      setShowAddModal(false);
      setNotice(
        lang === 'bn'
          ? 'অফলাইন কিউতে সদস্য সংরক্ষিত হয়েছে (অনলাইন হলে স্বয়ংক্রিয় সিঙ্ক হবে)।'
          : 'Member saved to Admin offline queue (auto-syncs when online).'
      );
      await loadMembers();
    };

    try {
      if (shouldEnqueueOffline()) {
        await queueMemberCreate();
        return;
      }

      await apiFetch('/api/members', {
        method: 'POST',
        body: JSON.stringify(payload),
      });
      setShowAddModal(false);
      setNotice(lang === 'bn' ? 'নতুন সদস্য সফলভাবে নিবন্ধিত হয়েছে।' : 'New member registered.');
      await loadMembers();
    } catch (err) {
      if (user.roleName === 'ADMIN' && isNetworkErr(err)) {
        await queueMemberCreate();
      } else {
        setError(err instanceof Error ? err.message : 'Failed to register member.');
      }
    } finally {
      setSaving(false);
    }
  };

  const handleEditSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!editingMember) return;
    setSaving(true);
    setError(null);
    setNotice(null);

    const editPayload: Record<string, unknown> = {
      name: formName.trim(),
      guardianName: formGuardian.trim(),
      mobile: formMobile.trim(),
      address: formAddress.trim(),
      ...(user.roleName === 'ADMIN' ? { status: formStatus } : {}),
      newAnnualFee: Number(formAnnualFee),
      effectiveFromYear: Number(formEffYear),
    };

    const queueMemberEdit = async () => {
      if (user.roleName !== 'ADMIN') {
        throw new Error('Only Admin devices may edit members offline.');
      }
      const clientTxId = `offline-edit-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      await enqueueAdminOfflineItem({
        clientTxId,
        operationType: 'UPDATE_MEMBER',
        payload: {
          ...editPayload,
          memberId: editingMember.id,
          memberTempClientOfflineId: editingMember.tempClientOfflineId,
          memberCodeSnapshot: editingMember.memberCode,
        },
        summary: `Edit Member: ${editPayload.name} (${editingMember.memberCode})`,
        createdOfflineAt: new Date().toISOString(),
        syncStatus: 'UNSYNCED',
      });
      onRefreshOfflineCount();
      setEditingMember(null);
      setNotice(
        lang === 'bn'
          ? 'সদস্যের পরিবর্তিত তথ্য অফলাইন কিউতে সেভ হয়েছে (অনলাইন হলে অটো সিঙ্ক হবে)।'
          : 'Member edits saved offline (auto-syncs when online).'
      );
      await loadMembers();
    };

    const isNetworkErr = (err: unknown) =>
      err instanceof TypeError ||
      (err instanceof Error && /failed to fetch|networkerror|load failed/i.test(err.message));

    try {
      if (isOfflineMode || editingMember.id < 0 || (typeof navigator !== 'undefined' && !navigator.onLine)) {
        await queueMemberEdit();
        return;
      }

      await apiFetch(`/api/members/${editingMember.id}`, {
        method: 'PUT',
        body: JSON.stringify(editPayload),
      });
      setEditingMember(null);
      setNotice(
        lang === 'bn'
          ? 'সদস্যের তথ্য ও ভবিষ্যৎ ফি হালনাগাদ হয়েছে (পূর্বের বছরের ফি অপরিবর্তিত)।'
          : 'Member updated. Future fee schedule applied without altering historical fees.'
      );
      await loadMembers();
    } catch (err) {
      if (user.roleName === 'ADMIN' && isNetworkErr(err)) {
        await queueMemberEdit();
      } else {
        setError(err instanceof Error ? err.message : 'Failed to update member.');
      }
    } finally {
      setSaving(false);
    }
  };

  const handleConfirmDelete = async () => {
    if (!deletingMember) return;
    setDeleting(true);
    setError(null);
    setNotice(null);

    const removedName = deletingMember.name;
    const removedCode = deletingMember.memberCode;

    const queueMemberDelete = async () => {
      if (user.roleName !== 'ADMIN') {
        throw new Error('Only Admin devices may delete members offline.');
      }
      const clientTxId = `offline-del-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      await enqueueAdminOfflineItem({
        clientTxId,
        operationType: 'DELETE_MEMBER',
        payload: {
          memberId: deletingMember.id,
          memberTempClientOfflineId: deletingMember.tempClientOfflineId,
          memberCodeSnapshot: removedCode,
          memberNameSnapshot: removedName,
          memberStatusSnapshot: deletingMember.status,
        },
        summary: `Delete Member: ${removedName} (${removedCode})`,
        createdOfflineAt: new Date().toISOString(),
        syncStatus: 'UNSYNCED',
      });
      onRefreshOfflineCount();
      setDeletingMember(null);
      setNotice(
        lang === 'bn'
          ? `সদস্য ${removedName} (${removedCode}) অফলাইনে মুছে ফেলা হয়েছে (অনলাইন হলে সার্ভার থেকেও মুছে যাবে)।`
          : `Member ${removedName} (${removedCode}) deleted offline (auto-syncs to server when online).`
      );
      await loadMembers();
    };

    const isNetworkErr = (err: unknown) =>
      err instanceof TypeError ||
      (err instanceof Error && /failed to fetch|networkerror|load failed/i.test(err.message));

    try {
      if (isOfflineMode || deletingMember.id < 0 || (typeof navigator !== 'undefined' && !navigator.onLine)) {
        await queueMemberDelete();
        return;
      }

      await apiFetch(`/api/members/${deletingMember.id}`, { method: 'DELETE' });
      setDeletingMember(null);
      setNotice(
        lang === 'bn'
          ? `সদস্য ${removedName} (${removedCode}) সফলভাবে মুছে ফেলা হয়েছে।`
          : `Member ${removedName} (${removedCode}) deleted.`
      );
      await loadMembers();
    } catch (err) {
      if (user.roleName === 'ADMIN' && isNetworkErr(err)) {
        await queueMemberDelete();
      } else {
        setError(err instanceof Error ? err.message : 'Failed to delete member.');
        setDeletingMember(null);
      }
    } finally {
      setDeleting(false);
    }
  };

  return (
    <div className="space-y-5">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-slate-900">{t(lang, 'members')}</h1>
          <p className="text-sm text-slate-500 mt-0.5">
            {lang === 'bn'
              ? 'প্রতিটি সদস্যের স্বতন্ত্র বার্ষিক ফি ও আইডি ব্যবস্থাপনা'
              : 'Individual annual fee profiles · Automatic SKM IDs'}
          </p>
        </div>

        {canCreate && (
          <button
            type="button"
            onClick={openAdd}
            className="inline-flex items-center justify-center gap-2 rounded-xl bg-[#0B5D2E] hover:bg-[#094A25] text-white px-4 h-11 text-sm font-semibold transition-colors whitespace-nowrap shrink-0"
          >
            <UserPlus className="h-4 w-4" />
            <span>{t(lang, 'addMember')}</span>
          </button>
        )}
      </div>

      {notice && (
        <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-[#0B5D2E]">
          {notice}
        </div>
      )}
      {error && (
        <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-[#DC2626]">
          {error}
        </div>
      )}

      {/* Search & Filter Toolbar */}
      <div className="flex flex-col md:flex-row gap-3 items-stretch md:items-center justify-between bg-white border border-slate-200 rounded-xl p-3">
        <div className="relative flex-1">
          <Search className="h-4 w-4 text-slate-400 absolute left-3.5 top-1/2 -translate-y-1/2" />
          <input
            type="search"
            aria-label={t(lang, 'searchPlaceholder')}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder={t(lang, 'searchPlaceholder')}
            className="w-full h-11 pl-10 pr-4 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#0B5D2E]"
          />
        </div>

        <div className="flex items-center gap-1 p-1 bg-slate-100 rounded-lg shrink-0">
          {(['ALL', 'ACTIVE', 'INACTIVE'] as const).map((st) => (
            <button
              key={st}
              type="button"
              onClick={() => setStatusFilter(st)}
              className={`px-3 py-2 text-xs font-semibold rounded-md transition-colors whitespace-nowrap ${
                statusFilter === st
                  ? 'bg-white text-slate-900 shadow-xs'
                  : 'text-slate-600 hover:text-slate-900'
              }`}
            >
              {st === 'ALL'
                ? lang === 'bn'
                  ? 'সকল'
                  : 'All'
                : st === 'ACTIVE'
                  ? t(lang, 'active')
                  : t(lang, 'inactive')}
            </button>
          ))}
        </div>
      </div>

      {/* Members Table */}
      <div className="rounded-xl bg-white border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="border-b border-slate-200 bg-slate-50 text-xs font-semibold text-slate-600">
                <th className="py-3 px-4">{t(lang, 'memberId')}</th>
                <th className="py-3 px-4">{t(lang, 'memberName')}</th>
                <th className="py-3 px-4">{t(lang, 'mobile')}</th>
                <th className="py-3 px-4 text-right">{t(lang, 'annualFee')}</th>
                <th className="py-3 px-4">{selectedYear} {t(lang, 'status')}</th>
                <th className="py-3 px-4 text-right">{t(lang, 'totalOutstanding')}</th>
                <th className="py-3 px-4 text-right">{lang === 'bn' ? 'কার্যক্রম' : 'Actions'}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-sm">
              {loading ? (
                <tr>
                  <td colSpan={7} className="py-10 text-center text-slate-500">
                    {t(lang, 'loading')}
                  </td>
                </tr>
              ) : membersList.length === 0 ? (
                <tr>
                  <td colSpan={7} className="py-10 text-center text-slate-500">
                    {t(lang, 'noRecords')}
                  </td>
                </tr>
              ) : (
                membersList.map((m) => (
                  <tr key={m.id} className="hover:bg-slate-50/80">
                    <td className="py-3 px-4 font-mono-num text-xs font-bold text-[#0B5D2E]">
                      {m.memberCode}
                    </td>
                    <td className="py-3 px-4">
                      <div className="font-semibold text-slate-900">{m.name}</div>
                      <div className="text-xs text-slate-500">
                        {m.guardianName} · {m.status === 'ACTIVE' ? t(lang, 'active') : t(lang, 'inactive')}
                      </div>
                    </td>
                    <td className="py-3 px-4 font-mono-num text-slate-700">{m.mobile}</td>
                    <td className="py-3 px-4 text-right font-mono-num font-bold text-slate-900">
                      {formatCurrency(m.defaultAnnualFee)}
                    </td>
                    <td className="py-3 px-4">
                      <span
                        className={`text-xs font-bold ${
                          m.currentYearStatus === 'PAID'
                            ? 'text-[#16A34A]'
                            : m.currentYearStatus === 'PARTIAL'
                              ? 'text-amber-700'
                              : 'text-[#DC2626]'
                        }`}
                      >
                        {m.currentYearStatus === 'PAID'
                          ? t(lang, 'paid')
                          : m.currentYearStatus === 'PARTIAL'
                            ? t(lang, 'partial')
                            : t(lang, 'unpaid')}
                      </span>
                    </td>
                    <td className="py-3 px-4 text-right font-mono-num font-bold text-[#DC2626]">
                      {formatCurrency(m.totalOutstanding)}
                    </td>
                    <td className="py-3 px-4">
                      <div className="flex items-center justify-end gap-1.5">
                        {(() => {
                          const targetReceipt = m.currentYearReceiptNumber || m.latestReceiptNumber;
                          return targetReceipt && (!isOfflineMode || targetReceipt.startsWith('OFF-')) ? (
                            <>
                              <button
                                type="button"
                                onClick={() => onOpenReceipt(targetReceipt)}
                                aria-label={`View receipt for ${m.name}`}
                                title={
                                  lang === 'bn'
