import { useEffect, useState, type ChangeEvent, type FormEvent } from 'react';
import {
  CheckCircle2,
  Download,
  Edit3,
  Eye,
  EyeOff,
  FileUp,
  ImagePlus,
  Megaphone,
  Pin,
  PinOff,
  Trash2,
  X,
} from 'lucide-react';
import { apiFetch } from '../services/api';
import {
  enqueueAdminOfflineItem,
  getAdminOfflineQueue,
  getOfflineSnapshot,
  saveOfflineSnapshot,
} from '../services/offlineDb';
import { mergeNoticesWithOfflineQueue } from '../services/offlineOverlay';
import { downloadNoticeAttachmentBlob } from './PublicNoticeBoard';
import type { AuthUser, Language, PublicNoticeItem } from '../types/app';

interface NoticePostsViewProps {
  lang: Language;
  user?: AuthUser;
  isOfflineMode?: boolean;
  onRefreshOfflineCount?: () => void;
  refreshTick?: number;
}

const MAX_IMAGE_BYTES = 5 * 1024 * 1024;
const MAX_ATTACHMENT_BYTES = 8 * 1024 * 1024;
const ADMIN_NOTICES_CACHE_KEY = 'admin:notices';
const PUBLIC_NOTICES_CACHE_KEY = 'public:notices';

function readFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ''));
    reader.onerror = () => reject(new Error('Failed to read selected file.'));
    reader.readAsDataURL(file);
  });
}

function isNetworkError(err: unknown): boolean {
  return (
    err instanceof TypeError ||
    (err instanceof Error && /failed to fetch|networkerror|load failed/i.test(err.message))
  );
}

export function NoticePostsView({
  lang,
  user,
  isOfflineMode = false,
  onRefreshOfflineCount,
  refreshTick = 0,
}: NoticePostsViewProps) {
  const [notices, setNotices] = useState<PublicNoticeItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  // Create / Edit Form states
  const [editingItem, setEditingItem] = useState<PublicNoticeItem | null>(null);
  const editingId = editingItem?.id ?? null;
  const [noticeType, setNoticeType] = useState<'NOTICE' | 'PUBLIC_POST' | 'EVENT'>('NOTICE');
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [isPinned, setIsPinned] = useState(true);
  const [isPublished, setIsPublished] = useState(true);

  const [imageDataUrl, setImageDataUrl] = useState<string | null>(null);
  const [imageChanged, setImageChanged] = useState(false);

  const [attachmentDataUrl, setAttachmentDataUrl] = useState<string | null>(null);
  const [attachmentName, setAttachmentName] = useState<string | null>(null);
  const [attachmentMime, setAttachmentMime] = useState<string | null>(null);
  const [attachmentChanged, setAttachmentChanged] = useState(false);

  const actorName = user?.fullName || 'Farhan Gazi Admin';

  const loadOfflineMerged = async () => {
    const [cachedAdmin, cachedPublic, queue] = await Promise.all([
      getOfflineSnapshot<PublicNoticeItem[]>(ADMIN_NOTICES_CACHE_KEY),
      getOfflineSnapshot<PublicNoticeItem[]>(PUBLIC_NOTICES_CACHE_KEY),
      getAdminOfflineQueue(),
    ]);
    const base = cachedAdmin || cachedPublic || [];
    const mergedAdmin = mergeNoticesWithOfflineQueue(base, queue, actorName);
    const mergedPublic = mergeNoticesWithOfflineQueue(base, queue, actorName, { publicOnly: true });
    await saveOfflineSnapshot(PUBLIC_NOTICES_CACHE_KEY, mergedPublic);
    return mergedAdmin;
  };

  const loadAdminNotices = async () => {
    setLoading(true);
    setError(null);
    if (isOfflineMode || (typeof navigator !== 'undefined' && !navigator.onLine)) {
      const merged = await loadOfflineMerged();
      setNotices(merged);
      setLoading(false);
      return;
    }
    try {
      const res = await apiFetch<{ items: PublicNoticeItem[] }>('/api/admin/notices');
      const items = res.items || [];
      const queue = await getAdminOfflineQueue();
      const merged = mergeNoticesWithOfflineQueue(items, queue, actorName);
      setNotices(merged);
      await saveOfflineSnapshot(ADMIN_NOTICES_CACHE_KEY, items);
      const publishedSorted = [...items]
        .filter((n) => n.isPublished)
        .sort(
          (a, b) =>
            Number(b.isPinned) - Number(a.isPinned) || b.createdAt.localeCompare(a.createdAt) || b.id - a.id
        );
      await saveOfflineSnapshot(PUBLIC_NOTICES_CACHE_KEY, publishedSorted);
    } catch (err) {
      if (isNetworkError(err)) {
        const merged = await loadOfflineMerged();
        setNotices(merged);
      } else {
        setError(err instanceof Error ? err.message : 'Failed to load notices.');
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadAdminNotices();
  }, [isOfflineMode, refreshTick]);

  const resetForm = () => {
    setEditingItem(null);
    setNoticeType('NOTICE');
    setTitle('');
    setContent('');
    setIsPinned(true);
    setIsPublished(true);
    setImageDataUrl(null);
    setImageChanged(false);
    setAttachmentDataUrl(null);
    setAttachmentName(null);
    setAttachmentMime(null);
    setAttachmentChanged(false);
  };

  const handleImagePick = async (e: ChangeEvent<HTMLInputElement>) => {
    setError(null);
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file) return;
    if (!file.type.startsWith('image/')) {
      setError(lang === 'bn' ? 'শুধুমাত্র ছবির ফাইল (JPG/PNG/WebP) নির্বাচন করুন।' : 'Please choose a valid image file.');
      return;
    }
    if (file.size > MAX_IMAGE_BYTES) {
      setError(lang === 'bn' ? 'ছবির সাইজ সর্বোচ্চ ৫ MB হতে পারবে।' : 'Image file must be under 5 MB.');
      return;
    }
    try {
      const dataUrl = await readFileAsDataUrl(file);
      setImageDataUrl(dataUrl);
      setImageChanged(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Could not load image.');
    }
  };

  const handleAttachmentPick = async (e: ChangeEvent<HTMLInputElement>) => {
    setError(null);
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file) return;
    if (file.size > MAX_ATTACHMENT_BYTES) {
      setError(lang === 'bn' ? 'ফাইলের সাইজ সর্বোচ্চ ৮ MB হতে পারবে।' : 'Attachment file must be under 8 MB.');
      return;
    }
    try {
      const dataUrl = await readFileAsDataUrl(file);
      setAttachmentDataUrl(dataUrl);
      setAttachmentName(file.name);
      setAttachmentMime(file.type || 'application/octet-stream');
      setAttachmentChanged(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Could not read attachment file.');
    }
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccess(null);
    if (!title.trim() || !content.trim()) {
      setError(lang === 'bn' ? 'নোটিশের শিরোনাম এবং বিস্তারিত লেখা আবশ্যক।' : 'Title and content are required.');
      return;
    }

    const useOffline =
      isOfflineMode ||
      (typeof navigator !== 'undefined' && !navigator.onLine) ||
      Boolean(editingItem && editingItem.id < 0);

    const queueCreateOrUpdateOffline = async () => {
      if (editingItem) {
        const body: Record<string, unknown> = {
          noticeId: editingItem.id,
          noticeTempClientOfflineId: editingItem.tempClientOfflineId,
          title: title.trim(),
          content: content.trim(),
          noticeType,
          isPinned,
          isPublished,
        };
        if (imageChanged) body.imageDataUrl = imageDataUrl;
        if (attachmentChanged) {
          body.attachmentDataUrl = attachmentDataUrl;
          body.attachmentName = attachmentName;
          body.attachmentMime = attachmentMime;
        }
        await enqueueAdminOfflineItem({
          clientTxId: `offline-notice-edit-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
          operationType: 'UPDATE_NOTICE',
          payload: body,
          summary: `Edit Notice: ${title.trim()}`,
          createdOfflineAt: new Date().toISOString(),
          syncStatus: 'UNSYNCED',
        });
        setSuccess(
          lang === 'bn'
            ? 'নোটিশের পরিবর্তন অফলাইনে সংরক্ষিত হয়েছে — ইন্টারনেট এলেই অনলাইনে আপডেট হবে।'
            : 'Notice update queued offline — will sync online automatically.'
        );
      } else {
        const clientTxId = `offline-notice-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
        await enqueueAdminOfflineItem({
          clientTxId,
          operationType: 'CREATE_NOTICE',
          payload: {
            title: title.trim(),
            content: content.trim(),
            noticeType,
            isPinned,
            isPublished,
            imageDataUrl,
            attachmentDataUrl,
            attachmentName,
            attachmentMime,
            createdAt: new Date().toISOString(),
            clientOfflineId: clientTxId,
          },
          summary: `Publish Notice: ${title.trim()}`,
          createdOfflineAt: new Date().toISOString(),
          syncStatus: 'UNSYNCED',
        });
        setSuccess(
          lang === 'bn'
            ? 'অফলাইনে নোটিশ ও ছবি সেভ হয়েছে! ইন্টারনেট এলেই স্বয়ংক্রিয়ভাবে অনলাইন পাবলিক ড্যাশবোর্ডে চলে আসবে।'
            : 'Notice & photo saved offline! It will publish automatically to the online public dashboard when internet returns.'
        );
      }
      onRefreshOfflineCount?.();
      resetForm();
      await loadAdminNotices();
    };

    setSaving(true);
    try {
      if (useOffline) {
        await queueCreateOrUpdateOffline();
        return;
      }

      if (editingItem) {
        const body: Record<string, unknown> = {
          title: title.trim(),
          content: content.trim(),
          noticeType,
          isPinned,
          isPublished,
        };
        if (imageChanged) {
          body.imageDataUrl = imageDataUrl;
        }
        if (attachmentChanged) {
          body.attachmentDataUrl = attachmentDataUrl;
          body.attachmentName = attachmentName;
          body.attachmentMime = attachmentMime;
        }
        await apiFetch(`/api/admin/notices/${editingItem.id}`, {
          method: 'PATCH',
          body: JSON.stringify(body),
        });
        setSuccess(
          lang === 'bn'
            ? 'নোটিশ / পাবলিক পোস্ট সফলভাবে আপডেট হয়েছে।'
            : 'Notice / Public Post updated successfully.'
        );
      } else {
        await apiFetch('/api/admin/notices', {
          method: 'POST',
          body: JSON.stringify({
            title: title.trim(),
            content: content.trim(),
            noticeType,
            isPinned,
            isPublished,
            imageDataUrl,
            attachmentDataUrl,
            attachmentName,
            attachmentMime,
          }),
        });
        setSuccess(
          lang === 'bn'
            ? 'নতুন নোটিশ ও পাবলিক পোস্ট পোর্টালে প্রকাশিত হয়েছে!'
            : 'New Notice / Public Post published to the portal!'
        );
      }
      resetForm();
      await loadAdminNotices();
    } catch (err) {
      if (isNetworkError(err)) {
        await queueCreateOrUpdateOffline();
      } else {
        setError(err instanceof Error ? err.message : 'Failed to save notice.');
      }
    } finally {
      setSaving(false);
    }
  };

  const startEdit = (item: PublicNoticeItem) => {
    setError(null);
    setSuccess(null);
    setEditingItem(item);
    setNoticeType(item.noticeType);
    setTitle(item.title);
    setContent(item.content);
    setIsPinned(item.isPinned);
    setIsPublished(item.isPublished);
    setImageDataUrl(item.imageDataUrl);
    setImageChanged(false);
    setAttachmentDataUrl(null);
    setAttachmentName(item.hasAttachment ? item.attachmentName : null);
    setAttachmentMime(item.attachmentMime);
    setAttachmentChanged(false);
  };

  const handleTogglePin = async (item: PublicNoticeItem) => {
    setError(null);
    const queuePin = async () => {
      await enqueueAdminOfflineItem({
        clientTxId: `offline-notice-pin-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        operationType: 'UPDATE_NOTICE',
        payload: {
          noticeId: item.id,
          noticeTempClientOfflineId: item.tempClientOfflineId,
          isPinned: !item.isPinned,
        },
        summary: `${!item.isPinned ? 'Pin' : 'Unpin'} Notice: ${item.title}`,
        createdOfflineAt: new Date().toISOString(),
        syncStatus: 'UNSYNCED',
      });
      onRefreshOfflineCount?.();
      await loadAdminNotices();
    };
    try {
      if (isOfflineMode || item.id < 0 || (typeof navigator !== 'undefined' && !navigator.onLine)) {
        await queuePin();
        return;
      }
      await apiFetch(`/api/admin/notices/${item.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ isPinned: !item.isPinned }),
      });
      await loadAdminNotices();
    } catch (err) {
      if (isNetworkError(err)) {
        await queuePin();
      } else {
        setError(err instanceof Error ? err.message : 'Failed to update pin state.');
      }
    }
  };

  const handleTogglePublish = async (item: PublicNoticeItem) => {
    setError(null);
    const queuePub = async () => {
      await enqueueAdminOfflineItem({
        clientTxId: `offline-notice-pub-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        operationType: 'UPDATE_NOTICE',
        payload: {
          noticeId: item.id,
          noticeTempClientOfflineId: item.tempClientOfflineId,
          isPublished: !item.isPublished,
        },
        summary: `${!item.isPublished ? 'Publish' : 'Hide'} Notice: ${item.title}`,
        createdOfflineAt: new Date().toISOString(),
        syncStatus: 'UNSYNCED',
      });
      onRefreshOfflineCount?.();
      await loadAdminNotices();
    };
    try {
      if (isOfflineMode || item.id < 0 || (typeof navigator !== 'undefined' && !navigator.onLine)) {
        await queuePub();
        return;
      }
      await apiFetch(`/api/admin/notices/${item.id}`, {
        method: 'PATCH',
        body: JSON.stringify({ isPublished: !item.isPublished }),
      });
      await loadAdminNotices();
    } catch (err) {
      if (isNetworkError(err)) {
        await queuePub();
      } else {
        setError(err instanceof Error ? err.message : 'Failed to update visibility.');
      }
    }
  };

  const handleDelete = async (item: PublicNoticeItem) => {
    setError(null);
    setSuccess(null);
    const queueDel = async () => {
      await enqueueAdminOfflineItem({
        clientTxId: `offline-notice-del-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        operationType: 'DELETE_NOTICE',
        payload: {
          noticeId: item.id,
          noticeTempClientOfflineId: item.tempClientOfflineId,
          titleSnapshot: item.title,
        },
        summary: `Delete Notice: ${item.title}`,
        createdOfflineAt: new Date().toISOString(),
        syncStatus: 'UNSYNCED',
      });
      onRefreshOfflineCount?.();
      if (editingId === item.id) resetForm();
      setSuccess(
        lang === 'bn'
          ? `"${item.title}" অফলাইনে মুছে ফেলা হয়েছে (অনলাইন হলে সার্ভার থেকেও মুছবে)।`
          : `Deleted "${item.title}" offline (will sync online).`
      );
      await loadAdminNotices();
    };
    try {
      if (isOfflineMode || item.id < 0 || (typeof navigator !== 'undefined' && !navigator.onLine)) {
        await queueDel();
        return;
      }
      await apiFetch(`/api/admin/notices/${item.id}`, { method: 'DELETE' });
      if (editingId === item.id) resetForm();
      setSuccess(
        lang === 'bn' ? `"${item.title}" মুছে ফেলা হয়েছে।` : `Deleted "${item.title}".`
      );
      await loadAdminNotices();
    } catch (err) {
      if (isNetworkError(err)) {
        await queueDel();
      } else {
        setError(err instanceof Error ? err.message : 'Failed to delete notice.');
      }
    }
  };

  const typeLabel = (t: PublicNoticeItem['noticeType']) => {
    if (t === 'PUBLIC_POST') return lang === 'bn' ? 'পাবলিক পোস্ট' : 'Public Post';
    if (t === 'EVENT') return lang === 'bn' ? 'অনুষ্ঠান / ঘোষণা' : 'Event / Program';
    return lang === 'bn' ? 'জরুরি নোটিশ' : 'Official Notice';
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 flex items-center gap-2.5">
            <Megaphone className="h-6 w-6 text-[#0B5D2E]" />
            <span>{lang === 'bn' ? 'নোটিশ ও পাবলিক পোস্ট' : 'Notice & Public Posts'}</span>
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            {lang === 'bn'
              ? 'এখান থেকে পাবলিক ড্যাশবোর্ডের নোটিশবোর্ড, জরুরি নোটিশ, ছবি এবং ডাউনলোডযোগ্য ফাইল পোস্ট করুন — অফলাইনে লিখলে নেট আসার সাথে সাথেই অনলাইনে অটো আপডেট হয়ে যাবে।'
              : 'Publish official notices, public posts, photos, and downloadable documents directly to the public dashboard — offline posts auto-sync online when internet returns.'}
          </p>
        </div>
      </div>

      {isOfflineMode && (
        <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs sm:text-sm font-medium text-amber-900">
          {lang === 'bn'
            ? 'অফলাইন মোড সক্রিয়: এখান থেকে নতুন নোটিশ বা ছবি পোস্ট করলে তা স্থানীয়ভাবে সেভ থাকবে এবং ইন্টারনেট এলেই স্বয়ংক্রিয়ভাবে অনলাইন পাবলিক ড্যাশবোর্ডে প্রকাশিত হবে।'
            : 'Offline Mode Active: Notices and photos posted offline are saved locally and auto-sync to the online public dashboard once internet reconnects.'}
        </div>
      )}

      {success && (
        <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-[#0B5D2E] flex items-center gap-2">
          <CheckCircle2 className="h-4 w-4 shrink-0" />
          <span>{success}</span>
        </div>
      )}

      {error && (
        <div
          role="alert"
          className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-[#DC2626]"
        >
          {error}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        {/* Publish / Edit Notice Form */}
        <form
          onSubmit={handleSubmit}
          className="lg:col-span-5 bg-white border border-slate-200 rounded-2xl p-5 sm:p-6 space-y-4 shadow-xs"
        >
          <div className="flex items-center justify-between gap-2 border-b border-slate-100 pb-3">
            <h2 className="text-base font-bold text-slate-900">
              {editingId
                ? lang === 'bn'
                  ? 'পোস্ট সম্পাদনা করুন'
                  : 'Edit Notice / Post'
                : lang === 'bn'
                  ? 'নতুন নোটিশ বা পাবলিক পোস্ট প্রকাশ'
                  : 'Publish New Notice or Public Post'}
            </h2>
            {editingId && (
              <button
                type="button"
                onClick={resetForm}
                className="text-xs font-semibold text-slate-600 hover:text-slate-900 underline"
              >
                {lang === 'bn' ? 'বাতিল করুন' : 'Cancel Edit'}
              </button>
            )}
          </div>

          <div>
            <label
              htmlFor="notice-type-select"
              className="block text-xs font-semibold text-slate-700 mb-1"
            >
              {lang === 'bn' ? 'ধরণ নির্বাচন করুন' : 'Post Category'}
            </label>
            <select
              id="notice-type-select"
              value={noticeType}
              onChange={(e) =>
                setNoticeType(e.target.value as 'NOTICE' | 'PUBLIC_POST' | 'EVENT')
              }
              className="w-full h-11 px-3 rounded-xl border border-slate-300 bg-white text-sm text-slate-900 focus:outline-none focus:ring-2 focus:ring-[#0B5D2E]"
            >
              <option value="NOTICE">
                {lang === 'bn' ? 'জরুরি নোটিশ (Official Notice)' : 'Official Notice'}
              </option>
              <option value="PUBLIC_POST">
                {lang === 'bn' ? 'পাবলিক পোস্ট (Public Post)' : 'Public Post'}
              </option>
              <option value="EVENT">
                {lang === 'bn' ? 'অনুষ্ঠান / মাহফিল (Event)' : 'Event / Program'}
              </option>
            </select>
          </div>

          <div>
            <label
              htmlFor="notice-title-input"
              className="block text-xs font-semibold text-slate-700 mb-1"
            >
              {lang === 'bn' ? 'শিরোনাম *' : 'Title *'}
            </label>
            <input
              id="notice-title-input"
              type="text"
              required
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder={
                lang === 'bn'
                  ? 'যেমন: বার্ষিক জলসা ও চাঁদা সংগ্রহ সংক্রান্ত জরুরি বিজ্ঞপ্তি'
                  : 'e.g., Annual Program & Membership Collection Notice'
              }
              className="w-full h-11 px-3.5 rounded-xl border border-slate-300 text-sm text-slate-900 focus:outline-none focus:ring-2 focus:ring-[#0B5D2E]"
            />
          </div>

          <div>
            <label
              htmlFor="notice-content-input"
              className="block text-xs font-semibold text-slate-700 mb-1"
            >
              {lang === 'bn' ? 'বিস্তারিত বিবরণ *' : 'Notice / Post Content *'}
            </label>
            <textarea
              id="notice-content-input"
              required
              rows={5}
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder={
                lang === 'bn'
                  ? 'নোটিশ বা পাবলিক পোস্টের সম্পূর্ণ তথ্য এখানে লিখুন...'
                  : 'Write the full message or public announcement details...'
              }
              className="w-full p-3.5 rounded-xl border border-slate-300 text-sm text-slate-900 focus:outline-none focus:ring-2 focus:ring-[#0B5D2E]"
            />
          </div>

          {/* Photo / Image Upload */}
          <div className="rounded-xl border border-dashed border-slate-300 bg-slate-50/70 p-3.5 space-y-2.5">
            <div className="flex items-center justify-between gap-2">
              <span className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                <ImagePlus className="h-4 w-4 text-[#0B5D2E]" />
                <span>{lang === 'bn' ? 'ছবি আপলোড (ঐচ্ছিক, সর্বোচ্চ ৫ MB)' : 'Upload Photo (Optional, max 5 MB)'}</span>
              </span>
              {imageDataUrl && (
                <button
                  type="button"
                  onClick={() => {
                    setImageDataUrl(null);
                    setImageChanged(true);
                  }}
                  className="inline-flex items-center gap-1 text-[11px] font-semibold text-[#DC2626] hover:underline"
                >
                  <X className="h-3.5 w-3.5" />
                  <span>{lang === 'bn' ? 'ছবি সরান' : 'Remove Photo'}</span>
                </button>
              )}
            </div>

            <input
              id="notice-image-upload"
              type="file"
              accept="image/*"
              onChange={handleImagePick}
              className="block w-full text-xs text-slate-600 file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-semibold file:bg-emerald-100 file:text-[#0B5D2E] hover:file:bg-emerald-200 cursor-pointer"
            />

            {imageDataUrl && (
              <img
                src={imageDataUrl}
                alt="Preview"
                className="w-full h-36 object-cover rounded-lg border border-slate-200 bg-white"
              />
            )}
          </div>

          {/* File Attachment Upload */}
          <div className="rounded-xl border border-dashed border-slate-300 bg-slate-50/70 p-3.5 space-y-2">
            <div className="flex items-center justify-between gap-2">
              <span className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                <FileUp className="h-4 w-4 text-[#0A3D91]" />
                <span>
                  {lang === 'bn'
                    ? 'ফাইল সংযুক্তি — PDF / ডকুমেন্ট / ছবি (সর্বোচ্চ ৮ MB)'
                    : 'Attach File — PDF / Doc / Image (max 8 MB)'}
                </span>
              </span>
              {attachmentName && (
                <button
                  type="button"
                  onClick={() => {
                    setAttachmentDataUrl(null);
                    setAttachmentName(null);
                    setAttachmentMime(null);
                    setAttachmentChanged(true);
                  }}
                  className="inline-flex items-center gap-1 text-[11px] font-semibold text-[#DC2626] hover:underline"
                >
                  <X className="h-3.5 w-3.5" />
                  <span>{lang === 'bn' ? 'ফাইল সরান' : 'Remove'}</span>
                </button>
              )}
            </div>

            <input
              id="notice-file-upload"
              type="file"
              onChange={handleAttachmentPick}
              className="block w-full text-xs text-slate-600 file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-semibold file:bg-blue-100 file:text-[#0A3D91] hover:file:bg-blue-200 cursor-pointer"
            />

            {attachmentName && (
              <div className="text-xs font-medium text-[#0A3D91] bg-blue-50 border border-blue-200 rounded-lg px-2.5 py-1.5 truncate">
                {lang === 'bn' ? 'সংযুক্ত ফাইল:' : 'Attached:'} {attachmentName}
              </div>
            )}
          </div>

          <div className="space-y-2 pt-1">
            <label className="flex items-center gap-2 text-xs font-semibold text-slate-800 cursor-pointer">
              <input
                type="checkbox"
                checked={isPinned}
                onChange={(e) => setIsPinned(e.target.checked)}
                className="h-4 w-4 rounded border-slate-300 text-[#0B5D2E] focus:ring-[#0B5D2E]"
              />
              <span>
                {lang === 'bn'
                  ? 'হোমপেজের উপরের "অনলাইন নোটিশ বার"-এ পিন করে দেখান'
                  : 'Pin this notice to the top Online Notice Bar on homepage'}
              </span>
            </label>

            <label className="flex items-center gap-2 text-xs font-semibold text-slate-800 cursor-pointer">
              <input
                type="checkbox"
                checked={isPublished}
