import { useEffect, useState } from 'react';
import { CloudOff, CloudUpload, RefreshCw, ShieldAlert, Trash2 } from 'lucide-react';
import { apiFetch } from '../services/api';
import {
  clearSyncedOfflineItems,
  getAdminOfflineQueue,
  updateOfflineItemStatus,
} from '../services/offlineDb';
import { sortQueueChronological } from '../services/offlineOverlay';
import { t } from '../i18n/translations';
import type { AuthUser, Language, OfflineQueueItem } from '../types/app';

interface OfflineSyncViewProps {
  lang: Language;
  user: AuthUser;
  isOfflineMode: boolean;
  onToggleOfflineMode: () => void;
  onRefreshOfflineCount: () => void;
}

interface SyncHistoryRow {
  id: number;
  clientTxId: string;
  operationType: string;
  syncStatus: string;
  conflictReason: string | null;
  createdOfflineAt: string;
  syncedAt: string;
}

export function OfflineSyncView({
  lang,
  user,
  isOfflineMode,
  onToggleOfflineMode,
  onRefreshOfflineCount,
}: OfflineSyncViewProps) {
  const [queue, setQueue] = useState<OfflineQueueItem[]>([]);
  const [serverHistory, setServerHistory] = useState<SyncHistoryRow[]>([]);
  const [syncing, setSyncing] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const loadAll = async () => {
    const localItems = await getAdminOfflineQueue();
    setQueue(localItems);
    onRefreshOfflineCount();

    if (!isOfflineMode) {
      try {
        const res = await apiFetch<{ history: SyncHistoryRow[] }>('/api/sync/history');
        setServerHistory(res.history);
      } catch {
        // Offline or unreachable
      }
    }
  };

  useEffect(() => {
    loadAll();
  }, [isOfflineMode]);

  const handleSyncNow = async () => {
    const unsynced = sortQueueChronological(queue.filter((q) => q.syncStatus === 'UNSYNCED'));
    if (unsynced.length === 0) return;

    setSyncing(true);
    setError(null);
    setMessage(null);
    try {
      const res = await apiFetch<{
        results: Array<{ clientTxId: string; status: string; message: string }>;
      }>('/api/sync/offline', {
        method: 'POST',
        body: JSON.stringify({ items: unsynced }),
      });

      for (const r of res.results) {
        if (r.status === 'SYNCED' || r.status === 'DUPLICATE_SKIPPED') {
          await updateOfflineItemStatus(r.clientTxId, 'SYNCED', r.message);
        } else {
          await updateOfflineItemStatus(r.clientTxId, 'CONFLICT', r.message);
        }
      }

      setMessage(
        lang === 'bn'
          ? `${res.results.length}টি অফলাইন রেকর্ড সিঙ্ক প্রক্রিয়া সম্পন্ন হয়েছে।`
          : `Processed ${res.results.length} offline records safely.`
      );
      await loadAll();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Synchronization failed.');
    } finally {
      setSyncing(false);
    }
  };

  if (user.roleName !== 'ADMIN') {
    return (
      <div className="rounded-xl border border-amber-200 bg-amber-50 p-6 flex items-start gap-3">
        <ShieldAlert className="h-5 w-5 text-amber-700 shrink-0 mt-0.5" />
        <div className="text-sm text-amber-900">
          <strong>Admin Only Policy:</strong> Only the authorized Admin device can create or synchronize offline entries. Staff accounts operate strictly through the central database.
        </div>
      </div>
    );
  }

  const unsyncedCount = queue.filter((q) => q.syncStatus === 'UNSYNCED').length;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-slate-900">{t(lang, 'offlineSync')}</h1>
          <p className="text-sm text-slate-500 mt-0.5">
            {lang === 'bn'
              ? 'শুধুমাত্র অ্যাডমিন ডিভাইসে নিরাপদ অফলাইন এন্ট্রি এবং স্বয়ংক্রিয় সিঙ্ক'
              : 'Admin-only IndexedDB offline queue · Duplicate-safe idempotent sync'}
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={onToggleOfflineMode}
            className={`inline-flex items-center gap-2 rounded-xl px-4 h-11 text-xs font-semibold border whitespace-nowrap ${
              isOfflineMode
                ? 'bg-amber-600 text-white border-amber-600'
                : 'bg-white text-slate-700 border-slate-300 hover:bg-slate-50'
            }`}
          >
            <CloudOff className="h-4 w-4" />
            <span>
              {isOfflineMode
                ? lang === 'bn'
                  ? 'অফলাইন মোড চালু (অনলাইন করুন)'
                  : 'Admin Offline Mode Active (Go Online)'
                : lang === 'bn'
                  ? 'অফলাইন মোড পরীক্ষা করুন'
                  : 'Switch to Admin Offline Mode'}
            </span>
          </button>

          <button
            type="button"
            disabled={syncing || unsyncedCount === 0 || isOfflineMode}
            onClick={handleSyncNow}
            className="inline-flex items-center gap-2 rounded-xl bg-[#0B5D2E] hover:bg-[#094A25] text-white px-4 h-11 text-xs font-semibold disabled:opacity-50 whitespace-nowrap"
          >
            <CloudUpload className="h-4 w-4" />
            <span>
              {syncing ? '...' : `${t(lang, 'syncNow')} (${unsyncedCount})`}
            </span>
          </button>
        </div>
      </div>

      {message && (
        <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-[#0B5D2E]">
          {message}
        </div>
      )}
      {error && (
        <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-[#DC2626]">
          {error}
        </div>
      )}

      {/* Local Admin Device Queue */}
      <section className="rounded-xl bg-white border border-slate-200 overflow-hidden">
        <div className="px-5 py-4 border-b border-slate-200 flex items-center justify-between">
          <h2 className="text-base font-bold text-slate-900">
            {lang === 'bn' ? 'স্থানীয় ডিভাইসের অফলাইন কিউ' : 'Local Admin Device Queue'}
          </h2>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={loadAll}
              className="p-2 rounded-lg border border-slate-200 text-slate-600 hover:bg-slate-50"
              aria-label="Reload local queue"
            >
              <RefreshCw className="h-4 w-4" />
            </button>
            <button
              type="button"
              onClick={async () => {
                await clearSyncedOfflineItems();
                await loadAll();
              }}
              className="inline-flex items-center gap-1 rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-semibold text-slate-600 hover:bg-slate-50"
            >
              <Trash2 className="h-3.5 w-3.5" />
              <span>{lang === 'bn' ? 'সিঙ্ককৃত মুছুন' : 'Clear Synced'}</span>
            </button>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse text-sm">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200 text-xs font-semibold text-slate-600">
                <th className="py-3 px-4">Client TX ID</th>
                <th className="py-3 px-4">Operation</th>
                <th className="py-3 px-4">Summary</th>
                <th className="py-3 px-4">Created Offline</th>
                <th className="py-3 px-4">Sync Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {queue.length === 0 ? (
                <tr>
                  <td colSpan={5} className="py-8 text-center text-slate-500">
                    {lang === 'bn'
                      ? 'এই ডিভাইসে কোনো অফলাইন এন্ট্রি নেই।'
                      : 'No local offline entries queued on this Admin device.'}
                  </td>
                </tr>
              ) : (
                queue.map((item) => (
                  <tr key={item.clientTxId}>
                    <td className="py-3 px-4 font-mono-num text-xs text-slate-600">
                      {item.clientTxId}
                    </td>
                    <td className="py-3 px-4 font-semibold text-xs">{item.operationType}</td>
                    <td className="py-3 px-4">{item.summary}</td>
                    <td className="py-3 px-4 font-mono-num text-xs text-slate-500">
                      {new Date(item.createdOfflineAt).toLocaleString()}
                    </td>
                    <td className="py-3 px-4">
                      <span
                        className={`text-xs font-bold ${
                          item.syncStatus === 'UNSYNCED'
                            ? 'text-amber-700'
                            : item.syncStatus === 'SYNCED'
                              ? 'text-[#16A34A]'
                              : 'text-[#DC2626]'
                        }`}
                      >
                        {item.syncStatus}
                      </span>
                      {item.errorMessage && (
                        <div className="text-[11px] text-slate-500 mt-0.5">{item.errorMessage}</div>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </section>

      {/* Server Synchronization History */}
      <section className="rounded-xl bg-white border border-slate-200 overflow-hidden">
        <div className="px-5 py-4 border-b border-slate-200">
          <h2 className="text-base font-bold text-slate-900">
            {lang === 'bn' ? 'সার্ভার সিঙ্ক্রোনাইজেশন ইতিহাস' : 'Central Server Synchronization History'}
          </h2>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse text-xs">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200 font-semibold text-slate-600">
                <th className="py-2.5 px-4">Transaction ID</th>
                <th className="py-2.5 px-4">Operation</th>
                <th className="py-2.5 px-4">Result</th>
                <th className="py-2.5 px-4">Notes / Conflict</th>
                <th className="py-2.5 px-4">Synced At</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {serverHistory.length === 0 ? (
                <tr>
                  <td colSpan={5} className="py-8 text-center text-slate-500">
                    {t(lang, 'noRecords')}
                  </td>
                </tr>
              ) : (
                serverHistory.map((h) => (
                  <tr key={h.id}>
                    <td className="py-2.5 px-4 font-mono-num">{h.clientTxId}</td>
                    <td className="py-2.5 px-4 font-semibold">{h.operationType}</td>
                    <td className="py-2.5 px-4 font-bold text-[#16A34A]">{h.syncStatus}</td>
                    <td className="py-2.5 px-4 text-slate-600">{h.conflictReason || 'OK'}</td>
                    <td className="py-2.5 px-4 font-mono-num text-slate-500">
                      {new Date(h.syncedAt).toLocaleString()}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
}

