  const [autoPrintOnSave, setAutoPrintOnSave] = useState<boolean>(() => {
    try {
      return localStorage.getItem('skm_auto_print_a6') !== 'false';
    } catch {
      return true;
    }
  });
  const [paperSize, setPaperSize] = useState<ReceiptPaperSize>(() => getPreferredPaperSize());
  const [submitting, setSubmitting] = useState(false);

  const handlePaperSizeChange = (next: ReceiptPaperSize) => {
    setPaperSize(next);
    setPreferredPaperSize(next);
  };

  const handleDirectPrintReceipt = async (receiptNo: string) => {
    setError(null);
    try {
      const cached = await getOfflineSnapshot<ReceiptData>(`receipt:${receiptNo}`);
      if ((isOfflineMode || receiptNo.startsWith('OFF-') || !navigator.onLine) && cached) {
        await printReceiptA6(cached, lang, paperSize);
        return;
      }
      const res = await apiFetch<{ receipt: ReceiptData }>(
        `/api/receipts/${encodeURIComponent(receiptNo)}`
      );
      await saveOfflineSnapshot(`receipt:${receiptNo}`, res.receipt);
      await printReceiptA6(res.receipt, lang, paperSize);
    } catch (err) {
      const cached = await getOfflineSnapshot<ReceiptData>(`receipt:${receiptNo}`);
      if (cached) {
        await printReceiptA6(cached, lang, paperSize);
        return;
      }
      setError(err instanceof Error ? err.message : 'Failed to send receipt to printer.');
    }
  };

  const canCreate = user.roleName === 'ADMIN' || user.permissions.includes('payments:create');
  const canCorrect = user.roleName === 'ADMIN' || user.permissions.includes('payments:correct');
  const allowPartial = settings.allowPartialPayments === 'true';

  const loadOfflineMergedData = async () => {
    const [cachedMembers, cachedPaysYear, cachedPaysLatest, queue] = await Promise.all([
      getCachedMembersSnapshot(),
      getOfflineSnapshot<PaymentItem[]>(`payments:year:${yearFilter}`),
      getOfflineSnapshot<PaymentItem[]>('payments:latest'),
      getAdminOfflineQueue(),
    ]);
    const mergedMembers = mergeMembersWithOfflineQueue(
      cachedMembers,
      queue,
      selectedYear,
      user.fullName
    );
    const basePays = cachedPaysYear || cachedPaysLatest || [];
    const mergedPays = mergePaymentsWithOfflineQueue(basePays, mergedMembers, queue, user);
    const q = search.trim().toLowerCase();
    const filteredPays = mergedPays.filter((p) => {
      if (yearFilter !== 'ALL' && p.paymentYear !== Number(yearFilter)) return false;
      if (!q) return true;
      return `${p.receiptNumber} ${p.memberCode || ''} ${p.memberName || ''} ${p.memberMobile || ''} ${p.memberAddress || ''}`
        .toLowerCase()
        .includes(q);
    });
    return { filteredPays, activeMembers: mergedMembers.filter((m) => m.status === 'ACTIVE') };
  };

  const loadData = async () => {
    setLoading(true);
    setError(null);
    if (isOfflineMode) {
      const offline = await loadOfflineMergedData();
      setPaymentsList(offline.filteredPays);
      setMembersList(offline.activeMembers);
      setLoading(false);
      return;
    }

    try {
      const yQuery = yearFilter === 'ALL' ? '' : `&year=${yearFilter}`;
      const sQuery = staffFilter === 'ALL' ? '' : `&staffId=${staffFilter}`;
      const [payRes, memRes] = await Promise.all([
        apiFetch<{ payments: PaymentItem[] }>(
          `/api/payments?q=${encodeURIComponent(search)}${yQuery}${sQuery}`
        ),
        apiFetch<{ members: MemberListItem[] }>(`/api/members?year=${selectedYear}`),
      ]);
      setPaymentsList(payRes.payments);
      setMembersList(memRes.members.filter((m) => m.status === 'ACTIVE'));
      await cacheMembersSnapshot(memRes.members);
      if (!search && staffFilter === 'ALL') {
        await Promise.all([
          saveOfflineSnapshot(`payments:year:${yearFilter}`, payRes.payments),
          saveOfflineSnapshot('payments:latest', payRes.payments),
        ]);
      }
      if (user.roleName === 'ADMIN' && staffOptions.length === 0) {
        apiFetch<{ staff: Array<{ id: number; username: string; fullName: string }> }>('/api/staff')
          .then((sRes) => setStaffOptions(sRes.staff))
          .catch(() => {});
      }
    } catch (err) {
      const offline = await loadOfflineMergedData();
      if (offline.activeMembers.length > 0 || offline.filteredPays.length > 0 || user.roleName === 'ADMIN') {
        setPaymentsList(offline.filteredPays);
        setMembersList(offline.activeMembers);
      } else {
        setError(err instanceof Error ? err.message : 'Failed to load payments.');
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadData();
  }, [search, yearFilter, staffFilter, refreshTick, isOfflineMode]);

  // Open preselected member from Members/Pending view
  useEffect(() => {
    if (preselectedMemberId) {
      setSelectedMemberId(String(preselectedMemberId));
      setPayYear(selectedYear);
      setShowCollectModal(true);
      onClearPreselected();
    }
  }, [preselectedMemberId]);

  // Load expected fee, paid so far, previous years pending, and existing receipts
  useEffect(() => {
    if (!selectedMemberId || !showCollectModal) return;
    const mId = Number(selectedMemberId);
    if (isOfflineMode) {
      const cached = membersList.find((m) => m.id === mId);
      if (cached) {
        const exp = payYear === selectedYear ? cached.currentYearExpected : cached.defaultAnnualFee;
        const already = payYear === selectedYear ? cached.currentYearPaid : 0;
        const rem = Math.max(0, roundMoney(exp - already));
        setExpectedFee(exp);
        setAlreadyPaid(already);
        setPrevDueItems([]);
        setProfileObligations([{ year: payYear, expectedFee: exp, alreadyPaid: already }]);
        setExistingYearReceipts([]);
        setIncludePrevDues(false);
        setPaidAmount(rem > 0 ? String(rem) : '0');
      }
      return;
    }

    apiFetch<MemberProfileData>(`/api/members/${mId}`)
      .then((prof) => {
        const row = prof.yearlyLedger.find((l) => l.year === payYear);
        const exp = row ? row.frozenAnnualFee : prof.member.defaultAnnualFee;
        const paid = row ? row.paidTotal : 0;
        const remCurrent = roundMoney(Math.max(0, exp - paid));

        const prevItems = prof.yearlyLedger
          .filter((l) => l.year < payYear && l.year >= START_YEAR && l.dueAmount > 0)
          .map((l) => ({ year: l.year, dueAmount: l.dueAmount }));
        const prevSum = roundMoney(prevItems.reduce((s, r) => s + r.dueAmount, 0));

        const obs: YearDueItem[] = prof.yearlyLedger
          .filter((l) => l.year <= payYear && l.year >= START_YEAR)
          .map((l) => ({
            year: l.year,
            expectedFee: l.frozenAnnualFee,
            alreadyPaid: l.paidTotal,
          }));

        const yearPays = prof.payments.filter((p) => !p.isVoided && p.paymentYear === payYear);

        setExpectedFee(exp);
        setAlreadyPaid(paid);
        setPrevDueItems(prevItems);
        setProfileObligations(obs);
        setExistingYearReceipts(yearPays);
        const shouldIncludePrev = prevSum > 0;
        setIncludePrevDues(shouldIncludePrev);
        const totalSuggested = roundMoney(remCurrent + (shouldIncludePrev ? prevSum : 0));
        setPaidAmount(totalSuggested > 0 ? String(totalSuggested) : '0');
      })
      .catch(() => {
        const fallback = membersList.find((m) => m.id === mId);
        if (fallback) {
          const exp = payYear === selectedYear ? fallback.currentYearExpected : fallback.defaultAnnualFee;
          const already = payYear === selectedYear ? fallback.currentYearPaid : 0;
          const rem = Math.max(0, roundMoney(exp - already));
          setExpectedFee(exp);
          setAlreadyPaid(already);
          setPrevDueItems([]);
          setProfileObligations([{ year: payYear, expectedFee: exp, alreadyPaid: already }]);
          setExistingYearReceipts([]);
          setIncludePrevDues(false);
          setPaidAmount(rem > 0 ? String(rem) : '0');
        }
      });
  }, [selectedMemberId, payYear, showCollectModal, isOfflineMode]);

  const prevYearsDueTotal = roundMoney(prevDueItems.reduce((s, r) => s + r.dueAmount, 0));
  const remainingCurrentYearDue = roundMoney(Math.max(0, expectedFee - alreadyPaid));
  const totalPayableDue = roundMoney(
    remainingCurrentYearDue + (includePrevDues ? prevYearsDueTotal : 0)
  );

  const allocationPreview =
    profileObligations.length > 0 && Number(paidAmount) > 0
      ? allocateMultiYearPayment({
          referenceYear: payYear,
          obligations: profileObligations,
          attemptAmount: Number(paidAmount),
          includePreviousDues: includePrevDues,
          allowPartialPayments: true,
        })
      : null;

  const dueAfterThisPayment =
    allocationPreview && allocationPreview.ok
      ? allocationPreview.totalRemainingDue
      : roundMoney(Math.max(0, totalPayableDue - (Number(paidAmount) || 0)));

  const handleToggleIncludePrev = (checked: boolean) => {
    setIncludePrevDues(checked);
    const nextPayable = roundMoney(
      remainingCurrentYearDue + (checked ? prevYearsDueTotal : 0)
    );
    setPaidAmount(nextPayable > 0 ? String(nextPayable) : '0');
  };

  const handleSubmitPayment = async (e: FormEvent) => {
    e.preventDefault();
    setError(null);
    setNotice(null);

    const mId = Number(selectedMemberId);
    const amountNum = Number(paidAmount);
    if (!mId || !Number.isFinite(amountNum) || amountNum <= 0) {
      setError('Select a member and enter a valid payment amount.');
      return;
    }

    setSubmitting(true);
    const clientTxId = `tx-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const now = new Date();
    const timeStr = now.toTimeString().slice(0, 8);

    try {
      if (isOfflineMode) {
        if (user.roleName !== 'ADMIN') {
          throw new Error('Only Admin devices may record offline payments.');
        }
        const m = membersList.find((item) => item.id === mId);
        const offlineReceiptNumber = `OFF-${clientTxId.slice(-6).toUpperCase()}`;
        const expFee = roundMoney(m?.currentYearExpected || m?.defaultAnnualFee || amountNum);
        const already = payYear === selectedYear ? roundMoney(m?.currentYearPaid || 0) : 0;
        const dueAfter = roundMoney(Math.max(0, expFee - already - amountNum));

        let memberTempClientOfflineId: string | undefined;
        if (mId < 0) {
          const queue = await getAdminOfflineQueue();
          const matchedCreate = queue.find(
            (q) => q.operationType === 'CREATE_MEMBER' && offlineTempMemberId(q.clientTxId) === mId
          );
          memberTempClientOfflineId = matchedCreate?.clientTxId;
        }

        const offlineReceipt = buildOfflineReceiptData({
          receiptNumber: offlineReceiptNumber,
          member: m || {
            memberCode: `ID-${mId}`,
            name: `Member #${mId}`,
            guardianName: '-',
            mobile: '-',
            address: '-',
            defaultAnnualFee: expFee,
          },
          paymentYear: payYear,
          expectedFee: expFee,
          paidAmount: amountNum,
          remainingDue: dueAfter,
          paymentDate,
          paymentTime: timeStr,
          paymentMethod,
          notes: notes || null,
          issuedByName: user.fullName,
          issuedByUsername: user.username,
          referenceYear: selectedYear,
          clientTxId,
        });

        await saveOfflineSnapshot(`receipt:${offlineReceiptNumber}`, offlineReceipt);
        await enqueueAdminOfflineItem({
          clientTxId,
          operationType: 'RECORD_PAYMENT',
          payload: {
            memberId: mId,
            memberTempClientOfflineId,
            memberCodeSnapshot: m?.memberCode,
            memberNameSnapshot: m?.name,
            memberMobileSnapshot: m?.mobile,
            memberAddressSnapshot: m?.address,
            expectedFeeSnapshot: expFee,
            dueAfterSnapshot: dueAfter,
            offlineReceiptNumber,
            paymentYear: payYear,
            paidAmount: amountNum,
            paymentDate,
            paymentTime: timeStr,
            paymentMethod,
            notes,
          },
          summary: `Payment ₹${amountNum} for ${m?.name || `Member #${mId}`} (${payYear}) · #${offlineReceiptNumber}`,
          createdOfflineAt: now.toISOString(),
          syncStatus: 'UNSYNCED',
        });
        onRefreshOfflineCount();
        setShowCollectModal(false);
        setNotes('');
        setNotice(
          lang === 'bn'
            ? `অফলাইন পেমেন্ট সংরক্ষিত হয়েছে। অফলাইন রসিদ: ${offlineReceiptNumber} (অনলাইন হলে স্বয়ংক্রিয় সিঙ্ক হবে)`
            : `Offline payment saved. Offline Receipt: ${offlineReceiptNumber} (will auto-sync when online).`
        );
        await loadData();
        onOpenReceipt(offlineReceiptNumber, autoPrintOnSave);
        return;
      }

      const res = await apiFetch<{ payment: { receiptNumber: string } }>('/api/payments', {
        method: 'POST',
        body: JSON.stringify({
          memberId: mId,
          paymentYear: payYear,
          paidAmount: amountNum,
          paymentDate,
          paymentTime: timeStr,
          paymentMethod,
          notes,
          clientTxId,
          includePreviousDues: includePrevDues,
        }),
      });

      setShowCollectModal(false);
      setNotes('');
      setNotice(
        lang === 'bn'
          ? `পেমেন্ট গৃহীত হয়েছে। রসিদ নম্বর: ${res.payment.receiptNumber}`
          : `Payment recorded. Receipt: ${res.payment.receiptNumber}`
      );
      await loadData();
      onOpenReceipt(res.payment.receiptNumber, autoPrintOnSave);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to record payment.');
    } finally {
      setSubmitting(false);
    }
  };

  const yearOptions = Array.from({ length: 30 }, (_, idx) => START_YEAR + idx);

  return (
    <div className="space-y-5">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-slate-900">{t(lang, 'payments')}</h1>
          <p className="text-sm text-slate-500 mt-0.5">
            {lang === 'bn'
              ? '২০২৬ থেকে ২০৫০+ স্বয়ংক্রিয় বাৎসরিক চাঁদা, রসিদ ও সংশোধন অডিট'
              : '2026–2050+ Fee Collection · Duplicate Prevention · Audited Corrections'}
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2.5 shrink-0">
          <select
            aria-label="Receipt paper size"
            value={paperSize}
            onChange={(e) => handlePaperSizeChange(e.target.value as ReceiptPaperSize)}
            className="h-11 rounded-xl border border-emerald-200 bg-white px-3 text-xs font-semibold text-[#0B5D2E]"
          >
            <option value="4x6">4" × 6" কাগজ</option>
            <option value="A6">A6 কাগজ</option>
          </select>

          <label className="inline-flex items-center gap-2 rounded-xl border border-emerald-200 bg-emerald-50 px-3 h-11 text-xs font-semibold text-[#0B5D2E] cursor-pointer select-none">
            <input
              type="checkbox"
              checked={autoPrintOnSave}
              onChange={(e) => {
                const checked = e.target.checked;
                setAutoPrintOnSave(checked);
                try {
                  localStorage.setItem('skm_auto_print_a6', checked ? 'true' : 'false');
                } catch {
                  // ignore
                }
              }}
              className="h-4 w-4 rounded border-slate-300 text-[#0B5D2E] focus:ring-[#0B5D2E]"
            />
            <span>
              {lang === 'bn'
                ? `অটো প্রিন্ট (${paperSize === '4x6' ? '4"×6"' : 'A6'})`
                : `Auto Print (${paperSize === '4x6' ? '4"×6"' : 'A6'})`}
            </span>
          </label>

          <button
            type="button"
            disabled={paymentsList.length === 0}
            onClick={() => {
              void printPaymentHistoryList(paymentsList, String(selectedYear), lang).catch((err) =>
                setError(err instanceof Error ? err.message : 'Failed to print payment history.')
              );
            }}
            className="inline-flex items-center justify-center gap-1.5 rounded-xl border border-slate-300 bg-white hover:bg-slate-50 text-slate-800 px-3.5 h-11 text-xs font-semibold whitespace-nowrap disabled:opacity-50"
          >
            <Printer className="h-4 w-4 text-[#0B5D2E]" />
            <span>{lang === 'bn' ? 'পেমেন্ট হিস্ট্রি প্রিন্ট' : 'Print History'}</span>
          </button>

          {canCreate && (
            <button
              type="button"
              onClick={() => {
                if (!selectedMemberId && membersList.length > 0) {
                  setSelectedMemberId(String(membersList[0].id));
                }
                setPayYear(selectedYear);
                setShowCollectModal(true);
              }}
              className="inline-flex items-center justify-center gap-2 rounded-xl bg-[#0B5D2E] hover:bg-[#094A25] text-white px-4 h-11 text-sm font-semibold whitespace-nowrap shrink-0"
            >
              <PlusCircle className="h-4 w-4" />
              <span>{t(lang, 'collectPayment')}</span>
            </button>
          )}
        </div>
      </div>

      {notice && (
        <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-[#0B5D2E]">
          {notice}
        </div>
      )}
      {error && (
        <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-[#DC2626]">
          {error}
        </div>
      )}

      {/* Filter Bar */}
      <div className="flex flex-col md:flex-row gap-3 items-stretch md:items-center justify-between bg-white border border-slate-200 rounded-xl p-3">
        <div className="relative flex-1">
          <Search className="h-4 w-4 text-slate-400 absolute left-3.5 top-1/2 -translate-y-1/2" />
          <input
            type="search"
            aria-label="Search payments"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder={
              lang === 'bn'
                ? 'রসিদ নম্বর, সদস্য আইডি, নাম বা মোবাইল...'
                : 'Search receipt #, member ID, name, or mobile...'
            }
            className="w-full h-11 pl-10 pr-4 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#0B5D2E]"
          />
        </div>
        <select
          aria-label="Filter by payment year"
          value={yearFilter}
          onChange={(e) => setYearFilter(e.target.value)}
          className="h-11 px-3 rounded-lg border border-slate-200 bg-white text-sm font-semibold font-mono-num"
        >
          <option value="ALL">{lang === 'bn' ? 'সকল বছর' : 'All Years'}</option>
          {yearOptions.map((y) => (
            <option key={y} value={y}>
              {y}
            </option>
          ))}
        </select>
        {user.roleName === 'ADMIN' && staffOptions.length > 0 && (
          <select
            aria-label="Filter by partner user ID"
            value={staffFilter}
            onChange={(e) => setStaffFilter(e.target.value)}
            className="h-11 px-3 rounded-lg border border-slate-200 bg-white text-sm font-semibold"
          >
            <option value="ALL">
              {lang === 'bn' ? 'সকল পার্টনার আইডি' : 'All Partner IDs'}
            </option>
            {staffOptions.map((s) => (
              <option key={s.id} value={s.id}>
                @{s.username} · {s.fullName}
              </option>
            ))}
          </select>
        )}
      </div>

      {/* Payments History Table */}
      <div className="rounded-xl bg-white border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="border-b border-slate-200 bg-slate-50 text-xs font-semibold text-slate-600">
                <th className="py-3 px-4">{t(lang, 'receiptNo')}</th>
                <th className="py-3 px-4">{t(lang, 'memberName')}</th>
                <th className="py-3 px-4">{t(lang, 'paymentYear')}</th>
                <th className="py-3 px-4 text-right">{t(lang, 'expectedFee')}</th>
                <th className="py-3 px-4 text-right">{t(lang, 'paidAmount')}</th>
                <th className="py-3 px-4 text-right">{t(lang, 'dueAmount')}</th>
                <th className="py-3 px-4">{lang === 'bn' ? 'তারিখ / মাধ্যম' : 'Date / Method'}</th>
                <th className="py-3 px-4 text-right">{lang === 'bn' ? 'কার্যক্রম' : 'Actions'}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-sm">
              {loading ? (
                <tr>
                  <td colSpan={8} className="py-10 text-center text-slate-500">
                    {t(lang, 'loading')}
                  </td>
                </tr>
              ) : paymentsList.length === 0 ? (
                <tr>
                  <td colSpan={8} className="py-10 text-center text-slate-500">
                    {t(lang, 'noRecords')}
                  </td>
                </tr>
              ) : (
                paymentsList.map((p) => (
                  <tr key={p.id} className="hover:bg-slate-50/70">
                    <td className="py-3 px-4 whitespace-nowrap">
                      <div className="font-mono-num text-xs font-bold text-[#0A3D91]">
                        {p.receiptNumber}
                      </div>
                      {p.isSyncedFromOffline && (
                        <div className="text-[11px] text-amber-700 font-medium">Offline Synced</div>
                      )}
                      {(p.corrections?.length ?? 0) > 0 && (
                        <div className="text-[11px] text-[#DC2626] font-medium flex items-center gap-1 mt-0.5">
                          <History className="h-3 w-3" />
                          <span>{p.corrections!.length} correction(s)</span>
                        </div>
                      )}
                    </td>
                    <td className="py-3 px-4">
                      <div className="font-semibold text-slate-900">{p.memberName}</div>
                      <div className="text-xs text-slate-500 font-mono-num">{p.memberCode}</div>
                      {p.memberAddress && (
                        <div className="text-xs text-slate-500 mt-0.5">{p.memberAddress}</div>
                      )}
                    </td>
                    <td className="py-3 px-4 font-mono-num font-semibold">{p.paymentYear}</td>
                    <td className="py-3 px-4 text-right font-mono-num text-slate-700">
                      {formatCurrency(p.expectedFee)}
                    </td>
                    <td className="py-3 px-4 text-right font-mono-num font-bold text-[#16A34A]">
                      {formatCurrency(p.paidAmount)}
                    </td>
                    <td className="py-3 px-4 text-right font-mono-num font-semibold text-slate-700">
                      {formatCurrency(p.dueAfterPayment)}
                    </td>
                    <td className="py-3 px-4 text-xs text-slate-600">
                      <div className="font-mono-num">{p.paymentDate}</div>
                      <div>
                        {p.paymentMethod} · By {p.receivedByName}
                        {p.receivedByUsername ? (
                          <span className="ml-1 font-mono-num text-[#0A3D91] font-semibold">
                            (@{p.receivedByUsername})
                          </span>
                        ) : null}
                      </div>
                    </td>
                    <td className="py-3 px-4">
                      <div className="flex items-center justify-end gap-1.5">
                        <button
                          type="button"
                          onClick={() => onOpenReceipt(p.receiptNumber)}
                          className="inline-flex items-center gap-1 rounded-lg border border-slate-200 px-2.5 py-1.5 text-xs font-semibold text-slate-700 hover:bg-slate-100 whitespace-nowrap"
                        >
                          <Receipt className="h-3.5 w-3.5 text-[#0B5D2E]" />
                          <span>{lang === 'bn' ? 'রসিদ' : 'Receipt'}</span>
                        </button>
                        <button
                          type="button"
                          onClick={() => void handleDirectPrintReceipt(p.receiptNumber)}
                          aria-label={`Print A6 receipt ${p.receiptNumber}`}
                          title={
                            lang === 'bn'
                              ? `কম্পিউটার প্রিন্টারে A6 রসিদ #${p.receiptNumber} প্রিন্ট`
                              : `Print Receipt #${p.receiptNumber} (A6)`
                          }
                          className="inline-flex items-center gap-1 rounded-lg border border-emerald-200 bg-emerald-50 px-2.5 py-1.5 text-xs font-semibold text-[#0B5D2E] hover:bg-emerald-100 whitespace-nowrap"
                        >
                          <Printer className="h-3.5 w-3.5" />
                          <span>{lang === 'bn' ? 'প্রিন্ট' : 'Print'}</span>
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            fetchAndDownloadReceiptPdf(p.receiptNumber).catch((err) =>
                              setError(err instanceof Error ? err.message : 'PDF download failed.')
                            );
                          }}
                          aria-label={`Download A6 PDF receipt ${p.receiptNumber}`}
                          title={
                            lang === 'bn'
                              ? `রসিদ #${p.receiptNumber} পুনরায় A6 PDF ডাউনলোড`
                              : `Re-download Receipt #${p.receiptNumber} A6 PDF`
                          }
                          className="inline-flex items-center gap-1 rounded-lg border border-blue-200 bg-blue-50 px-2.5 py-1.5 text-xs font-semibold text-[#0A3D91] hover:bg-blue-100 whitespace-nowrap"
                        >
                          <Download className="h-3.5 w-3.5" />
                          <span>PDF</span>
                        </button>
                        {canCorrect && (
                          <button
                            type="button"
                            onClick={() => onOpenCorrection(p)}
                            aria-label={`Correct payment ${p.receiptNumber}`}
                            className="inline-flex items-center gap-1 rounded-lg border border-red-200 px-2.5 py-1.5 text-xs font-semibold text-[#DC2626] hover:bg-red-50 whitespace-nowrap"
                          >
                            <Edit className="h-3.5 w-3.5" />
                            <span>{lang === 'bn' ? 'সংশোধন' : 'Correct'}</span>
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Collect Payment Modal */}
      {showCollectModal && (
        <div className="fixed inset-0 z-50 flex items-start sm:items-center justify-center bg-black/50 p-4 overflow-y-auto">
          <div className="w-full max-w-lg rounded-2xl bg-white border border-slate-200 shadow-2xl p-6 my-8">
            <div className="flex items-center justify-between border-b border-slate-100 pb-3">
              <h2 className="text-lg font-bold text-slate-900">{t(lang, 'collectPayment')}</h2>
              <button
                type="button"
                aria-label="Close collect payment modal"
                onClick={() => setShowCollectModal(false)}
                className="p-2 text-slate-500 hover:text-slate-800"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <form onSubmit={handleSubmitPayment} className="mt-4 space-y-3.5">
              <div>
                <label htmlFor="pay-member" className="block text-xs font-semibold text-slate-700 mb-1">
                  {t(lang, 'memberName')} *
                </label>
                <select
                  id="pay-member"
                  required
                  value={selectedMemberId}
                  onChange={(e) => setSelectedMemberId(e.target.value)}
                  className="w-full h-11 px-3 rounded-xl border border-slate-300 text-sm bg-white"
                >
                  <option value="">-- Select Member --</option>
                  {membersList.map((m) => (
                    <option key={m.id} value={m.id}>
                      {m.memberCode} — {m.name} ({m.mobile}) · {m.address}
                    </option>
                  ))}
                </select>
                {selectedMemberId && (() => {
                  const sel = membersList.find((m) => String(m.id) === selectedMemberId);
                  return sel ? (
                    <div className="mt-1.5 rounded-lg bg-slate-50 border border-slate-200 px-3 py-2 text-xs text-slate-700">
                      <span className="font-semibold text-slate-500">{t(lang, 'address')}: </span>
                      <span>{sel.address}</span>
                    </div>
                  ) : null;
                })()}
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label htmlFor="pay-year" className="block text-xs font-semibold text-slate-700 mb-1">
                    {t(lang, 'paymentYear')} *
                  </label>
                  <select
                    id="pay-year"
                    value={payYear}
                    onChange={(e) => setPayYear(Number(e.target.value))}
                    className="w-full h-11 px-3 rounded-xl border border-slate-300 text-sm font-mono-num font-bold bg-white"
                  >
                    {yearOptions.map((y) => (
                      <option key={y} value={y}>
                        {y}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label htmlFor="pay-date" className="block text-xs font-semibold text-slate-700 mb-1">
                    {lang === 'bn' ? 'তারিখ' : 'Payment Date'} *
                  </label>
                  <input
                    id="pay-date"
                    type="date"
                    required
                    value={paymentDate}
                    onChange={(e) => setPaymentDate(e.target.value)}
                    className="w-full h-11 px-3 rounded-xl border border-slate-300 text-sm font-mono-num"
                  />
                </div>
              </div>

              {/* Automatic Fee & Due Calculation Box */}
              <div className="rounded-xl bg-slate-50 border border-slate-200 p-3.5 space-y-2.5">
                <div className="grid grid-cols-3 gap-2 text-center">
                  <div>
                    <div className="text-[11px] font-semibold text-slate-500">
                      {t(lang, 'expectedFee')} ({payYear})
                    </div>
                    <div className="text-sm font-bold text-slate-900 font-mono-num mt-0.5">
                      {formatCurrency(expectedFee)}
                    </div>
                  </div>
                  <div>
                    <div className="text-[11px] font-semibold text-slate-500">
                      {lang === 'bn' ? 'পূর্বে জমা' : 'Paid So Far'}
                    </div>
                    <div className="text-sm font-bold text-[#16A34A] font-mono-num mt-0.5">
                      {formatCurrency(alreadyPaid)}
                    </div>
                  </div>
                  <div>
                    <div className="text-[11px] font-semibold text-slate-500">
                      {lang === 'bn' ? `চলতি বকেয়া (${payYear})` : `Current Due (${payYear})`}
                    </div>
                    <div className="text-sm font-bold text-[#DC2626] font-mono-num mt-0.5">
                      {formatCurrency(remainingCurrentYearDue)}
                    </div>
                  </div>
                </div>

                {prevYearsDueTotal > 0 && !isOfflineMode && (
                  <div className="pt-2.5 border-t border-slate-200 space-y-2">
                    <div className="flex items-center justify-between text-xs">
                      <span className="font-semibold text-amber-800">
                        {lang === 'bn'
                          ? 'বিগত বছরের বাকি চাঁদা:'
