                      />
                      <span>
                        {lang === 'bn'
                          ? `বিগত বছরের বকেয়া একসাথে পরিশোধ করুন (মোট প্রদেয়: ${formatCurrency(remainingCurrentYearDue + prevYearsDueTotal)})`
                          : `Include previous years' dues in this payment (Total Payable: ${formatCurrency(remainingCurrentYearDue + prevYearsDueTotal)})`}
                      </span>
                    </label>
                  </div>
                )}
              </div>

              {totalPayableDue <= 0 && !isOfflineMode ? (
                <div className="rounded-xl border border-emerald-200 bg-emerald-50 p-3.5 space-y-2.5">
                  <p className="text-xs font-semibold text-[#0B5D2E]">
                    {lang === 'bn'
                      ? `${payYear} সালের বার্ষিক চাঁদা ইতিমধ্যে সম্পূর্ণ পরিশোধিত। ডুপ্লিকেট পূর্ণ পেমেন্ট অনুমোদিত নয়। নিচের বাটন থেকে পুনরায় রসিদ ডাউনলোড বা প্রিন্ট করতে পারেন:`
                      : `Membership fee for ${payYear} is already PAID. Duplicate full-year payments are blocked. You can re-download or print the receipt below:`}
                  </p>
                  {existingYearReceipts.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {existingYearReceipts.map((r) => (
                        <div key={r.id} className="flex items-center gap-1.5">
                          <button
                            type="button"
                            onClick={() => onOpenReceipt(r.receiptNumber)}
                            className="inline-flex items-center gap-1 rounded-lg bg-white border border-emerald-300 px-2.5 py-1.5 text-xs font-semibold text-[#0B5D2E] hover:bg-emerald-100"
                          >
                            <Receipt className="h-3.5 w-3.5" />
                            <span>
                              {lang === 'bn'
                                ? `রসিদ #${r.receiptNumber} দেখুন`
                                : `View Receipt #${r.receiptNumber}`}
                            </span>
                          </button>
                          <button
                            type="button"
                            onClick={() => void handleDirectPrintReceipt(r.receiptNumber)}
                            className="inline-flex items-center gap-1 rounded-lg bg-[#16A34A] text-white px-2.5 py-1.5 text-xs font-semibold hover:bg-[#15803D]"
                          >
                            <Printer className="h-3.5 w-3.5" />
                            <span>{lang === 'bn' ? 'A6 প্রিন্ট' : 'Print A6'}</span>
                          </button>
                          <button
                            type="button"
                            onClick={() => {
                              fetchAndDownloadReceiptPdf(r.receiptNumber).catch((err) =>
                                setError(err instanceof Error ? err.message : 'PDF download failed.')
                              );
                            }}
                            className="inline-flex items-center gap-1 rounded-lg bg-[#0A3D91] text-white px-2.5 py-1.5 text-xs font-semibold hover:bg-[#083073]"
                          >
                            <Download className="h-3.5 w-3.5" />
                            <span>
                              {lang === 'bn' ? 'পুনরায় A6 PDF' : 'Re-download A6 PDF'}
                            </span>
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ) : (
                <>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <div>
                      <label htmlFor="pay-amount" className="block text-xs font-semibold text-slate-700 mb-1">
                        {t(lang, 'paidAmount')} (₹) *
                      </label>
                      <input
                        id="pay-amount"
                        type="number"
                        min="1"
                        max={isOfflineMode ? undefined : totalPayableDue}
                        step="0.01"
                        required
                        readOnly={!allowPartial && !isOfflineMode}
                        value={paidAmount}
                        onChange={(e) => setPaidAmount(e.target.value)}
                        className="w-full h-11 px-3 rounded-xl border border-slate-300 text-sm font-mono-num font-bold"
                      />
                      {(allowPartial || isOfflineMode) && (
                        <div className="flex flex-wrap gap-1.5 mt-1.5">
                          {[-100, -50, 50, 100].map((delta) => (
                            <button
                              key={delta}
                              type="button"
                              onClick={() => {
                                const cur = Number(paidAmount) || 0;
                                const maxCap = isOfflineMode ? Infinity : totalPayableDue;
                                const next = Math.min(maxCap, Math.max(1, roundMoney(cur + delta)));
                                setPaidAmount(String(next));
                              }}
                              className={`px-2 py-1 rounded-md text-[11px] font-bold font-mono-num border ${
                                delta > 0
                                  ? 'border-emerald-200 bg-emerald-50 text-[#0B5D2E] hover:bg-emerald-100'
                                  : 'border-amber-200 bg-amber-50 text-amber-800 hover:bg-amber-100'
                              }`}
                            >
                              {delta > 0 ? `+₹${delta}` : `-₹${Math.abs(delta)}`}
                            </button>
                          ))}
                        </div>
                      )}
                      {!allowPartial && (
                        <p className="text-[11px] text-amber-700 mt-1">
                          Partial payments disabled by Admin.
                        </p>
                      )}
                    </div>

                    <div>
                      <label htmlFor="pay-method" className="block text-xs font-semibold text-slate-700 mb-1">
                        {t(lang, 'paymentMethod')}
                      </label>
                      <select
                        id="pay-method"
                        value={paymentMethod}
                        onChange={(e) => setPaymentMethod(e.target.value)}
                        className="w-full h-11 px-3 rounded-xl border border-slate-300 text-sm bg-white"
                      >
                        <option value="Cash">Cash</option>
                        <option value="Bank">Bank</option>
                        <option value="bKash">bKash</option>
                        <option value="Nagad">Nagad</option>
                        <option value="Rocket">Rocket</option>
                      </select>
                    </div>
                  </div>

                  {allocationPreview && allocationPreview.ok && includePrevDues && prevYearsDueTotal > 0 && (
                    <div className="rounded-lg bg-emerald-50 border border-emerald-200 px-3 py-2 text-xs text-[#0B5D2E] space-y-1">
                      <div className="font-bold">
                        {lang === 'bn'
                          ? 'স্বয়ংক্রিয় রসিদ বিভাজন (অটো হিসাব):'
                          : 'Auto Receipt Allocation:'}
                      </div>
                      <div className="flex items-center justify-between font-mono-num">
                        <span>{lang === 'bn' ? 'বিগত বছরের চাঁদা পরিশোধ:' : 'Previous Years Paid:'}</span>
                        <strong>{formatCurrency(allocationPreview.previousYearsPaidNow)}</strong>
                      </div>
                      <div className="flex items-center justify-between font-mono-num">
                        <span>
                          {lang === 'bn'
                            ? `চলতি বছরের চাঁদা পরিশোধ (${payYear}):`
                            : `Current Year Paid (${payYear}):`}
                        </span>
                        <strong>{formatCurrency(allocationPreview.currentYearPaidNow)}</strong>
                      </div>
                    </div>
                  )}

                  <div className="text-xs text-slate-600 flex items-center justify-between px-1">
                    <span>{lang === 'bn' ? 'পেমেন্টের পর মোট বকেয়া:' : 'Due After Payment:'}</span>
                    <strong className="font-mono-num text-slate-900">
                      {formatCurrency(dueAfterThisPayment)}
                    </strong>
                  </div>

                  <div>
                    <label htmlFor="pay-notes" className="block text-xs font-semibold text-slate-700 mb-1">
                      {t(lang, 'notes')}
                    </label>
                    <input
                      id="pay-notes"
                      value={notes}
                      onChange={(e) => setNotes(e.target.value)}
                      placeholder={lang === 'bn' ? 'ঐচ্ছিক নোট...' : 'Optional notes...'}
                      className="w-full h-11 px-3 rounded-xl border border-slate-300 text-sm"
                    />
                  </div>

                  <div className="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-emerald-200 bg-emerald-50/70 px-3.5 py-2.5 text-xs font-semibold text-[#0B5D2E]">
                    <label className="flex items-center gap-2.5 cursor-pointer select-none">
                      <input
                        type="checkbox"
                        checked={autoPrintOnSave}
                        onChange={(e) => {
                          const checked = e.target.checked;
                          setAutoPrintOnSave(checked);
                          try {
                            localStorage.setItem('skm_auto_print_a6', checked ? 'true' : 'false');
                          } catch {
                            // ignore
                          }
                        }}
                        className="h-4 w-4 rounded border-slate-300 text-[#0B5D2E] focus:ring-[#0B5D2E]"
                      />
                      <span>
                        {lang === 'bn'
                          ? `সেভ হলে স্বয়ংক্রিয়ভাবে ${paperSize === '4x6' ? '4"×6" কাগজে' : 'A6'} প্রিন্ট`
                          : `Auto-print (${paperSize === '4x6' ? '4"×6"' : 'A6'}) on Save`}
                      </span>
                    </label>
                    <select
                      aria-label="Paper size for auto print"
                      value={paperSize}
                      onChange={(e) => handlePaperSizeChange(e.target.value as ReceiptPaperSize)}
                      className="rounded-lg border border-emerald-300 bg-white px-2 py-1 text-[11px] font-bold text-[#0B5D2E]"
                    >
                      <option value="4x6">4" × 6" কাগজ</option>
                      <option value="A6">A6 কাগজ</option>
                    </select>
                  </div>
                </>
              )}

              <div className="pt-2 flex items-center justify-end gap-3">
                <button
                  type="button"
                  onClick={() => setShowCollectModal(false)}
                  className="px-4 h-11 rounded-xl border border-slate-300 text-sm font-semibold text-slate-700"
                >
                  {t(lang, 'cancel')}
                </button>
                <button
                  type="submit"
                  disabled={submitting || (totalPayableDue <= 0 && !isOfflineMode)}
                  className="px-5 h-11 rounded-xl bg-[#0B5D2E] hover:bg-[#094A25] text-white text-sm font-semibold disabled:opacity-50"
                >
                  {submitting ? '...' : t(lang, 'save')}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { AlertCircle, CheckCircle2, Download, Printer, Receipt, Wallet } from 'lucide-react';
import { apiFetch } from '../services/api';
import { fetchAndDownloadReceiptPdf } from '../services/exportUtils';
import {
  getAdminOfflineQueue,
  getOfflineSnapshot,
  saveOfflineSnapshot,
} from '../services/offlineDb';
import {
  mergePendingWithOfflineQueue,
  type PendingApiResponse,
} from '../services/offlineOverlay';
import {
  getPreferredPaperSize,
  printPendingDueSlip,
  printPendingDuesList,
  printReceiptByNumber,
  setPreferredPaperSize,
  type ReceiptPaperSize,
} from '../services/printReceipt';
import { formatCurrency, t } from '../i18n/translations';
import type { AuthUser, Language } from '../types/app';

interface PendingDuesViewProps {
  lang: Language;
  user: AuthUser;
  selectedYear: number;
  isOfflineMode?: boolean;
  onOpenReceipt: (receiptNumber: string) => void;
  onQuickCollect: (memberId: number) => void;
}

export function PendingDuesView({
  lang,
  user,
  selectedYear,
  isOfflineMode = false,
  onOpenReceipt,
  onQuickCollect,
}: PendingDuesViewProps) {
  const [data, setData] = useState<PendingApiResponse | null>(null);
  const [statusFilter, setStatusFilter] = useState<'PENDING_ONLY' | 'PAID' | 'PARTIAL' | 'UNPAID'>('PENDING_ONLY');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [paperSize, setPaperSize] = useState<ReceiptPaperSize>(() => getPreferredPaperSize());

  const canPay = user.roleName === 'ADMIN' || user.permissions.includes('payments:create');

  const handlePaperSizeChange = (next: ReceiptPaperSize) => {
    setPaperSize(next);
    setPreferredPaperSize(next);
  };

  const loadFromOfflineCache = async (year: number): Promise<PendingApiResponse | null> => {
    const cached =
      (await getOfflineSnapshot<PendingApiResponse>(`pending:${year}`)) ||
      (await getOfflineSnapshot<PendingApiResponse>('pending:latest'));
    if (!cached) return null;
    const queue = await getAdminOfflineQueue();
    return mergePendingWithOfflineQueue(cached, queue);
  };

  useEffect(() => {
    let active = true;
    const run = async () => {
      setLoading(true);
      setError(null);
      if (isOfflineMode) {
        const offline = await loadFromOfflineCache(selectedYear);
        if (active) {
          if (offline) setData(offline);
          setLoading(false);
        }
        return;
      }

      try {
        const res = await apiFetch<PendingApiResponse>(`/api/pending?year=${selectedYear}`);
        await Promise.all([
          saveOfflineSnapshot(`pending:${selectedYear}`, res),
          saveOfflineSnapshot('pending:latest', res),
        ]);
        if (active) setData(res);
      } catch (err) {
        const offline = await loadFromOfflineCache(selectedYear);
        if (active) {
          if (offline) {
            setData(offline);
          } else {
            setError(err instanceof Error ? err.message : 'Failed to load pending dues.');
          }
        }
      } finally {
        if (active) setLoading(false);
      }
    };
    void run();
    return () => {
      active = false;
    };
  }, [selectedYear, isOfflineMode]);

  const rows = data
    ? statusFilter === 'PENDING_ONLY'
      ? data.items
      : data.allActiveStatus.filter((m) => m.currentYearStatus === statusFilter)
    : [];

  return (
    <div className="space-y-5">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-slate-900">{t(lang, 'pendingDues')}</h1>
          <p className="text-sm text-slate-500 mt-0.5">
            {lang === 'bn'
              ? `ভবিষ্যৎ বছর ব্যতীত ${selectedYear} পর্যন্ত বকেয়া হিসাব`
              : `Real-time arrears up to ${selectedYear} (future years excluded before their period)`}
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2 shrink-0">
          <select
            aria-label="Due slip paper size"
            value={paperSize}
            onChange={(e) => handlePaperSizeChange(e.target.value as ReceiptPaperSize)}
            className="h-10 rounded-xl border border-emerald-200 bg-white px-3 text-xs font-semibold text-[#0B5D2E]"
          >
            <option value="4x6">4" × 6" কাগজ</option>
            <option value="A6">A6 কাগজ</option>
          </select>

          <button
            type="button"
            disabled={!data || rows.length === 0}
            onClick={() => {
              if (!data) return;
              const filterLabels: Record<typeof statusFilter, string> = {
                PENDING_ONLY: lang === 'bn' ? 'সকল বকেয়া' : 'All Pending',
                UNPAID: t(lang, 'unpaid'),
                PARTIAL: t(lang, 'partial'),
                PAID: t(lang, 'paid'),
              };
              void printPendingDuesList(
                rows,
                data.summary,
                data.referenceYear,
                filterLabels[statusFilter],
                lang
              ).catch((err) =>
                setError(err instanceof Error ? err.message : 'Failed to print pending dues list.')
              );
            }}
            className="inline-flex items-center gap-1.5 rounded-xl bg-[#0B5D2E] hover:bg-[#094A25] text-white px-4 h-10 text-xs font-semibold whitespace-nowrap disabled:opacity-50"
          >
            <Printer className="h-4 w-4" />
