import { useEffect, useRef, useState } from 'react';
import { Download, Printer, X } from 'lucide-react';
import {
  closePrintPreview,
  downloadPrintPreviewPdf,
  regeneratePreviewForPaperSize,
  subscribePrintPreview,
  triggerNativePrintNow,
  type PrintPreviewPayload,
  type ReceiptPaperSize,
} from '../services/printReceipt';

export function PrintPreviewHost() {
  const [payload, setPayload] = useState<PrintPreviewPayload | null>(null);
  const [downloadingPdf, setDownloadingPdf] = useState(false);
  const iframeRef = useRef<HTMLIFrameElement | null>(null);

  useEffect(() => {
    return subscribePrintPreview((next) => {
      setPayload(next);
    });
  }, []);

  useEffect(() => {
    if (!payload) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        closePrintPreview();
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [payload]);

  if (!payload) return null;

  const isBn = payload.lang === 'bn';

  const handlePaperSizeChange = async (next: ReceiptPaperSize) => {
    const updated = await regeneratePreviewForPaperSize(payload, next);
    setPayload(updated);
  };

  const handlePrintNow = () => {
    // Synchronous native print inside the click handler using #skm-print-root
    triggerNativePrintNow(payload.html, payload.paperSize);
  };

  const handleSavePdf = async () => {
    setDownloadingPdf(true);
    try {
      await downloadPrintPreviewPdf(payload);
    } finally {
      setDownloadingPdf(false);
    }
  };

  const paperLabel =
    payload.paperSize === '4x6' ? '4"×6"' : payload.paperSize === 'A6' ? 'A6' : 'A4';

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label={isBn ? 'প্রিন্ট প্রিভিউ এবং পিডিএফ' : 'Print Preview & PDF'}
      className="no-print fixed inset-0 z-[90] flex items-center justify-center bg-slate-950/75 p-3 sm:p-5 overflow-y-auto"
    >
      <div className="w-full max-w-3xl rounded-2xl bg-white border border-slate-200 shadow-2xl overflow-hidden flex flex-col max-h-[92vh]">
        {/* Top Print Action Toolbar */}
        <div className="bg-slate-900 text-white px-4 sm:px-5 py-3 flex flex-wrap items-center justify-between gap-2.5 shrink-0">
          <div className="min-w-0">
            <div className="text-sm font-bold truncate">{payload.title}</div>
            <div className="text-[11px] text-emerald-300 font-medium">
              {isBn
                ? `প্রিন্ট প্রিভিউ (${paperLabel}) · সরাসরি প্রিন্ট বা PDF ডাউনলোড করুন`
                : `Print Preview (${paperLabel}) · Ready to Print or Save PDF`}
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2 shrink-0">
            {payload.supportsPaperToggle && (
              <select
                aria-label={isBn ? 'কাগজের সাইজ' : 'Paper Size'}
                value={payload.paperSize === 'A6' ? 'A6' : '4x6'}
                onChange={(e) => void handlePaperSizeChange(e.target.value as ReceiptPaperSize)}
                className="rounded-lg bg-slate-800 border border-slate-700 px-2.5 py-2 text-xs font-semibold text-white"
              >
                <option value="4x6">4" × 6" কাগজ</option>
                <option value="A6">A6 কাগজ</option>
              </select>
            )}

            <button
              type="button"
              onClick={handlePrintNow}
              className="inline-flex items-center gap-1.5 rounded-lg bg-[#16A34A] hover:bg-[#15803D] px-3.5 py-2 text-xs font-bold text-white whitespace-nowrap"
            >
              <Printer className="h-4 w-4" />
              <span>{isBn ? 'প্রিন্ট করুন' : 'Print Now'}</span>
            </button>

            <button
              type="button"
              disabled={downloadingPdf}
              onClick={() => void handleSavePdf()}
              className="inline-flex items-center gap-1.5 rounded-lg bg-[#0A3D91] hover:bg-[#083073] px-3.5 py-2 text-xs font-bold text-white whitespace-nowrap disabled:opacity-60"
            >
              <Download className="h-4 w-4" />
              <span>
                {downloadingPdf
                  ? '...'
                  : isBn
                    ? 'PDF সেভ করুন'
                    : 'Save PDF'}
              </span>
            </button>

            <button
              type="button"
              aria-label={isBn ? 'প্রিন্ট প্রিভিউ বন্ধ করুন' : 'Close print preview'}
              onClick={closePrintPreview}
              className="p-2 rounded-lg text-slate-300 hover:text-white hover:bg-slate-800"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>

        {/* Helpful guidance when embedded inside restricted iframe */}
        <div className="bg-emerald-50 border-b border-emerald-200 px-4 py-2 text-[11px] text-[#0B5D2E] font-medium shrink-0">
          {isBn
            ? 'টিপস: সরাসরি প্রিন্ট ডায়ালগ না এলে উপরের সবুজ "প্রিন্ট করুন" বাটনে ক্লিক করুন অথবা নীল "PDF সেভ করুন" বাটনে ক্লিক করে পিডিএফ ডাউনলোড করে প্রিন্ট করুন।'
            : 'Tip: If browser print dialog does not auto-open inside a preview frame, click "Print Now" above or click "Save PDF" to download and print immediately.'}
        </div>

        {/* Exact Paper Visual Frame */}
        <div className="flex-1 bg-slate-100 p-3 sm:p-5 overflow-auto flex justify-center">
          <div
            className={`bg-white shadow-md border border-slate-300 rounded-lg overflow-hidden ${
              payload.paperSize === 'A4'
                ? 'w-full max-w-[794px] min-h-[560px]'
                : 'w-full max-w-[420px] min-h-[580px]'
            }`}
          >
            <iframe
              ref={iframeRef}
              title={payload.title}
              srcDoc={payload.html}
              className="w-full h-full min-h-[580px] border-0 bg-white"
            />
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, type FormEvent } from 'react';
import { CheckCircle2, Clock, Search, UserCheck, XCircle } from 'lucide-react';
import { getCachedMembersSnapshot } from '../services/offlineDb';
import { formatCurrency } from '../i18n/translations';
import { roundMoney, START_YEAR } from '../domain/membershipRules';
import type { Language } from '../types/app';

export interface PublicMemberResult {
  memberCode: string;
  name: string;
  guardianName: string;
  status: string;
  referenceYear: number;
  currentYearStatus: 'PAID' | 'PARTIAL' | 'UNPAID';
  currentYearExpected: number;
  currentYearPaid: number;
  currentYearDue: number;
  previousYearsDue: number;
  totalOutstanding: number;
  totalPaidAllTime: number;
  lastPaymentDate: string | null;
  yearlySummary: Array<{
    year: number;
    expectedFee: number;
    paidTotal: number;
    dueAmount: number;
    status: 'PAID' | 'PARTIAL' | 'UNPAID';
  }>;
}

interface PublicMemberLookupProps {
  lang: Language;
}

export function PublicMemberLookup({ lang }: PublicMemberLookupProps) {
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [searched, setSearched] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [results, setResults] = useState<PublicMemberResult[]>([]);

  const runLookup = async (rawQuery: string) => {
    const clean = rawQuery.trim();
    setError(null);
    if (!clean) {
      setError(
        lang === 'bn'
          ? 'অনুগ্রহ করে সদস্য আইডি (যেমন SKM 1), আপনার নাম অথবা মোবাইল নম্বর লিখুন।'
          : 'Please enter SKM Member ID (e.g. SKM 1), Member Name, or Mobile Number.'
      );
      return;
    }

    setLoading(true);
    setSearched(true);
    try {
      const res = await fetch(`/api/public/member-lookup?q=${encodeURIComponent(clean)}`);
      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        throw new Error(body.error || 'Failed to look up member.');
      }
      const data = (await res.json()) as { items: PublicMemberResult[]; referenceYear: number };
      setResults(data.items || []);
    } catch {
      // Fallback to local cached snapshot if offline on an installed device
      try {
        const cached = await getCachedMembersSnapshot();
        const qLower = clean.toLowerCase();
        const qCompact = qLower.replace(/\s+/g, '');
        const qDigits = clean.replace(/\D/g, '');
        const isNum = /^\d+$/.test(clean);
        const isSkmExplicit = /^skm\s*-?\s*\d+$/i.test(clean);
        const matches = cached
          .filter((m) => {
            const cLow = m.memberCode.toLowerCase();
            const cCompact = cLow.replace(/\s+/g, '');
            if (isSkmExplicit) return cCompact === `skm${qDigits}`;
            if (isNum) {
              if (cCompact === `skm${clean}`) return true;
              if (qDigits.length >= 4 && m.mobile.replace(/\D/g, '').includes(qDigits)) return true;
              return false;
            }
            if (cLow === qLower || cCompact === qCompact) return true;
            if (qLower.length >= 2 && m.name.toLowerCase().includes(qLower)) return true;
            if (qDigits.length >= 4 && m.mobile.replace(/\D/g, '').includes(qDigits)) return true;
            return false;
          })
          .slice(0, 20)
          .map<PublicMemberResult>((m) => ({
            memberCode: m.memberCode,
            name: m.name,
            guardianName: m.guardianName,
            status: m.status,
            referenceYear: START_YEAR,
            currentYearStatus: m.currentYearStatus,
            currentYearExpected: m.currentYearExpected,
            currentYearPaid: m.currentYearPaid,
            currentYearDue: roundMoney(Math.max(0, m.currentYearExpected - m.currentYearPaid)),
            previousYearsDue: roundMoney(
              Math.max(0, m.totalOutstanding - Math.max(0, m.currentYearExpected - m.currentYearPaid))
            ),
            totalOutstanding: m.totalOutstanding,
            totalPaidAllTime: m.currentYearPaid,
            lastPaymentDate: null,
            yearlySummary: [],
          }));
        setResults(matches);
      } catch {
        setError(
          lang === 'bn'
            ? 'সদস্যের তথ্য যাচাই করা যায়নি। অনুগ্রহ করে পরে আবার চেষ্টা করুন।'
            : 'Unable to check member record right now.'
        );
      }
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = async (e: FormEvent) => {
    e.preventDefault();
    await runLookup(query);
  };

  const renderStatusBadge = (status: 'PAID' | 'PARTIAL' | 'UNPAID') => {
    if (status === 'PAID') {
      return (
        <span className="inline-flex items-center gap-1 rounded-lg bg-emerald-100 text-[#0B5D2E] px-2.5 py-1 text-xs font-bold">
          <CheckCircle2 className="h-3.5 w-3.5" />
          <span>{lang === 'bn' ? 'পরিশোধিত (Paid)' : 'Paid'}</span>
        </span>
      );
    }
    if (status === 'PARTIAL') {
      return (
        <span className="inline-flex items-center gap-1 rounded-lg bg-amber-100 text-amber-900 px-2.5 py-1 text-xs font-bold">
          <Clock className="h-3.5 w-3.5" />
          <span>{lang === 'bn' ? 'আংশিক পরিশোধ (Partial)' : 'Partial'}</span>
        </span>
      );
    }
    return (
      <span className="inline-flex items-center gap-1 rounded-lg bg-red-100 text-[#DC2626] px-2.5 py-1 text-xs font-bold">
        <XCircle className="h-3.5 w-3.5" />
        <span>{lang === 'bn' ? 'বকেয়া (Unpaid)' : 'Unpaid'}</span>
      </span>
    );
  };

  return (
    <section
      id="public-member-portal"
      aria-label={lang === 'bn' ? 'পাবলিক সদস্য প্রোফাইল ও বকেয়া যাচাই' : 'Public Member Profile & Ledger Lookup'}
      className="w-full max-w-4xl bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden scroll-mt-4"
    >
      <div className="bg-gradient-to-r from-[#0B5D2E]/5 via-emerald-50/70 to-blue-50/50 border-b border-slate-200 px-5 sm:px-8 py-4 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div className="flex items-start gap-3">
          <div className="h-10 w-10 rounded-xl bg-[#0B5D2E] text-white flex items-center justify-center shrink-0">
            <UserCheck className="h-5 w-5 text-[#F4D06F]" />
          </div>
          <div>
            <h2 className="text-base sm:text-lg font-bold text-slate-900">
              {lang === 'bn'
                ? 'সদস্য প্রোফাইল ও বকেয়া যাচাই (Public Member Profile)'
                : 'Public Member Profile & Ledger Lookup'}
            </h2>
            <p className="text-xs text-slate-600 mt-0.5">
              {lang === 'bn'
