}

import { useEffect, useState } from 'react';
import {
  Bell,
  Calendar,
  Download,
  ExternalLink,
  FileText,
  Image as ImageIcon,
  Megaphone,
  Pin,
  Printer,
  X,
} from 'lucide-react';
import { getAdminOfflineQueue, getOfflineSnapshot, saveOfflineSnapshot } from '../services/offlineDb';
import { mergeNoticesWithOfflineQueue } from '../services/offlineOverlay';
import { printNoticeDocument } from '../services/printReceipt';
import type { Language, PublicNoticeItem } from '../types/app';

interface PublicNoticeBoardProps {
  lang: Language;
  mode?: 'bar' | 'board' | 'both';
}

const OFFLINE_PUBLIC_NOTICES_KEY = 'public:notices';

export async function downloadNoticeAttachmentBlob(
  noticeId: number,
  fallbackName: string
): Promise<void> {
  const res = await fetch(`/api/public/notices/${noticeId}/attachment`, {
    credentials: 'same-origin',
  });
  if (!res.ok) {
    throw new Error('Failed to download attachment.');
  }
  const blob = await res.blob();
  const blobUrl = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = blobUrl;
  a.download = fallbackName || `notice-${noticeId}-file`;
  a.rel = 'noopener';
  a.style.display = 'none';
  document.body.appendChild(a);
  a.click();
  setTimeout(() => {
    a.remove();
    URL.revokeObjectURL(blobUrl);
  }, 60_000);
}

export function PublicNoticeBoard({ lang, mode = 'both' }: PublicNoticeBoardProps) {
  const [notices, setNotices] = useState<PublicNoticeItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedNotice, setSelectedNotice] = useState<PublicNoticeItem | null>(null);
  const [lightboxImage, setLightboxImage] = useState<{ src: string; title: string } | null>(null);
  const [downloadingId, setDownloadingId] = useState<number | null>(null);
  const [downloadErr, setDownloadErr] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    const load = async () => {
      try {
        let baseList: PublicNoticeItem[] = [];
        if (typeof navigator === 'undefined' || navigator.onLine) {
          const res = await fetch('/api/public/notices');
          if (!res.ok) throw new Error('HTTP error');
          const data = (await res.json()) as { items: PublicNoticeItem[] };
          baseList = data.items || [];
          void saveOfflineSnapshot(OFFLINE_PUBLIC_NOTICES_KEY, baseList).catch(() => {});
        } else {
          baseList = (await getOfflineSnapshot<PublicNoticeItem[]>(OFFLINE_PUBLIC_NOTICES_KEY)) || [];
        }
        const queue = await getAdminOfflineQueue().catch(() => []);
        const merged = mergeNoticesWithOfflineQueue(baseList, queue, 'Farhan Gazi Admin', {
          publicOnly: true,
        });
        if (active) {
          setNotices(merged);
          setLoading(false);
        }
      } catch {
        const [cached, queue] = await Promise.all([
          getOfflineSnapshot<PublicNoticeItem[]>(OFFLINE_PUBLIC_NOTICES_KEY),
          getAdminOfflineQueue().catch(() => []),
        ]);
        const merged = mergeNoticesWithOfflineQueue(cached || [], queue, 'Farhan Gazi Admin', {
          publicOnly: true,
        });
        if (active) setNotices(merged);
      } finally {
        if (active) setLoading(false);
      }
    };
    void load();
    return () => {
      active = false;
    };
  }, []);

  const pinnedNotices = notices.filter((n) => n.isPinned);
  const topBarNotices = pinnedNotices.length > 0 ? pinnedNotices : notices.slice(0, 3);

  const getTypeMeta = (type: PublicNoticeItem['noticeType']) => {
    if (type === 'PUBLIC_POST') {
      return {
        label: lang === 'bn' ? 'পাবলিক পোস্ট' : 'Public Post',
        badgeCls: 'bg-blue-50 text-[#0A3D91] border-blue-200',
      };
    }
    if (type === 'EVENT') {
      return {
        label: lang === 'bn' ? 'অনুষ্ঠান / মাহফিল' : 'Event / Program',
        badgeCls: 'bg-amber-50 text-amber-800 border-amber-200',
      };
    }
    return {
      label: lang === 'bn' ? 'জরুরি নোটিশ' : 'Official Notice',
      badgeCls: 'bg-emerald-50 text-[#0B5D2E] border-emerald-200',
    };
  };

  const formatDate = (iso: string) => {
    try {
      return new Date(iso).toLocaleDateString(lang === 'bn' ? 'bn-BD' : 'en-IN', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
      });
    } catch {
      return iso.slice(0, 10);
    }
  };

  const handleDownloadAttachment = async (item: PublicNoticeItem) => {
    setDownloadErr(null);
    setDownloadingId(item.id);
    try {
      await downloadNoticeAttachmentBlob(item.id, item.attachmentName || `notice-${item.id}-file`);
    } catch (err) {
      setDownloadErr(
        err instanceof Error
          ? err.message
          : lang === 'bn'
            ? 'ফাইল ডাউনলোড করা যায়নি।'
            : 'Failed to download attached file.'
      );
    } finally {
      setDownloadingId(null);
    }
  };

  if (loading && notices.length === 0 && mode === 'bar') {
    return null;
  }

  return (
    <>
      {/* Top Pinned Notice Bar */}
      {(mode === 'bar' || mode === 'both') && topBarNotices.length > 0 && (
        <section
          aria-label={lang === 'bn' ? 'অনলাইন নোটিশ বার' : 'Online Notice Bar'}
          className="w-full max-w-4xl rounded-xl border border-amber-300 bg-gradient-to-r from-[#0B5D2E] via-[#094A25] to-[#0B5D2E] text-white shadow-xs px-3.5 py-2.5"
        >
          <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-3">
            <div className="inline-flex items-center gap-1.5 rounded-lg bg-[#D4AF37] text-slate-950 px-2.5 py-1 text-[11px] font-bold shrink-0 w-fit">
              <Megaphone className="h-3.5 w-3.5" />
              <span>{lang === 'bn' ? 'অনলাইন নোটিশ বার' : 'NOTICE BAR'}</span>
            </div>
            <div className="flex-1 flex flex-wrap items-center gap-x-3 gap-y-1.5 text-xs">
              {topBarNotices.map((n, idx) => (
                <button
                  key={n.id}
                  type="button"
                  onClick={() => setSelectedNotice(n)}
                  className="inline-flex items-center gap-1.5 text-left text-emerald-50 hover:text-[#F4D06F] font-medium transition-colors"
                >
                  {idx > 0 && <span className="text-white/30">•</span>}
                  {n.isPinned && <Pin className="h-3 w-3 text-[#F4D06F] shrink-0" />}
                  <span className="underline-offset-2 hover:underline font-semibold">
                    {n.title}
                  </span>
                  {n.imageDataUrl && <ImageIcon className="h-3 w-3 text-[#F4D06F] shrink-0" />}
                  {n.hasAttachment && <FileText className="h-3 w-3 text-emerald-200 shrink-0" />}
                </button>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Full Public Notice & Photo Post Cards */}
      {(mode === 'board' || mode === 'both') && (
        <section
          id="public-notice-board"
          aria-label={lang === 'bn' ? 'মাদ্রাসা নোটিশ বোর্ড' : 'Madrasa Notice Board'}
          className="w-full max-w-4xl bg-white border border-slate-200 rounded-2xl p-5 sm:p-6 shadow-sm space-y-4 scroll-mt-4"
        >
          <div className="flex flex-wrap items-center justify-between gap-2 border-b border-slate-100 pb-3">
            <div className="flex items-center gap-2.5">
              <div className="h-9 w-9 rounded-xl bg-emerald-50 border border-emerald-200 flex items-center justify-center text-[#0B5D2E] shrink-0">
                <Bell className="h-4.5 w-4.5" />
              </div>
              <div>
                <h2 className="text-base sm:text-lg font-bold text-slate-900">
                  {lang === 'bn'
                    ? 'নোটিশ বোর্ড — অফিশিয়াল নোটিশ, ছবি ও পাবলিক পোস্ট'
                    : 'Notice Board — Official Madrasa Notices, Photos & Posts'}
                </h2>
                <p className="text-xs text-slate-500">
                  {lang === 'bn'
                    ? 'অফলাইন বা অনলাইন অ্যাডমিন পোর্টাল থেকে প্রকাশিত সাম্প্রতিক নোটিশ, ছবি ও সংযুক্ত ফাইল দেখুন'
                    : 'View notices, photos, and downloadable documents published by Admin (syncs automatically from offline/online)'}
                </p>
              </div>
            </div>
            <span className="font-mono-num text-xs font-bold px-2.5 py-1 rounded-lg bg-slate-100 text-slate-700">
              {notices.length} {lang === 'bn' ? 'টি নোটিশ' : 'Notices'}
            </span>
          </div>

          {downloadErr && (
            <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs font-medium text-[#DC2626]">
              {downloadErr}
            </div>
          )}

          {notices.length === 0 ? (
            <div className="rounded-xl border border-dashed border-slate-200 bg-slate-50/60 px-4 py-6 text-center text-xs sm:text-sm text-slate-500">
              {loading
                ? lang === 'bn'
                  ? 'নোটিশ বোর্ড লোড হচ্ছে...'
                  : 'Loading Notice Board...'
                : lang === 'bn'
                  ? 'এখনও কোনো পাবলিক নোটিশ প্রকাশিত হয়নি। অ্যাডমিন পোর্টাল (অনলাইন বা অফলাইন) থেকে নোটিশ বা ছবি পোস্ট করলে এখানে দেখা যাবে।'
                  : 'No public notices posted yet. Notices or photos published by Admin (offline or online) will appear here.'}
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {notices.map((item) => {
              const meta = getTypeMeta(item.noticeType);
              return (
                <article
                  key={item.id}
                  className="rounded-xl border border-slate-200 bg-slate-50/50 hover:bg-white transition-colors overflow-hidden flex flex-col justify-between"
                >
                  <div>
                    {item.imageDataUrl && (
                      <button
                        type="button"
                        onClick={() =>
                          setLightboxImage({ src: item.imageDataUrl!, title: item.title })
                        }
                        aria-label={`${item.title} ${lang === 'bn' ? 'ছবি বড় করে দেখুন' : 'View full image'}`}
                        className="w-full h-44 bg-slate-100 border-b border-slate-200 overflow-hidden block group"
                      >
                        <img
                          src={item.imageDataUrl}
                          alt={item.title}
                          className="w-full h-full object-cover group-hover:scale-[1.02] transition-transform duration-200"
