                <span>
                  {lang === 'bn' ? 'প্রকাশক:' : 'Published By:'}{' '}
                  <strong className="text-slate-700">{selectedNotice.createdByName}</strong>
                </span>
                <span>{formatDate(selectedNotice.createdAt)}</span>
              </div>
            </div>

            <div className="px-5 py-3.5 border-t border-slate-200 bg-slate-50 flex flex-wrap items-center justify-end gap-2">
              <button
                type="button"
                onClick={() => void printNoticeDocument(selectedNotice, lang)}
                className="h-9 px-3.5 rounded-xl bg-[#0B5D2E] hover:bg-[#094A25] text-white text-xs font-bold inline-flex items-center gap-1.5"
              >
                <Printer className="h-3.5 w-3.5" />
                <span>{lang === 'bn' ? 'প্রিন্ট / PDF' : 'Print / PDF'}</span>
              </button>
              {selectedNotice.hasAttachment && (
                <button
                  type="button"
                  disabled={downloadingId === selectedNotice.id}
                  onClick={() => void handleDownloadAttachment(selectedNotice)}
                  className="h-9 px-3.5 rounded-xl bg-[#0A3D91] hover:bg-[#083073] text-white text-xs font-bold inline-flex items-center gap-1.5"
                >
                  <Download className="h-3.5 w-3.5" />
                  <span>
                    {selectedNotice.attachmentName ||
                      (lang === 'bn' ? 'সংযুক্ত ফাইল ডাউনলোড' : 'Download Attachment')}
                  </span>
                </button>
              )}
              <button
                type="button"
                onClick={() => setSelectedNotice(null)}
                className="h-9 px-4 rounded-xl border border-slate-300 bg-white hover:bg-slate-100 text-slate-700 text-xs font-bold"
              >
                {lang === 'bn' ? 'বন্ধ করুন' : 'Close'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Full Image Lightbox */}
      {lightboxImage && (
        <div
          className="fixed inset-0 z-50 bg-black/80 flex items-center justify-center p-4"
          role="dialog"
          aria-modal="true"
        >
          <div className="relative max-w-4xl w-full bg-slate-900 rounded-2xl overflow-hidden border border-slate-700">
            <div className="flex items-center justify-between px-4 py-3 border-b border-slate-800 text-white">
              <span className="text-sm font-semibold truncate">{lightboxImage.title}</span>
              <button
                type="button"
                aria-label="Close image preview"
                onClick={() => setLightboxImage(null)}
                className="p-1 rounded-lg hover:bg-white/10"
              >
                <X className="h-5 w-5" />
              </button>
            </div>
            <div className="p-3 bg-black flex items-center justify-center">
              <img
                src={lightboxImage.src}
                alt={lightboxImage.title}
                className="max-h-[78vh] w-auto object-contain"
              />
            </div>
          </div>
        </div>
      )}
    </>
  );
}

import { useState } from 'react';
import { Download, X } from 'lucide-react';
import { usePWAInstall } from '../hooks/usePWAInstall';
import type { Language } from '../types/app';

export function PWAInstallButton({ lang }: { lang: Language }) {
