  if (isIOS) {
    return (
      <>
        <button
          type="button"
          onClick={() => setShowIOSGuide(true)}
          className="inline-flex items-center gap-1.5 rounded-lg border border-slate-300 bg-white px-3 py-2 text-xs font-medium text-slate-700 hover:bg-slate-50 whitespace-nowrap shrink-0 min-h-[40px]"
        >
          <Download className="h-4 w-4" />
          <span>{lang === 'bn' ? 'iOS ইনস্টল' : 'Install on iOS'}</span>
        </button>

        {showIOSGuide && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
            <div className="w-full max-w-sm rounded-2xl bg-white p-6 border border-slate-200 shadow-xl">
              <div className="flex items-center justify-between">
                <h3 className="text-base font-bold text-slate-900">
                  {lang === 'bn' ? 'আইফোন / আইপ্যাডে ইনস্টল করুন' : 'Install on iPhone / iPad'}
                </h3>
                <button
                  type="button"
                  aria-label="Close install instructions"
                  onClick={() => setShowIOSGuide(false)}
                  className="p-2 text-slate-500 hover:text-slate-800"
                >
                  <X className="h-4 w-4" />
                </button>
              </div>
              <ol className="mt-3 space-y-2 text-sm text-slate-600 list-decimal pl-5">
                <li>
                  {lang === 'bn'
                    ? 'Safari টুলবারে Share আইকনে ট্যাপ করুন।'
                    : 'Tap the Share button in the Safari toolbar.'}
                </li>
                <li>
                  {lang === 'bn'
                    ? 'নিচে স্ক্রল করে "Add to Home Screen" নির্বাচন করুন।'
                    : 'Scroll down and tap "Add to Home Screen".'}
                </li>
              </ol>
            </div>
          </div>
        )}
      </>
    );
  }

  return null;
}

import { useEffect, useRef, useState } from 'react';
import { Download, Printer, X } from 'lucide-react';
import { apiFetch } from '../services/api';
import { downloadReceiptPdf } from '../services/exportUtils';
import { getOfflineSnapshot, saveOfflineSnapshot } from '../services/offlineDb';
import {
  getPreferredPaperSize,
  printReceiptA6,
  setPreferredPaperSize,
  type ReceiptPaperSize,
} from '../services/printReceipt';
import { formatCurrency, t } from '../i18n/translations';
import type { Language, ReceiptData } from '../types/app';

const AUTO_PRINT_STORAGE_KEY = 'skm_auto_print_a6';

interface ReceiptModalProps {
  lang: Language;
  receiptNumber: string;
  autoPrint?: boolean;
  onClose: () => void;
}

export function ReceiptModal({ lang, receiptNumber, autoPrint = false, onClose }: ReceiptModalProps) {
  const [receipt, setReceipt] = useState<ReceiptData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [autoPrintEnabled, setAutoPrintEnabled] = useState<boolean>(() => {
    try {
      return localStorage.getItem(AUTO_PRINT_STORAGE_KEY) !== 'false';
    } catch {
      return true;
    }
  });
  const [paperSize, setPaperSize] = useState<ReceiptPaperSize>(() => getPreferredPaperSize());
  const printedReceiptRef = useRef<string | null>(null);

  useEffect(() => {
    let active = true;
    setLoading(true);
    setError(null);
    printedReceiptRef.current = null;

    const loadReceipt = async () => {
      const cached = await getOfflineSnapshot<ReceiptData>(`receipt:${receiptNumber}`);
      const isOfflineNoNet = typeof navigator !== 'undefined' && !navigator.onLine;
      if ((isOfflineNoNet || receiptNumber.startsWith('OFF-')) && cached) {
        if (active) {
          setReceipt(cached);
          setLoading(false);
        }
        return;
      }

      try {
        const res = await apiFetch<{ receipt: ReceiptData }>(
          `/api/receipts/${encodeURIComponent(receiptNumber)}`
        );
        await saveOfflineSnapshot(`receipt:${receiptNumber}`, res.receipt);
        if (active) setReceipt(res.receipt);
      } catch (err) {
        if (cached) {
          if (active) setReceipt(cached);
        } else if (active) {
          setError(err instanceof Error ? err.message : 'Failed to load receipt.');
        }
      } finally {
        if (active) setLoading(false);
      }
    };

    void loadReceipt();
    return () => {
      active = false;
    };
  }, [receiptNumber]);

  useEffect(() => {
    if (
      autoPrint &&
      autoPrintEnabled &&
      receipt &&
      !loading &&
      printedReceiptRef.current !== receipt.receiptNumber
    ) {
      printedReceiptRef.current = receipt.receiptNumber;
      const timer = setTimeout(() => {
        void printReceiptA6(receipt, lang, paperSize);
      }, 320);
      return () => clearTimeout(timer);
    }
  }, [autoPrint, autoPrintEnabled, receipt, loading, lang, paperSize]);

  const handleToggleAutoPrint = (checked: boolean) => {
    setAutoPrintEnabled(checked);
    try {
      localStorage.setItem(AUTO_PRINT_STORAGE_KEY, checked ? 'true' : 'false');
    } catch {
      // ignore storage errors
    }
  };

  const handlePaperSizeChange = (next: ReceiptPaperSize) => {
    setPaperSize(next);
    setPreferredPaperSize(next);
  };

  const prevDueList = receipt?.previousPendingDues || [];
  const totalPrevDue = Number(receipt?.totalPreviousDueAmount || 0);
  const currentSelectedDue = receipt?.breakdown
    ? receipt.breakdown.currentYearRemainingDue
    : Number(receipt?.remainingDue || 0);
  const combinedTotalDue = receipt?.breakdown
    ? receipt.breakdown.previousYearsRemainingDue > 0
      ? receipt.breakdown.totalRemainingDue
      : receipt.breakdown.totalRemainingDue + totalPrevDue
    : Number(receipt?.remainingDue || 0) + totalPrevDue;

  const isAdvanceYear = Boolean(
    receipt &&
      (receipt.isAdvanceYearPayment ||
        receipt.paymentYear > (receipt.activeReferenceYear || new Date().getFullYear()))
  );

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/60 p-4 overflow-y-auto">
      <div className="w-full max-w-lg rounded-2xl bg-white shadow-2xl overflow-hidden my-6">
        {/* Top Action Bar (hidden during print) */}
        <div className="no-print bg-slate-900 text-white px-5 py-3 flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-2.5 min-w-0">
            <span className="text-sm font-semibold font-mono-num truncate">
              {lang === 'bn' ? `রসিদ আইডি #${receiptNumber}` : `Receipt ID #${receiptNumber}`}
            </span>
            <span className="text-[11px] font-medium text-emerald-300 whitespace-nowrap">
              · {paperSize === '4x6' ? '4"×6" (4×6 in)' : 'A6 (105×148mm)'}
            </span>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <select
              aria-label="Paper size"
              value={paperSize}
              onChange={(e) => handlePaperSizeChange(e.target.value as ReceiptPaperSize)}
              className="rounded-lg bg-slate-800 border border-slate-700 px-2 py-1.5 text-[11px] font-semibold text-white"
            >
              <option value="4x6">4" × 6" কাগজ</option>
              <option value="A6">A6 কাগজ</option>
            </select>
            <label className="inline-flex items-center gap-1.5 rounded-lg bg-slate-800 px-2.5 py-1.5 text-[11px] font-medium text-slate-200 cursor-pointer select-none">
              <input
                type="checkbox"
                checked={autoPrintEnabled}
                onChange={(e) => handleToggleAutoPrint(e.target.checked)}
                className="h-3.5 w-3.5 rounded border-slate-500 text-[#16A34A] focus:ring-[#16A34A]"
              />
              <span>
                {lang === 'bn'
                  ? `অটো প্রিন্ট (${paperSize === '4x6' ? '4"×6"' : 'A6'})`
                  : `Auto Print (${paperSize === '4x6' ? '4"×6"' : 'A6'})`}
              </span>
            </label>
            {receipt && (
              <>
                <button
                  type="button"
                  onClick={() => void downloadReceiptPdf(receipt, paperSize)}
                  className="inline-flex items-center gap-1.5 rounded-lg bg-[#0A3D91] hover:bg-[#083073] px-3 py-2 text-xs font-semibold text-white whitespace-nowrap"
                >
                  <Download className="h-4 w-4" />
                  <span>
                    {lang === 'bn'
                      ? `${paperSize === '4x6' ? '4"×6"' : 'A6'} PDF ডাউনলোড`
                      : `Download ${paperSize === '4x6' ? '4"×6"' : 'A6'} PDF`}
                  </span>
                </button>
                <button
                  type="button"
                  onClick={() => void printReceiptA6(receipt, lang, paperSize)}
                  className="inline-flex items-center gap-1.5 rounded-lg bg-[#16A34A] hover:bg-[#15803D] px-3 py-2 text-xs font-semibold text-white whitespace-nowrap"
                >
                  <Printer className="h-4 w-4" />
                  <span>
                    {lang === 'bn'
                      ? `${paperSize === '4x6' ? '4"×6"' : 'A6'} প্রিন্ট করুন`
                      : `Print (${paperSize === '4x6' ? '4"×6"' : 'A6'})`}
                  </span>
                </button>
              </>
            )}
            <button
              type="button"
              aria-label="Close receipt"
              onClick={onClose}
              className="p-2 text-slate-300 hover:text-white"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>

        {/* Printable Receipt Surface (A6 Portrait Ready) */}
        <div id="printable-receipt" className="p-4 sm:p-5 bg-white text-slate-900">
          {loading ? (
            <p className="text-sm text-slate-500 py-10 text-center">{t(lang, 'loading')}</p>
          ) : error ? (
            <p className="text-sm text-[#DC2626] py-10 text-center">{error}</p>
          ) : receipt ? (
            <div className="a6-frame border-2 border-[#0B5D2E] rounded-xl p-4 space-y-3.5">
              {/* Official Logo & Madrasa Header */}
              <div className="a6-header flex flex-col sm:flex-row items-center gap-3 border-b-2 border-[#D4AF37] pb-3 text-center sm:text-left">
                <img
                  src="/assets/madrasa-logo.png"
                  alt="Saidpur kudduchiyya madrasah Logo"
                  className="a6-logo h-14 w-14 object-contain aspect-square shrink-0"
                />
                <div className="flex-1 min-w-0">
                  <h2 className="a6-title-bn text-base font-bold text-[#0B5D2E]">
                    সৈয়দপুর কুদ্দুসিয়া মাদ্রাসা
                  </h2>
                  <p className="a6-title-en text-xs font-bold text-slate-900 tracking-wide">
                    Saidpur kudduchiyya madrasah
                  </p>
                  <p className="a6-subtitle text-[11px] text-slate-600 mt-0.5">
                    Saidpur, Taki · Est. 1986 · Official Payment Receipt ({paperSize === '4x6' ? '4"×6"' : 'A6'})
                  </p>
                </div>
                <div className="text-center sm:text-right shrink-0">
                  <div className="text-[10px] font-semibold text-slate-500">
                    {t(lang, 'receiptNo')}
                  </div>
                  <div className="text-xs font-bold font-mono-num text-[#0A3D91]">
                    {receipt.receiptNumber}
                  </div>
                  {isAdvanceYear && (
                    <div className="mt-1 inline-block rounded bg-blue-50 border border-blue-200 px-1.5 py-0.5 text-[10px] font-bold text-[#0A3D91]">
                      {lang === 'bn'
                        ? `আগত বছরের অগ্রিম (${receipt.paymentYear})`
                        : `Upcoming Year (${receipt.paymentYear})`}
                    </div>
                  )}
                </div>
              </div>

              {/* Member & Payment Details */}
              <div className="a6-meta-grid grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs">
                <div className="space-y-1">
                  <div>
                    <span className="text-slate-500">{t(lang, 'memberId')}: </span>
                    <strong className="font-mono-num text-[#0B5D2E]">{receipt.memberCode}</strong>
                  </div>
                  <div>
                    <span className="text-slate-500">{t(lang, 'memberName')}: </span>
                    <strong>{receipt.issuedToName}</strong>
                  </div>
                  <div>
                    <span className="text-slate-500">{t(lang, 'guardianName')}: </span>
                    <span>{receipt.guardianName}</span>
                  </div>
                  <div>
                    <span className="text-slate-500">{t(lang, 'mobile')}: </span>
                    <span className="font-mono-num">{receipt.mobile}</span>
                  </div>
                  <div>
                    <span className="text-slate-500">{t(lang, 'address')}: </span>
                    <span>{receipt.address}</span>
                  </div>
                </div>

                <div className="a6-meta-right space-y-1 sm:text-right">
                  <div>
                    <span className="text-slate-500">{t(lang, 'paymentYear')}: </span>
                    <strong className="font-mono-num">
                      {receipt.paymentYear}
                      {isAdvanceYear
                        ? lang === 'bn'
                          ? ' (আগত বছর)'
                          : ' (Advance)'
                        : ''}
                    </strong>
                  </div>
                  <div>
                    <span className="text-slate-500">{lang === 'bn' ? 'তারিখ ও সময়' : 'Date & Time'}: </span>
                    <span className="font-mono-num">
                      {receipt.paymentDate} {receipt.paymentTime}
                    </span>
                  </div>
                  <div>
                    <span className="text-slate-500">{t(lang, 'paymentMethod')}: </span>
                    <strong>{receipt.paymentMethod}</strong>
                  </div>
                  <div>
                    <span className="text-slate-500">{t(lang, 'receivedBy')}: </span>
                    <strong>
                      {receipt.issuedByName}
                      {receipt.issuedByUsername ? ` (@${receipt.issuedByUsername})` : ''}
                    </strong>
                  </div>
                </div>
              </div>

              {/* Financial Summary Table with Explicit "বকেয়া" Balance */}
              <table className="a6-table w-full border border-slate-200 text-xs">
                <tbody>
                  {receipt.breakdown ? (
                    <>
                      <tr className="border-b border-slate-200">
                        <td className="py-1.5 px-3 bg-slate-50 font-medium text-slate-600">
                          <div>
                            {lang === 'bn'
                              ? 'বিগত বছরের চাঁদা পরিশোধ'
                              : 'Previous Years Paid'}
                          </div>
                          {receipt.breakdown.yearLines.some((l) => l.isPreviousYear) && (
                            <div className="text-[10px] text-slate-500 font-mono-num">
                              {receipt.breakdown.yearLines
                                .filter((l) => l.isPreviousYear)
                                .map((l) => `${l.year}: ${formatCurrency(l.paidNow)}`)
                                .join(', ')}
                            </div>
                          )}
                        </td>
                        <td className="py-1.5 px-3 text-right font-mono-num font-semibold text-[#0B5D2E]">
                          {formatCurrency(receipt.breakdown.previousYearsPaid)}
                        </td>
                      </tr>
                      <tr className="border-b border-slate-200">
                        <td className="py-1.5 px-3 bg-slate-50 font-medium text-slate-600">
                          {lang === 'bn'
                            ? `${isAdvanceYear ? 'আগত' : 'চলতি'} বছরের চাঁদা পরিশোধ (${receipt.breakdown.referenceYear})`
                            : `${isAdvanceYear ? 'Upcoming' : 'Current'} Year Paid (${receipt.breakdown.referenceYear})`}
                        </td>
                        <td className="py-1.5 px-3 text-right font-mono-num font-semibold text-[#0B5D2E]">
                          {formatCurrency(receipt.breakdown.currentYearPaid)}
                        </td>
                      </tr>
                      <tr className="border-b border-slate-200">
                        <td className="py-2 px-3 bg-emerald-50/70 font-bold text-[#0B5D2E]">
                          {lang === 'bn' ? 'মোট পরিশোধিত টাকা' : 'Total Amount Paid'}
                        </td>
                        <td className="py-2 px-3 text-right font-mono-num text-sm font-bold text-[#16A34A]">
                          {formatCurrency(receipt.breakdown.totalPaid)}
                        </td>
                      </tr>
                      {receipt.breakdown.previousYearsRemainingDue > 0 && (
                        <tr className="border-b border-slate-200">
                          <td className="py-1.5 px-3 bg-amber-50/70 font-semibold text-amber-800">
                            {lang === 'bn' ? 'পূর্বের বছরের বকেয়া' : 'Previous Years Due (Bokeya)'}
                          </td>
                          <td className="py-1.5 px-3 text-right font-mono-num font-bold text-[#DC2626]">
                            {formatCurrency(receipt.breakdown.previousYearsRemainingDue)}
                          </td>
                        </tr>
                      )}
                      {currentSelectedDue > 0 && (
                        <tr className="border-b border-slate-200">
                          <td className="py-1.5 px-3 bg-red-50/50 font-semibold text-slate-700">
                            {lang === 'bn'
                              ? `${receipt.paymentYear} সালের বকেয়া`
                              : `Due for ${receipt.paymentYear}`}
                          </td>
                          <td className="py-1.5 px-3 text-right font-mono-num font-bold text-[#DC2626]">
                            {formatCurrency(currentSelectedDue)}
                          </td>
                        </tr>
                      )}
                      <tr>
                        <td className="py-2 px-3 bg-slate-50 font-bold text-slate-900">
                          {lang === 'bn' ? 'বকেয়া টাকার পরিমাণ (মোট বকেয়া)' : 'Remaining Due Balance (Bokeya)'}
                        </td>
                        <td
                          className={`py-2 px-3 text-right font-mono-num text-sm font-bold ${
                            combinedTotalDue > 0 ? 'text-[#DC2626]' : 'text-[#16A34A]'
                          }`}
                        >
                          {formatCurrency(combinedTotalDue)}
                          {combinedTotalDue === 0
                            ? lang === 'bn'
                              ? ' (পরিশোধিত)'
                              : ' (Paid)'
                            : ''}
                        </td>
                      </tr>
                    </>
                  ) : (
                    <>
                      <tr className="border-b border-slate-200">
                        <td className="py-2 px-3 bg-slate-50 font-medium text-slate-600">
                          {lang === 'bn'
                            ? `${isAdvanceYear ? 'আগত বছরের নির্ধারিত ফি' : t(lang, 'expectedFee')} (${receipt.paymentYear})`
                            : `${t(lang, 'expectedFee')} (${receipt.paymentYear})`}
                        </td>
                        <td className="py-2 px-3 text-right font-mono-num font-semibold">
                          {formatCurrency(receipt.expectedFee)}
                        </td>
                      </tr>
                      <tr className="border-b border-slate-200">
                        <td className="py-2 px-3 bg-emerald-50/70 font-bold text-[#0B5D2E]">
                          {t(lang, 'paidAmount')}
                        </td>
                        <td className="py-2 px-3 text-right font-mono-num text-sm font-bold text-[#16A34A]">
                          {formatCurrency(receipt.amountPaid)}
                        </td>
                      </tr>
                      {totalPrevDue > 0 && (
                        <tr className="border-b border-slate-200">
                          <td className="py-1.5 px-3 bg-amber-50/70 font-semibold text-amber-900">
                            <div>
                              {lang === 'bn' ? 'পূর্বের বছরের বকেয়া' : 'Previous Years Due (Bokeya)'}
                            </div>
                            <div className="text-[10px] font-mono-num text-amber-800">
                              {prevDueList
                                .map((d) => `${d.year}: ${formatCurrency(d.dueAmount)}`)
                                .join(', ')}
                            </div>
                          </td>
                          <td className="py-1.5 px-3 text-right font-mono-num font-bold text-[#DC2626]">
                            {formatCurrency(totalPrevDue)}
                          </td>
                        </tr>
                      )}
                      {totalPrevDue > 0 && receipt.remainingDue > 0 && (
                        <tr className="border-b border-slate-200">
                          <td className="py-1.5 px-3 bg-red-50/50 font-medium text-slate-700">
                            {lang === 'bn'
                              ? `${receipt.paymentYear} সালের বকেয়া`
                              : `${receipt.paymentYear} Remaining Due`}
                          </td>
                          <td className="py-1.5 px-3 text-right font-mono-num font-semibold text-[#DC2626]">
                            {formatCurrency(receipt.remainingDue)}
                          </td>
                        </tr>
                      )}
                      <tr>
                        <td className="py-2 px-3 bg-slate-50 font-bold text-slate-900">
                          {lang === 'bn'
                            ? totalPrevDue > 0
                              ? 'মোট বকেয়া টাকার পরিমাণ'
                              : 'বকেয়া টাকার পরিমাণ (বকেয়া)'
                            : 'Due Balance (Bokeya)'}
                        </td>
                        <td
                          className={`py-2 px-3 text-right font-mono-num text-sm font-bold ${
                            combinedTotalDue > 0 ? 'text-[#DC2626]' : 'text-[#16A34A]'
                          }`}
                        >
                          {formatCurrency(combinedTotalDue)}
                          {combinedTotalDue === 0
                            ? lang === 'bn'
                              ? ' (পরিশোধিত)'
                              : ' (Paid)'
                            : ''}
                        </td>
                      </tr>
                    </>
                  )}
                </tbody>
              </table>

              {receipt.notes && (
                <p className="text-[11px] text-slate-600">
                  <strong>{t(lang, 'notes')}:</strong> {receipt.notes}
                </p>
              )}

              {/* Signatures & Verification */}
              <div className="a6-signatures pt-6 grid grid-cols-2 gap-6 text-[11px] text-slate-600">
                <div>
                  <div className="a6-sig-line border-t border-slate-400 pt-1 w-36">
                    {lang === 'bn' ? 'সদস্য / প্রদানকারীর স্বাক্ষর' : 'Member / Payer Signature'}
                  </div>
                </div>
                <div className="flex flex-col items-end">
                  <div className="a6-sig-line border-t border-slate-400 pt-1 w-40 text-right">
                    {lang === 'bn'
                      ? 'অনুমোদিত স্বাক্ষর ও মাদ্রাসা সীল'
                      : 'Authorized Signature & Seal'}
                  </div>
                </div>
              </div>

              <div className="a6-footer pt-2 border-t border-slate-100 flex items-center justify-between text-[10px] text-slate-400 font-mono-num">
                <span>Ref: {receipt.verificationHash}</span>
                <span>Saidpur kudduchiyya madrasah · {paperSize === '4x6' ? '4"×6"' : 'A6'}</span>
              </div>
            </div>
          ) : null}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Download, FileSpreadsheet, FileText, Printer, Receipt } from 'lucide-react';
import { apiFetch } from '../services/api';
import {
  exportReportToPdf,
  exportRowsToExcel,
  fetchAndDownloadReceiptPdf,
} from '../services/exportUtils';
import {
  getAdminOfflineQueue,
  getCachedMembersSnapshot,
  getOfflineSnapshot,
  saveOfflineSnapshot,
} from '../services/offlineDb';
import {
  mergeMembersWithOfflineQueue,
  mergePaymentsWithOfflineQueue,
} from '../services/offlineOverlay';
import { printReceiptByNumber, printReportTable } from '../services/printReceipt';
import { t } from '../i18n/translations';
import { START_YEAR } from '../domain/membershipRules';
import type { Language, MemberListItem, PaymentItem } from '../types/app';

const REPORT_TYPES = [
  { id: 'all-members', en: 'All Members Report', bn: 'সকল সদস্যের রিপোর্ট' },
  { id: 'active-members', en: 'Active Members Report', bn: 'সক্রিয় সদস্যের রিপোর্ট' },
  { id: 'inactive-members', en: 'Inactive Members Report', bn: 'নিষ্ক্রিয় সদস্যের রিপোর্ট' },
  { id: 'yearly-collection', en: 'Yearly Collection Report', bn: 'বাৎসরিক আদায় রিপোর্ট' },
  { id: 'paid-members', en: 'Paid Members Report', bn: 'পরিশোধিত সদস্যের রিপোর্ট' },
  { id: 'pending-members', en: 'Pending Members Report', bn: 'বকেয়া সদস্যের রিপোর্ট' },
  { id: 'member-history', en: 'Member-wise Payment History', bn: 'সদস্যভিত্তিক পেমেন্ট ইতিহাস' },
  { id: 'staff-activity', en: 'Staff Activity Report', bn: 'স্টাফ কার্যক্রম রিপোর্ট' },
  { id: 'total-collection', en: 'Total Collection Report', bn: 'মোট আদায় রিপোর্ট' },
  { id: 'outstanding-dues', en: 'Outstanding Dues Report', bn: 'সর্বমোট বকেয়া রিপোর্ট' },
];

export function ReportsView({
  lang,
  selectedYear,
  onOpenReceipt,
}: {
  lang: Language;
  selectedYear: number;
  onOpenReceipt?: (receiptNumber: string) => void;
}) {
  const [reportType, setReportType] = useState('yearly-collection');
  const [year, setYear] = useState<string>(String(selectedYear));
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [memberId, setMemberId] = useState('');
  const [staffId, setStaffId] = useState('');

  const [membersOpt, setMembersOpt] = useState<MemberListItem[]>([]);
  const [staffOpt, setStaffOpt] = useState<Array<{ id: number; fullName: string }>>([]);
  const [rows, setRows] = useState<Array<Record<string, unknown>>>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    apiFetch<{ members: MemberListItem[] }>(`/api/members?year=${selectedYear}`)
      .then((res) => setMembersOpt(res.members))
      .catch(async () => {
        const cached = await getCachedMembersSnapshot();
        if (cached.length > 0) setMembersOpt(cached);
      });
    apiFetch<{ staff: Array<{ id: number; fullName: string }> }>('/api/staff')
      .then((res) => setStaffOpt(res.staff))
      .catch(() => {});
  }, [selectedYear]);

  const buildLocalReportFallback = async (key: string): Promise<Array<Record<string, unknown>> | null> => {
    const cachedReport = await getOfflineSnapshot<Array<Record<string, unknown>>>(key);
    if (cachedReport) return cachedReport;

    const [cachedMembers, cachedPayments, queue] = await Promise.all([
      getCachedMembersSnapshot(),
      getOfflineSnapshot<PaymentItem[]>('payments:latest'),
      getAdminOfflineQueue(),
    ]);
    const refY = Number(year) || selectedYear;
    const mergedMembers = mergeMembersWithOfflineQueue(cachedMembers, queue, refY);
    if (reportType === 'all-members' || reportType === 'active-members' || reportType === 'inactive-members') {
      const list = mergedMembers.filter((m) =>
        reportType === 'all-members'
          ? true
          : reportType === 'active-members'
            ? m.status === 'ACTIVE'
            : m.status === 'INACTIVE'
      );
      return list.map((m) => ({
        memberCode: m.memberCode,
        name: m.name,
        mobile: m.mobile,
        address: m.address,
        annualFee: m.defaultAnnualFee,
        status: m.status,
      }));
    }
    if (reportType === 'pending-members' || reportType === 'outstanding-dues') {
      return mergedMembers
        .filter((m) => m.status === 'ACTIVE' && m.totalOutstanding > 0)
        .map((m) => ({
          memberCode: m.memberCode,
          name: m.name,
          mobile: m.mobile,
          currentYearStatus: m.currentYearStatus,
          totalOutstanding: m.totalOutstanding,
        }));
    }
    if (reportType === 'yearly-collection' && cachedPayments) {
      const mergedPays = mergePaymentsWithOfflineQueue(cachedPayments, mergedMembers, queue);
      return mergedPays
        .filter((p) => !year || p.paymentYear === Number(year))
        .map((p) => ({
          receiptNumber: p.receiptNumber,
          memberCode: p.memberCode,
          memberName: p.memberName,
          paymentYear: p.paymentYear,
          paidAmount: p.paidAmount,
          paymentDate: p.paymentDate,
          paymentMethod: p.paymentMethod,
        }));
    }
    return null;
  };

  const loadReport = async () => {
    setLoading(true);
    setError(null);
    const params = new URLSearchParams();
    if (year) params.set('year', year);
    if (fromDate) params.set('fromDate', fromDate);
    if (toDate) params.set('toDate', toDate);
    if (memberId) params.set('memberId', memberId);
    if (staffId) params.set('staffId', staffId);
    const cacheKey = `report:${reportType}:${params.toString()}`;

    if (typeof navigator !== 'undefined' && !navigator.onLine) {
      const offlineRows = await buildLocalReportFallback(cacheKey);
      if (offlineRows) {
        setRows(offlineRows);
        setLoading(false);
        return;
      }
    }

    try {
      const res = await apiFetch<{ rows: Array<Record<string, unknown>> }>(
        `/api/reports/${reportType}?${params.toString()}`
      );
      setRows(res.rows);
      await saveOfflineSnapshot(cacheKey, res.rows);
    } catch (err) {
      const offlineRows = await buildLocalReportFallback(cacheKey);
      if (offlineRows) {
        setRows(offlineRows);
      } else {
        setError(err instanceof Error ? err.message : 'Failed to load report.');
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadReport();
  }, [reportType, year, fromDate, toDate, memberId, staffId]);

  const columns = rows.length > 0 ? Object.keys(rows[0]) : [];
  const activeReportMeta = REPORT_TYPES.find((r) => r.id === reportType);
  const yearOptions = Array.from({ length: 30 }, (_, idx) => START_YEAR + idx);

  const handleExportExcel = () => {
    if (rows.length === 0) return;
    exportRowsToExcel(`skm-${reportType}-${year || 'all'}`, reportType, rows);
  };

  const handleExportPdf = () => {
    if (rows.length === 0) return;
    const body = rows.map((r) =>
      columns.map((c) => {
        const val = r[c];
        return val === null || val === undefined ? '' : String(val);
      })
    );
    exportReportToPdf(
      `skm-${reportType}-${year || 'all'}`,
      activeReportMeta?.en || reportType,
      columns,
      body
    );
  };

  return (
    <div className="space-y-5">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold text-slate-900">{t(lang, 'reports')}</h1>
          <p className="text-sm text-slate-500 mt-0.5">
            {lang === 'bn'
              ? 'সকল ১০টি রিপোর্ট · বছর, তারিখ, সদস্য ও স্টাফ অনুযায়ী ফিল্টার এবং Excel/PDF এক্সপোর্ট'
              : 'All 10 Operational & Financial Reports · Excel (.xlsx) & PDF Exports'}
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <button
            type="button"
            disabled={rows.length === 0}
            onClick={() => {
              const title =
                (lang === 'bn' ? activeReportMeta?.bn : activeReportMeta?.en) || reportType;
              void printReportTable(title, columns, rows, lang).catch((err) =>
                setError(err instanceof Error ? err.message : 'Failed to print report.')
              );
            }}
            className="inline-flex items-center gap-1.5 rounded-xl border border-slate-300 bg-white hover:bg-slate-50 text-slate-800 px-3.5 h-10 text-xs font-semibold disabled:opacity-50 whitespace-nowrap"
          >
            <Printer className="h-4 w-4 text-[#0B5D2E]" />
            <span>{lang === 'bn' ? 'প্রিন্ট করুন' : 'Print'}</span>
          </button>
          <button
            type="button"
            disabled={rows.length === 0}
            onClick={handleExportExcel}
            className="inline-flex items-center gap-1.5 rounded-xl bg-[#0B5D2E] hover:bg-[#094A25] text-white px-3.5 h-10 text-xs font-semibold disabled:opacity-50 whitespace-nowrap"
          >
            <FileSpreadsheet className="h-4 w-4" />
            <span>{t(lang, 'exportExcel')}</span>
          </button>
          <button
            type="button"
            disabled={rows.length === 0}
            onClick={handleExportPdf}
            className="inline-flex items-center gap-1.5 rounded-xl bg-[#0A3D91] hover:bg-[#083073] text-white px-3.5 h-10 text-xs font-semibold disabled:opacity-50 whitespace-nowrap"
          >
            <FileText className="h-4 w-4" />
            <span>{t(lang, 'exportPdf')}</span>
          </button>
        </div>
      </div>

      {/* Report Selector & Multi-Filter Bar */}
      <div className="rounded-xl bg-white border border-slate-200 p-4 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-6 gap-3">
        <div className="lg:col-span-2">
          <label htmlFor="rep-type" className="block text-xs font-semibold text-slate-600 mb-1">
            {lang === 'bn' ? 'রিপোর্টের ধরন' : 'Report Type'}
          </label>
          <select
            id="rep-type"
            value={reportType}
            onChange={(e) => setReportType(e.target.value)}
            className="w-full h-10 px-3 rounded-lg border border-slate-300 text-sm font-semibold bg-white"
          >
            {REPORT_TYPES.map((r) => (
              <option key={r.id} value={r.id}>
                {lang === 'bn' ? r.bn : r.en}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="rep-year" className="block text-xs font-semibold text-slate-600 mb-1">
            {t(lang, 'paymentYear')}
          </label>
          <select
            id="rep-year"
            value={year}
            onChange={(e) => setYear(e.target.value)}
            className="w-full h-10 px-3 rounded-lg border border-slate-300 text-sm font-mono-num bg-white"
          >
            {yearOptions.map((y) => (
              <option key={y} value={y}>
                {y}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="rep-from" className="block text-xs font-semibold text-slate-600 mb-1">
            {lang === 'bn' ? 'তারিখ হতে' : 'From Date'}
          </label>
          <input
            id="rep-from"
            type="date"
            value={fromDate}
            onChange={(e) => setFromDate(e.target.value)}
            className="w-full h-10 px-3 rounded-lg border border-slate-300 text-xs font-mono-num"
          />
        </div>

        <div>
          <label htmlFor="rep-to" className="block text-xs font-semibold text-slate-600 mb-1">
            {lang === 'bn' ? 'তারিখ পর্যন্ত' : 'To Date'}
          </label>
          <input
            id="rep-to"
            type="date"
            value={toDate}
            onChange={(e) => setToDate(e.target.value)}
            className="w-full h-10 px-3 rounded-lg border border-slate-300 text-xs font-mono-num"
          />
        </div>

        <div>
          <label htmlFor="rep-member" className="block text-xs font-semibold text-slate-600 mb-1">
            {lang === 'bn' ? 'সদস্য / স্টাফ' : 'Member Filter'}
          </label>
          <select
            id="rep-member"
            value={memberId}
            onChange={(e) => setMemberId(e.target.value)}
            className="w-full h-10 px-3 rounded-lg border border-slate-300 text-xs bg-white"
          >
            <option value="">All Members</option>
            {membersOpt.map((m) => (
              <option key={m.id} value={m.id}>
                {m.memberCode} - {m.name}
              </option>
            ))}
          </select>
        </div>

        {staffOpt.length > 0 && (
          <div className="lg:col-span-2">
            <label htmlFor="rep-staff" className="block text-xs font-semibold text-slate-600 mb-1">
              {lang === 'bn' ? 'স্টাফ অনুযায়ী ফিল্টার' : 'Staff Filter'}
            </label>
            <select
              id="rep-staff"
              value={staffId}
              onChange={(e) => setStaffId(e.target.value)}
              className="w-full h-10 px-3 rounded-lg border border-slate-300 text-xs bg-white"
            >
              <option value="">All Staff & Admin</option>
              {staffOpt.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.fullName}
                </option>
              ))}
            </select>
          </div>
        )}
      </div>

      {error && (
        <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-[#DC2626]">
          {error}
        </div>
      )}

      {/* Report Data Table */}
      <div className="rounded-xl bg-white border border-slate-200 overflow-hidden">
        <div className="px-5 py-3 border-b border-slate-200 flex items-center justify-between text-xs text-slate-500">
          <span className="font-semibold text-slate-800">
            {lang === 'bn' ? activeReportMeta?.bn : activeReportMeta?.en}
          </span>
          <span className="font-mono-num">{rows.length} record(s)</span>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse text-xs">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200 text-slate-600 font-semibold">
                {columns.map((col) => (
                  <th key={col} className="py-3 px-4 whitespace-nowrap">
                    {col}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                  <td colSpan={Math.max(1, columns.length)} className="py-10 text-center text-slate-500">
                    {t(lang, 'loading')}
                  </td>
                </tr>
              ) : rows.length === 0 ? (
                <tr>
                  <td colSpan={Math.max(1, columns.length)} className="py-10 text-center text-slate-500">
                    {t(lang, 'noRecords')}
                  </td>
                </tr>
              ) : (
                rows.map((row, idx) => (
                  <tr key={idx} className="hover:bg-slate-50">
                    {columns.map((col) => {
                      const val = row[col];
                      if (col === 'receiptNumber' && val && String(val).trim() !== '') {
                        const rNo = String(val);
                        return (
                          <td key={col} className="py-2.5 px-4 whitespace-nowrap font-mono-num">
                            <div className="inline-flex items-center gap-1.5">
                              <span className="font-bold text-[#0A3D91]">#{rNo}</span>
                              {onOpenReceipt && (
                                <button
                                  type="button"
                                  onClick={() => onOpenReceipt(rNo)}
                                  className="inline-flex items-center gap-1 rounded border border-emerald-200 bg-emerald-50 px-1.5 py-0.5 text-[11px] font-semibold text-[#0B5D2E] hover:bg-emerald-100"
                                >
                                  <Receipt className="h-3 w-3" />
                                  <span>{lang === 'bn' ? 'রসিদ' : 'View'}</span>
                                </button>
                              )}
                              <button
                                type="button"
                                onClick={() => {
                                  void printReceiptByNumber(rNo, lang).catch((err) =>
                                    setError(err instanceof Error ? err.message : 'Print failed.')
                                  );
                                }}
                                className="inline-flex items-center gap-1 rounded border border-emerald-200 bg-white px-1.5 py-0.5 text-[11px] font-semibold text-[#0B5D2E] hover:bg-emerald-50"
                              >
                                <Printer className="h-3 w-3" />
                                <span>{lang === 'bn' ? 'প্রিন্ট' : 'Print'}</span>
                              </button>
                              <button
                                type="button"
                                onClick={() => {
                                  fetchAndDownloadReceiptPdf(rNo).catch((err) =>
                                    setError(err instanceof Error ? err.message : 'PDF download failed.')
                                  );
                                }}
                                className="inline-flex items-center gap-1 rounded border border-blue-200 bg-blue-50 px-1.5 py-0.5 text-[11px] font-semibold text-[#0A3D91] hover:bg-blue-100"
                              >
                                <Download className="h-3 w-3" />
                                <span>PDF</span>
                              </button>
                            </div>
                          </td>
                        );
                      }
                      return (
                        <td key={col} className="py-2.5 px-4 whitespace-nowrap font-mono-num text-slate-800">
                          {val === null || val === undefined || val === '' ? '—' : String(val)}
                        </td>
                      );
                    })}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import {
  Check,
  CheckCircle2,
  Copy,
  Download,
  ExternalLink,
  FileArchive,
  FileText,
  Globe,
  HardDriveDownload,
  Laptop,
  Loader2,
  MessageCircle,
  Share2,
  Smartphone,
  Terminal,
  WifiOff,
  X,
} from 'lucide-react';
import { usePWAInstall } from '../hooks/usePWAInstall';
import {
  cacheZipBundleOffline,
  downloadPackageAsset,
  isPackageCachedOffline,
  type PackageAssetKind,
} from '../services/packageDownload';
import type { Language } from '../types/app';

const DEFAULT_SHARED_CLOUD_URL =
  'https://ais-pre-qsr24lruf76zxcxeendpqy-742281932289.asia-east1.run.app';

interface ShareInstallModalProps {
  lang: Language;
  onClose: () => void;
}

export function ShareInstallModal({ lang, onClose }: ShareInstallModalProps) {
  const { isInstallable, isInstalled, isIOS, install } = usePWAInstall();
  const [copied, setCopied] = useState(false);
  const [downloadingKind, setDownloadingKind] = useState<PackageAssetKind | 'cache-zip' | null>(null);
  const [zipCachedOffline, setZipCachedOffline] = useState(false);
  const [bundleNotice, setBundleNotice] = useState<string | null>(null);
  const [bundleError, setBundleError] = useState<string | null>(null);

  useEffect(() => {
    void isPackageCachedOffline('zip').then(setZipCachedOffline);
  }, []);

  const handleDownloadAsset = async (kind: PackageAssetKind) => {
    setBundleError(null);
    setBundleNotice(null);
    setDownloadingKind(kind);
    try {
      await downloadPackageAsset(kind);
      if (kind === 'zip') {
        setZipCachedOffline(true);
