function generateUniquePassword(length = 10): string {
  const upper = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
  const lower = 'abcdefghijkmnopqrstuvwxyz';
  const digits = '23456789';
  const symbols = '@#$%';
  const all = upper + lower + digits + symbols;
  const arr = new Uint32Array(length);
  crypto.getRandomValues(arr);
  const chars = [
    upper[arr[0] % upper.length],
    lower[arr[1] % lower.length],
    digits[arr[2] % digits.length],
    symbols[arr[3] % symbols.length],
  ];
  for (let i = 4; i < length; i++) {
    chars.push(all[arr[i] % all.length]);
  }
  return chars.join('');
}

const DEFAULT_PARTNER_PERMS = ['members:view', 'members:edit', 'payments:view', 'payments:create'];
const ADMIN_ONLY_PERM_CODES = new Set(['members:create', 'members:delete']);

export function StaffView({
