  const [tab, setTab] = useState<'STAFF' | 'LOGS' | 'GATEWAY' | 'GUIDE'>('STAFF');
  const [staffList, setStaffList] = useState<StaffMember[]>([]);
  const [permsList, setPermsList] = useState<PermissionDef[]>([]);
  const [logs, setLogs] = useState<ActivityLogRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const [staffSearch, setStaffSearch] = useState('');
  const [issuedCredentials, setIssuedCredentials] = useState<{
    username: string;
    password: string;
    fullName: string;
  } | null>(null);
  const [copiedCreds, setCopiedCreds] = useState(false);

  // Create / Edit Staff modal
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [editingStaff, setEditingStaff] = useState<StaffMember | null>(null);
  const [formUsername, setFormUsername] = useState('');
  const [formPassword, setFormPassword] = useState('');
  const [formFullName, setFormFullName] = useState('');
  const [formPhone, setFormPhone] = useState('');
  const [formEmail, setFormEmail] = useState('');
  const [formPerms, setFormPerms] = useState<string[]>(DEFAULT_PARTNER_PERMS);
  const [formActive, setFormActive] = useState(true);
  const [saving, setSaving] = useState(false);

  // Admin OTP Gateway status & editable inputs
  const [gwStatus, setGwStatus] = useState<{
    emailConfigured: boolean;
    smsGatewayConfigured: boolean;
    firebasePhoneEnabled: boolean;
    smsProvider: string;
    smtpUserMasked: string | null;
    hasFast2SmsKey: boolean;
    hasTwilioConfig: boolean;
    hasCustomSmsUrl: boolean;
    smsGatewayUrl: string;
    smsSenderId: string;
  } | null>(null);
  const [gwFast2SmsKey, setGwFast2SmsKey] = useState('');
  const [gwTwilioSid, setGwTwilioSid] = useState('');
  const [gwTwilioToken, setGwTwilioToken] = useState('');
  const [gwTwilioFrom, setGwTwilioFrom] = useState('');
  const [gwCustomUrl, setGwCustomUrl] = useState('');
  const [gwCustomKey, setGwCustomKey] = useState('');
  const [gwSenderId, setGwSenderId] = useState('SKMADRASA');
  const [gwSmtpUser, setGwSmtpUser] = useState('');
  const [gwSmtpPass, setGwSmtpPass] = useState('');
  const [gwSaving, setGwSaving] = useState(false);

  const loadData = async () => {
    setLoading(true);
    setError(null);
    try {
      const [sRes, lRes, gRes] = await Promise.all([
        apiFetch<{ staff: StaffMember[]; permissions: PermissionDef[] }>('/api/staff'),
        apiFetch<{ logs: ActivityLogRow[] }>('/api/activity-logs'),
        apiFetch<{
          emailConfigured: boolean;
          smsGatewayConfigured: boolean;
          firebasePhoneEnabled: boolean;
          smsProvider: string;
          smtpUserMasked: string | null;
          hasFast2SmsKey: boolean;
          hasTwilioConfig: boolean;
          hasCustomSmsUrl: boolean;
          smsGatewayUrl: string;
          smsSenderId: string;
        }>('/api/admin/otp-gateway').catch(() => null),
      ]);
      setStaffList(sRes.staff);
      setPermsList(sRes.permissions);
      setLogs(lRes.logs);
      if (gRes) {
        setGwStatus(gRes);
        setGwCustomUrl(gRes.smsGatewayUrl || '');
        setGwSenderId(gRes.smsSenderId || 'SKMADRASA');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load staff records.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user.roleName === 'ADMIN') {
      loadData();
    }
  }, [user.roleName]);

  const handleSaveOtpGateway = async (e: FormEvent) => {
    e.preventDefault();
    setGwSaving(true);
    setError(null);
    setNotice(null);
    try {
      const payload: Record<string, string> = {};
      if (gwFast2SmsKey.trim()) payload.fast2SmsApiKey = gwFast2SmsKey.trim();
      if (gwTwilioSid.trim()) payload.twilioAccountSid = gwTwilioSid.trim();
      if (gwTwilioToken.trim()) payload.twilioAuthToken = gwTwilioToken.trim();
      if (gwTwilioFrom.trim()) payload.twilioFromNumber = gwTwilioFrom.trim();
      if (gwCustomUrl.trim()) payload.smsGatewayUrl = gwCustomUrl.trim();
      if (gwCustomKey.trim()) payload.smsGatewayApiKey = gwCustomKey.trim();
      if (gwSenderId.trim()) payload.smsSenderId = gwSenderId.trim();
      if (gwSmtpUser.trim()) payload.smtpUser = gwSmtpUser.trim();
      if (gwSmtpPass.trim()) payload.smtpPass = gwSmtpPass.trim();

