        emailConfigured: boolean;
        smsGatewayConfigured: boolean;
        firebasePhoneEnabled: boolean;
        smsProvider: string;
        smtpUserMasked: string | null;
        hasFast2SmsKey: boolean;
        hasTwilioConfig: boolean;
        hasCustomSmsUrl: boolean;
        smsGatewayUrl: string;
        smsSenderId: string;
