          username: cleanUsername,
          password: cleanPassword,
          fullName: cleanName,
          email: formEmail,
          phone: formPhone,
          roleName: 'STAFF',
          permissionCodes: formPerms.filter((p) => !ADMIN_ONLY_PERM_CODES.has(p)),
