    if (!editingStaff) return;
    setSaving(true);
    setError(null);
    const cleanUsername = formUsername.trim().toLowerCase();
    const resetPass = formPassword;
    try {
      await apiFetch(`/api/staff/${editingStaff.id}`, {
        method: 'PUT',
        body: JSON.stringify({
          username: cleanUsername || editingStaff.username,
          fullName: formFullName,
          email: formEmail,
          phone: formPhone,
          isActive: formActive,
          newPassword: resetPass || undefined,
          permissionCodes:
            editingStaff.roleName === 'STAFF'
              ? formPerms.filter((p) => !ADMIN_ONLY_PERM_CODES.has(p))
              : undefined,
        }),
      });
      if (resetPass && resetPass.length >= 6) {
        setIssuedCredentials({
          username: cleanUsername || editingStaff.username,
          password: resetPass,
          fullName: formFullName,
