// Drizzle Relations
export const rolesRelations = relations(roles, ({ many }) => ({
  users: many(users),
}));

export const usersRelations = relations(users, ({ one, many }) => ({
  role: one(roles, {
    fields: [users.roleId],
    references: [roles.id],
  }),
  userPermissions: many(userPermissions),
  createdMembers: many(members),
  receivedPayments: many(payments),
}));

export const userPermissionsRelations = relations(userPermissions, ({ one }) => ({
  user: one(users, {
    fields: [userPermissions.userId],
    references: [users.id],
  }),
  permission: one(permissions, {
    fields: [userPermissions.permissionId],
    references: [permissions.id],
  }),
}));

export const membersRelations = relations(members, ({ one, many }) => ({
  createdBy: one(users, {
    fields: [members.createdByUserId],
    references: [users.id],
  }),
  feeSchedules: many(annualMembershipFees),
  obligations: many(yearlyObligations),
  payments: many(payments),
}));

export const annualMembershipFeesRelations = relations(annualMembershipFees, ({ one }) => ({
  member: one(members, {
    fields: [annualMembershipFees.memberId],
    references: [members.id],
  }),
}));

export const yearlyObligationsRelations = relations(yearlyObligations, ({ one, many }) => ({
  member: one(members, {
    fields: [yearlyObligations.memberId],
    references: [members.id],
  }),
  payments: many(payments),
}));

export const paymentsRelations = relations(payments, ({ one, many }) => ({
  obligation: one(yearlyObligations, {
    fields: [payments.obligationId],
    references: [yearlyObligations.id],
  }),
  member: one(members, {
    fields: [payments.memberId],
    references: [members.id],
  }),
  receivedBy: one(users, {
    fields: [payments.receivedByUserId],
    references: [users.id],
  }),
  corrections: many(paymentCorrections),
  receipt: one(receipts),
}));

export const paymentCorrectionsRelations = relations(paymentCorrections, ({ one }) => ({
  payment: one(payments, {
    fields: [paymentCorrections.paymentId],
    references: [payments.id],
  }),
  correctedBy: one(users, {
    fields: [paymentCorrections.correctedByUserId],
    references: [users.id],
  }),
