export const START_YEAR = 2026;
export const MAX_SUPPORTED_YEAR = 2060; // Supports 2050+ seamlessly

export type ObligationStatus = 'UNPAID' | 'PARTIAL' | 'PAID';

export interface FeeScheduleEntry {
  effectiveFromYear: number;
  annualFee: number;
}

export interface ObligationRecord {
  year: number;
  frozenAnnualFee: number;
  paidTotal: number;
  status: ObligationStatus;
}

/**
 * Generates automatic sequential unique member ID starting from SKM 1: e.g. SKM 1, SKM 2...
 */
export function formatMemberCode(sequenceNumber: number, _joiningYear = START_YEAR): string {
  return `SKM ${Math.max(1, Math.trunc(sequenceNumber))}`;
}

/**
 * Generates simple auto-incrementing numeric receipt ID starting at 1: e.g. 1, 2, 3...
 */
export function formatReceiptNumber(_year: number, sequenceNumber: number): string {
  return String(Math.max(1, Math.trunc(sequenceNumber)));
}

/**
 * Rounds financial values cleanly to 2 decimal places.
 */
export function roundMoney(value: number): number {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

/**
 * Resolves the applicable annual fee for a target year based on fee schedules,
 * never retroactively changing an earlier year's already-frozen obligation.
 */
export function resolveAnnualFeeForYear(
  targetYear: number,
  defaultAnnualFee: number,
  schedules: FeeScheduleEntry[]
): number {
  if (targetYear < START_YEAR) {
    throw new Error(`Payment year cannot be earlier than ${START_YEAR}.`);
  }
  const sorted = [...schedules]
    .filter((s) => s.effectiveFromYear <= targetYear)
    .sort((a, b) => b.effectiveFromYear - a.effectiveFromYear);
  if (sorted.length > 0) {
    return roundMoney(sorted[0].annualFee);
  }
  return roundMoney(defaultAnnualFee);
}

/**
 * Computes obligation status and remaining due.
 */
export function computeObligationState(
  expectedFee: number,
  paidTotal: number
): { dueAmount: number; status: ObligationStatus } {
  const expected = roundMoney(expectedFee);
  const paid = roundMoney(paidTotal);
  const due = roundMoney(Math.max(0, expected - paid));
  if (paid <= 0) {
    return { dueAmount: expected, status: 'UNPAID' };
  }
  if (due <= 0) {
    return { dueAmount: 0, status: 'PAID' };
  }
  return { dueAmount: due, status: 'PARTIAL' };
}

/**
 * Validates a payment attempt against business rules:
 * - Year must be >= 2026
 * - Paid amount must be > 0
 * - Prevents duplicate payment when obligation is already PAID
 * - Enforces Admin allowPartialPayments toggle
 * - Prevents paying more than remaining due
 */
export function validatePaymentAttempt(params: {
  paymentYear: number;
  expectedFee: number;
  alreadyPaid: number;
  attemptAmount: number;
  allowPartialPayments: boolean;
}): { ok: true; newPaidTotal: number; dueAfterPayment: number; status: ObligationStatus } | { ok: false; error: string } {
  const { paymentYear, expectedFee, alreadyPaid, attemptAmount, allowPartialPayments } = params;

  if (!Number.isInteger(paymentYear) || paymentYear < START_YEAR) {
    return { ok: false, error: `Payment year must be ${START_YEAR} or later.` };
  }
  if (!Number.isFinite(attemptAmount) || attemptAmount <= 0) {
    return { ok: false, error: 'Paid amount must be greater than zero.' };
  }

  const expected = roundMoney(expectedFee);
  const paidSoFar = roundMoney(alreadyPaid);
  const attempt = roundMoney(attemptAmount);
  const remainingDue = roundMoney(Math.max(0, expected - paidSoFar));

  if (remainingDue <= 0) {
    return {
      ok: false,
      error: `Duplicate payment blocked: Membership fee for ${paymentYear} is already fully paid.`,
    };
  }

  if (attempt > remainingDue) {
    return {
      ok: false,
      error: `Payment (${attempt}) exceeds remaining due (${remainingDue}) for ${paymentYear}.`,
    };
  }

  if (!allowPartialPayments && attempt < remainingDue) {
    return {
      ok: false,
      error: `Partial payments are currently disabled by Admin. Full remaining due (${remainingDue}) is required.`,
    };
  }

  const newPaidTotal = roundMoney(paidSoFar + attempt);
  const { dueAmount, status } = computeObligationState(expected, newPaidTotal);

  return {
    ok: true,
    newPaidTotal,
    dueAfterPayment: dueAmount,
    status,
  };
}

/**
 * Computes pending dues up to `referenceYear` (inclusive).
 * Future years (> referenceYear) are NEVER counted as overdue/pending before their period.
 */
export function calculatePendingSummary(
  obligations: ObligationRecord[],
  referenceYear: number
): {
  currentYearPending: number;
  previousYearsPending: number;
  totalOutstanding: number;
  overdueYears: number[];
} {
  let currentYearPending = 0;
  let previousYearsPending = 0;
  const overdueYears: number[] = [];

  for (const ob of obligations) {
    if (ob.year < START_YEAR || ob.year > referenceYear) {
      // Never count future years as overdue before their applicable payment period
      continue;
    }
    const { dueAmount } = computeObligationState(ob.frozenAnnualFee, ob.paidTotal);
    if (dueAmount > 0) {
      overdueYears.push(ob.year);
      if (ob.year === referenceYear) {
        currentYearPending = roundMoney(currentYearPending + dueAmount);
      } else {
        previousYearsPending = roundMoney(previousYearsPending + dueAmount);
      }
    }
  }

  return {
    currentYearPending,
    previousYearsPending,
    totalOutstanding: roundMoney(currentYearPending + previousYearsPending),
    overdueYears: overdueYears.sort((a, b) => a - b),
  };
}

/**
 * Generates automatic yearly years range from startYear (min 2026) through targetHorizonYear (e.g. max(currentYear, 2050+)).
 */
export function getAutomaticYearsRange(memberJoiningYear: number, horizonYear: number): number[] {
  const effectiveStart = Math.max(START_YEAR, memberJoiningYear);
  const years: number[] = [];
  for (let y = effectiveStart; y <= horizonYear; y++) {
    years.push(y);
  }
  return years;
}

/**
 * Validates an immutable payment correction request.
 */
export function validateCorrectionRequest(params: {
  originalAmount: number;
  newAmount: number;
  reason: string;
  otherPaymentsPaidTotal: number;
  expectedFee: number;
}): { ok: true; newObligationPaidTotal: number; newObligationDue: number; newStatus: ObligationStatus } | { ok: false; error: string } {
  const trimmedReason = params.reason.trim();
  if (trimmedReason.length < 5) {
    return {
      ok: false,
      error: 'A detailed reason (at least 5 characters) is required for any payment correction.',
    };
  }
  if (!Number.isFinite(params.newAmount) || params.newAmount < 0) {
    return { ok: false, error: 'Corrected amount cannot be negative.' };
  }
  const newPaid = roundMoney(params.otherPaymentsPaidTotal + params.newAmount);
  if (newPaid > roundMoney(params.expectedFee)) {
    return {
      ok: false,
      error: `Corrected total (${newPaid}) cannot exceed expected annual fee (${params.expectedFee}).`,
    };
  }
  const { dueAmount, status } = computeObligationState(params.expectedFee, newPaid);
  return {
    ok: true,
    newObligationPaidTotal: newPaid,
    newObligationDue: dueAmount,
    newStatus: status,
  };
}

export interface YearDueItem {
  year: number;
  expectedFee: number;
  alreadyPaid: number;
}

export interface YearAllocationResult {
  year: number;
  expectedFee: number;
  alreadyPaid: number;
  paidNow: number;
  newPaidTotal: number;
  dueAfterPayment: number;
  status: ObligationStatus;
  isPreviousYear: boolean;
}

export interface MultiYearAllocationPlan {
  ok: true;
  referenceYear: number;
  totalPaidNow: number;
  previousYearsPaidNow: number;
  currentYearPaidNow: number;
  previousYearsRemainingDue: number;
  currentYearRemainingDue: number;
  totalRemainingDue: number;
  allocations: YearAllocationResult[];
}

/**
 * Allocates a payment amount across overdue previous years (< referenceYear, oldest first)
 * and the current referenceYear obligation. Enforces duplicate-payment & partial-payment rules.
 */
export function allocateMultiYearPayment(params: {
  referenceYear: number;
  obligations: YearDueItem[];
  attemptAmount: number;
  includePreviousDues: boolean;
  allowPartialPayments: boolean;
}): MultiYearAllocationPlan | { ok: false; error: string } {
  const { referenceYear, obligations, attemptAmount, includePreviousDues, allowPartialPayments } = params;

  if (!Number.isInteger(referenceYear) || referenceYear < START_YEAR) {
    return { ok: false, error: `Payment year must be ${START_YEAR} or later.` };
  }
  if (!Number.isFinite(attemptAmount) || attemptAmount <= 0) {
    return { ok: false, error: 'Paid amount must be greater than zero.' };
  }

  const relevant = obligations
    .filter((o) => (includePreviousDues ? o.year <= referenceYear && o.year >= START_YEAR : o.year === referenceYear))
    .sort((a, b) => a.year - b.year);

  const payableRows = relevant
    .map((o) => {
      const expectedFee = roundMoney(o.expectedFee);
      const alreadyPaid = roundMoney(o.alreadyPaid);
      const due = roundMoney(Math.max(0, expectedFee - alreadyPaid));
      return { ...o, expectedFee, alreadyPaid, due };
    })
    .filter((o) => o.due > 0);

  const totalDue = roundMoney(payableRows.reduce((s, r) => s + r.due, 0));
  const attempt = roundMoney(attemptAmount);

  if (totalDue <= 0) {
    return {
      ok: false,
      error: includePreviousDues
        ? `All dues up to ${referenceYear} are already fully paid.`
        : `Duplicate payment blocked: Membership fee for ${referenceYear} is already fully paid.`,
    };
  }

  if (attempt > totalDue) {
    return {
      ok: false,
      error: `Payment (${attempt}) exceeds total payable due (${totalDue}) up to ${referenceYear}.`,
    };
  }

  if (!allowPartialPayments && attempt < totalDue) {
    return {
      ok: false,
      error: `Partial payments are currently disabled by Admin. Full payable due (${totalDue}) is required.`,
    };
  }

  let remainingToAllocate = attempt;
  const allocations: YearAllocationResult[] = [];

  for (const row of payableRows) {
    if (remainingToAllocate <= 0) break;
    const paidNow = roundMoney(Math.min(row.due, remainingToAllocate));
    if (paidNow <= 0) continue;
    remainingToAllocate = roundMoney(remainingToAllocate - paidNow);
    const newPaidTotal = roundMoney(row.alreadyPaid + paidNow);
    const { dueAmount, status } = computeObligationState(row.expectedFee, newPaidTotal);
    allocations.push({
      year: row.year,
      expectedFee: row.expectedFee,
      alreadyPaid: row.alreadyPaid,
      paidNow,
      newPaidTotal,
      dueAfterPayment: dueAmount,
      status,
      isPreviousYear: row.year < referenceYear,
    });
  }

  // Compute remaining dues across all relevant rows (even unallocated ones)
  let previousYearsRemainingDue = 0;
  let currentYearRemainingDue = 0;
  for (const row of relevant) {
    const alloc = allocations.find((a) => a.year === row.year);
    const paidAfter = alloc ? alloc.newPaidTotal : roundMoney(row.alreadyPaid);
    const dueAfter = roundMoney(Math.max(0, roundMoney(row.expectedFee) - paidAfter));
    if (row.year < referenceYear) {
      previousYearsRemainingDue = roundMoney(previousYearsRemainingDue + dueAfter);
    } else if (row.year === referenceYear) {
      currentYearRemainingDue = roundMoney(currentYearRemainingDue + dueAfter);
    }
  }

  const previousYearsPaidNow = roundMoney(
    allocations.filter((a) => a.isPreviousYear).reduce((s, a) => s + a.paidNow, 0)
  );
  const currentYearPaidNow = roundMoney(
    allocations.filter((a) => !a.isPreviousYear).reduce((s, a) => s + a.paidNow, 0)
  );

  return {
    ok: true,
    referenceYear,
    totalPaidNow: attempt,
    previousYearsPaidNow,
    currentYearPaidNow,
    previousYearsRemainingDue,
    currentYearRemainingDue,
    totalRemainingDue: roundMoney(previousYearsRemainingDue + currentYearRemainingDue),
    allocations,
  };
}

import { useEffect, useState } from 'react';

export function useOnlineStatus() {
  const [isOnline, setIsOnline] = useState(
    typeof navigator !== 'undefined' ? navigator.onLine : true
  );

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  return isOnline;
}

import { useEffect, useState } from 'react';

interface BeforeInstallPromptEvent extends Event {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed'; platform: string }>;
}

export function usePWAInstall() {
  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(null);
  const [isInstalled, setIsInstalled] = useState(false);
  const [isIOS, setIsIOS] = useState(false);

  useEffect(() => {
    const isStandalone =
      window.matchMedia('(display-mode: standalone)').matches ||
      (window.navigator as unknown as { standalone?: boolean }).standalone === true;
    setIsInstalled(isStandalone);

    const userAgent = window.navigator.userAgent.toLowerCase();
    setIsIOS(/iphone|ipad|ipod/.test(userAgent));

    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e as BeforeInstallPromptEvent);
    };

    const handleAppInstalled = () => {
      setIsInstalled(true);
      setDeferredPrompt(null);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    window.addEventListener('appinstalled', handleAppInstalled);
    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
      window.removeEventListener('appinstalled', handleAppInstalled);
    };
  }, []);

  const install = async () => {
    if (!deferredPrompt) return false;
    await deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setIsInstalled(true);
      setDeferredPrompt(null);
      return true;
    }
    return false;
  };

  return {
    isInstallable: !!deferredPrompt,
    isInstalled,
    isIOS,
    install,
  };
}

