function loadServerFirebaseConfig(): { projectId: string; firestoreDatabaseId?: string } {
  const candidates = [
    path.resolve(process.cwd(), 'firebase-applet-config.json'),
    path.resolve(import.meta.dirname, '..', '..', 'firebase-applet-config.json'),
  ];
  for (const p of candidates) {
    if (fs.existsSync(p)) {
      return JSON.parse(fs.readFileSync(p, 'utf8'));
    }
  }
  return { projectId: process.env.GOOGLE_CLOUD_PROJECT || 'skm-madrasa-local' };
}

export const serverFirebaseConfig = loadServerFirebaseConfig();

if (!getApps().length) {
  initializeApp({
    projectId: serverFirebaseConfig.projectId,
  });
}

