const TOKEN_SECRET =
  process.env.SESSION_SECRET ||
  crypto
    .createHash('sha256')
    .update(`skm-session-key-${serverFirebaseConfig.projectId}-${process.env.SQL_DB_NAME || 'local'}`)
    .digest('hex');

export interface AuthenticatedUser {
  id: number;
  uid: string | null;
  username: string;
  fullName: string;
  email: string | null;
  phone: string | null;
  roleName: 'ADMIN' | 'STAFF';
  permissions: string[];
  canOfflineEntry: boolean;
}

export interface AuthRequest extends Request {
  authUser?: AuthenticatedUser;
  authMethod?: 'skm' | 'firebase';
}

export function hashPassword(password: string): string {
  const salt = crypto.randomBytes(16).toString('hex');
  const derived = crypto.scryptSync(password, salt, 64).toString('hex');
  return `${salt}:${derived}`;
}

export function verifyPassword(password: string, storedHash: string): boolean {
  const parts = storedHash.split(':');
  if (parts.length !== 2) return false;
  const [salt, expectedHex] = parts;
  const derived = crypto.scryptSync(password, salt, 64);
  const expected = Buffer.from(expectedHex, 'hex');
  if (derived.length !== expected.length) return false;
  return crypto.timingSafeEqual(derived, expected);
}

export function signSessionToken(userId: number, username: string): string {
  const payload = Buffer.from(
    JSON.stringify({
      sub: userId,
      username,
      exp: Date.now() + 1000 * 60 * 60 * 24 * 7, // 7 days
    })
  ).toString('base64url');
  const sig = crypto.createHmac('sha256', TOKEN_SECRET).update(payload).digest('base64url');
  return `skm.${payload}.${sig}`;
}

export function verifySessionToken(token: string): { sub: number; username: string } | null {
  if (!token.startsWith('skm.')) return null;
  const parts = token.split('.');
  if (parts.length !== 3) return null;
  const [, payload, sig] = parts;
  const expectedSig = crypto.createHmac('sha256', TOKEN_SECRET).update(payload).digest('base64url');
  const sigBuf = Buffer.from(sig);
  const expBuf = Buffer.from(expectedSig);
  if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
    return null;
  }
  try {
    const parsed = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8')) as {
      sub: number;
      username: string;
      exp: number;
    };
    if (!parsed.sub || !parsed.exp || Date.now() > parsed.exp) return null;
    return { sub: parsed.sub, username: parsed.username };
  } catch {
    return null;
  }
}

export async function loadAuthenticatedUserById(userId: number): Promise<AuthenticatedUser | null> {
  if (!isPostgresConfigured()) {
    return localStore.read((data) => {
      const user = data.users.find((u) => u.id === userId);
      if (!user || !user.isActive) return null;
      const role = data.roles.find((r) => r.id === user.roleId);
      const roleName = (role?.name === 'ADMIN' ? 'ADMIN' : 'STAFF') as 'ADMIN' | 'STAFF';
      let permCodes: string[] = [];
      if (roleName === 'ADMIN') {
        permCodes = data.permissions.map((p) => p.code);
      } else {
        const pIdSet = new Set(
          data.userPermissions.filter((up) => up.userId === user.id).map((up) => up.permissionId)
        );
        permCodes = data.permissions.filter((p) => pIdSet.has(p.id)).map((p) => p.code);
      }
      return {
        id: user.id,
        uid: user.uid,
        username: user.username,
        fullName: user.fullName,
        email: user.email,
        phone: user.phone,
        roleName,
        permissions: permCodes,
        canOfflineEntry: roleName === 'ADMIN' ? true : user.canOfflineEntry,
      };
    });
  }

  const rows = await db
    .select({
      id: users.id,
      uid: users.uid,
      username: users.username,
      fullName: users.fullName,
      email: users.email,
      phone: users.phone,
      isActive: users.isActive,
      canOfflineEntry: users.canOfflineEntry,
      roleName: roles.name,
    })
    .from(users)
    .innerJoin(roles, eq(users.roleId, roles.id))
    .where(eq(users.id, userId))
    .limit(1);

  if (rows.length === 0 || !rows[0].isActive) {
    return null;
  }

  const user = rows[0];
  const roleName = (user.roleName === 'ADMIN' ? 'ADMIN' : 'STAFF') as 'ADMIN' | 'STAFF';

  let permCodes: string[] = [];
  if (roleName === 'ADMIN') {
    const allPerms = await db.select({ code: permissions.code }).from(permissions);
    permCodes = allPerms.map((p) => p.code);
  } else {
    const userPerms = await db
      .select({ code: permissions.code })
      .from(userPermissions)
      .innerJoin(permissions, eq(userPermissions.permissionId, permissions.id))
      .where(eq(userPermissions.userId, user.id));
    permCodes = userPerms.map((p) => p.code);
  }

  return {
    id: user.id,
    uid: user.uid,
    username: user.username,
    fullName: user.fullName,
    email: user.email,
    phone: user.phone,
    roleName,
    permissions: permCodes,
    canOfflineEntry: roleName === 'ADMIN' ? true : user.canOfflineEntry,
  };
}

export async function getOrCreateFirebaseUser(
  uid: string,
  email: string,
  displayName?: string
): Promise<AuthenticatedUser | null> {
  const normalizedEmail = String(email || '').trim().toLowerCase();

  if (!isPostgresConfigured()) {
    const matchedUserId = await localStore.transaction((draft) => {
      const nowIso = new Date().toISOString();
      const byUid = draft.users.find((u) => u.uid === uid);
      if (byUid) {
        byUid.lastLoginAt = nowIso;
        byUid.updatedAt = nowIso;
        return byUid.id;
      }

      if (normalizedEmail) {
        const byEmail = draft.users.find(
          (u) => (u.email || '').trim().toLowerCase() === normalizedEmail
        );
        if (byEmail) {
          byEmail.uid = uid;
          byEmail.lastLoginAt = nowIso;
          byEmail.updatedAt = nowIso;
          return byEmail.id;
        }
        // If Admin Gmail signs in via Google, bind it to the primary ADMIN account
        if (normalizedEmail === ADMIN_DEFAULT_EMAIL.toLowerCase()) {
          const adminRole = draft.roles.find((r) => r.name === 'ADMIN');
          const adminUser = draft.users.find((u) => u.roleId === adminRole?.id);
          if (adminUser) {
            adminUser.uid = uid;
            adminUser.email = ADMIN_DEFAULT_EMAIL;
            if (!adminUser.phone) adminUser.phone = ADMIN_DEFAULT_PHONE;
            adminUser.lastLoginAt = nowIso;
            adminUser.updatedAt = nowIso;
            return adminUser.id;
          }
        }
      }

      const adminRole = draft.roles.find((r) => r.name === 'ADMIN');
      const staffRole = draft.roles.find((r) => r.name === 'STAFF');
      if (!staffRole) return null;

      const hasAdmin = adminRole ? draft.users.some((u) => u.roleId === adminRole.id) : false;
      const roleId = !hasAdmin && adminRole ? adminRole.id : staffRole.id;
      const cleanUsername = (normalizedEmail ? normalizedEmail.split('@')[0] : `user_${uid.slice(0, 8)}`).replace(
        /[^a-zA-Z0-9_]/g,
        '_'
      );

      const createdId = nextSeq(draft, 'users');
      draft.users.push({
        id: createdId,
        uid,
        username: `${cleanUsername}_${uid.slice(0, 4)}`,
        passwordHash: hashPassword(crypto.randomBytes(16).toString('hex')),
        fullName: displayName || email || 'Madrasa Staff',
        email: normalizedEmail || null,
        phone: roleId === adminRole?.id ? ADMIN_DEFAULT_PHONE : null,
        roleId,
        isActive: true,
        canOfflineEntry: roleId === adminRole?.id,
        lastLoginAt: nowIso,
        createdAt: nowIso,
        updatedAt: nowIso,
      });

      if (roleId === staffRole.id) {
        const defaultCodes = ['members:view', 'members:edit', 'payments:view', 'payments:create'];
        for (const code of defaultCodes) {
          const p = draft.permissions.find((perm) => perm.code === code);
          if (p) {
            draft.userPermissions.push({
              id: nextSeq(draft, 'userPermissions'),
              userId: createdId,
              permissionId: p.id,
              grantedAt: nowIso,
            });
          }
        }
      }
      return createdId;
    });

    return matchedUserId ? loadAuthenticatedUserById(matchedUserId) : null;
  }

  // First check if a user already exists by uid or email
  const existingByUid = await db.select().from(users).where(eq(users.uid, uid)).limit(1);
  if (existingByUid.length > 0) {
    return loadAuthenticatedUserById(existingByUid[0].id);
  }

  if (normalizedEmail) {
    const existingByEmail = await db.select().from(users).where(eq(users.email, normalizedEmail)).limit(1);
    if (existingByEmail.length > 0) {
      await db
        .update(users)
        .set({ uid, lastLoginAt: new Date(), updatedAt: new Date() })
        .where(eq(users.id, existingByEmail[0].id));
      return loadAuthenticatedUserById(existingByEmail[0].id);
    }

    if (normalizedEmail === ADMIN_DEFAULT_EMAIL.toLowerCase()) {
      const [adminRoleRow] = await db.select().from(roles).where(eq(roles.name, 'ADMIN')).limit(1);
      if (adminRoleRow) {
        const [adminUser] = await db
          .select()
          .from(users)
          .where(eq(users.roleId, adminRoleRow.id))
          .limit(1);
        if (adminUser) {
          await db
            .update(users)
            .set({
              uid,
              email: ADMIN_DEFAULT_EMAIL,
              phone: adminUser.phone || ADMIN_DEFAULT_PHONE,
              lastLoginAt: new Date(),
              updatedAt: new Date(),
            })
            .where(eq(users.id, adminUser.id));
          return loadAuthenticatedUserById(adminUser.id);
        }
      }
    }
  }

  // Provision as STAFF by default (or ADMIN if no ADMIN exists yet)
  const adminRole = await db.select().from(roles).where(eq(roles.name, 'ADMIN')).limit(1);
  const staffRole = await db.select().from(roles).where(eq(roles.name, 'STAFF')).limit(1);
  if (!staffRole.length) return null;

  const existingAdmins = adminRole.length
    ? await db.select({ id: users.id }).from(users).where(eq(users.roleId, adminRole[0].id)).limit(1)
    : [];
  const roleId = existingAdmins.length === 0 && adminRole.length ? adminRole[0].id : staffRole[0].id;
  const cleanUsername = (normalizedEmail ? normalizedEmail.split('@')[0] : `user_${uid.slice(0, 8)}`).replace(
    /[^a-zA-Z0-9_]/g,
    '_'
  );

  const inserted = await db
    .insert(users)
    .values({
      uid,
      username: `${cleanUsername}_${uid.slice(0, 4)}`,
      passwordHash: hashPassword(crypto.randomBytes(16).toString('hex')),
      fullName: displayName || email || 'Madrasa Staff',
      email: normalizedEmail || null,
      phone: roleId === adminRole[0]?.id ? ADMIN_DEFAULT_PHONE : null,
      roleId,
      isActive: true,
      canOfflineEntry: roleId === adminRole[0]?.id,
      lastLoginAt: new Date(),
    })
    .onConflictDoUpdate({
      target: users.uid,
      set: {
        email: normalizedEmail || null,
        lastLoginAt: new Date(),
      },
    })
    .returning();

  return loadAuthenticatedUserById(inserted[0].id);
}

export const requireAuth = async (req: AuthRequest, res: Response, next: NextFunction) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized: Missing authentication token' });
  }

  const token = authHeader.slice('Bearer '.length).trim();

  // 1. Check SKM HMAC session token (for individual Staff/Admin username+password accounts)
  if (token.startsWith('skm.')) {
    const parsed = verifySessionToken(token);
    if (!parsed) {
      return res.status(401).json({ error: 'Unauthorized: Session expired or invalid' });
    }
    try {
      const authUser = await loadAuthenticatedUserById(parsed.sub);
      if (!authUser) {
        return res.status(401).json({ error: 'Unauthorized: Account disabled or not found' });
      }
      req.authUser = authUser;
      req.authMethod = 'skm';
      return next();
    } catch (err) {
      console.error('Auth user lookup failed:', err);
      return res.status(500).json({ error: 'Authentication verification failed' });
    }
  }

  // 2. Verify Firebase ID Token (Google Sign-In)
  try {
    const decoded = await adminAuth.verifyIdToken(token);
    const authUser = await getOrCreateFirebaseUser(
      decoded.uid,
      decoded.email || '',
      decoded.name || decoded.email || 'Google User'
    );
    if (!authUser) {
      return res.status(403).json({ error: 'Account is disabled or role unavailable' });
    }
    req.authUser = authUser;
    req.authMethod = 'firebase';
    return next();
  } catch (err) {
    console.error('Error verifying token:', err);
    return res.status(401).json({ error: 'Unauthorized: Invalid authentication token' });
  }
};

export const requirePermission = (code: string) => {
  return (req: AuthRequest, res: Response, next: NextFunction) => {
    if (!req.authUser) {
      return res.status(401).json({ error: 'Unauthorized' });
    }
    if (req.authUser.roleName === 'ADMIN' || req.authUser.permissions.includes(code)) {
      return next();
    }
    return res.status(403).json({
      error: `Forbidden: Missing required permission (${code})`,
    });
  };
};

export const requireAdmin = (req: AuthRequest, res: Response, next: NextFunction) => {
  if (!req.authUser) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  if (req.authUser.roleName !== 'ADMIN') {
    return res.status(403).json({ error: 'Forbidden: Administrator access required' });
  }
  return next();
};

import crypto from 'node:crypto';
import { serverFirebaseConfig } from '../lib/firebase-admin.ts';

const DEFAULT_BACKUP_SECRET = crypto
  .createHash('sha256')
  .update(`skm-backup-master-${serverFirebaseConfig.projectId}`)
  .digest();

export interface EncryptedBackupEnvelope {
  format: 'SKM_ENCRYPTED_BACKUP_V1';
  algorithm: 'AES-256-GCM';
  createdAt: string;
  ivBase64: string;
  authTagBase64: string;
  saltBase64: string;
  ciphertextBase64: string;
  checksumSha256: string;
  recordCount: number;
}

function deriveKey(passphrase: string | undefined, salt: Buffer): Buffer {
  if (!passphrase || !passphrase.trim()) {
    return crypto.hkdfSync('sha256', DEFAULT_BACKUP_SECRET, salt, Buffer.from('skm-backup'), 32) as unknown as Buffer;
  }
  return crypto.scryptSync(passphrase.trim(), salt, 32);
}

export function sha256Hex(input: string): string {
  return crypto.createHash('sha256').update(input, 'utf8').digest('hex');
}

export function encryptBackupPayload(
  payload: unknown,
  recordCount: number,
  passphrase?: string
): EncryptedBackupEnvelope {
  const plaintext = JSON.stringify(payload);
  const checksumSha256 = sha256Hex(plaintext);
  const salt = crypto.randomBytes(16);
  const iv = crypto.randomBytes(12);
  const key = Buffer.from(deriveKey(passphrase, salt));
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  const encrypted = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const authTag = cipher.getAuthTag();

  return {
    format: 'SKM_ENCRYPTED_BACKUP_V1',
    algorithm: 'AES-256-GCM',
    createdAt: new Date().toISOString(),
    ivBase64: iv.toString('base64'),
    authTagBase64: authTag.toString('base64'),
    saltBase64: salt.toString('base64'),
    ciphertextBase64: encrypted.toString('base64'),
    checksumSha256,
    recordCount,
  };
}

export function decryptBackupPayload<T = unknown>(
  envelope: EncryptedBackupEnvelope,
  passphrase?: string
): T {
  if (!envelope || envelope.format !== 'SKM_ENCRYPTED_BACKUP_V1') {
    throw new Error('Invalid backup envelope format.');
  }
  const salt = Buffer.from(envelope.saltBase64, 'base64');
  const iv = Buffer.from(envelope.ivBase64, 'base64');
  const authTag = Buffer.from(envelope.authTagBase64, 'base64');
  const ciphertext = Buffer.from(envelope.ciphertextBase64, 'base64');
  const key = Buffer.from(deriveKey(passphrase, salt));

  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
  decipher.setAuthTag(authTag);
  const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString('utf8');
  const actualChecksum = sha256Hex(decrypted);
  if (actualChecksum !== envelope.checksumSha256) {
    throw new Error('Backup checksum verification failed (file corrupted or tampered).');
  }
  return JSON.parse(decrypted) as T;
}

