function buildSettingsMap(data: LocalDatabaseSnapshot): Record<string, string> {
  const map: Record<string, string> = {
    allowPartialPayments: 'true',
    autoBackupEnabled: 'true',
    autoBackupIntervalHours: '24',
    currentActiveYear: String(Math.max(START_YEAR, new Date().getFullYear())),
  };
  for (const row of data.systemSettings) {
    map[row.key] = row.value;
  }
  return map;
}

function appendActivity(
  draft: LocalDatabaseSnapshot,
  params: {
    actorUserId: number | null;
    actorName: string;
    actionType: string;
    entityType: string;
    entityId: string;
    summary: string;
    metadata?: unknown;
  }
) {
  draft.activityLogs.push({
    id: nextSeq(draft, 'activityLogs'),
    actorUserId: params.actorUserId,
    actorName: params.actorName,
    actionType: params.actionType,
    entityType: params.entityType,
    entityId: params.entityId,
    summary: params.summary,
    metadataJson: params.metadata ? JSON.stringify(params.metadata) : null,
    createdAt: new Date().toISOString(),
  });
}

function generateNextMemberCodeSync(draft: LocalDatabaseSnapshot, joinYear: number): string {
  let maxSeq = 0;
  for (const m of draft.members) {
    const match = /^SKM (\d+)$/.exec(m.memberCode);
    if (match) {
      maxSeq = Math.max(maxSeq, Number(match[1]));
    }
  }
  let nextNum = maxSeq + 1;
  while (true) {
    const candidate = formatMemberCode(nextNum, joinYear);
    if (!draft.members.some((m) => m.memberCode === candidate)) return candidate;
    nextNum += 1;
  }
}

function generateNextReceiptNumberSync(draft: LocalDatabaseSnapshot, yearNum: number): string {
  let maxSeq = 0;
  for (const p of draft.payments) {
    if (/^\d+$/.test(p.receiptNumber)) maxSeq = Math.max(maxSeq, Number(p.receiptNumber));
  }
  for (const r of draft.receipts) {
    if (/^\d+$/.test(r.receiptNumber)) maxSeq = Math.max(maxSeq, Number(r.receiptNumber));
  }
  let nextNum = maxSeq + 1;
  while (true) {
    const candidate = formatReceiptNumber(yearNum, nextNum);
    const conflict =
      draft.payments.some((p) => p.receiptNumber === candidate) ||
      draft.receipts.some((r) => r.receiptNumber === candidate);
    if (!conflict) return candidate;
    nextNum += 1;
  }
}

function ensureObligationInDraft(
  draft: LocalDatabaseSnapshot,
  memberId: number,
  targetYear: number
): LocalYearlyObligation {
  if (targetYear < START_YEAR || targetYear > MAX_SUPPORTED_YEAR) {
    throw new RepoHttpError(400, `Year must be between ${START_YEAR} and ${MAX_SUPPORTED_YEAR}.`);
  }
  const existing = draft.yearlyObligations.find(
    (o) => o.memberId === memberId && o.year === targetYear
  );
  if (existing) return existing;

  const member = draft.members.find((m) => m.id === memberId);
  if (!member) throw new RepoHttpError(404, 'Member not found.');

  const schedules = draft.annualMembershipFees.filter((s) => s.memberId === memberId);
  const fee = resolveAnnualFeeForYear(
    targetYear,
    Number(member.defaultAnnualFee),
    schedules.map((s) => ({
      effectiveFromYear: s.effectiveFromYear,
      annualFee: Number(s.annualFee),
    }))
  );

  const nowIso = new Date().toISOString();
  const created: LocalYearlyObligation = {
    id: nextSeq(draft, 'yearlyObligations'),
    memberId,
    year: targetYear,
    frozenAnnualFee: fee.toFixed(2),
    paidTotal: '0.00',
    status: 'UNPAID',
    createdAt: nowIso,
    updatedAt: nowIso,
  };
  draft.yearlyObligations.push(created);
  return created;
}

