export async function findUserForLoginLocal(identifier: string) {
  const clean = String(identifier || '').trim().toLowerCase();
  const cleanDigits = clean.replace(/\D/g, '');
  return localStore.read((data) => {
    const user = data.users.find((u) => {
      if (u.username.toLowerCase() === clean) return true;
      if (u.email && u.email.toLowerCase() === clean) return true;
      if (cleanDigits.length >= 10 && u.phone) {
        const uDigits = u.phone.replace(/\D/g, '');
        if (uDigits === cleanDigits || uDigits.endsWith(cleanDigits) || cleanDigits.endsWith(uDigits)) {
          return true;
        }
      }
      return false;
    });
    if (!user) return null;
    const role = data.roles.find((r) => r.id === user.roleId);
    return {
      ...user,
      roleName: (role?.name === 'ADMIN' ? 'ADMIN' : 'STAFF') as 'ADMIN' | 'STAFF',
    };
  });
}

export async function findAdminByOtpIdentifierLocal(identifier: string) {
  const clean = String(identifier || '').trim().toLowerCase();
  const cleanDigits = clean.replace(/\D/g, '');
  return localStore.read((data) => {
    const adminRole = data.roles.find((r) => r.name === 'ADMIN');
    if (!adminRole) return null;
    const adminUser = data.users.find((u) => {
      if (u.roleId !== adminRole.id) return false;
      if (!clean) return true;
      if (u.username.toLowerCase() === clean) return true;
      if (u.email && u.email.toLowerCase() === clean) return true;
      if (cleanDigits.length >= 10 && u.phone) {
        const uDigits = u.phone.replace(/\D/g, '');
        return uDigits === cleanDigits || uDigits.endsWith(cleanDigits) || cleanDigits.endsWith(uDigits);
      }
      return false;
    });
    return adminUser || null;
  });
}

