export async function updateSettingsLocal(
  body: Record<string, unknown>,
  actor: { id: number; fullName: string }
) {
  const allowedKeys = [
    'allowPartialPayments',
    'autoBackupEnabled',
    'autoBackupIntervalHours',
    'currentActiveYear',
  ];
  return localStore.transaction((draft) => {
    const nowIso = new Date().toISOString();
    for (const key of allowedKeys) {
      if (body[key] !== undefined) {
        const existing = draft.systemSettings.find((s) => s.key === key);
        if (existing) {
          existing.value = String(body[key]);
          existing.updatedAt = nowIso;
        } else {
          draft.systemSettings.push({ key, value: String(body[key]), updatedAt: nowIso });
        }
      }
    }
    appendActivity(draft, {
      actorUserId: actor.id,
      actorName: actor.fullName,
      actionType: 'UPDATE_SETTINGS',
      entityType: 'SETTINGS',
      entityId: 'system',
      summary: 'Updated system configuration settings',
      metadata: body,
    });
    return buildSettingsMap(draft);
  });
}

export async function getDashboardLocal(yearParam?: number) {
  return localStore.transaction((draft) => {
    const settings = buildSettingsMap(draft);
    const referenceYear = Math.max(
      START_YEAR,
      Number(yearParam || settings.currentActiveYear || new Date().getFullYear())
    );

    const totalMembers = draft.members.length;
    const activeMembers = draft.members.filter((m) => m.status === 'ACTIVE').length;
    const inactiveMembers = draft.members.filter((m) => m.status !== 'ACTIVE').length;

    for (const m of draft.members) {
      if (m.status === 'ACTIVE') {
        ensureObligationInDraft(draft, m.id, referenceYear);
      }
    }

    const memberById = new Map(draft.members.map((m) => [m.id, m]));
    const userById = new Map(draft.users.map((u) => [u.id, u]));

    const activePayments = draft.payments
      .filter((p) => !p.isVoided)
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt) || b.id - a.id)
      .map((p) => {
        const mem = memberById.get(p.memberId);
        const u = userById.get(p.receivedByUserId);
        return {
          id: p.id,
          memberId: p.memberId,
          memberName: mem?.name || 'Unknown',
          memberCode: mem?.memberCode || '',
          paymentYear: p.paymentYear,
          paidAmount: p.paidAmount,
          dueAfterPayment: p.dueAfterPayment,
          paymentDate: p.paymentDate,
          paymentTime: p.paymentTime,
          paymentMethod: p.paymentMethod,
          receiptNumber: p.receiptNumber,
          receivedByName: u?.fullName || 'Madrasa Staff',
          receivedByUsername: u?.username || '',
          isVoided: p.isVoided,
          isSyncedFromOffline: p.isSyncedFromOffline,
          createdAt: p.createdAt,
        };
      });

    const totalCollection = roundMoney(
      activePayments.reduce((sum, p) => sum + Number(p.paidAmount), 0)
    );
    const currentYearCollection = roundMoney(
      activePayments
        .filter((p) => p.paymentYear === referenceYear)
        .reduce((sum, p) => sum + Number(p.paidAmount), 0)
    );

    const activeIds = new Set(draft.members.filter((m) => m.status === 'ACTIVE').map((m) => m.id));
    let paidMembers = 0;
    let pendingMembers = 0;
    for (const ob of draft.yearlyObligations) {
      if (ob.year !== referenceYear || !activeIds.has(ob.memberId)) continue;
      if (ob.status === 'PAID') paidMembers += 1;
      else pendingMembers += 1;
    }

    const yearlyMap = new Map<number, number>();
    const maxChartYear = Math.max(
      referenceYear + 1,
      ...activePayments.map((p) => p.paymentYear),
      START_YEAR + 2
    );
    for (let y = START_YEAR; y <= maxChartYear; y++) yearlyMap.set(y, 0);
    for (const p of activePayments) {
      yearlyMap.set(
        p.paymentYear,
        roundMoney((yearlyMap.get(p.paymentYear) || 0) + Number(p.paidAmount))
      );
    }

    const recentActivities = [...draft.activityLogs]
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt) || b.id - a.id)
      .slice(0, 10)
      .map((a) => ({
        id: a.id,
        actorUserId: a.actorUserId,
        actorName: a.actorName,
        actorUsername: a.actorUserId ? userById.get(a.actorUserId)?.username || null : null,
        actionType: a.actionType,
        entityType: a.entityType,
        entityId: a.entityId,
        summary: a.summary,
        metadataJson: a.metadataJson,
        createdAt: a.createdAt,
      }));

    return {
      referenceYear,
      stats: {
        totalMembers,
        activeMembers,
        inactiveMembers,
        totalCollection,
        paidMembers,
        pendingMembers,
        currentYearCollection,
      },
      yearlyChart: Array.from(yearlyMap.entries()).map(([year, amount]) => ({ year, amount })),
      recentPayments: activePayments.slice(0, 8),
      recentActivities,
      settings,
    };
  });
}

export async function listMembersLocal(params: { q?: string; status?: string; year?: number }) {
  return localStore.read((data) => {
    const query = String(params.q || '').trim().toLowerCase();
    const statusFilter = String(params.status || 'ALL').toUpperCase();
    const settings = buildSettingsMap(data);
    const refYear = Math.max(START_YEAR, Number(params.year || settings.currentActiveYear || START_YEAR));
    const userById = new Map(data.users.map((u) => [u.id, u]));

    const filtered = data.members
      .filter((m) => {
        if (statusFilter === 'ACTIVE' || statusFilter === 'INACTIVE') {
          if (m.status !== statusFilter) return false;
        }
        if (query) {
          const hay = `${m.memberCode} ${m.name} ${m.mobile} ${m.guardianName}`.toLowerCase();
          if (!hay.includes(query)) return false;
        }
        return true;
      })
      .sort((a, b) => b.id - a.id);

    const activePayments = data.payments
      .filter((p) => !p.isVoided)
      .sort((a, b) => b.id - a.id);

    const latestReceiptByMember = new Map<number, string>();
    const yearReceiptByMember = new Map<string, string>();
    for (const p of activePayments) {
      if (!latestReceiptByMember.has(p.memberId)) {
        latestReceiptByMember.set(p.memberId, p.receiptNumber);
      }
      const key = `${p.memberId}:${p.paymentYear}`;
      if (!yearReceiptByMember.has(key)) {
        yearReceiptByMember.set(key, p.receiptNumber);
      }
    }

    const enriched = filtered.map((m) => {
      const mObs = data.yearlyObligations.filter((o) => o.memberId === m.id);
      const pending = calculatePendingSummary(
        mObs.map((o) => ({
          year: o.year,
          frozenAnnualFee: Number(o.frozenAnnualFee),
          paidTotal: Number(o.paidTotal),
          status: o.status as 'UNPAID' | 'PARTIAL' | 'PAID',
        })),
        refYear
      );
      const currentOb = mObs.find((o) => o.year === refYear);
      return {
        id: m.id,
        memberCode: m.memberCode,
        name: m.name,
        guardianName: m.guardianName,
        mobile: m.mobile,
        address: m.address,
        joiningDate: m.joiningDate,
        defaultAnnualFee: Number(m.defaultAnnualFee),
        status: m.status,
        registrationDate: m.registrationDate,
        createdByName: userById.get(m.createdByUserId)?.fullName || 'Admin',
        createdAt: m.createdAt,
        currentYearStatus: currentOb ? currentOb.status : 'UNPAID',
        currentYearPaid: currentOb ? Number(currentOb.paidTotal) : 0,
        currentYearExpected: currentOb ? Number(currentOb.frozenAnnualFee) : Number(m.defaultAnnualFee),
        totalOutstanding: pending.totalOutstanding,
        currentYearReceiptNumber: yearReceiptByMember.get(`${m.id}:${refYear}`) || null,
        latestReceiptNumber: latestReceiptByMember.get(m.id) || null,
      };
    });

    return { members: enriched, referenceYear: refYear };
  });
}

export async function searchPublicMembersLocal(rawQuery: string) {
  return localStore.read((data) => {
    const q = String(rawQuery || '').trim();
    const settings = buildSettingsMap(data);
    const refYear = Math.max(START_YEAR, Number(settings.currentActiveYear || START_YEAR));
    if (!q) {
      return { items: [], referenceYear: refYear };
    }

    const qLower = q.toLowerCase();
    const qCompact = qLower.replace(/\s+/g, '');
    const qDigits = q.replace(/\D/g, '');
    const isNumericOnly = /^\d+$/.test(q);
    const isSkmExplicit = /^skm\s*-?\s*\d+$/i.test(q);

    if (!isNumericOnly && q.length < 2) {
      return { items: [], referenceYear: refYear };
    }

    const matches = data.members.filter((m) => {
      const codeLower = m.memberCode.toLowerCase();
      const codeCompact = codeLower.replace(/\s+/g, '');
      if (isSkmExplicit) {
        return codeCompact === `skm${qDigits}`;
      }
      if (isNumericOnly) {
        if (codeCompact === `skm${q}`) return true;
        if (qDigits.length >= 4 && m.mobile.replace(/\D/g, '').includes(qDigits)) return true;
        return false;
      }
      if (codeLower === qLower || codeCompact === qCompact) return true;
      if (qLower.length >= 2 && m.name.toLowerCase().includes(qLower)) return true;
      if (qDigits.length >= 4 && m.mobile.replace(/\D/g, '').includes(qDigits)) return true;
      return false;
    });

    const items = matches.slice(0, 20).map((m) => {
      const mObs = data.yearlyObligations
        .filter((o) => o.memberId === m.id)
        .sort((a, b) => a.year - b.year);
      const pending = calculatePendingSummary(
        mObs.map((o) => ({
          year: o.year,
          frozenAnnualFee: Number(o.frozenAnnualFee),
          paidTotal: Number(o.paidTotal),
          status: o.status as 'UNPAID' | 'PARTIAL' | 'PAID',
        })),
        refYear
      );
      const currentOb = mObs.find((o) => o.year === refYear);
      const currentYearExpected = currentOb
        ? Number(currentOb.frozenAnnualFee)
        : Number(m.defaultAnnualFee);
      const currentYearPaid = currentOb ? Number(currentOb.paidTotal) : 0;
      const currentState = computeObligationState(currentYearExpected, currentYearPaid);

      const memberPays = data.payments
        .filter((p) => p.memberId === m.id && !p.isVoided)
        .sort((a, b) => b.paymentDate.localeCompare(a.paymentDate) || b.id - a.id);
      const totalPaidAllTime = roundMoney(
        memberPays.reduce((sum, p) => sum + Number(p.paidAmount), 0)
      );
      const yearlySummary = mObs
        .filter((o) => o.year <= refYear || Number(o.paidTotal) > 0)
        .map((o) => {
          const exp = Number(o.frozenAnnualFee);
          const paid = Number(o.paidTotal);
          const st = computeObligationState(exp, paid);
          return {
            year: o.year,
            expectedFee: exp,
            paidTotal: paid,
            dueAmount: st.dueAmount,
            status: st.status,
          };
        });

      return {
        memberCode: m.memberCode,
        name: m.name,
        guardianName: m.guardianName,
        status: m.status,
        referenceYear: refYear,
        currentYearStatus: currentState.status,
        currentYearExpected,
        currentYearPaid,
        currentYearDue: currentState.dueAmount,
        previousYearsDue: pending.previousYearsPending,
        totalOutstanding: pending.totalOutstanding,
        totalPaidAllTime,
        lastPaymentDate: memberPays[0]?.paymentDate || null,
        yearlySummary,
      };
    });

    return { items, referenceYear: refYear };
  });
}

export async function createMemberLocal(
  body: Record<string, unknown>,
  actor: { id: number; fullName: string }
) {
  const { name, guardianName, mobile, address, joiningDate, defaultAnnualFee, status, clientOfflineId } = body;
  if (!name || !guardianName || !mobile || !address || !joiningDate) {
    throw new RepoHttpError(400, 'All member registration fields are required.');
  }
  const feeNum = Number(defaultAnnualFee);
  if (!Number.isFinite(feeNum) || feeNum <= 0) {
    throw new RepoHttpError(400, 'Individual annual membership fee must be greater than 0.');
  }

  return localStore.transaction((draft) => {
    if (clientOfflineId) {
      const dup = draft.members.find((m) => m.clientOfflineId === String(clientOfflineId));
      if (dup) return { member: dup, duplicateSkipped: true };
    }

    const joinYear = Math.max(START_YEAR, Number(String(joiningDate).slice(0, 4)) || START_YEAR);
    const memberCode = generateNextMemberCodeSync(draft, joinYear);
    const regDate = new Date().toISOString().slice(0, 10);
    const nowIso = new Date().toISOString();

    const member: LocalMember = {
      id: nextSeq(draft, 'members'),
      memberCode,
      name: String(name).trim(),
      guardianName: String(guardianName).trim(),
      mobile: String(mobile).trim(),
      address: String(address).trim(),
      joiningDate: String(joiningDate),
      defaultAnnualFee: roundMoney(feeNum).toFixed(2),
      status: status === 'INACTIVE' ? 'INACTIVE' : 'ACTIVE',
      registrationDate: regDate,
      createdByUserId: actor.id,
      clientOfflineId: clientOfflineId ? String(clientOfflineId) : null,
      createdAt: nowIso,
      updatedAt: nowIso,
    };
    draft.members.push(member);

    draft.annualMembershipFees.push({
      id: nextSeq(draft, 'annualMembershipFees'),
      memberId: member.id,
      effectiveFromYear: joinYear,
      annualFee: roundMoney(feeNum).toFixed(2),
      notes: 'Initial registration annual fee',
      setByUserId: actor.id,
      createdAt: nowIso,
    });

    const currentYear = Math.max(START_YEAR, new Date().getFullYear());
    for (let y = joinYear; y <= Math.max(currentYear, START_YEAR + 1); y++) {
      draft.yearlyObligations.push({
        id: nextSeq(draft, 'yearlyObligations'),
        memberId: member.id,
        year: y,
        frozenAnnualFee: roundMoney(feeNum).toFixed(2),
        paidTotal: '0.00',
        status: 'UNPAID',
        createdAt: nowIso,
        updatedAt: nowIso,
      });
    }

    appendActivity(draft, {
      actorUserId: actor.id,
      actorName: actor.fullName,
      actionType: 'CREATE_MEMBER',
      entityType: 'MEMBER',
      entityId: member.memberCode,
      summary: `Registered member ${member.name} (${member.memberCode}) with fee ₹${roundMoney(feeNum)}`,
    });

    return { member, duplicateSkipped: false };
  });
}

export async function getMemberProfileLocal(memberId: number) {
  return localStore.read((data) => {
    const m = data.members.find((row) => row.id === memberId);
    if (!m) throw new RepoHttpError(404, 'Member not found.');
    const userById = new Map(data.users.map((u) => [u.id, u]));

    const schedules = data.annualMembershipFees
      .filter((s) => s.memberId === memberId)
      .sort((a, b) => a.effectiveFromYear - b.effectiveFromYear);
    const obligations = data.yearlyObligations
      .filter((o) => o.memberId === memberId)
      .sort((a, b) => a.year - b.year);
    const memberPayments = data.payments
      .filter((p) => p.memberId === memberId)
      .sort((a, b) => b.paymentYear - a.paymentYear || b.createdAt.localeCompare(a.createdAt))
      .map((p) => {
        const u = userById.get(p.receivedByUserId);
        return {
          ...p,
          expectedFee: Number(p.expectedFee),
          paidAmount: Number(p.paidAmount),
          dueAfterPayment: Number(p.dueAfterPayment),
          receivedByName: u?.fullName || 'Madrasa Staff',
          receivedByUsername: u?.username || '',
        };
      });

    const settings = buildSettingsMap(data);
    const refYear = Math.max(START_YEAR, Number(settings.currentActiveYear || START_YEAR));

    const obByYear = new Map(obligations.map((o) => [o.year, o]));
    const scheduleEntries = schedules.map((s) => ({
      effectiveFromYear: s.effectiveFromYear,
      annualFee: Number(s.annualFee),
    }));
    const joinYear = Math.max(START_YEAR, Number(m.joiningDate.slice(0, 4)) || START_YEAR);
    const yearlyLedger = [];
    for (let y = joinYear; y <= 2055; y++) {
      const existingOb = obByYear.get(y);
      const expectedFee = existingOb
        ? Number(existingOb.frozenAnnualFee)
        : resolveAnnualFeeForYear(y, Number(m.defaultAnnualFee), scheduleEntries);
      const paidTotal = existingOb ? Number(existingOb.paidTotal) : 0;
      const computed = computeObligationState(expectedFee, paidTotal);
      yearlyLedger.push({
        year: y,
        frozenAnnualFee: expectedFee,
        paidTotal,
        dueAmount: computed.dueAmount,
        status: existingOb ? existingOb.status : computed.status,
        isFutureYear: y > refYear,
        isPersisted: !!existingOb,
      });
    }

    const pendingSummary = calculatePendingSummary(
      obligations.map((o) => ({
        year: o.year,
        frozenAnnualFee: Number(o.frozenAnnualFee),
        paidTotal: Number(o.paidTotal),
        status: o.status as 'UNPAID' | 'PARTIAL' | 'PAID',
      })),
      refYear
    );

    return {
      member: {
        ...m,
        defaultAnnualFee: Number(m.defaultAnnualFee),
        createdByName: userById.get(m.createdByUserId)?.fullName || 'Admin',
      },
      schedules: schedules.map((s) => ({ ...s, annualFee: Number(s.annualFee) })),
      yearlyLedger,
      payments: memberPayments,
      pendingSummary,
      referenceYear: refYear,
    };
  });
}

function applyMemberUpdateInDraft(
  draft: LocalDatabaseSnapshot,
  memberId: number,
  body: Record<string, unknown>,
  actor: { id: number; fullName: string; roleName: 'ADMIN' | 'STAFF' }
) {
  const member = draft.members.find((m) => m.id === memberId);
  if (!member) throw new RepoHttpError(404, 'Member not found.');

  const { name, guardianName, mobile, address, status, newAnnualFee, effectiveFromYear, feeNotes } = body;
  const nowIso = new Date().toISOString();

  if (name) member.name = String(name).trim();
  if (guardianName) member.guardianName = String(guardianName).trim();
  if (mobile) member.mobile = String(mobile).trim();
  if (address) member.address = String(address).trim();
  if (status !== undefined && status !== member.status && actor.roleName !== 'ADMIN') {
    throw new RepoHttpError(403, 'Only Admin can activate or deactivate members.');
  }
  if ((status === 'ACTIVE' || status === 'INACTIVE') && actor.roleName === 'ADMIN') {
    member.status = status;
  }

  if (newAnnualFee !== undefined && Number(newAnnualFee) > 0) {
    const feeVal = roundMoney(Number(newAnnualFee));
    const effYear = Math.max(START_YEAR, Number(effectiveFromYear || new Date().getFullYear()));
    member.defaultAnnualFee = feeVal.toFixed(2);

    const existingSched = draft.annualMembershipFees.find(
      (s) => s.memberId === memberId && s.effectiveFromYear === effYear
    );
    if (existingSched) {
      existingSched.annualFee = feeVal.toFixed(2);
      existingSched.notes = feeNotes ? String(feeNotes) : `Updated fee from ${effYear}`;
      existingSched.setByUserId = actor.id;
    } else {
      draft.annualMembershipFees.push({
        id: nextSeq(draft, 'annualMembershipFees'),
        memberId,
        effectiveFromYear: effYear,
        annualFee: feeVal.toFixed(2),
        notes: feeNotes ? String(feeNotes) : `Updated fee from ${effYear}`,
        setByUserId: actor.id,
        createdAt: nowIso,
      });
    }

    for (const ob of draft.yearlyObligations) {
      if (ob.memberId === memberId && ob.year >= effYear) {
        const paidNum = Number(ob.paidTotal);
        if (paidNum === 0 || (ob.year === effYear && feeVal >= paidNum)) {
          const nextState = computeObligationState(feeVal, paidNum);
          ob.frozenAnnualFee = feeVal.toFixed(2);
          ob.status = nextState.status;
          ob.updatedAt = nowIso;
        }
      }
    }
  }

  member.updatedAt = nowIso;

  appendActivity(draft, {
    actorUserId: actor.id,
    actorName: actor.fullName,
    actionType: 'UPDATE_MEMBER',
    entityType: 'MEMBER',
    entityId: member.memberCode,
    summary: `Updated member ${member.name} (${member.memberCode})`,
    metadata: body,
  });

  return member;
}

