    return { member };
  });
}

function applyMemberDeleteInDraft(
  draft: LocalDatabaseSnapshot,
  memberId: number,
  actor: { id: number; fullName: string }
) {
  const idx = draft.members.findIndex((m) => m.id === memberId);
  if (idx === -1) throw new RepoHttpError(404, 'Member not found.');
  const existing = draft.members[idx];

  const removedPaymentIds = new Set(
    draft.payments.filter((p) => p.memberId === memberId).map((p) => p.id)
  );
  draft.members.splice(idx, 1);
  draft.annualMembershipFees = draft.annualMembershipFees.filter((f) => f.memberId !== memberId);
  draft.yearlyObligations = draft.yearlyObligations.filter((o) => o.memberId !== memberId);
  draft.payments = draft.payments.filter((p) => p.memberId !== memberId);
  draft.paymentCorrections = draft.paymentCorrections.filter(
    (c) => !removedPaymentIds.has(c.paymentId)
  );
  draft.receipts = draft.receipts.filter((r) => !removedPaymentIds.has(r.paymentId));

  appendActivity(draft, {
    actorUserId: actor.id,
    actorName: actor.fullName,
    actionType: 'DELETE_MEMBER',
    entityType: 'MEMBER',
    entityId: existing.memberCode,
    summary: `Deleted member ${existing.name} (${existing.memberCode})`,
    metadata: {
      memberId: existing.id,
      memberCode: existing.memberCode,
      name: existing.name,
      mobile: existing.mobile,
    },
  });

  return { ok: true, deletedMemberCode: existing.memberCode, deletedName: existing.name };
}

export async function deleteMemberLocal(
  memberId: number,
  actor: { id: number; fullName: string }
) {
  return localStore.transaction((draft) => applyMemberDeleteInDraft(draft, memberId, actor));
}

export async function recordPaymentLocal(
  body: Record<string, unknown>,
  actor: { id: number; fullName: string }
) {
  const mId = Number(body.memberId);
  const yearNum = Number(body.paymentYear);
  const amountNum = Number(body.paidAmount);
  const includePrev = Boolean(body.includePreviousDues);
  const clientTxId = body.clientTxId ? String(body.clientTxId) : null;

  if (!Number.isInteger(mId) || !Number.isInteger(yearNum) || !Number.isFinite(amountNum)) {
    throw new RepoHttpError(400, 'Member, valid payment year, and amount are required.');
  }

  return localStore.transaction((draft) => {
    if (clientTxId) {
      const dup = draft.payments.find((p) => p.clientTxId === clientTxId);
      if (dup) return { payment: dup, duplicateSkipped: true };
    }

    const member = draft.members.find((m) => m.id === mId);
    if (!member) throw new RepoHttpError(404, 'Member not found.');

    const settings = buildSettingsMap(draft);
    const allowPartialPayments = settings.allowPartialPayments === 'true';

    const joinYear = Math.max(START_YEAR, Number(member.joiningDate.slice(0, 4)) || START_YEAR);
    const ensureStartYear = includePrev ? Math.min(joinYear, yearNum) : yearNum;
    for (let y = ensureStartYear; y <= yearNum; y++) {
      ensureObligationInDraft(draft, mId, y);
    }

    const obRows = draft.yearlyObligations
      .filter((o) =>
        includePrev
          ? o.memberId === mId && o.year >= START_YEAR && o.year <= yearNum
          : o.memberId === mId && o.year === yearNum
      )
      .sort((a, b) => a.year - b.year);

    if (obRows.length === 0) throw new RepoHttpError(400, 'Obligation row missing.');

    const plan = allocateMultiYearPayment({
      referenceYear: yearNum,
      obligations: obRows.map((o) => ({
        year: o.year,
        expectedFee: Number(o.frozenAnnualFee),
        alreadyPaid: Number(o.paidTotal),
      })),
      attemptAmount: amountNum,
      includePreviousDues: includePrev,
      allowPartialPayments,
    });

    if (!plan.ok) {
      throw new RepoHttpError(400, plan.error || 'Payment validation failed.');
    }

    const now = new Date();
    const nowIso = now.toISOString();
    const dateStr = body.paymentDate ? String(body.paymentDate) : nowIso.slice(0, 10);
    const monthStr = dateStr.slice(0, 7);
    const timeStr = body.paymentTime ? String(body.paymentTime) : now.toTimeString().slice(0, 8);
    const methodStr = body.paymentMethod ? String(body.paymentMethod) : 'Cash';
    const notesStr = body.notes ? String(body.notes) : null;

    const receiptNumber = generateNextReceiptNumberSync(draft, yearNum);
    const obByYear = new Map(obRows.map((o) => [o.year, o]));
    const primaryAlloc =
      plan.allocations.find((a) => a.year === yearNum) ??
      plan.allocations[plan.allocations.length - 1];

    let primaryPayment: LocalPayment | null = null;
    const insertedPayments: LocalPayment[] = [];

    for (const alloc of plan.allocations) {
      const ob = obByYear.get(alloc.year);
      if (!ob) throw new RepoHttpError(500, 'Obligation missing during allocation.');
      const isPrimaryRow = alloc.year === primaryAlloc.year;
      const rowReceiptNumber = isPrimaryRow ? receiptNumber : `${receiptNumber}/${alloc.year}`;
      const rowNotes =
        plan.allocations.length > 1
          ? [
              notesStr ? notesStr.trim() : '',
              isPrimaryRow
                ? `Combined Receipt #${receiptNumber} (Prev: ₹${plan.previousYearsPaidNow}, ${yearNum}: ₹${plan.currentYearPaidNow})`
                : `Previous year (${alloc.year}) settled in Receipt #${receiptNumber}`,
            ]
              .filter(Boolean)
              .join(' · ')
          : notesStr
            ? notesStr.trim()
            : null;

      const pay: LocalPayment = {
        id: nextSeq(draft, 'payments'),
        obligationId: ob.id,
        memberId: mId,
        paymentYear: alloc.year,
        expectedFee: alloc.expectedFee.toFixed(2),
        paidAmount: alloc.paidNow.toFixed(2),
        dueAfterPayment: alloc.dueAfterPayment.toFixed(2),
        paymentDate: dateStr,
        paymentMonth: monthStr,
        paymentTime: timeStr,
        paymentMethod: methodStr,
        receiptNumber: rowReceiptNumber,
        receivedByUserId: actor.id,
        notes: rowNotes,
        clientTxId: isPrimaryRow && clientTxId ? clientTxId : null,
        isSyncedFromOffline: false,
        isVoided: false,
        createdAt: nowIso,
        updatedAt: nowIso,
      };
      draft.payments.push(pay);
      insertedPayments.push(pay);
      if (isPrimaryRow) primaryPayment = pay;

      ob.paidTotal = alloc.newPaidTotal.toFixed(2);
      ob.status = alloc.status;
      ob.updatedAt = nowIso;
    }

    if (!primaryPayment) throw new RepoHttpError(500, 'Failed to allocate primary payment.');

    const hasPreviousContext =
      plan.previousYearsPaidNow > 0 || plan.previousYearsRemainingDue > 0;
    const breakdownObj = hasPreviousContext
      ? {
          isCombinedArrearsReceipt: true,
          referenceYear: yearNum,
          previousYearsPaid: plan.previousYearsPaidNow,
          currentYearPaid: plan.currentYearPaidNow,
          previousYearsRemainingDue: plan.previousYearsRemainingDue,
          currentYearRemainingDue: plan.currentYearRemainingDue,
          totalPaid: plan.totalPaidNow,
          totalRemainingDue: plan.totalRemainingDue,
          yearLines: plan.allocations.map((a) => ({
            year: a.year,
            expectedFee: a.expectedFee,
            paidNow: a.paidNow,
            totalPaidForYear: a.newPaidTotal,
            remainingDue: a.dueAfterPayment,
            isPreviousYear: a.isPreviousYear,
          })),
        }
      : null;

    const receipt = {
      id: nextSeq(draft, 'receipts'),
      paymentId: primaryPayment.id,
      receiptNumber,
      memberCode: member.memberCode,
      issuedToName: member.name,
      paymentYear: yearNum,
      amountPaid: plan.totalPaidNow.toFixed(2),
      remainingDue: plan.totalRemainingDue.toFixed(2),
      issuedByName: actor.fullName,
      issuedAt: nowIso,
      verificationHash: sha256Hex(`${receiptNumber}:${member.memberCode}:${plan.totalPaidNow}:${dateStr}`).slice(0, 16),
      breakdownJson: breakdownObj ? JSON.stringify(breakdownObj) : null,
    };
    draft.receipts.push(receipt);

    const summaryNote =
      plan.previousYearsPaidNow > 0
        ? `Received ₹${plan.totalPaidNow} from ${member.name} (${member.memberCode}) [Prev: ₹${plan.previousYearsPaidNow}, ${yearNum}: ₹${plan.currentYearPaidNow}]`
        : `Received ₹${plan.totalPaidNow} from ${member.name} (${member.memberCode}) for ${yearNum}`;

    appendActivity(draft, {
      actorUserId: actor.id,
      actorName: actor.fullName,
      actionType: 'RECORD_PAYMENT',
      entityType: 'PAYMENT',
      entityId: receiptNumber,
      summary: summaryNote,
      metadata: {
        memberCode: member.memberCode,
        year: yearNum,
        paidAmount: plan.totalPaidNow,
        previousYearsPaid: plan.previousYearsPaidNow,
        currentYearPaid: plan.currentYearPaidNow,
        dueAfterPayment: plan.totalRemainingDue,
        settledYears: plan.allocations.map((a) => a.year),
      },
    });

    return {
      payment: primaryPayment,
      payments: insertedPayments,
      receipt,
      member,
      breakdown: breakdownObj,
    };
  });
}

export async function listPaymentsLocal(filters: {
  year?: number | null;
  memberId?: number | null;
  staffId?: number | null;
  q?: string;
}) {
  return localStore.read((data) => {
    const memberById = new Map(data.members.map((m) => [m.id, m]));
    const userById = new Map(data.users.map((u) => [u.id, u]));
    const search = String(filters.q || '').trim().toLowerCase();

    const filtered = data.payments
      .filter((p) => {
        if (filters.year && p.paymentYear !== filters.year) return false;
        if (filters.memberId && p.memberId !== filters.memberId) return false;
        if (filters.staffId && p.receivedByUserId !== filters.staffId) return false;
        if (search) {
          const mem = memberById.get(p.memberId);
          const hay = `${p.receiptNumber} ${mem?.memberCode || ''} ${mem?.name || ''} ${mem?.mobile || ''} ${mem?.address || ''}`.toLowerCase();
          if (!hay.includes(search)) return false;
        }
        return true;
      })
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt) || b.id - a.id);

    const corrByPayment = new Map<number, Array<Record<string, unknown>>>();
    const sortedCorrs = [...data.paymentCorrections].sort((a, b) =>
      b.correctedAt.localeCompare(a.correctedAt)
    );
    for (const c of sortedCorrs) {
      const list = corrByPayment.get(c.paymentId) || [];
      list.push({
        ...c,
        correctedByName: userById.get(c.correctedByUserId)?.fullName || 'Admin',
      });
      corrByPayment.set(c.paymentId, list);
    }

    return {
      payments: filtered.map((p) => {
        const mem = memberById.get(p.memberId);
        const u = userById.get(p.receivedByUserId);
        return {
          ...p,
          memberCode: mem?.memberCode || '',
          memberName: mem?.name || '',
          memberMobile: mem?.mobile || '',
          memberAddress: mem?.address || '',
          receivedByName: u?.fullName || 'Madrasa Staff',
          receivedByUsername: u?.username || '',
          expectedFee: Number(p.expectedFee),
          paidAmount: Number(p.paidAmount),
          dueAfterPayment: Number(p.dueAfterPayment),
          corrections: corrByPayment.get(p.id) || [],
        };
      }),
    };
  });
}

export async function correctPaymentLocal(
  paymentId: number,
  body: Record<string, unknown>,
  actor: { id: number; fullName: string }
) {
  const { newPaidAmount, newPaymentMethod, newNotes, reason } = body;
  if (!reason || String(reason).trim().length < 5) {
    throw new RepoHttpError(
      400,
      'A detailed reason (minimum 5 characters) is mandatory for payment corrections.'
    );
  }

  return localStore.transaction((draft) => {
    const pay = draft.payments.find((p) => p.id === paymentId);
    if (!pay) throw new RepoHttpError(404, 'Payment not found.');

    const ob = draft.yearlyObligations.find((o) => o.id === pay.obligationId);
    if (!ob) throw new RepoHttpError(404, 'Obligation not found.');

    const siblingPayments = draft.payments.filter(
      (p) => p.obligationId === ob.id && !p.isVoided
    );
    const otherPaidTotal = roundMoney(
      siblingPayments
        .filter((p) => p.id !== paymentId)
        .reduce((sum, p) => sum + Number(p.paidAmount), 0)
    );

    const targetAmount = newPaidAmount !== undefined ? Number(newPaidAmount) : Number(pay.paidAmount);
    const validation = validateCorrectionRequest({
      originalAmount: Number(pay.paidAmount),
      newAmount: targetAmount,
      reason: String(reason),
      otherPaymentsPaidTotal: otherPaidTotal,
      expectedFee: Number(ob.frozenAnnualFee),
    });

    if (!validation.ok) {
      throw new RepoHttpError(400, validation.error || 'Invalid payment correction.');
    }

    const auditEntries: Array<{ fieldName: string; originalValue: string; updatedValue: string }> = [];
    if (roundMoney(targetAmount) !== roundMoney(Number(pay.paidAmount))) {
      auditEntries.push({
        fieldName: 'paidAmount',
        originalValue: pay.paidAmount,
        updatedValue: roundMoney(targetAmount).toFixed(2),
      });
    }
    if (newPaymentMethod && String(newPaymentMethod) !== pay.paymentMethod) {
      auditEntries.push({
        fieldName: 'paymentMethod',
        originalValue: pay.paymentMethod,
        updatedValue: String(newPaymentMethod),
      });
    }
    if (newNotes !== undefined && String(newNotes) !== (pay.notes || '')) {
      auditEntries.push({
        fieldName: 'notes',
        originalValue: pay.notes || '(empty)',
        updatedValue: String(newNotes) || '(empty)',
      });
    }

    if (auditEntries.length === 0) {
      throw new RepoHttpError(400, 'No changes were made to the payment record.');
    }

    const nowIso = new Date().toISOString();
    pay.paidAmount = roundMoney(targetAmount).toFixed(2);
    pay.dueAfterPayment = validation.newObligationDue.toFixed(2);
    if (newPaymentMethod) pay.paymentMethod = String(newPaymentMethod);
    if (newNotes !== undefined) pay.notes = String(newNotes);
    pay.updatedAt = nowIso;

    ob.paidTotal = validation.newObligationPaidTotal.toFixed(2);
    ob.status = validation.newStatus;
    ob.updatedAt = nowIso;

    const rcp = draft.receipts.find((r) => r.paymentId === paymentId);
    if (rcp) {
      rcp.amountPaid = roundMoney(targetAmount).toFixed(2);
      rcp.remainingDue = validation.newObligationDue.toFixed(2);
    }

    for (const entry of auditEntries) {
      draft.paymentCorrections.push({
        id: nextSeq(draft, 'paymentCorrections'),
        paymentId,
        fieldName: entry.fieldName,
        originalValue: entry.originalValue,
        updatedValue: entry.updatedValue,
        reason: String(reason).trim(),
        correctedByUserId: actor.id,
        correctedAt: nowIso,
      });
    }

    appendActivity(draft, {
      actorUserId: actor.id,
      actorName: actor.fullName,
      actionType: 'CORRECT_PAYMENT',
      entityType: 'PAYMENT',
      entityId: pay.receiptNumber,
      summary: `Corrected receipt ${pay.receiptNumber}: ${String(reason).trim()}`,
      metadata: auditEntries,
    });

    return { payment: pay };
  });
}

export async function getReceiptLocal(rawParam: string) {
  return localStore.read((data) => {
    const primaryNo = rawParam.includes('/') ? rawParam.split('/')[0] : rawParam;
    let rcp = data.receipts.find((r) => r.receiptNumber === rawParam);
    if (!rcp && primaryNo !== rawParam) {
      rcp = data.receipts.find((r) => r.receiptNumber === primaryNo);
    }
    if (!rcp) throw new RepoHttpError(404, 'Receipt not found.');

    const pay = data.payments.find((p) => p.id === rcp.paymentId);
    if (!pay) throw new RepoHttpError(404, 'Payment record for receipt not found.');
    const mem = data.members.find((m) => m.id === pay.memberId);
    if (!mem) throw new RepoHttpError(404, 'Member for receipt not found.');
    const u = data.users.find((usr) => usr.id === pay.receivedByUserId);

    let parsedBreakdown = null;
    if (rcp.breakdownJson) {
      try {
        parsedBreakdown = JSON.parse(rcp.breakdownJson);
      } catch {
        parsedBreakdown = null;
      }
    }

    const settings = buildSettingsMap(data);
    const activeReferenceYear = Math.max(
      START_YEAR,
      Number(settings.currentActiveYear) || new Date().getFullYear()
    );
    const joinYear = Math.max(START_YEAR, Number(mem.joiningDate.slice(0, 4)) || START_YEAR);
    const scheds = data.annualMembershipFees
      .filter((s) => s.memberId === mem.id)
      .map((s) => ({ effectiveFromYear: s.effectiveFromYear, annualFee: Number(s.annualFee) }));
    const obByYear = new Map(
      data.yearlyObligations.filter((o) => o.memberId === mem.id).map((o) => [o.year, o])
    );

    const previousPendingDues: Array<{ year: number; dueAmount: number }> = [];
    for (let y = joinYear; y < rcp.paymentYear; y++) {
      const ob = obByYear.get(y);
      const expFee = ob
        ? Number(ob.frozenAnnualFee)
        : resolveAnnualFeeForYear(y, Number(mem.defaultAnnualFee), scheds);
      const paidVal = ob ? Number(ob.paidTotal) : 0;
      const dueVal = roundMoney(Math.max(0, expFee - paidVal));
      if (dueVal > 0) {
        previousPendingDues.push({ year: y, dueAmount: dueVal });
      }
    }
    const totalPreviousDueAmount = roundMoney(
      previousPendingDues.reduce((sum, item) => sum + item.dueAmount, 0)
    );

    return {
      receipt: {
        receiptNumber: rcp.receiptNumber,
        memberCode: rcp.memberCode,
        issuedToName: rcp.issuedToName,
        paymentYear: rcp.paymentYear,
        amountPaid: Number(rcp.amountPaid),
        remainingDue: Number(rcp.remainingDue),
        expectedFee: parsedBreakdown
          ? Number(parsedBreakdown.totalPaid + parsedBreakdown.totalRemainingDue)
          : Number(pay.expectedFee),
        issuedByName: rcp.issuedByName,
        issuedByUsername: u?.username || undefined,
        issuedAt: rcp.issuedAt,
        verificationHash: rcp.verificationHash,
        paymentDate: pay.paymentDate,
        paymentTime: pay.paymentTime,
        paymentMethod: pay.paymentMethod,
        notes: pay.notes,
        guardianName: mem.guardianName,
        mobile: mem.mobile,
        address: mem.address,
        isAdvanceYearPayment: rcp.paymentYear > activeReferenceYear,
        activeReferenceYear,
        previousPendingDues,
        totalPreviousDueAmount,
        breakdown: parsedBreakdown,
      },
    };
  });
}

export async function getPendingDuesLocal(yearParam?: number) {
  return localStore.transaction((draft) => {
    const settings = buildSettingsMap(draft);
    const referenceYear = Math.max(
      START_YEAR,
      Number(yearParam || settings.currentActiveYear || START_YEAR)
    );

    const activeMembers = draft.members
      .filter((m) => m.status === 'ACTIVE')
      .sort((a, b) => a.memberCode.localeCompare(b.memberCode));

    for (const m of activeMembers) {
      const joinYear = Math.max(START_YEAR, Number(m.joiningDate.slice(0, 4)) || START_YEAR);
      for (let y = joinYear; y <= referenceYear; y++) {
        ensureObligationInDraft(draft, m.id, y);
      }
    }

    const activePayments = draft.payments
      .filter((p) => !p.isVoided)
      .sort((a, b) => b.id - a.id);

    const latestReceiptByMember = new Map<number, string>();
    const yearReceiptByMember = new Map<string, string>();
    for (const p of activePayments) {
      if (!latestReceiptByMember.has(p.memberId)) {
        latestReceiptByMember.set(p.memberId, p.receiptNumber);
      }
      const key = `${p.memberId}:${p.paymentYear}`;
      if (!yearReceiptByMember.has(key)) yearReceiptByMember.set(key, p.receiptNumber);
    }

    let totalCurrentYearPending = 0;
    let totalPreviousYearsPending = 0;

    const memberPendingList = activeMembers.map((m) => {
      const joinYear = Math.max(START_YEAR, Number(m.joiningDate.slice(0, 4)) || START_YEAR);
      const obs = draft.yearlyObligations.filter(
        (o) => o.memberId === m.id && o.year <= referenceYear && o.year >= joinYear
      );
      const summary = calculatePendingSummary(
        obs.map((o) => ({
          year: o.year,
          frozenAnnualFee: Number(o.frozenAnnualFee),
          paidTotal: Number(o.paidTotal),
          status: o.status as 'UNPAID' | 'PARTIAL' | 'PAID',
        })),
        referenceYear
      );
      totalCurrentYearPending = roundMoney(totalCurrentYearPending + summary.currentYearPending);
      totalPreviousYearsPending = roundMoney(totalPreviousYearsPending + summary.previousYearsPending);
      const currentYearOb = obs.find((o) => o.year === referenceYear);
      const currentStatus = currentYearOb
        ? (currentYearOb.status as 'UNPAID' | 'PARTIAL' | 'PAID')
        : 'UNPAID';

      return {
        memberId: m.id,
        memberCode: m.memberCode,
        name: m.name,
        guardianName: m.guardianName,
        mobile: m.mobile,
        defaultAnnualFee: Number(m.defaultAnnualFee),
        currentYearStatus: currentStatus,
        currentYearPending: summary.currentYearPending,
        previousYearsPending: summary.previousYearsPending,
        totalOutstanding: summary.totalOutstanding,
        overdueYears: summary.overdueYears,
        currentYearReceiptNumber: yearReceiptByMember.get(`${m.id}:${referenceYear}`) || null,
        latestReceiptNumber: latestReceiptByMember.get(m.id) || null,
      };
    });

    return {
      referenceYear,
      summary: {
        currentYearPending: totalCurrentYearPending,
        previousYearsPending: totalPreviousYearsPending,
        totalOutstanding: roundMoney(totalCurrentYearPending + totalPreviousYearsPending),
        pendingMemberCount: memberPendingList.filter((m) => m.totalOutstanding > 0).length,
      },
      items: memberPendingList.filter((m) => m.totalOutstanding > 0),
      allActiveStatus: memberPendingList,
    };
  });
}

export async function getReportLocal(
  reportType: string,
  filters: {
    year?: number | null;
    fromDate?: string | null;
    toDate?: string | null;
    memberId?: number | null;
    staffId?: number | null;
  }
) {
  return localStore.transaction((draft) => {
    const settings = buildSettingsMap(draft);
    const refYear = filters.year || Math.max(START_YEAR, Number(settings.currentActiveYear || START_YEAR));

    if (reportType === 'all-members' || reportType === 'active-members' || reportType === 'inactive-members') {
      const rows = draft.members
        .filter((m) => {
          if (reportType === 'active-members') return m.status === 'ACTIVE';
          if (reportType === 'inactive-members') return m.status === 'INACTIVE';
          return true;
        })
        .sort((a, b) => a.memberCode.localeCompare(b.memberCode))
        .map((m) => ({
          memberCode: m.memberCode,
          name: m.name,
          guardianName: m.guardianName,
          mobile: m.mobile,
          address: m.address,
          joiningDate: m.joiningDate,
          annualFee: Number(m.defaultAnnualFee),
          status: m.status,
          registrationDate: m.registrationDate,
        }));
      return { reportType, rows };
    }

    if (reportType === 'paid-members' || reportType === 'pending-members' || reportType === 'outstanding-dues') {
      const allMembers = [...draft.members].sort((a, b) => a.memberCode.localeCompare(b.memberCode));
      for (const m of allMembers) {
        if (m.status === 'ACTIVE') ensureObligationInDraft(draft, m.id, refYear);
      }

      const yearReceiptMap = new Map<string, string>();
      for (const p of draft.payments.filter((p) => !p.isVoided).sort((a, b) => b.id - a.id)) {
        const key = `${p.memberId}:${p.paymentYear}`;
        if (!yearReceiptMap.has(key)) yearReceiptMap.set(key, p.receiptNumber);
      }

      const rows = allMembers
        .filter((m) => (filters.memberId ? m.id === filters.memberId : true))
        .map((m) => {
          const mObs = draft.yearlyObligations.filter((o) => o.memberId === m.id && o.year <= refYear);
          const yearOb = mObs.find((o) => o.year === refYear);
          const pending = calculatePendingSummary(
            mObs.map((o) => ({
              year: o.year,
              frozenAnnualFee: Number(o.frozenAnnualFee),
              paidTotal: Number(o.paidTotal),
              status: o.status as 'UNPAID' | 'PARTIAL' | 'PAID',
            })),
            refYear
          );
          const expected = yearOb ? Number(yearOb.frozenAnnualFee) : Number(m.defaultAnnualFee);
          const paid = yearOb ? Number(yearOb.paidTotal) : 0;
          const status = yearOb ? yearOb.status : 'UNPAID';
          return {
            memberCode: m.memberCode,
            name: m.name,
            mobile: m.mobile,
            memberStatus: m.status,
            year: refYear,
            expectedFee: expected,
            paidAmount: paid,
            currentYearDue: roundMoney(Math.max(0, expected - paid)),
            previousYearsDue: pending.previousYearsPending,
            totalOutstanding: pending.totalOutstanding,
            paymentStatus: status,
            receiptNumber: yearReceiptMap.get(`${m.id}:${refYear}`) || '',
          };
        });

      const filtered =
        reportType === 'paid-members'
          ? rows.filter((r) => r.paymentStatus === 'PAID')
          : rows.filter((r) => r.totalOutstanding > 0 || r.paymentStatus !== 'PAID');
      return { reportType, year: refYear, rows: filtered };
    }

    if (
      reportType === 'yearly-collection' ||
      reportType === 'total-collection' ||
      reportType === 'member-history'
    ) {
      const memberById = new Map(draft.members.map((m) => [m.id, m]));
      const userById = new Map(draft.users.map((u) => [u.id, u]));
      const rows = draft.payments
        .filter((p) => {
          if (p.isVoided) return false;
          if (filters.year && reportType !== 'total-collection' && p.paymentYear !== filters.year) return false;
          if (filters.memberId && p.memberId !== filters.memberId) return false;
          if (filters.staffId && p.receivedByUserId !== filters.staffId) return false;
          if (filters.fromDate && p.paymentDate < filters.fromDate) return false;
          if (filters.toDate && p.paymentDate > filters.toDate) return false;
          return true;
        })
        .sort((a, b) => b.paymentDate.localeCompare(a.paymentDate) || b.id - a.id)
        .map((p) => {
          const mem = memberById.get(p.memberId);
          const u = userById.get(p.receivedByUserId);
          return {
            receiptNumber: p.receiptNumber,
            memberCode: mem?.memberCode || '',
            memberName: mem?.name || '',
            mobile: mem?.mobile || '',
            paymentYear: p.paymentYear,
            expectedFee: Number(p.expectedFee),
            paidAmount: Number(p.paidAmount),
            dueAfterPayment: Number(p.dueAfterPayment),
            paymentDate: p.paymentDate,
            paymentTime: p.paymentTime,
            paymentMethod: p.paymentMethod,
            receivedByName: u?.fullName || 'Madrasa Staff',
            notes: p.notes,
          };
        });
      return { reportType, rows };
    }

    if (reportType === 'staff-activity') {
      const rows = draft.activityLogs
        .filter((l) => {
          if (filters.staffId && l.actorUserId !== filters.staffId) return false;
          const d = l.createdAt.slice(0, 10);
          if (filters.fromDate && d < filters.fromDate) return false;
          if (filters.toDate && d > filters.toDate) return false;
          return true;
        })
        .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
        .slice(0, 300);
      return { reportType, rows };
    }

    throw new RepoHttpError(400, `Unknown report type: ${reportType}`);
  });
}

export async function listStaffLocal(isAdmin: boolean) {
  return localStore.read((data) => {
    const roleById = new Map(data.roles.map((r) => [r.id, r.name]));
    const allPerms = [...data.permissions].sort((a, b) => a.id - b.id);
    const permCodeById = new Map(allPerms.map((p) => [p.id, p.code]));
    const sortedUsers = [...data.users].sort((a, b) => a.id - b.id);

    if (!isAdmin) {
      return {
        staff: sortedUsers.map((u) => ({
          id: u.id,
          fullName: u.fullName,
          username: u.username,
          roleName: roleById.get(u.roleId) || 'STAFF',
        })),
        permissions: [],
      };
    }

    const permMap = new Map<number, string[]>();
    for (const up of data.userPermissions) {
      const code = permCodeById.get(up.permissionId);
      if (!code) continue;
      const list = permMap.get(up.userId) || [];
      list.push(code);
      permMap.set(up.userId, list);
    }

    return {
      staff: sortedUsers.map((u) => {
        const roleName = roleById.get(u.roleId) || 'STAFF';
        return {
          id: u.id,
          username: u.username,
          fullName: u.fullName,
          email: u.email,
          phone: u.phone,
          roleName,
          isActive: u.isActive,
          canOfflineEntry: u.canOfflineEntry,
          lastLoginAt: u.lastLoginAt,
          createdAt: u.createdAt,
          permissions: roleName === 'ADMIN' ? allPerms.map((p) => p.code) : permMap.get(u.id) || [],
        };
      }),
      permissions: allPerms,
    };
  });
}

export async function createStaffLocal(
  body: Record<string, unknown>,
  actor: { id: number; fullName: string }
) {
  const { username, password, fullName, email, phone, roleName, permissionCodes } = body;
  if (!username || !password || !fullName) {
    throw new RepoHttpError(400, 'Username, password, and full name are required.');
  }
  const cleanUsername = String(username).trim().toLowerCase();
  const targetRoleName = roleName === 'ADMIN' ? 'ADMIN' : 'STAFF';

  return localStore.transaction((draft) => {
    if (draft.users.some((u) => u.username.toLowerCase() === cleanUsername)) {
      throw new RepoHttpError(400, 'Failed to create staff account (username already exists).');
    }
    const role = draft.roles.find((r) => r.name === targetRoleName);
    if (!role) throw new RepoHttpError(500, 'Role configuration missing.');

    const nowIso = new Date().toISOString();
    const newUser = {
      id: nextSeq(draft, 'users'),
      uid: null,
      username: cleanUsername,
      passwordHash: hashPassword(String(password)),
      fullName: String(fullName).trim(),
      email: email ? String(email).trim() : null,
      phone: phone ? String(phone).trim() : null,
      roleId: role.id,
      isActive: true,
      canOfflineEntry: targetRoleName === 'ADMIN',
      lastLoginAt: null,
      createdAt: nowIso,
      updatedAt: nowIso,
    };
    draft.users.push(newUser);

    if (targetRoleName === 'STAFF' && Array.isArray(permissionCodes)) {
      const byCode = new Map(draft.permissions.map((p) => [p.code, p.id]));
      const allowedCodes = permissionCodes
        .map((c) => String(c))
        .filter((code) => code !== 'members:create' && code !== 'members:delete');
      for (const code of allowedCodes) {
        const pId = byCode.get(code);
        if (pId) {
          draft.userPermissions.push({
            id: nextSeq(draft, 'userPermissions'),
            userId: newUser.id,
            permissionId: pId,
            grantedAt: nowIso,
          });
        }
      }
    }

    appendActivity(draft, {
      actorUserId: actor.id,
      actorName: actor.fullName,
      actionType: 'CREATE_STAFF',
      entityType: 'USER',
      entityId: newUser.username,
      summary: `Created ${targetRoleName} account ${newUser.fullName} (${newUser.username})`,
    });

    return { id: newUser.id, username: newUser.username, fullName: newUser.fullName };
  });
}

export async function updateStaffLocal(
  userId: number,
  body: Record<string, unknown>,
  actor: { id: number; fullName: string }
) {
  const { username, fullName, email, phone, isActive, newPassword, permissionCodes } = body;
  return localStore.transaction((draft) => {
    const existing = draft.users.find((u) => u.id === userId);
    if (!existing) throw new RepoHttpError(404, 'Staff user not found.');
    const nowIso = new Date().toISOString();

    if (username && String(username).trim().length >= 3) {
      const clean = String(username).trim().toLowerCase();
      if (draft.users.some((u) => u.id !== userId && u.username.toLowerCase() === clean)) {
        throw new RepoHttpError(400, 'Username already in use by another account.');
      }
      existing.username = clean;
    }
    if (fullName) existing.fullName = String(fullName).trim();
    if (email !== undefined) existing.email = email ? String(email).trim() : null;
    if (phone !== undefined) existing.phone = phone ? String(phone).trim() : null;
    if (typeof isActive === 'boolean') existing.isActive = isActive;
    if (newPassword !== undefined && String(newPassword).length > 0) {
      if (String(newPassword).length < 6) {
        throw new RepoHttpError(400, 'Password must be at least 6 characters.');
      }
      existing.passwordHash = hashPassword(String(newPassword));
    }
    existing.updatedAt = nowIso;

    if (Array.isArray(permissionCodes)) {
      const role = draft.roles.find((r) => r.id === existing.roleId);
      if (role?.name === 'STAFF') {
        draft.userPermissions = draft.userPermissions.filter((up) => up.userId !== userId);
        const byCode = new Map(draft.permissions.map((p) => [p.code, p.id]));
        const allowedCodes = permissionCodes
          .map((c) => String(c))
          .filter((code) => code !== 'members:create' && code !== 'members:delete');
        for (const code of allowedCodes) {
          const pId = byCode.get(code);
          if (pId) {
            draft.userPermissions.push({
              id: nextSeq(draft, 'userPermissions'),
              userId,
              permissionId: pId,
              grantedAt: nowIso,
            });
          }
        }
      }
    }

    appendActivity(draft, {
      actorUserId: actor.id,
      actorName: actor.fullName,
      actionType: 'UPDATE_STAFF',
      entityType: 'USER',
      entityId: existing.username,
      summary: `Updated staff credentials/permissions for ${existing.fullName} (${existing.username})`,
    });

    return { ok: true, username: existing.username };
  });
}

export async function updateUserPasswordLocal(userId: number, newPassword: string) {
  if (!newPassword || newPassword.length < 6) {
    throw new RepoHttpError(400, 'New password must be at least 6 characters.');
  }
  return localStore.transaction((draft) => {
    const existing = draft.users.find((u) => u.id === userId);
    if (!existing) throw new RepoHttpError(404, 'Account not found.');
    if (!existing.isActive) throw new RepoHttpError(403, 'Account is disabled.');
    const nowIso = new Date().toISOString();
    existing.passwordHash = hashPassword(newPassword);
    existing.updatedAt = nowIso;

    appendActivity(draft, {
      actorUserId: existing.id,
      actorName: existing.fullName,
      actionType: 'FORGOT_PASSWORD_RESET',
      entityType: 'USER',
      entityId: existing.username,
      summary: `Reset password via Mobile/Gmail OTP verification (${existing.username})`,
    });

    return { ok: true, username: existing.username };
  });
}

