function serializePublicNoticeRow(n: LocalPublicNotice) {
  return {
    id: n.id,
    title: n.title,
    content: n.content,
    noticeType: n.noticeType,
    imageDataUrl: n.imageDataUrl,
    attachmentName: n.attachmentName,
    attachmentMime: n.attachmentMime,
    hasAttachment: Boolean(n.attachmentDataUrl && n.attachmentName),
    isPinned: n.isPinned,
    isPublished: n.isPublished,
    createdByName: n.createdByName,
    createdAt: n.createdAt,
    updatedAt: n.updatedAt,
  };
}

function normalizeNoticeType(raw: unknown): 'NOTICE' | 'PUBLIC_POST' | 'EVENT' {
  const val = String(raw || 'NOTICE').toUpperCase();
  if (val === 'PUBLIC_POST' || val === 'EVENT') return val;
  return 'NOTICE';
}

function applyCreateNoticeInDraft(
  draft: LocalDatabaseSnapshot,
  body: Record<string, unknown>,
  actor: { id: number; fullName: string },
  clientOfflineId: string | null = null
) {
  draft.publicNotices = draft.publicNotices || [];
  if (clientOfflineId) {
    const existing = draft.publicNotices.find((n) => n.clientOfflineId === clientOfflineId);
    if (existing) return existing;
  }
  const title = String(body.title || '').trim();
  const content = String(body.content || '').trim();
  if (!title || !content) {
    throw new RepoHttpError(400, 'Notice title and content are required.');
  }
  const nowIso = String(body.createdAt || new Date().toISOString());
  const notice: LocalPublicNotice = {
    id: nextSeq(draft, 'publicNotices'),
    title: title.slice(0, 240),
    content,
    noticeType: normalizeNoticeType(body.noticeType),
    imageDataUrl: body.imageDataUrl ? String(body.imageDataUrl) : null,
    attachmentDataUrl: body.attachmentDataUrl ? String(body.attachmentDataUrl) : null,
    attachmentName: body.attachmentName ? String(body.attachmentName).slice(0, 180) : null,
    attachmentMime: body.attachmentMime ? String(body.attachmentMime).slice(0, 120) : null,
    isPinned: body.isPinned === undefined ? true : Boolean(body.isPinned),
    isPublished: body.isPublished === undefined ? true : Boolean(body.isPublished),
    createdByUserId: actor.id,
    createdByName: actor.fullName || 'Farhan Gazi Admin',
    clientOfflineId,
    createdAt: nowIso,
    updatedAt: nowIso,
  };
  draft.publicNotices.push(notice);
  appendActivity(draft, {
    actorUserId: actor.id,
    actorName: actor.fullName,
    actionType: 'CREATE_NOTICE',
    entityType: 'NOTICE',
    entityId: String(notice.id),
    summary: `Published notice "${notice.title}"`,
  });
  return notice;
}

function applyUpdateNoticeInDraft(
  draft: LocalDatabaseSnapshot,
  noticeId: number,
  body: Record<string, unknown>,
  actor: { id: number; fullName: string }
) {
  draft.publicNotices = draft.publicNotices || [];
  const notice = draft.publicNotices.find((n) => n.id === noticeId);
  if (!notice) throw new RepoHttpError(404, 'Notice not found.');

  if (body.title !== undefined) {
    const t = String(body.title).trim();
    if (!t) throw new RepoHttpError(400, 'Notice title cannot be empty.');
    notice.title = t.slice(0, 240);
  }
  if (body.content !== undefined) {
    const c = String(body.content).trim();
    if (!c) throw new RepoHttpError(400, 'Notice content cannot be empty.');
    notice.content = c;
  }
  if (body.noticeType !== undefined) notice.noticeType = normalizeNoticeType(body.noticeType);
  if (body.isPinned !== undefined) notice.isPinned = Boolean(body.isPinned);
  if (body.isPublished !== undefined) notice.isPublished = Boolean(body.isPublished);
  if ('imageDataUrl' in body) {
    notice.imageDataUrl = body.imageDataUrl ? String(body.imageDataUrl) : null;
  }
  if ('attachmentDataUrl' in body) {
    notice.attachmentDataUrl = body.attachmentDataUrl ? String(body.attachmentDataUrl) : null;
    notice.attachmentName = body.attachmentName ? String(body.attachmentName).slice(0, 180) : null;
    notice.attachmentMime = body.attachmentMime ? String(body.attachmentMime).slice(0, 120) : null;
  }
  notice.updatedAt = new Date().toISOString();

  appendActivity(draft, {
    actorUserId: actor.id,
    actorName: actor.fullName,
    actionType: 'UPDATE_NOTICE',
    entityType: 'NOTICE',
    entityId: String(notice.id),
    summary: `Updated notice "${notice.title}"`,
  });
  return notice;
}

function applyDeleteNoticeInDraft(
  draft: LocalDatabaseSnapshot,
  noticeId: number,
  actor: { id: number; fullName: string }
) {
  draft.publicNotices = draft.publicNotices || [];
  const idx = draft.publicNotices.findIndex((n) => n.id === noticeId);
  if (idx === -1) throw new RepoHttpError(404, 'Notice not found.');
  const removed = draft.publicNotices[idx];
  draft.publicNotices.splice(idx, 1);

  appendActivity(draft, {
    actorUserId: actor.id,
    actorName: actor.fullName,
    actionType: 'DELETE_NOTICE',
    entityType: 'NOTICE',
    entityId: String(noticeId),
    summary: `Deleted notice "${removed.title}"`,
  });
  return { ok: true };
}

