export async function syncOfflineItemsLocal(
  items: Array<Record<string, unknown>>,
  actor: { id: number; fullName: string }
) {
  return localStore.transaction((draft) => {
    const settings = buildSettingsMap(draft);
    const allowPartialPayments = settings.allowPartialPayments === 'true';

    const results: Array<{
      clientTxId: string;
      status: 'SYNCED' | 'DUPLICATE_SKIPPED' | 'CONFLICT';
      message: string;
    }> = [];

    for (const item of items) {
      const clientTxId = String(item.clientTxId || '');
      if (!clientTxId) continue;

      if (draft.offlineSyncQueue.some((q) => q.clientTxId === clientTxId)) {
        results.push({
          clientTxId,
          status: 'DUPLICATE_SKIPPED',
          message: 'Already synchronized previously (duplicate prevented).',
        });
        continue;
      }

      const nowIso = new Date().toISOString();
      if (item.operationType === 'CREATE_MEMBER') {
        try {
          const p = (item.payload ?? {}) as Record<string, unknown>;
          const feeNum = roundMoney(Number(p.defaultAnnualFee || 1000));
          const joinDate = String(p.joiningDate || nowIso.slice(0, 10));
          const joinYear = Math.max(START_YEAR, Number(joinDate.slice(0, 4)) || START_YEAR);
          const memberCode = generateNextMemberCodeSync(draft, joinYear);

          const member: LocalMember = {
            id: nextSeq(draft, 'members'),
            memberCode,
            name: String(p.name || 'Member'),
            guardianName: String(p.guardianName || '-'),
            mobile: String(p.mobile || '-'),
            address: String(p.address || '-'),
            joiningDate: joinDate,
            defaultAnnualFee: feeNum.toFixed(2),
            status: String(p.status || 'ACTIVE') === 'INACTIVE' ? 'INACTIVE' : 'ACTIVE',
            registrationDate: joinDate,
            createdByUserId: actor.id,
            clientOfflineId: clientTxId,
            createdAt: nowIso,
            updatedAt: nowIso,
          };
          draft.members.push(member);
          draft.annualMembershipFees.push({
            id: nextSeq(draft, 'annualMembershipFees'),
            memberId: member.id,
            effectiveFromYear: joinYear,
            annualFee: feeNum.toFixed(2),
            notes: 'Offline Admin registration synced',
            setByUserId: actor.id,
            createdAt: nowIso,
          });
          draft.yearlyObligations.push({
            id: nextSeq(draft, 'yearlyObligations'),
            memberId: member.id,
            year: joinYear,
            frozenAnnualFee: feeNum.toFixed(2),
            paidTotal: '0.00',
            status: 'UNPAID',
            createdAt: nowIso,
            updatedAt: nowIso,
          });
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'CREATE_MEMBER',
            payloadJson: JSON.stringify(p),
            syncStatus: 'SYNCED',
            conflictReason: null,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({
            clientTxId,
            status: 'SYNCED',
            message: 'Offline member synced to database.',
          });
        } catch (err) {
          const reason = err instanceof Error ? err.message : 'Sync failed';
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'CREATE_MEMBER',
            payloadJson: JSON.stringify(item.payload ?? {}),
            syncStatus: 'CONFLICT',
            conflictReason: reason,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({ clientTxId, status: 'CONFLICT', message: 'Conflict recorded for review.' });
        }
      } else if (item.operationType === 'UPDATE_MEMBER') {
        try {
          const p = (item.payload ?? {}) as Record<string, unknown>;
          let mId = Number(p.memberId);
          if ((mId < 0 || !Number.isInteger(mId)) && p.memberTempClientOfflineId) {
            const linkedMember = draft.members.find(
              (m) => m.clientOfflineId === String(p.memberTempClientOfflineId)
            );
            if (linkedMember) mId = linkedMember.id;
          }
          applyMemberUpdateInDraft(draft, mId, p, { ...actor, roleName: 'ADMIN' });
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'UPDATE_MEMBER',
            payloadJson: JSON.stringify(p),
            syncStatus: 'SYNCED',
            conflictReason: null,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({
            clientTxId,
            status: 'SYNCED',
            message: 'Offline member edits synced to database.',
          });
        } catch (err) {
          const reason = err instanceof Error ? err.message : 'Member update conflict';
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'UPDATE_MEMBER',
            payloadJson: JSON.stringify(item.payload ?? {}),
            syncStatus: 'CONFLICT',
            conflictReason: reason,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({ clientTxId, status: 'CONFLICT', message: reason });
        }
      } else if (item.operationType === 'DELETE_MEMBER') {
        try {
          const p = (item.payload ?? {}) as Record<string, unknown>;
          let mId = Number(p.memberId);
          if ((mId < 0 || !Number.isInteger(mId)) && p.memberTempClientOfflineId) {
            const linkedMember = draft.members.find(
              (m) => m.clientOfflineId === String(p.memberTempClientOfflineId)
            );
            if (linkedMember) mId = linkedMember.id;
          }
          if (draft.members.some((m) => m.id === mId)) {
            applyMemberDeleteInDraft(draft, mId, actor);
          }
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'DELETE_MEMBER',
            payloadJson: JSON.stringify(p),
            syncStatus: 'SYNCED',
            conflictReason: null,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({
            clientTxId,
            status: 'SYNCED',
            message: 'Offline member deletion synced cleanly.',
          });
        } catch (err) {
          const reason = err instanceof Error ? err.message : 'Member delete conflict';
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'DELETE_MEMBER',
            payloadJson: JSON.stringify(item.payload ?? {}),
            syncStatus: 'CONFLICT',
            conflictReason: reason,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({ clientTxId, status: 'CONFLICT', message: reason });
        }
      } else if (item.operationType === 'RECORD_PAYMENT') {
        try {
          const p = (item.payload ?? {}) as Record<string, unknown>;
          let mId = Number(p.memberId);
          if ((mId < 0 || !Number.isInteger(mId)) && p.memberTempClientOfflineId) {
            const linkedMember = draft.members.find(
              (m) => m.clientOfflineId === String(p.memberTempClientOfflineId)
            );
            if (linkedMember) {
              mId = linkedMember.id;
            }
          }
          const yearNum = Number(p.paymentYear);
          const amountNum = Number(p.paidAmount);
          const member = draft.members.find((m) => m.id === mId);
          if (!member) throw new Error('Target member not found.');

          const ob = ensureObligationInDraft(draft, mId, yearNum);
          const validation = validatePaymentAttempt({
            paymentYear: yearNum,
            expectedFee: Number(ob.frozenAnnualFee),
            alreadyPaid: Number(ob.paidTotal),
            attemptAmount: amountNum,
            allowPartialPayments,
          });
          if (!validation.ok) throw new Error(validation.error);

          const receiptNumber = generateNextReceiptNumberSync(draft, yearNum);
          const dateStr = String(p.paymentDate || nowIso.slice(0, 10));

          const pay: LocalPayment = {
            id: nextSeq(draft, 'payments'),
            obligationId: ob.id,
            memberId: mId,
            paymentYear: yearNum,
            expectedFee: Number(ob.frozenAnnualFee).toFixed(2),
            paidAmount: roundMoney(amountNum).toFixed(2),
            dueAfterPayment: validation.dueAfterPayment.toFixed(2),
            paymentDate: dateStr,
            paymentMonth: dateStr.slice(0, 7),
            paymentTime: String(p.paymentTime || '12:00:00'),
            paymentMethod: String(p.paymentMethod || 'Cash'),
            receiptNumber,
            receivedByUserId: actor.id,
            notes: p.notes ? `${p.notes} [Offline Synced]` : '[Offline Synced]',
            clientTxId,
            isSyncedFromOffline: true,
            isVoided: false,
            createdAt: nowIso,
            updatedAt: nowIso,
          };
          draft.payments.push(pay);
          ob.paidTotal = validation.newPaidTotal.toFixed(2);
          ob.status = validation.status;
          ob.updatedAt = nowIso;

          draft.receipts.push({
            id: nextSeq(draft, 'receipts'),
            paymentId: pay.id,
            receiptNumber,
            memberCode: member.memberCode,
            issuedToName: member.name,
            paymentYear: yearNum,
            amountPaid: roundMoney(amountNum).toFixed(2),
            remainingDue: validation.dueAfterPayment.toFixed(2),
            issuedByName: actor.fullName,
            issuedAt: nowIso,
            verificationHash: sha256Hex(`${receiptNumber}:${clientTxId}`).slice(0, 16),
            breakdownJson: null,
          });

          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'RECORD_PAYMENT',
            payloadJson: JSON.stringify(p),
            syncStatus: 'SYNCED',
            conflictReason: null,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });

          results.push({ clientTxId, status: 'SYNCED', message: 'Offline payment synced cleanly.' });
        } catch (err) {
          const reason = err instanceof Error ? err.message : 'Payment sync conflict';
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'RECORD_PAYMENT',
            payloadJson: JSON.stringify(item.payload ?? {}),
            syncStatus: 'CONFLICT',
            conflictReason: reason,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({ clientTxId, status: 'CONFLICT', message: reason });
        }
      } else if (item.operationType === 'CREATE_NOTICE') {
        try {
          const p = (item.payload ?? {}) as Record<string, unknown>;
          applyCreateNoticeInDraft(draft, p, actor, clientTxId);
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'CREATE_NOTICE',
            payloadJson: JSON.stringify({ title: p.title, noticeType: p.noticeType }),
            syncStatus: 'SYNCED',
            conflictReason: null,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({
            clientTxId,
            status: 'SYNCED',
            message: 'Offline notice & photo synced to live public portal.',
          });
        } catch (err) {
          const reason = err instanceof Error ? err.message : 'Notice sync failed';
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'CREATE_NOTICE',
            payloadJson: '{}',
            syncStatus: 'CONFLICT',
            conflictReason: reason,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({ clientTxId, status: 'CONFLICT', message: reason });
        }
      } else if (item.operationType === 'UPDATE_NOTICE') {
        try {
          const p = (item.payload ?? {}) as Record<string, unknown>;
          let nId = Number(p.noticeId);
          if ((nId < 0 || !Number.isInteger(nId)) && p.noticeTempClientOfflineId) {
            const linkedNotice = (draft.publicNotices || []).find(
              (n) => n.clientOfflineId === String(p.noticeTempClientOfflineId)
            );
            if (linkedNotice) nId = linkedNotice.id;
          }
          applyUpdateNoticeInDraft(draft, nId, p, actor);
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'UPDATE_NOTICE',
            payloadJson: JSON.stringify({ noticeId: nId, title: p.title }),
            syncStatus: 'SYNCED',
            conflictReason: null,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({
            clientTxId,
            status: 'SYNCED',
            message: 'Offline notice update synced.',
          });
        } catch (err) {
          const reason = err instanceof Error ? err.message : 'Notice update conflict';
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'UPDATE_NOTICE',
            payloadJson: '{}',
            syncStatus: 'CONFLICT',
            conflictReason: reason,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({ clientTxId, status: 'CONFLICT', message: reason });
        }
      } else if (item.operationType === 'DELETE_NOTICE') {
        try {
          const p = (item.payload ?? {}) as Record<string, unknown>;
          let nId = Number(p.noticeId);
          if ((nId < 0 || !Number.isInteger(nId)) && p.noticeTempClientOfflineId) {
            const linkedNotice = (draft.publicNotices || []).find(
              (n) => n.clientOfflineId === String(p.noticeTempClientOfflineId)
            );
            if (linkedNotice) nId = linkedNotice.id;
          }
          if ((draft.publicNotices || []).some((n) => n.id === nId)) {
            applyDeleteNoticeInDraft(draft, nId, actor);
          }
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'DELETE_NOTICE',
            payloadJson: JSON.stringify({ noticeId: nId }),
            syncStatus: 'SYNCED',
            conflictReason: null,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({
            clientTxId,
            status: 'SYNCED',
            message: 'Offline notice deletion synced.',
          });
        } catch (err) {
          const reason = err instanceof Error ? err.message : 'Notice delete conflict';
          draft.offlineSyncQueue.push({
            id: nextSeq(draft, 'offlineSyncQueue'),
            clientTxId,
            adminUserId: actor.id,
            operationType: 'DELETE_NOTICE',
            payloadJson: '{}',
            syncStatus: 'CONFLICT',
            conflictReason: reason,
            createdOfflineAt: String(item.createdOfflineAt || nowIso),
            syncedAt: nowIso,
          });
          results.push({ clientTxId, status: 'CONFLICT', message: reason });
        }
      }
    }

    if (results.length > 0) {
      appendActivity(draft, {
        actorUserId: actor.id,
        actorName: actor.fullName,
        actionType: 'OFFLINE_SYNC',
        entityType: 'SYNC',
        entityId: String(results.length),
        summary: `Synchronized ${results.filter((r) => r.status === 'SYNCED').length}/${results.length} offline Admin records`,
      });
    }

    return { results };
  });
}

