export async function listBackupsLocal() {
  return localStore.read((data) => {
    const userById = new Map(data.users.map((u) => [u.id, u]));
    return {
      history: [...data.backupHistory]
        .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
        .slice(0, 50)
        .map((b) => ({
          ...b,
          createdByName: b.createdByUserId ? userById.get(b.createdByUserId)?.fullName || null : null,
        })),
    };
  });
}

export async function createBackupLocal(
  body: Record<string, unknown>,
  actor: { id: number; fullName: string }
) {
  const { backupType, targetLocation, passphrase } = body;
  return localStore.transaction((draft) => {
    const snapshot = {
      exportedAt: new Date().toISOString(),
      organization: 'Saidpur kudduchiyya madrasah',
      members: draft.members,
      annualMembershipFees: draft.annualMembershipFees,
      yearlyObligations: draft.yearlyObligations,
      payments: draft.payments,
      paymentCorrections: draft.paymentCorrections,
      receipts: draft.receipts,
      systemSettings: draft.systemSettings,
      publicNotices: draft.publicNotices || [],
    };

    const recordCount =
      snapshot.members.length +
      snapshot.yearlyObligations.length +
      snapshot.payments.length +
      snapshot.paymentCorrections.length +
      snapshot.publicNotices.length;

    const encrypted = encryptBackupPayload(snapshot, recordCount, passphrase ? String(passphrase) : undefined);
    const serialized = JSON.stringify(encrypted, null, 2);

    const entry = {
      id: nextSeq(draft, 'backupHistory'),
      backupType: String(backupType || 'MANUAL'),
      targetLocation: String(targetLocation || 'Cloud Encrypted Download'),
      encryptionAlg: encrypted.algorithm,
      checksumSha256: encrypted.checksumSha256,
      recordCount,
      fileSizeBytes: Buffer.byteLength(serialized, 'utf8'),
      status: 'VERIFIED',
      createdByUserId: actor.id,
      createdAt: new Date().toISOString(),
    };
    draft.backupHistory.push(entry);

    appendActivity(draft, {
      actorUserId: actor.id,
      actorName: actor.fullName,
      actionType: 'CREATE_BACKUP',
      entityType: 'BACKUP',
      entityId: String(entry.id),
      summary: `Created encrypted ${entry.backupType} backup (${recordCount} records) -> ${entry.targetLocation}`,
    });

    return { backupRecord: entry, encryptedEnvelope: encrypted };
  });
}

export async function verifyOrRestoreBackupLocal(
  body: Record<string, unknown>,
  actor: { id: number; fullName: string }
) {
  const { envelope, passphrase, confirmRestore } = body;
  if (!envelope) {
    throw new RepoHttpError(400, 'Encrypted backup file payload is required.');
  }

  const decrypted = decryptBackupPayload<{
    exportedAt: string;
    organization: string;
    members: LocalDatabaseSnapshot['members'];
    annualMembershipFees: LocalDatabaseSnapshot['annualMembershipFees'];
    yearlyObligations: LocalDatabaseSnapshot['yearlyObligations'];
    payments: LocalDatabaseSnapshot['payments'];
    paymentCorrections: LocalDatabaseSnapshot['paymentCorrections'];
    receipts: LocalDatabaseSnapshot['receipts'];
    systemSettings: LocalDatabaseSnapshot['systemSettings'];
    publicNotices?: LocalDatabaseSnapshot['publicNotices'];
  }>(envelope as EncryptedBackupEnvelope, passphrase ? String(passphrase) : undefined);

  const summary = {
    verified: true,
    exportedAt: decrypted.exportedAt,
    organization: decrypted.organization,
    counts: {
      members: decrypted.members?.length ?? 0,
      obligations: decrypted.yearlyObligations?.length ?? 0,
      payments: decrypted.payments?.length ?? 0,
      corrections: decrypted.paymentCorrections?.length ?? 0,
      notices: decrypted.publicNotices?.length ?? 0,
    },
  };

  if (!confirmRestore) {
    return { mode: 'VERIFIED_PREVIEW', ...summary };
  }

  await localStore.transaction((draft) => {
    const nowIso = new Date().toISOString();
    for (const s of decrypted.systemSettings || []) {
      const ex = draft.systemSettings.find((row) => row.key === s.key);
      if (ex) {
        ex.value = s.value;
        ex.updatedAt = nowIso;
      } else {
        draft.systemSettings.push({ key: s.key, value: s.value, updatedAt: nowIso });
      }
    }
    for (const m of decrypted.members || []) {
      if (!draft.members.some((row) => row.id === m.id || row.memberCode === m.memberCode)) {
        draft.members.push(m);
        draft.sequences.members = Math.max(draft.sequences.members, m.id);
      }
    }
    for (const f of decrypted.annualMembershipFees || []) {
      if (
        !draft.annualMembershipFees.some(
          (row) => row.id === f.id || (row.memberId === f.memberId && row.effectiveFromYear === f.effectiveFromYear)
        )
      ) {
        draft.annualMembershipFees.push(f);
        draft.sequences.annualMembershipFees = Math.max(draft.sequences.annualMembershipFees, f.id);
      }
    }
    for (const o of decrypted.yearlyObligations || []) {
      if (
        !draft.yearlyObligations.some(
          (row) => row.id === o.id || (row.memberId === o.memberId && row.year === o.year)
        )
      ) {
        draft.yearlyObligations.push(o);
        draft.sequences.yearlyObligations = Math.max(draft.sequences.yearlyObligations, o.id);
      }
    }
    for (const p of decrypted.payments || []) {
      if (!draft.payments.some((row) => row.id === p.id || row.receiptNumber === p.receiptNumber)) {
        draft.payments.push(p);
        draft.sequences.payments = Math.max(draft.sequences.payments, p.id);
      }
    }
    for (const c of decrypted.paymentCorrections || []) {
      if (!draft.paymentCorrections.some((row) => row.id === c.id)) {
        draft.paymentCorrections.push(c);
        draft.sequences.paymentCorrections = Math.max(draft.sequences.paymentCorrections, c.id);
      }
    }
    for (const r of decrypted.receipts || []) {
      if (!draft.receipts.some((row) => row.id === r.id || row.receiptNumber === r.receiptNumber)) {
        draft.receipts.push(r);
        draft.sequences.receipts = Math.max(draft.sequences.receipts, r.id);
      }
    }
    draft.publicNotices = draft.publicNotices || [];
    for (const n of decrypted.publicNotices || []) {
      if (!draft.publicNotices.some((row) => row.id === n.id)) {
        draft.publicNotices.push(n);
        draft.sequences.publicNotices = Math.max(draft.sequences.publicNotices || 0, n.id);
      }
    }

    const envObj = envelope as { checksumSha256?: string };
    appendActivity(draft, {
      actorUserId: actor.id,
      actorName: actor.fullName,
      actionType: 'RESTORE_BACKUP',
      entityType: 'BACKUP',
      entityId: String(envObj.checksumSha256 || '').slice(0, 12),
      summary: `Restored verified backup (${summary.counts.members} members, ${summary.counts.payments} payments)`,
    });
  });

  return { mode: 'RESTORED', ...summary };
}

