export function nextSeq(dbData: LocalDatabaseSnapshot, table: keyof LocalDatabaseSnapshot['sequences']): number {
  dbData.sequences[table] = (dbData.sequences[table] || 0) + 1;
  return dbData.sequences[table];
}

function seedAndMigrateLocalSnapshot(dbData: LocalDatabaseSnapshot): boolean {
  let dirty = false;
  const nowIso = new Date().toISOString();

  // 1. Roles
  if (dbData.roles.length === 0) {
    dbData.roles.push(
      {
        id: nextSeq(dbData, 'roles'),
        name: 'ADMIN',
        description: 'Full Madrasa System Administrator',
        createdAt: nowIso,
      },
      {
        id: nextSeq(dbData, 'roles'),
        name: 'STAFF',
        description: 'Permission-Controlled Madrasa Staff Member',
        createdAt: nowIso,
      }
    );
    dirty = true;
  }

  // 2. Permissions
  for (const p of PERMISSION_DEFS) {
    const existing = dbData.permissions.find((row) => row.code === p.code);
    if (!existing) {
      dbData.permissions.push({
        id: nextSeq(dbData, 'permissions'),
        code: p.code,
        label: p.label,
        labelBn: p.labelBn,
        createdAt: nowIso,
      });
      dirty = true;
    } else if (existing.label !== p.label || existing.labelBn !== p.labelBn) {
      existing.label = p.label;
      existing.labelBn = p.labelBn;
      dirty = true;
    }
  }

  // 3. System Settings
  const defaultSettings = [
    { key: 'allowPartialPayments', value: 'true' },
    { key: 'autoBackupEnabled', value: 'true' },
    { key: 'autoBackupIntervalHours', value: '24' },
    { key: 'currentActiveYear', value: String(START_YEAR) },
  ];
  for (const s of defaultSettings) {
    if (!dbData.systemSettings.some((row) => row.key === s.key)) {
      dbData.systemSettings.push({ key: s.key, value: s.value, updatedAt: nowIso });
      dirty = true;
    }
  }

  const adminRole = dbData.roles.find((r) => r.name === 'ADMIN');
  const staffRole = dbData.roles.find((r) => r.name === 'STAFF');
  if (!adminRole || !staffRole) return dirty;

  const permByCode = new Map(dbData.permissions.map((p) => [p.code, p.id]));

  // 4. Users (Admin + 22 Staff)
