  // Idempotent enforcement of Partner (STAFF) permissions
  const staffUserIds = new Set(dbData.users.filter((u) => u.roleId === staffRole.id).map((u) => u.id));
  const restrictedPermIds = new Set(
    ['members:create', 'members:delete']
      .map((code) => permByCode.get(code))
      .filter((id): id is number => typeof id === 'number')
