  const beforeLen = dbData.userPermissions.length;
  dbData.userPermissions = dbData.userPermissions.filter(
    (up) => !(staffUserIds.has(up.userId) && restrictedPermIds.has(up.permissionId))
  );
  if (dbData.userPermissions.length !== beforeLen) dirty = true;

  const requiredPartnerCodes = ['members:view', 'members:edit', 'payments:view', 'payments:create'];
  for (const sId of staffUserIds) {
    for (const code of requiredPartnerCodes) {
      const pId = permByCode.get(code);
