      noticeType: 'NOTICE',
      imageDataUrl: null,
      attachmentDataUrl: null,
      attachmentName: null,
      attachmentMime: null,
      isPinned: true,
      isPublished: true,
      createdByUserId: noticeAdmin ? noticeAdmin.id : 1,
      createdByName: noticeAdmin ? noticeAdmin.fullName : 'Farhan Gazi Admin',
      clientOfflineId: null,
      createdAt: nowIso,
      updatedAt: nowIso,
    });
    dbData.systemSettings.push({
      key: 'defaultNoticeSeeded',
      value: 'true',
      updatedAt: nowIso,
    });
    dirty = true;
  }

  return dirty;
}

class LocalJsonStore {
  private cached: LocalDatabaseSnapshot | null = null;
  private loadedFilePath: string | null = null;
  private lockQueue: Promise<void> = Promise.resolve();

  private writeAtomic(filePath: string, data: LocalDatabaseSnapshot) {
    const dir = path.dirname(filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    const tmpPath = `${filePath}.${process.pid}.${Date.now()}.tmp`;
    fs.writeFileSync(tmpPath, JSON.stringify(data, null, 2), 'utf8');
    fs.renameSync(tmpPath, filePath);
  }

  public resetCache() {
    this.cached = null;
    this.loadedFilePath = null;
  }

  public getSnapshot(): LocalDatabaseSnapshot {
    const filePath = getLocalDbFilePath();
    if (this.cached && this.loadedFilePath === filePath) {
      return this.cached;
    }

    let snapshot: LocalDatabaseSnapshot;
    if (fs.existsSync(filePath)) {
      const raw = fs.readFileSync(filePath, 'utf8');
      snapshot = JSON.parse(raw) as LocalDatabaseSnapshot;
    } else {
      snapshot = createEmptyDb();
    }

    const changed = seedAndMigrateLocalSnapshot(snapshot);
    if (changed || !fs.existsSync(filePath)) {
      this.writeAtomic(filePath, snapshot);
    }

    this.cached = snapshot;
    this.loadedFilePath = filePath;
    return snapshot;
  }

  public async ensureReady(): Promise<void> {
    await this.read(async () => undefined);
  }

  public async read<T>(fn: (dbData: LocalDatabaseSnapshot) => T | Promise<T>): Promise<T> {
    const snapshot = this.getSnapshot();
    return fn(snapshot);
  }

  public async transaction<T>(fn: (draft: LocalDatabaseSnapshot) => T | Promise<T>): Promise<T> {
    let release!: () => void;
    const prev = this.lockQueue;
    this.lockQueue = new Promise<void>((res) => {
      release = res;
    });
    await prev;

    try {
      const current = this.getSnapshot();
      const draft = structuredClone(current);
      const result = await fn(draft);
      const filePath = getLocalDbFilePath();
      this.writeAtomic(filePath, draft);
      this.cached = draft;
      this.loadedFilePath = filePath;
      return result;
    } finally {
      release();
    }
  }
}

