function readPersistedGatewayConfig(): OtpGatewayConfig {
  try {
    if (!fs.existsSync(GATEWAY_CONFIG_PATH)) return {};
    const raw = fs.readFileSync(GATEWAY_CONFIG_PATH, 'utf8');
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? (parsed as OtpGatewayConfig) : {};
  } catch {
    return {};
  }
}

function getEffectiveGatewayConfig(): Required<{
  smtpUser: string;
  smtpPass: string;
  smtpHost: string;
  smtpPort: number;
  emailFrom: string;
  resendApiKey: string;
  fast2SmsApiKey: string;
  twilioAccountSid: string;
  twilioAuthToken: string;
  twilioFromNumber: string;
  smsGatewayUrl: string;
  smsGatewayApiKey: string;
  smsSenderId: string;
}> {
  const saved = readPersistedGatewayConfig();
  return {
    smtpUser: (saved.smtpUser || process.env.SMTP_USER || '').trim(),
    smtpPass: (saved.smtpPass || process.env.SMTP_PASS || '').trim(),
    smtpHost: (saved.smtpHost || process.env.SMTP_HOST || '').trim(),
    smtpPort: Number(saved.smtpPort || process.env.SMTP_PORT || 465),
    emailFrom: (saved.emailFrom || process.env.EMAIL_FROM || '').trim(),
    resendApiKey: (saved.resendApiKey || process.env.RESEND_API_KEY || '').trim(),
    fast2SmsApiKey: (saved.fast2SmsApiKey || process.env.FAST2SMS_API_KEY || '').trim(),
    twilioAccountSid: (saved.twilioAccountSid || process.env.TWILIO_ACCOUNT_SID || '').trim(),
    twilioAuthToken: (saved.twilioAuthToken || process.env.TWILIO_AUTH_TOKEN || '').trim(),
    twilioFromNumber: (saved.twilioFromNumber || process.env.TWILIO_FROM_NUMBER || '').trim(),
    smsGatewayUrl: (saved.smsGatewayUrl || process.env.SMS_GATEWAY_URL || '').trim(),
    smsGatewayApiKey: (saved.smsGatewayApiKey || process.env.SMS_GATEWAY_API_KEY || '').trim(),
    smsSenderId: (saved.smsSenderId || process.env.SMS_SENDER_ID || 'SKMADRASA').trim(),
  };
}

export function saveOtpGatewayConfig(patch: Partial<OtpGatewayConfig>): void {
  const current = readPersistedGatewayConfig();
  const next: OtpGatewayConfig = { ...current };
  const assign = <K extends keyof OtpGatewayConfig>(key: K, val: OtpGatewayConfig[K]) => {
    if (val === undefined) return;
    if (typeof val === 'string') {
      const trimmed = val.trim();
      if (trimmed) {
        next[key] = trimmed as OtpGatewayConfig[K];
      } else {
        delete next[key];
      }
    } else {
      next[key] = val;
    }
  };
  assign('smtpUser', patch.smtpUser);
  assign('smtpPass', patch.smtpPass);
  assign('smtpHost', patch.smtpHost);
  assign('smtpPort', patch.smtpPort);
  assign('emailFrom', patch.emailFrom);
  assign('resendApiKey', patch.resendApiKey);
  assign('fast2SmsApiKey', patch.fast2SmsApiKey);
  assign('twilioAccountSid', patch.twilioAccountSid);
  assign('twilioAuthToken', patch.twilioAuthToken);
  assign('twilioFromNumber', patch.twilioFromNumber);
  assign('smsGatewayUrl', patch.smsGatewayUrl);
  assign('smsGatewayApiKey', patch.smsGatewayApiKey);
  assign('smsSenderId', patch.smsSenderId);

  fs.mkdirSync(path.dirname(GATEWAY_CONFIG_PATH), { recursive: true });
  fs.writeFileSync(GATEWAY_CONFIG_PATH, JSON.stringify(next, null, 2), 'utf8');
}

export function getOtpGatewayPublicStatus() {
  const cfg = getEffectiveGatewayConfig();
  const hasSmtp = Boolean(cfg.smtpUser && cfg.smtpPass);
  const hasResend = Boolean(cfg.resendApiKey);
  const hasTwilio = Boolean(cfg.twilioAccountSid && cfg.twilioAuthToken && cfg.twilioFromNumber);
  const hasFast2Sms = Boolean(cfg.fast2SmsApiKey);
  const hasGenericSms = Boolean(cfg.smsGatewayUrl);

  return {
    emailConfigured: hasSmtp || hasResend,
    smsGatewayConfigured: hasTwilio || hasFast2Sms || hasGenericSms,
    firebasePhoneEnabled: true,
    smsProvider: hasFast2Sms
      ? 'FAST2SMS'
      : hasTwilio
        ? 'TWILIO'
        : hasGenericSms
          ? 'CUSTOM_WEBHOOK'
          : 'FIREBASE_SMS',
    smtpUserMasked: maskEmail(cfg.smtpUser),
    hasFast2SmsKey: hasFast2Sms,
    hasTwilioConfig: hasTwilio,
    hasCustomSmsUrl: hasGenericSms,
    smsGatewayUrl: cfg.smsGatewayUrl || '',
    smsSenderId: cfg.smsSenderId,
  };
}

export interface OtpChallengeRecord {
  challengeId: string;
  userId: number;
  username: string;
  phone: string;
  email: string;
  otpHash: string;
  salt: string;
  attempts: number;
  maxAttempts: number;
  expiresAt: number;
  createdAt: number;
  consumed: boolean;
}

const activeChallenges = new Map<string, OtpChallengeRecord>();

// Strictly internal test-only observer (never serialized in HTTP responses)
let otpTestObserver: ((info: { userId: number; username: string; phone: string; email: string; otp: string }) => void) | null = null;
export function setOtpTestObserver(
  fn: ((info: { userId: number; username: string; phone: string; email: string; otp: string }) => void) | null
) {
  otpTestObserver = fn;
}

function cleanupExpiredChallenges() {
  const now = Date.now();
  for (const [id, ch] of activeChallenges.entries()) {
    if (ch.consumed || now > ch.expiresAt + 60_000) {
      activeChallenges.delete(id);
    }
  }
}

export function normalizeOtpPhone(rawPhone: string): string {
  const digits = String(rawPhone || '').replace(/\D/g, '');
  if (digits.length === 10 && /^[6-9]/.test(digits)) {
    return `+91${digits}`;
  }
  if (digits.length === 11 && digits.startsWith('01')) {
    return `+88${digits}`;
  }
  if (digits.length >= 10) {
    return rawPhone.trim().startsWith('+') ? rawPhone.trim() : `+${digits}`;
  }
  return rawPhone.trim();
}

export function maskPhone(phone: string): string {
  const clean = String(phone || '').replace(/\s+/g, '');
  if (clean.length <= 4) return '****';
  return `${'*'.repeat(Math.max(4, clean.length - 4))}${clean.slice(-4)}`;
}

export function maskEmail(email: string | null | undefined): string | null {
  if (!email || !email.includes('@')) return null;
  const [local, domain] = email.split('@');
  if (local.length <= 2) return `${local[0] || '*'}***@${domain}`;
  return `${local.slice(0, 2)}${'*'.repeat(Math.min(6, Math.max(3, local.length - 2)))}@${domain}`;
}

export function resolveOtpEmailForUser(
  userEmail: string | null | undefined,
  fallbackAdminEmail: string
): string {
  const clean = String(userEmail || '').trim();
  if (clean && clean.includes('@') && !clean.toLowerCase().endsWith('@syedpurmadrasa.org')) {
    return clean;
  }
  return fallbackAdminEmail;
}

export function isOtpGatewayConfigured(): { email: boolean; sms: boolean; any: boolean } {
  const cfg = getEffectiveGatewayConfig();
  const hasSmtp = Boolean(cfg.smtpUser && cfg.smtpPass);
  const hasResend = Boolean(cfg.resendApiKey);
  const hasTwilio = Boolean(cfg.twilioAccountSid && cfg.twilioAuthToken && cfg.twilioFromNumber);
  const hasFast2Sms = Boolean(cfg.fast2SmsApiKey);
  const hasGenericSms = Boolean(cfg.smsGatewayUrl);
  const email = hasSmtp || hasResend;
  const sms = hasTwilio || hasFast2Sms || hasGenericSms;
  return { email, sms, any: email || sms };
}

function hashOtp(otp: string, salt: string): string {
  return crypto.createHash('sha256').update(`${salt}:${otp}:${OTP_SECRET}`).digest('hex');
}

function signChallengeId(challengeId: string, userId: number): string {
  const payload = Buffer.from(JSON.stringify({ cid: challengeId, uid: userId })).toString('base64url');
  const sig = crypto.createHmac('sha256', OTP_SECRET).update(payload).digest('base64url');
  return `${payload}.${sig}`;
}

function verifyChallengeToken(token: string): { cid: string; uid: number } | null {
  const parts = String(token || '').split('.');
  if (parts.length !== 2) return null;
  const [payload, sig] = parts;
  const expected = crypto.createHmac('sha256', OTP_SECRET).update(payload).digest('base64url');
  const a = Buffer.from(sig);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return null;
  try {
    const parsed = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8')) as {
      cid: string;
      uid: number;
    };
    if (!parsed.cid || !parsed.uid) return null;
    return parsed;
  } catch {
    return null;
  }
}

async function sendSmtpEmail(to: string, subject: string, textBody: string, htmlBody: string): Promise<boolean> {
  const cfg = getEffectiveGatewayConfig();
  const user = cfg.smtpUser;
  const pass = cfg.smtpPass;
  if (!user || !pass || !to) return false;

  const isGmail = user.toLowerCase().endsWith('@gmail.com') || user.toLowerCase().endsWith('@googlemail.com');
  const host = cfg.smtpHost || (isGmail ? 'smtp.gmail.com' : '');
  if (!host) return false;

  const configuredPort = Number(cfg.smtpPort || 465);
  const candidatePorts =
    host === 'smtp.gmail.com'
      ? Array.from(
          new Set(
            configuredPort === 465 || configuredPort === 587
              ? [configuredPort, configuredPort === 465 ? 587 : 465]
              : [465, 587]
          )
        )
      : [configuredPort];

  for (const port of candidatePorts) {
    const secure = port === 465;
    try {
      const transporter = nodemailer.createTransport({
        host,
        port,
        secure,
        auth: { user, pass },
        connectionTimeout: 3500,
        greetingTimeout: 3500,
        socketTimeout: 5000,
      });

      await transporter.sendMail({
        from: `"সৈয়দপুর কুদ্দুসিয়া মাদ্রাসা" <${cfg.emailFrom || user}>`,
        to,
        subject,
        text: textBody,
        html: htmlBody,
      });
      return true;
    } catch (err) {
      console.error(
        `[OTP Email SMTP Error port ${port}]:`,
        err instanceof Error ? err.message : err
      );
    }
  }
  return false;
}

async function sendSmsViaConfiguredGateway(phone: string, otp: string): Promise<boolean> {
  if (!phone) return false;
  const cfg = getEffectiveGatewayConfig();
  const normalized = normalizeOtpPhone(phone);
  const msg = `Saidpur kudduchiyya madrasah OTP: ${otp}. Valid for 5 minutes.`;

  // 1. Twilio SMS
  const twSid = cfg.twilioAccountSid;
  const twToken = cfg.twilioAuthToken;
  const twFrom = cfg.twilioFromNumber;
  if (twSid && twToken && twFrom) {
    try {
      const form = new URLSearchParams({
        To: normalized,
        From: twFrom,
        Body: msg,
      });
      const authHeader = Buffer.from(`${twSid}:${twToken}`).toString('base64');
      const res = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${twSid}/Messages.json`, {
        method: 'POST',
        signal: AbortSignal.timeout(4500),
        headers: {
          Authorization: `Basic ${authHeader}`,
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: form.toString(),
      });
      if (res.ok) return true;
      console.error('[OTP Twilio Error]:', res.status, await res.text().catch(() => ''));
    } catch (err) {
      console.error('[OTP Twilio Fetch Error]:', err instanceof Error ? err.message : err);
    }
  }

  // 2. Fast2SMS (India 10-digit mobile numbers e.g. 7797383198)
  const fast2Key = cfg.fast2SmsApiKey;
  if (fast2Key) {
    try {
      const digits10 = normalized.replace(/\D/g, '').slice(-10);
      const res = await fetch('https://www.fast2sms.com/dev/bulkV2', {
        method: 'POST',
        signal: AbortSignal.timeout(4500),
        headers: {
          authorization: fast2Key,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          route: 'otp',
          variables_values: otp,
          numbers: digits10,
        }),
      });
      if (res.ok) return true;
      console.error('[OTP Fast2SMS Error]:', res.status, await res.text().catch(() => ''));
    } catch (err) {
      console.error('[OTP Fast2SMS Fetch Error]:', err instanceof Error ? err.message : err);
    }
  }

  // 3. Generic JSON HTTP SMS Gateway (BulkSMSBD / Custom Webhook)
  const smsUrl = cfg.smsGatewayUrl;
  const smsKey = cfg.smsGatewayApiKey;
  const senderId = cfg.smsSenderId || 'SKMADRASA';
  if (smsUrl) {
    try {
      const res = await fetch(smsUrl, {
        method: 'POST',
        signal: AbortSignal.timeout(4500),
        headers: {
          'Content-Type': 'application/json',
          ...(smsKey ? { Authorization: `Bearer ${smsKey}`, 'x-api-key': smsKey } : {}),
        },
        body: JSON.stringify({
          to: normalized,
          phone: normalized,
          sender: senderId,
          otp,
          message: msg,
        }),
      });
      if (res.ok) return true;
      console.error('[OTP SMS Gateway Error]:', res.status);
    } catch (err) {
      console.error('[OTP SMS Gateway Fetch Error]:', err instanceof Error ? err.message : err);
    }
  }

  return false;
}

async function dispatchExternalOtp(params: {
  phone: string;
  email: string;
  otp: string;
}): Promise<{ smsSent: boolean; emailSent: boolean }> {
  const cfg = getEffectiveGatewayConfig();
  const sendEmailTask = async (): Promise<boolean> => {
    if (!params.email) return false;
    const subject = 'OTP Verification - Saidpur kudduchiyya madrasah';
    const textBody =
      `সৈয়দপুর কুদ্দুসিয়া মাদ্রাসা (Saidpur kudduchiyya madrasah)\n\n` +
      `Your 6-digit verification OTP is: ${params.otp}\n` +
      `Valid for 5 minutes.\n\n` +
      `You may sign in using EITHER the OTP received on your Mobile (${params.phone || '-'}) OR this Gmail (${params.email}).`;
    const htmlBody = `
      <div style="font-family:Arial,sans-serif;max-width:480px;margin:0 auto;border:2px solid #0B5D2E;border-radius:10px;padding:20px;">
        <h2 style="color:#0B5D2E;margin:0 0 6px;">সৈয়দপুর কুদ্দুসিয়া মাদ্রাসা</h2>
        <p style="color:#475569;font-size:13px;margin:0 0 16px;">Saidpur kudduchiyya madrasah · Security OTP</p>
        <p style="font-size:14px;color:#0f172a;">আপনার ৬ সংখ্যার যাচাইকরণ কোড (OTP):</p>
        <div style="background:#ECFDF5;border:1px solid #A7F3D0;border-radius:8px;padding:14px;text-align:center;font-size:28px;font-weight:bold;letter-spacing:8px;color:#0B5D2E;margin:12px 0;">
          ${params.otp}
        </div>
        <p style="font-size:12px;color:#64748b;">এই কোডটি ৫ মিনিটের জন্য বৈধ। মোবাইল অথবা জিমেইল — যেকোনো একটি থেকে প্রাপ্ত OTP দিয়ে প্রবেশ করা যাবে।</p>
      </div>`;

    const smtpOk = await sendSmtpEmail(params.email, subject, textBody, htmlBody);
    if (smtpOk) return true;

    const resendKey = cfg.resendApiKey;
    if (resendKey) {
      try {
        const fromEmail = cfg.emailFrom || 'onboarding@resend.dev';
        const res = await fetch('https://api.resend.com/emails', {
          method: 'POST',
          signal: AbortSignal.timeout(4500),
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${resendKey}`,
          },
          body: JSON.stringify({
            from: fromEmail,
            to: [params.email],
            subject,
            text: textBody,
            html: htmlBody,
          }),
        });
        if (res.ok) return true;
        console.error('[OTP Resend Error]:', res.status, await res.text().catch(() => ''));
      } catch (err) {
        console.error('[OTP Resend Fetch Error]:', err instanceof Error ? err.message : err);
      }
    }

    return false;
  };

  const [smsResult, emailResult] = await Promise.allSettled([
    sendSmsViaConfiguredGateway(params.phone, params.otp),
    sendEmailTask(),
  ]);

  return {
    smsSent: smsResult.status === 'fulfilled' && smsResult.value,
    emailSent: emailResult.status === 'fulfilled' && emailResult.value,
  };
}

export interface IssuedOtpChallengeResponse {
  requiresOtp: true;
  challengeToken: string;
  maskedPhone: string;
  maskedEmail: string | null;
  expiresInSeconds: number;
  deliveryMode: 'SMS_AND_EMAIL' | 'SMS' | 'EMAIL' | 'GATEWAY_NOT_CONFIGURED';
  smsDispatched: boolean;
  emailDispatched: boolean;
  firebasePhoneReady?: boolean;
  smsTargetPhone?: string | null;
}

export async function issueAdminOtpChallenge(params: {
  userId: number;
  username: string;
  phone: string;
  email: string;
  includePhoneTarget?: boolean;
}): Promise<IssuedOtpChallengeResponse> {
  cleanupExpiredChallenges();
  const otp = String(crypto.randomInt(100000, 1000000));
  const salt = crypto.randomBytes(12).toString('hex');
  const challengeId = crypto.randomUUID();
  const expiresAt = Date.now() + 5 * 60 * 1000;

  activeChallenges.set(challengeId, {
    challengeId,
    userId: params.userId,
    username: params.username,
    phone: params.phone,
    email: params.email,
    otpHash: hashOtp(otp, salt),
    salt,
    attempts: 0,
    maxAttempts: 5,
    expiresAt,
    createdAt: Date.now(),
    consumed: false,
  });

  if (otpTestObserver) {
    otpTestObserver({
      userId: params.userId,
      username: params.username,
      phone: params.phone,
      email: params.email,
      otp,
    });
  }

  const { smsSent, emailSent } = await dispatchExternalOtp({
    phone: params.phone,
    email: params.email,
    otp,
  });

  const deliveryMode: IssuedOtpChallengeResponse['deliveryMode'] =
    smsSent && emailSent
      ? 'SMS_AND_EMAIL'
      : smsSent
        ? 'SMS'
        : emailSent
          ? 'EMAIL'
          : 'GATEWAY_NOT_CONFIGURED';

  const normalizedPhone = params.phone ? normalizeOtpPhone(params.phone) : '';

  // Never expose raw OTP to client API responses
  return {
    requiresOtp: true,
    challengeToken: signChallengeId(challengeId, params.userId),
    maskedPhone: maskPhone(params.phone),
    maskedEmail: maskEmail(params.email),
    expiresInSeconds: 300,
    deliveryMode,
    smsDispatched: smsSent,
    emailDispatched: emailSent,
    firebasePhoneReady: Boolean(normalizedPhone && normalizedPhone.replace(/\D/g, '').length >= 10),
    smsTargetPhone:
      params.includePhoneTarget && normalizedPhone && normalizedPhone.replace(/\D/g, '').length >= 10
        ? normalizedPhone
        : null,
  };
}

export function verifyAdminOtpChallenge(
  challengeToken: string,
  otpInput: string
): { ok: true; userId: number; username: string } | { ok: false; error: string; status: number } {
  const verifiedToken = verifyChallengeToken(challengeToken);
  if (!verifiedToken) {
    return { ok: false, error: 'Invalid or tampered OTP session. Please sign in again.', status: 401 };
  }

  const record = activeChallenges.get(verifiedToken.cid);
  if (!record || record.userId !== verifiedToken.uid) {
    return { ok: false, error: 'OTP challenge expired or not found. Please request a new OTP.', status: 401 };
  }
  if (record.consumed) {
    return { ok: false, error: 'This OTP has already been used. Please sign in again.', status: 401 };
  }
  if (Date.now() > record.expiresAt) {
    activeChallenges.delete(verifiedToken.cid);
    return { ok: false, error: 'OTP expired after 5 minutes. Please resend OTP.', status: 401 };
  }
  if (record.attempts >= record.maxAttempts) {
    activeChallenges.delete(verifiedToken.cid);
    return { ok: false, error: 'Too many invalid OTP attempts. Please sign in again.', status: 429 };
  }

  const cleanOtp = String(otpInput || '').replace(/\D/g, '');
  if (cleanOtp.length !== 6) {
    record.attempts += 1;
    return { ok: false, error: 'Please enter the 6-digit OTP code.', status: 400 };
  }

  const candidateHash = hashOtp(cleanOtp, record.salt);
  const a = Buffer.from(candidateHash, 'hex');
  const b = Buffer.from(record.otpHash, 'hex');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    record.attempts += 1;
    const remaining = Math.max(0, record.maxAttempts - record.attempts);
    if (remaining === 0) {
      activeChallenges.delete(verifiedToken.cid);
      return { ok: false, error: 'Maximum OTP attempts exceeded. Please sign in again.', status: 429 };
    }
    return {
      ok: false,
      error: `Invalid OTP code. ${remaining} attempt(s) remaining.`,
      status: 401,
    };
  }

  record.consumed = true;
  activeChallenges.delete(verifiedToken.cid);
  return { ok: true, userId: record.userId, username: record.username };
}

export function peekOtpChallenge(
  challengeToken: string
): { userId: number; username: string; phone: string; email: string; createdAt: number } | null {
  const verifiedToken = verifyChallengeToken(challengeToken);
  if (!verifiedToken) return null;
  const record = activeChallenges.get(verifiedToken.cid);
  if (!record || record.consumed || record.userId !== verifiedToken.uid) return null;
  return {
    userId: record.userId,
    username: record.username,
    phone: record.phone,
    email: record.email,
    createdAt: record.createdAt,
  };
}

export function consumeOtpChallenge(
  challengeToken: string
): { ok: true; userId: number; username: string; phone: string } | { ok: false; error: string; status: number } {
  const verifiedToken = verifyChallengeToken(challengeToken);
  if (!verifiedToken) {
    return { ok: false, error: 'Invalid or expired OTP challenge token.', status: 401 };
  }
  const record = activeChallenges.get(verifiedToken.cid);
  if (!record || record.userId !== verifiedToken.uid) {
    return { ok: false, error: 'OTP session expired or not found.', status: 401 };
  }
  if (record.consumed) {
    return { ok: false, error: 'OTP session already consumed.', status: 401 };
  }
  if (Date.now() > record.expiresAt) {
    activeChallenges.delete(verifiedToken.cid);
    return { ok: false, error: 'OTP session expired after 5 minutes.', status: 401 };
  }
  record.consumed = true;
  activeChallenges.delete(verifiedToken.cid);
  return { ok: true, userId: record.userId, username: record.username, phone: record.phone };
}

