function collectCleanProjectSourceBundle(): {
  generatedAt: string;
  totalFiles: number;
  files: Array<{ path: string; sizeBytes: number; content: string }>;
} {
  const rootDir = process.cwd();
  const skipDirs = new Set([
    'node_modules',
    '.git',
    'dist',
    'data',
    '.playwright-cli',
    'downloads',
    '.aistudio',
  ]);
  const allowedExt = new Set([
    '.ts',
    '.tsx',
    '.js',
    '.mjs',
    '.cjs',
    '.css',
    '.html',
    '.json',
    '.bat',
    '.md',
    '.txt',
    '.rules',
  ]);
  const excludedFileNames = new Set([
    'package-lock.json',
    'skm-source-bundle.json',
    '.env',
    '.env.local',
    '.env.production',
  ]);

  const files: Array<{ path: string; sizeBytes: number; content: string }> = [];

  const walk = (dirPath: string) => {
    const entries = fs.readdirSync(dirPath, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.name.startsWith('.env') && entry.name !== '.env.example') continue;
      if (excludedFileNames.has(entry.name)) continue;
      if (/firebase-adminsdk|service-account|\.pem$|\.key$/i.test(entry.name)) continue;

      const absPath = path.join(dirPath, entry.name);
      const relPath = path.relative(rootDir, absPath).replace(/\\/g, '/');

      if (entry.isDirectory()) {
        if (skipDirs.has(entry.name)) continue;
        walk(absPath);
      } else if (entry.isFile()) {
        const ext = path.extname(entry.name).toLowerCase();
        const isEnvExample = entry.name === '.env.example';
        if (!isEnvExample && !allowedExt.has(ext)) continue;
        try {
          const stat = fs.statSync(absPath);
          if (stat.size > 512 * 1024) continue;
          const content = fs.readFileSync(absPath, 'utf8');
          files.push({ path: relPath, sizeBytes: stat.size, content });
        } catch {
          // skip unreadable files
        }
      }
    }
  };

  walk(rootDir);
  files.sort((a, b) => a.path.localeCompare(b.path));
  return {
    generatedAt: new Date().toISOString(),
    totalFiles: files.length,
    files,
  };
}

function isLocalOfflinePcRequest(req: AuthRequest): boolean {
  if (process.env.SKM_ALLOW_OFFLINE_LOCAL_LOGIN !== 'true') return false;
  if (req.headers['x-forwarded-for']) return false;
  const host = String(req.hostname || '').toLowerCase();
  const remote = String(req.socket?.remoteAddress || req.ip || '').toLowerCase();
  const isLoopHost = host === 'localhost' || host === '127.0.0.1' || host === '::1';
  const isLoopIp =
    remote === '127.0.0.1' || remote === '::1' || remote === '::ffff:127.0.0.1';
  return isLoopHost && isLoopIp;
}

async function findUserByIdentifierPg(identifier: string) {
  const clean = String(identifier || '').trim();
  const cleanLower = clean.toLowerCase();
  const digits = clean.replace(/\D/g, '');
  const all = await db
    .select({
      user: users,
      roleName: roles.name,
    })
    .from(users)
    .innerJoin(roles, eq(users.roleId, roles.id));

  const match = all.find(({ user }) => {
    if (user.username.toLowerCase() === cleanLower) return true;
    if (user.email && user.email.toLowerCase() === cleanLower) return true;
    if (digits.length >= 10 && user.phone) {
      const uDigits = user.phone.replace(/\D/g, '');
      return uDigits === digits || uDigits.endsWith(digits) || digits.endsWith(uDigits);
    }
    return false;
  });
  return match || null;
}

async function findAdminByIdentifierPg(identifier: string) {
  const clean = String(identifier || '').trim().toLowerCase();
  const digits = clean.replace(/\D/g, '');
  const admins = await db
    .select({ user: users })
    .from(users)
    .innerJoin(roles, eq(users.roleId, roles.id))
    .where(eq(roles.name, 'ADMIN'));

  const match = admins.find(({ user }) => {
    if (!clean) return true;
    if (user.username.toLowerCase() === clean) return true;
    if (user.email && user.email.toLowerCase() === clean) return true;
    if (digits.length >= 10 && user.phone) {
      const uDigits = user.phone.replace(/\D/g, '');
      return uDigits === digits || uDigits.endsWith(digits) || digits.endsWith(uDigits);
    }
    return false;
  });
  return match?.user || null;
}

