type DbTx = Parameters<Parameters<typeof db.transaction>[0]>[0];

async function generateNextMemberCode(tx: DbTx, joinYear: number): Promise<string> {
  await tx.execute(sql`SELECT pg_advisory_xact_lock(90202602)`);
  const [row] = await tx
    .select({
      maxSeq: sql<number>`coalesce(max(case when ${members.memberCode} ~ '^SKM [0-9]+$' then substring(${members.memberCode} from '^SKM ([0-9]+)$')::int else 0 end), 0)::int`,
    })
    .from(members);

  let nextSeq = (row?.maxSeq ?? 0) + 1;
  while (true) {
    const candidate = formatMemberCode(nextSeq, joinYear);
    const existing = await tx
      .select({ id: members.id })
      .from(members)
      .where(eq(members.memberCode, candidate))
      .limit(1);
    if (existing.length === 0) return candidate;
    nextSeq += 1;
  }
}

async function generateNextReceiptNumber(tx: DbTx, yearNum: number): Promise<string> {
  await tx.execute(sql`SELECT pg_advisory_xact_lock(90202601)`);
  const [payRow] = await tx
    .select({
      maxSeq: sql<number>`coalesce(max(case when ${payments.receiptNumber} ~ '^[0-9]+$' then ${payments.receiptNumber}::int else 0 end), 0)::int`,
    })
    .from(payments);
  const [rcpRow] = await tx
    .select({
      maxSeq: sql<number>`coalesce(max(case when ${receipts.receiptNumber} ~ '^[0-9]+$' then ${receipts.receiptNumber}::int else 0 end), 0)::int`,
    })
    .from(receipts);

  let nextSeq = Math.max(payRow?.maxSeq ?? 0, rcpRow?.maxSeq ?? 0) + 1;
  while (true) {
    const candidate = formatReceiptNumber(yearNum, nextSeq);
    const existingPay = await tx
      .select({ id: payments.id })
      .from(payments)
      .where(eq(payments.receiptNumber, candidate))
      .limit(1);
    const existingRcp = await tx
      .select({ id: receipts.id })
      .from(receipts)
      .where(eq(receipts.receiptNumber, candidate))
      .limit(1);
    if (existingPay.length === 0 && existingRcp.length === 0) return candidate;
    nextSeq += 1;
  }
}

/**
 * Ensures a member has an obligation row for `targetYear` (2026..2060+).
 * Only creates missing rows; NEVER alters existing frozen obligations.
 */
async function ensureMemberObligationForYear(memberId: number, targetYear: number) {
  if (targetYear < START_YEAR || targetYear > MAX_SUPPORTED_YEAR) {
    throw new Error(`Year must be between ${START_YEAR} and ${MAX_SUPPORTED_YEAR}.`);
  }
  const existing = await db
    .select()
    .from(yearlyObligations)
    .where(and(eq(yearlyObligations.memberId, memberId), eq(yearlyObligations.year, targetYear)))
    .limit(1);
  if (existing.length > 0) return existing[0];

  const [member] = await db.select().from(members).where(eq(members.id, memberId)).limit(1);
  if (!member) throw new Error('Member not found.');

  const schedules = await db
    .select()
    .from(annualMembershipFees)
    .where(eq(annualMembershipFees.memberId, memberId));

  const fee = resolveAnnualFeeForYear(
    targetYear,
    Number(member.defaultAnnualFee),
    schedules.map((s) => ({
      effectiveFromYear: s.effectiveFromYear,
      annualFee: Number(s.annualFee),
    }))
  );

  const [created] = await db
    .insert(yearlyObligations)
    .values({
      memberId,
      year: targetYear,
      frozenAnnualFee: fee.toFixed(2),
      paidTotal: '0.00',
      status: 'UNPAID',
    })
    .onConflictDoNothing()
    .returning();

  if (created) return created;
  const fallback = await db
    .select()
    .from(yearlyObligations)
    .where(and(eq(yearlyObligations.memberId, memberId), eq(yearlyObligations.year, targetYear)))
    .limit(1);
  return fallback[0];
}

