// Public Member Status Lookup (Home Page: search by SKM Member Code, Name, or Mobile Number)
apiRouter.get('/public/member-lookup', async (req, res) => {
  try {
    await ensureSeeded();
    const rawQ = String(req.query.q || '').trim();
    if (!isPostgresConfigured()) {
      const out = await searchPublicMembersLocal(rawQ);
      return res.json(out);
    }

    const settings = await getSystemSettingsMap();
    const refYear = Math.max(START_YEAR, Number(settings.currentActiveYear || START_YEAR));
    if (!rawQ) {
      return res.json({ items: [], referenceYear: refYear });
    }

    const qLower = rawQ.toLowerCase();
    const qCompact = qLower.replace(/\s+/g, '');
    const qDigits = rawQ.replace(/\D/g, '');
    const isNumericOnly = /^\d+$/.test(rawQ);
    const isSkmExplicit = /^skm\s*-?\s*\d+$/i.test(rawQ);
    if (!isNumericOnly && rawQ.length < 2) {
      return res.json({ items: [], referenceYear: refYear });
    }

    const allMembers = await db.select().from(members).orderBy(asc(members.id));
    const matches = allMembers.filter((m) => {
      const codeLower = m.memberCode.toLowerCase();
      const codeCompact = codeLower.replace(/\s+/g, '');
      if (isSkmExplicit) {
        return codeCompact === `skm${qDigits}`;
      }
      if (isNumericOnly) {
        if (codeCompact === `skm${rawQ}`) return true;
        if (qDigits.length >= 4 && m.mobile.replace(/\D/g, '').includes(qDigits)) return true;
        return false;
      }
      if (codeLower === qLower || codeCompact === qCompact) return true;
      if (qLower.length >= 2 && m.name.toLowerCase().includes(qLower)) return true;
      if (qDigits.length >= 4 && m.mobile.replace(/\D/g, '').includes(qDigits)) return true;
      return false;
    });

    const sliced = matches.slice(0, 20);
    if (sliced.length === 0) {
      return res.json({ items: [], referenceYear: refYear });
    }

    const allObs = await db.select().from(yearlyObligations);
    const activePayments = await db
      .select({
        memberId: payments.memberId,
        paidAmount: payments.paidAmount,
        paymentDate: payments.paymentDate,
        id: payments.id,
      })
      .from(payments)
      .where(eq(payments.isVoided, false))
      .orderBy(desc(payments.paymentDate), desc(payments.id));

    const items = sliced.map((m) => {
      const mObs = allObs.filter((o) => o.memberId === m.id).sort((a, b) => a.year - b.year);
      const pending = calculatePendingSummary(
        mObs.map((o) => ({
          year: o.year,
          frozenAnnualFee: Number(o.frozenAnnualFee),
          paidTotal: Number(o.paidTotal),
          status: o.status as 'UNPAID' | 'PARTIAL' | 'PAID',
        })),
        refYear
      );
      const currentOb = mObs.find((o) => o.year === refYear);
      const currentYearExpected = currentOb
        ? Number(currentOb.frozenAnnualFee)
        : Number(m.defaultAnnualFee);
      const currentYearPaid = currentOb ? Number(currentOb.paidTotal) : 0;
      const currentState = computeObligationState(currentYearExpected, currentYearPaid);

      const mPays = activePayments.filter((p) => p.memberId === m.id);
      const totalPaidAllTime = roundMoney(mPays.reduce((s, p) => s + Number(p.paidAmount), 0));
      const yearlySummary = mObs
        .filter((o) => o.year <= refYear || Number(o.paidTotal) > 0)
        .map((o) => {
          const exp = Number(o.frozenAnnualFee);
          const paid = Number(o.paidTotal);
          const st = computeObligationState(exp, paid);
          return {
            year: o.year,
            expectedFee: exp,
            paidTotal: paid,
            dueAmount: st.dueAmount,
            status: st.status,
          };
        });

      return {
        memberCode: m.memberCode,
        name: m.name,
        guardianName: m.guardianName,
        status: m.status,
        referenceYear: refYear,
        currentYearStatus: currentState.status,
        currentYearExpected,
        currentYearPaid,
        currentYearDue: currentState.dueAmount,
        previousYearsDue: pending.previousYearsPending,
        totalOutstanding: pending.totalOutstanding,
        totalPaidAllTime,
        lastPaymentDate: mPays[0]?.paymentDate || null,
        yearlySummary,
      };
    });

    return res.json({ items, referenceYear: refYear });
  } catch (err) {
    console.error('Public member lookup failed:', err);
    return res.status(500).json({ error: 'Failed to search member records.' });
  }
});

const ROUTES_PROJECT_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');

function resolveExistingPackageFile(...relativeCandidates: string[]): string | null {
  const roots = Array.from(new Set([ROUTES_PROJECT_ROOT, process.cwd()]));
  for (const rel of relativeCandidates) {
    for (const root of roots) {
      const abs = path.join(root, rel);
      if (fs.existsSync(abs) && fs.statSync(abs).isFile()) {
        return abs;
      }
    }
  }
  return null;
}

