// Download attached file on a published notice
apiRouter.get('/public/notices/:id/attachment', async (req, res) => {
  try {
    const noticeId = Number(req.params.id);
    if (!Number.isInteger(noticeId)) {
      return res.status(400).json({ error: 'Invalid notice ID.' });
    }
    let dataUrl = '';
    let fileName = `notice-${noticeId}-file`;
    let mime = 'application/octet-stream';

    if (!isPostgresConfigured()) {
      const att = await getNoticeAttachmentLocal(noticeId);
      dataUrl = att.attachmentDataUrl;
      fileName = att.attachmentName;
      mime = att.attachmentMime;
    } else {
      await ensurePgPublicNoticesTable();
      const [row] = await db
        .select()
        .from(publicNotices)
        .where(eq(publicNotices.id, noticeId))
        .limit(1);
      if (!row || !row.attachmentDataUrl) {
        return res.status(404).json({ error: 'Attachment not found.' });
      }
      dataUrl = row.attachmentDataUrl;
      fileName = row.attachmentName || fileName;
      mime = row.attachmentMime || mime;
    }

    const base64Idx = dataUrl.indexOf('base64,');
    if (base64Idx === -1) {
      return res.status(400).json({ error: 'Unsupported attachment encoding.' });
    }
    const buf = Buffer.from(dataUrl.slice(base64Idx + 'base64,'.length), 'base64');
    res.setHeader('Content-Type', mime);
    res.setHeader(
      'Content-Disposition',
      `attachment; filename="${fileName.replace(/["\r\n]/g, '_')}"`
    );
    return res.send(buf);
  } catch (err) {
    return handleRouteError(res, err, 'Failed to download notice attachment.');
  }
});

