apiRouter.patch('/admin/notices/:id', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    const noticeId = Number(req.params.id);
    if (!Number.isInteger(noticeId)) {
      return res.status(400).json({ error: 'Invalid notice ID.' });
    }
    if (!isPostgresConfigured()) {
      const out = await updateNoticeLocal(noticeId, req.body ?? {}, req.authUser!);
      return res.json(out);
    }
    await ensurePgPublicNoticesTable();
    const [existing] = await db
      .select()
      .from(publicNotices)
      .where(eq(publicNotices.id, noticeId))
      .limit(1);
    if (!existing) {
      return res.status(404).json({ error: 'Notice not found.' });
    }

    const b = req.body ?? {};
    const updates: Partial<typeof publicNotices.$inferInsert> = { updatedAt: new Date() };
    if (b.title !== undefined) {
      const t = String(b.title).trim();
      if (!t) return res.status(400).json({ error: 'Notice title cannot be empty.' });
      updates.title = t.slice(0, 240);
    }
    if (b.content !== undefined) {
      const c = String(b.content).trim();
      if (!c) return res.status(400).json({ error: 'Notice content cannot be empty.' });
      updates.content = c;
    }
    if (b.noticeType !== undefined) {
      const nt = String(b.noticeType).toUpperCase();
      updates.noticeType = nt === 'PUBLIC_POST' || nt === 'EVENT' ? nt : 'NOTICE';
    }
    if (b.isPinned !== undefined) updates.isPinned = Boolean(b.isPinned);
    if (b.isPublished !== undefined) updates.isPublished = Boolean(b.isPublished);
    if ('imageDataUrl' in b) updates.imageDataUrl = b.imageDataUrl ? String(b.imageDataUrl) : null;
    if ('attachmentDataUrl' in b) {
      updates.attachmentDataUrl = b.attachmentDataUrl ? String(b.attachmentDataUrl) : null;
      updates.attachmentName = b.attachmentName ? String(b.attachmentName).slice(0, 180) : null;
      updates.attachmentMime = b.attachmentMime ? String(b.attachmentMime).slice(0, 120) : null;
    }

    const [saved] = await db
      .update(publicNotices)
      .set(updates)
      .where(eq(publicNotices.id, noticeId))
      .returning();

    return res.json({
      item: {
        id: saved.id,
        title: saved.title,
        content: saved.content,
        noticeType: saved.noticeType,
        imageDataUrl: saved.imageDataUrl,
        attachmentName: saved.attachmentName,
        attachmentMime: saved.attachmentMime,
        hasAttachment: Boolean(saved.attachmentDataUrl && saved.attachmentName),
        isPinned: saved.isPinned,
        isPublished: saved.isPublished,
        createdByName: saved.createdByName,
        createdAt: saved.createdAt.toISOString(),
        updatedAt: saved.updatedAt.toISOString(),
      },
    });
  } catch (err) {
    return handleRouteError(res, err, 'Failed to update notice.');
  }
});

