      username = found.username;
      fullName = found.fullName;
      phone = found.phone;
      email = found.email;
      isActive = found.isActive;
    } else {
      const foundPg = await findUserByIdentifierPg(identifier);
      if (!foundPg) {
        return res.status(404).json({
          error: 'No account found with that Mobile Number, Gmail, or User ID.',
        });
      }
      userId = foundPg.user.id;
      username = foundPg.user.username;
      fullName = foundPg.user.fullName;
      phone = foundPg.user.phone;
      email = foundPg.user.email;
      isActive = foundPg.user.isActive;
    }

    if (!isActive) {
      return res.status(403).json({
        error: 'This account is disabled. Contact the Madrasa Admin.',
      });
    }
    if (!phone && !email) {
      return res.status(400).json({
        error: 'No Mobile number or Gmail is registered on this account. Ask Admin to reset your password.',
      });
    }

    const challenge = await issueAdminOtpChallenge({
      userId,
      username,
      phone: phone || '',
      email: email || '',
    });

    // Offline-Only Admin Direct Recovery:
    // On a local offline PC where OTP cannot reach Gmail/SMS, if the entered identifier
    // matches the active Admin's registered Email or Mobile Number, sign Admin straight in.
    if (
      !challenge.emailDispatched &&
      !challenge.smsDispatched &&
      isLocalOfflinePcRequest(req as AuthRequest)
    ) {
      const authUser = await loadAuthenticatedUserById(userId);
      if (authUser && authUser.roleName === 'ADMIN') {
        const cleanId = identifier.toLowerCase();
        const digitsId = identifier.replace(/\D/g, '');
        const emailMatches = Boolean(email && email.toLowerCase() === cleanId);
        const phoneDigits = String(phone || '').replace(/\D/g, '');
        const phoneMatches = Boolean(
          digitsId.length >= 10 &&
            phoneDigits &&
            (phoneDigits === digitsId ||
              phoneDigits.endsWith(digitsId) ||
              digitsId.endsWith(phoneDigits))
        );

        if (emailMatches || phoneMatches) {
          if (!isPostgresConfigured()) {
            await markLastLoginLocal(authUser.id);
            const settings = await getSystemSettingsMapLocal();
            await logActivityLocal({
              actorUserId: authUser.id,
              actorName: authUser.fullName,
              actionType: 'LOGIN_OFFLINE_ADMIN_RECOVERY',
              entityType: 'USER',
              entityId: authUser.username,
              summary: `Admin signed in offline directly via registered Mobile/Gmail recovery`,
            });
            const token = signSessionToken(authUser.id, authUser.username);
            return res.json({ ...challenge, offlineDirectLogin: true, token, user: authUser, settings });
          } else {
            await db
              .update(users)
              .set({ lastLoginAt: new Date(), updatedAt: new Date() })
              .where(eq(users.id, authUser.id));
            const settings = await getSystemSettingsMap();
            await logActivity({
              actorUserId: authUser.id,
              actorName: authUser.fullName,
              actionType: 'LOGIN_OFFLINE_ADMIN_RECOVERY',
              entityType: 'USER',
              entityId: authUser.username,
              summary: `Admin signed in offline directly via registered Mobile/Gmail recovery`,
            });
            const token = signSessionToken(authUser.id, authUser.username);
            return res.json({ ...challenge, offlineDirectLogin: true, token, user: authUser, settings });
          }
        }
      }
    }

    if (!isPostgresConfigured()) {
      await logActivityLocal({
        actorUserId: userId,
        actorName: fullName,
        actionType: 'FORGOT_PASSWORD_OTP_REQUEST',
        entityType: 'USER',
        entityId: username,
        summary: `Forgot-password OTP requested for ${username} (${challenge.maskedPhone})`,
      });
    } else {
      await logActivity({
        actorUserId: userId,
        actorName: fullName,
        actionType: 'FORGOT_PASSWORD_OTP_REQUEST',
        entityType: 'USER',
        entityId: username,
        summary: `Forgot-password OTP requested for ${username} (${challenge.maskedPhone})`,
      });
    }

    return res.json({
      ...challenge,
      accountUsername: username,
      accountName: fullName,
    });
  } catch (err) {
    console.error('Forgot password OTP request failed:', err);
    return res.status(500).json({ error: 'Failed to send password reset OTP.' });
  }
});

// Complete Forgot Password after 6-digit Mobile/Gmail OTP Verification
apiRouter.post('/auth/forgot-password-reset', async (req, res) => {
  try {
    await ensureSeeded();
    const { challengeToken, otp, newPassword } = req.body ?? {};
    if (!challengeToken || !otp || !newPassword) {
      return res.status(400).json({
        error: 'OTP challenge token, 6-digit OTP, and new password are required.',
      });
    }
    if (String(newPassword).length < 6) {
      return res.status(400).json({
        error: 'New password must be at least 6 characters long.',
      });
    }

    const verified = verifyAdminOtpChallenge(String(challengeToken), String(otp));
    if (!verified.ok) {
      return res.status(verified.status).json({ error: verified.error });
    }

    if (!isPostgresConfigured()) {
      const result = await updateUserPasswordLocal(verified.userId, String(newPassword));
      return res.json({
        ok: true,
        username: result.username,
        message: 'Password updated successfully. You may now sign in.',
      });
    }

    const [existing] = await db.select().from(users).where(eq(users.id, verified.userId)).limit(1);
    if (!existing) return res.status(404).json({ error: 'Account not found.' });
    if (!existing.isActive) return res.status(403).json({ error: 'Account is disabled.' });

    await db
      .update(users)
      .set({
        passwordHash: hashPassword(String(newPassword)),
        updatedAt: new Date(),
      })
      .where(eq(users.id, verified.userId));

    await logActivity({
      actorUserId: existing.id,
      actorName: existing.fullName,
      actionType: 'FORGOT_PASSWORD_RESET',
      entityType: 'USER',
      entityId: existing.username,
      summary: `Reset password via Mobile/Gmail OTP verification (${existing.username})`,
    });

    return res.json({
      ok: true,
      username: existing.username,
      message: 'Password updated successfully. You may now sign in.',
    });
  } catch (err) {
    return handleRouteError(res, err, 'Failed to reset password.');
  }
});

