// Verify Firebase Mobile SMS OTP bound to challengeToken (supports BOTH Admin & Staff Login and Password Reset)
apiRouter.post('/auth/verify-firebase-phone-otp', async (req, res) => {
  try {
    await ensureSeeded();
    const { challengeToken, idToken, newPassword } = req.body ?? {};
    if (!challengeToken || !idToken) {
      return res.status(400).json({
        error: 'OTP session token and Firebase SMS verification token are required.',
      });
    }

    const peek = peekOtpChallenge(String(challengeToken));
    if (!peek) {
      return res.status(401).json({ error: 'OTP session expired or invalid. Please restart login.' });
    }

    const decoded = await adminAuth.verifyIdToken(String(idToken));
    const verifiedPhoneDigits = String(decoded.phone_number || '').replace(/\D/g, '');
    const accountPhoneDigits = String(peek.phone || '').replace(/\D/g, '');
    if (
      !verifiedPhoneDigits ||
      !accountPhoneDigits ||
      verifiedPhoneDigits.slice(-10) !== accountPhoneDigits.slice(-10)
    ) {
      return res.status(403).json({
        error: 'Verified mobile SMS number does not match this account registered mobile.',
      });
    }

    if (newPassword !== undefined) {
      const cleanPass = String(newPassword || '');
      if (cleanPass.length < 6) {
        return res.status(400).json({ error: 'New password must be at least 6 characters long.' });
      }
      const consumed = consumeOtpChallenge(String(challengeToken));
      if (!consumed.ok) {
        return res.status(consumed.status).json({ error: consumed.error });
      }
      const newHash = hashPassword(cleanPass);
      if (!isPostgresConfigured()) {
        await updateUserPasswordLocal(consumed.userId, newHash);
        await logActivityLocal({
          actorUserId: consumed.userId,
          actorName: consumed.username,
          actionType: 'FORGOT_PASSWORD_SMS_RESET',
          entityType: 'USER',
          entityId: consumed.username,
          summary: `Password reset via Mobile SMS OTP verification (${consumed.username})`,
        });
      } else {
        await db
          .update(users)
          .set({ passwordHash: newHash, updatedAt: new Date() })
          .where(eq(users.id, consumed.userId));
        await logActivity({
          actorUserId: consumed.userId,
          actorName: consumed.username,
          actionType: 'FORGOT_PASSWORD_SMS_RESET',
          entityType: 'USER',
          entityId: consumed.username,
          summary: `Password reset via Mobile SMS OTP verification (${consumed.username})`,
        });
      }
      return res.json({
        ok: true,
        username: consumed.username,
        message: 'Password updated via Mobile SMS OTP. Please sign in.',
      });
    }

    const consumed = consumeOtpChallenge(String(challengeToken));
    if (!consumed.ok) {
      return res.status(consumed.status).json({ error: consumed.error });
    }

    if (!isPostgresConfigured()) {
      await markLastLoginLocal(consumed.userId);
    } else {
      await db
        .update(users)
        .set({ lastLoginAt: new Date(), updatedAt: new Date() })
        .where(eq(users.id, consumed.userId));
    }

    const authUser = await loadAuthenticatedUserById(consumed.userId);
    if (!authUser || !authUser.username) {
      return res.status(403).json({ error: 'Account unavailable.' });
    }
    const token = signSessionToken(authUser.id, authUser.username);
    const settings = !isPostgresConfigured()
      ? await getSystemSettingsMapLocal()
      : await getSystemSettingsMap();

    if (!isPostgresConfigured()) {
      await logActivityLocal({
        actorUserId: authUser.id,
        actorName: authUser.fullName,
        actionType: 'LOGIN_MOBILE_SMS_OTP',
        entityType: 'USER',
        entityId: String(authUser.id),
        summary: `${authUser.roleName} verified Mobile SMS OTP & signed in (${authUser.username})`,
