// Live Dashboard Statistics (Real DB queries, zero hardcoded demo stats)
apiRouter.get('/dashboard', requireAuth, async (req: AuthRequest, res) => {
  try {
    await ensureSeeded();
    if (!isPostgresConfigured()) {
      const data = await getDashboardLocal(req.query.year ? Number(req.query.year) : undefined);
      return res.json(data);
    }
    const settings = await getSystemSettingsMap();
    const referenceYear = Math.max(
      START_YEAR,
      Number(req.query.year || settings.currentActiveYear || new Date().getFullYear())
    );

    const allMembers = await db.select().from(members);
    const totalMembers = allMembers.length;
    const activeMembers = allMembers.filter((m) => m.status === 'ACTIVE').length;
    const inactiveMembers = allMembers.filter((m) => m.status !== 'ACTIVE').length;

    // Ensure current referenceYear obligations exist for active members
    for (const m of allMembers) {
      if (m.status === 'ACTIVE') {
        await ensureMemberObligationForYear(m.id, referenceYear);
      }
    }

    const allPayments = await db
      .select({
        id: payments.id,
        memberId: payments.memberId,
        memberName: members.name,
        memberCode: members.memberCode,
        paymentYear: payments.paymentYear,
        paidAmount: payments.paidAmount,
        dueAfterPayment: payments.dueAfterPayment,
        paymentDate: payments.paymentDate,
        paymentTime: payments.paymentTime,
        paymentMethod: payments.paymentMethod,
        receiptNumber: payments.receiptNumber,
        receivedByName: users.fullName,
        receivedByUsername: users.username,
        isVoided: payments.isVoided,
        isSyncedFromOffline: payments.isSyncedFromOffline,
        createdAt: payments.createdAt,
      })
      .from(payments)
      .innerJoin(members, eq(payments.memberId, members.id))
      .innerJoin(users, eq(payments.receivedByUserId, users.id))
      .where(eq(payments.isVoided, false))
      .orderBy(desc(payments.createdAt));

    const totalCollection = roundMoney(
      allPayments.reduce((sum, p) => sum + Number(p.paidAmount), 0)
    );
    const currentYearCollection = roundMoney(
      allPayments
        .filter((p) => p.paymentYear === referenceYear)
        .reduce((sum, p) => sum + Number(p.paidAmount), 0)
    );

    const obligations = await db
      .select()
      .from(yearlyObligations)
      .where(eq(yearlyObligations.year, referenceYear));

    const activeIds = new Set(allMembers.filter((m) => m.status === 'ACTIVE').map((m) => m.id));
    let paidMembers = 0;
    let pendingMembers = 0;
    for (const ob of obligations) {
      if (!activeIds.has(ob.memberId)) continue;
      if (ob.status === 'PAID') paidMembers++;
      else pendingMembers++;
    }

    // Yearly Collection Chart (2026..max year with records or referenceYear+2)
    const yearlyMap = new Map<number, number>();
    const maxChartYear = Math.max(
      referenceYear + 1,
      ...allPayments.map((p) => p.paymentYear),
      START_YEAR + 2
    );
    for (let y = START_YEAR; y <= maxChartYear; y++) {
      yearlyMap.set(y, 0);
    }
    for (const p of allPayments) {
      yearlyMap.set(p.paymentYear, roundMoney((yearlyMap.get(p.paymentYear) || 0) + Number(p.paidAmount)));
    }
    const yearlyChart = Array.from(yearlyMap.entries()).map(([year, amount]) => ({
      year,
      amount,
    }));

    const recentActivities = await db
      .select({
        id: activityLogs.id,
        actorUserId: activityLogs.actorUserId,
        actorName: activityLogs.actorName,
        actorUsername: users.username,
        actionType: activityLogs.actionType,
        entityType: activityLogs.entityType,
        entityId: activityLogs.entityId,
        summary: activityLogs.summary,
        metadataJson: activityLogs.metadataJson,
        createdAt: activityLogs.createdAt,
      })
      .from(activityLogs)
      .leftJoin(users, eq(activityLogs.actorUserId, users.id))
      .orderBy(desc(activityLogs.createdAt))
      .limit(10);

    res.json({
      referenceYear,
      stats: {
        totalMembers,
        activeMembers,
        inactiveMembers,
        totalCollection,
        paidMembers,
        pendingMembers,
        currentYearCollection,
      },
      yearlyChart,
      recentPayments: allPayments.slice(0, 8),
      recentActivities,
      settings,
    });
  } catch (err) {
    console.error('Dashboard load failed:', err);
    res.status(500).json({ error: 'Failed to load dashboard statistics.' });
  }
});

