          ilike(members.guardianName, `%${query}%`)
        )
      );
    }
    if (statusFilter === 'ACTIVE' || statusFilter === 'INACTIVE') {
      conditions.push(eq(members.status, statusFilter));
    }

    const memberRows = await db
      .select({
        id: members.id,
        memberCode: members.memberCode,
        name: members.name,
        guardianName: members.guardianName,
        mobile: members.mobile,
        address: members.address,
        joiningDate: members.joiningDate,
        defaultAnnualFee: members.defaultAnnualFee,
        status: members.status,
        registrationDate: members.registrationDate,
        createdByName: users.fullName,
        createdAt: members.createdAt,
      })
      .from(members)
      .innerJoin(users, eq(members.createdByUserId, users.id))
      .where(conditions.length > 0 ? and(...conditions) : undefined)
      .orderBy(desc(members.id));

    const allObs = await db.select().from(yearlyObligations);
    const obsByMember = new Map<number, typeof allObs>();
    for (const ob of allObs) {
      const arr = obsByMember.get(ob.memberId) || [];
      arr.push(ob);
      obsByMember.set(ob.memberId, arr);
    }

    const activePayments = await db
      .select({
        memberId: payments.memberId,
        paymentYear: payments.paymentYear,
        receiptNumber: payments.receiptNumber,
      })
      .from(payments)
      .where(eq(payments.isVoided, false))
      .orderBy(desc(payments.id));

    const latestReceiptByMember = new Map<number, string>();
    const yearReceiptByMember = new Map<string, string>();
    for (const p of activePayments) {
      if (!latestReceiptByMember.has(p.memberId)) {
        latestReceiptByMember.set(p.memberId, p.receiptNumber);
      }
      const key = `${p.memberId}:${p.paymentYear}`;
      if (!yearReceiptByMember.has(key)) {
        yearReceiptByMember.set(key, p.receiptNumber);
      }
    }

    const enriched = memberRows.map((m) => {
      const mObs = obsByMember.get(m.id) || [];
      const pending = calculatePendingSummary(
        mObs.map((o) => ({
          year: o.year,
          frozenAnnualFee: Number(o.frozenAnnualFee),
          paidTotal: Number(o.paidTotal),
          status: o.status as 'UNPAID' | 'PARTIAL' | 'PAID',
        })),
        refYear
      );
      const currentOb = mObs.find((o) => o.year === refYear);
      return {
        ...m,
        defaultAnnualFee: Number(m.defaultAnnualFee),
        currentYearStatus: currentOb ? currentOb.status : 'UNPAID',
        currentYearPaid: currentOb ? Number(currentOb.paidTotal) : 0,
        currentYearExpected: currentOb ? Number(currentOb.frozenAnnualFee) : Number(m.defaultAnnualFee),
        totalOutstanding: pending.totalOutstanding,
        currentYearReceiptNumber: yearReceiptByMember.get(`${m.id}:${refYear}`) || null,
        latestReceiptNumber: latestReceiptByMember.get(m.id) || null,
      };
    });

    res.json({ members: enriched, referenceYear: refYear });
  } catch (err) {
    console.error('List members failed:', err);
    res.status(500).json({ error: 'Failed to search members.' });
  }
});

// Register New Member (Admin-Only)
apiRouter.post('/members', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    if (!isPostgresConfigured()) {
      const out = await createMemberLocal(req.body ?? {}, req.authUser!);
      return res.status(out.duplicateSkipped ? 200 : 201).json(out);
    }
    const {
      name,
      guardianName,
      mobile,
      address,
      joiningDate,
      defaultAnnualFee,
      status,
      clientOfflineId,
    } = req.body ?? {};

    if (!name || !guardianName || !mobile || !address || !joiningDate) {
      return res.status(400).json({ error: 'All member registration fields are required.' });
    }
    const feeNum = Number(defaultAnnualFee);
    if (!Number.isFinite(feeNum) || feeNum <= 0) {
      return res.status(400).json({ error: 'Individual annual membership fee must be greater than 0.' });
    }

    // Idempotency guard for offline sync
    if (clientOfflineId) {
      const dup = await db
        .select()
        .from(members)
        .where(eq(members.clientOfflineId, String(clientOfflineId)))
        .limit(1);
      if (dup.length > 0) {
        return res.json({ member: dup[0], duplicateSkipped: true });
      }
    }

    const created = await db.transaction(async (tx) => {
      const joinYear = Math.max(START_YEAR, Number(String(joiningDate).slice(0, 4)) || START_YEAR);
      const memberCode = await generateNextMemberCode(tx, joinYear);
      const regDate = new Date().toISOString().slice(0, 10);

      const [member] = await tx
        .insert(members)
        .values({
          memberCode,
          name: String(name).trim(),
          guardianName: String(guardianName).trim(),
          mobile: String(mobile).trim(),
          address: String(address).trim(),
          joiningDate: String(joiningDate),
          defaultAnnualFee: roundMoney(feeNum).toFixed(2),
          status: status === 'INACTIVE' ? 'INACTIVE' : 'ACTIVE',
          registrationDate: regDate,
          createdByUserId: req.authUser!.id,
          clientOfflineId: clientOfflineId ? String(clientOfflineId) : null,
        })
        .returning();

      await tx.insert(annualMembershipFees).values({
        memberId: member.id,
        effectiveFromYear: joinYear,
        annualFee: roundMoney(feeNum).toFixed(2),
        notes: 'Initial registration annual fee',
        setByUserId: req.authUser!.id,
      });

      const currentYear = Math.max(START_YEAR, new Date().getFullYear());
      for (let y = joinYear; y <= Math.max(currentYear, START_YEAR + 1); y++) {
        await tx.insert(yearlyObligations).values({
          memberId: member.id,
          year: y,
          frozenAnnualFee: roundMoney(feeNum).toFixed(2),
          paidTotal: '0.00',
          status: 'UNPAID',
        });
      }

      await tx.insert(activityLogs).values({
        actorUserId: req.authUser!.id,
        actorName: req.authUser!.fullName,
        actionType: 'CREATE_MEMBER',
        entityType: 'MEMBER',
        entityId: member.memberCode,
        summary: `Registered member ${member.name} (${member.memberCode}) with fee ₹${roundMoney(feeNum)}`,
      });

      return member;
    });

    res.status(201).json({ member: created });
  } catch (err) {
    return handleRouteError(res, err, 'Failed to register member.');
  }
});

// Get Full Member Profile + Yearly Ledger (2026..2050+) + Payment History
apiRouter.get('/members/:id', requireAuth, requirePermission('members:view'), async (req: AuthRequest, res) => {
  try {
    const memberId = Number(req.params.id);
    if (!Number.isInteger(memberId)) {
      return res.status(400).json({ error: 'Invalid member ID.' });
    }
    if (!isPostgresConfigured()) {
      const profile = await getMemberProfileLocal(memberId);
      return res.json(profile);
    }

    const found = await db
      .select({
        id: members.id,
        memberCode: members.memberCode,
        name: members.name,
        guardianName: members.guardianName,
        mobile: members.mobile,
        address: members.address,
        joiningDate: members.joiningDate,
        defaultAnnualFee: members.defaultAnnualFee,
        status: members.status,
        registrationDate: members.registrationDate,
        createdByName: users.fullName,
        createdAt: members.createdAt,
      })
      .from(members)
      .innerJoin(users, eq(members.createdByUserId, users.id))
      .where(eq(members.id, memberId))
      .limit(1);

    if (found.length === 0) {
      return res.status(404).json({ error: 'Member not found.' });
    }

    const member = found[0];
    const schedules = await db
      .select()
      .from(annualMembershipFees)
      .where(eq(annualMembershipFees.memberId, memberId))
      .orderBy(asc(annualMembershipFees.effectiveFromYear));

    const obligations = await db
      .select()
      .from(yearlyObligations)
      .where(eq(yearlyObligations.memberId, memberId))
      .orderBy(asc(yearlyObligations.year));

    const memberPayments = await db
      .select({
        id: payments.id,
        obligationId: payments.obligationId,
        paymentYear: payments.paymentYear,
        expectedFee: payments.expectedFee,
        paidAmount: payments.paidAmount,
        dueAfterPayment: payments.dueAfterPayment,
        paymentDate: payments.paymentDate,
        paymentMonth: payments.paymentMonth,
        paymentTime: payments.paymentTime,
        paymentMethod: payments.paymentMethod,
        receiptNumber: payments.receiptNumber,
        receivedByName: users.fullName,
        receivedByUsername: users.username,
        notes: payments.notes,
        isSyncedFromOffline: payments.isSyncedFromOffline,
        isVoided: payments.isVoided,
        createdAt: payments.createdAt,
      })
      .from(payments)
      .innerJoin(users, eq(payments.receivedByUserId, users.id))
      .where(eq(payments.memberId, memberId))
      .orderBy(desc(payments.paymentYear), desc(payments.createdAt));

    const settings = await getSystemSettingsMap();
    const refYear = Math.max(START_YEAR, Number(settings.currentActiveYear || START_YEAR));

    // Build dynamic projection from 2026 through 2055 (beyond 2050!)
    const obByYear = new Map(obligations.map((o) => [o.year, o]));
    const scheduleEntries = schedules.map((s) => ({
      effectiveFromYear: s.effectiveFromYear,
      annualFee: Number(s.annualFee),
    }));
    const joinYear = Math.max(START_YEAR, Number(member.joiningDate.slice(0, 4)) || START_YEAR);
    const yearlyLedger = [];
    for (let y = joinYear; y <= 2055; y++) {
      const existingOb = obByYear.get(y);
      const expectedFee = existingOb
        ? Number(existingOb.frozenAnnualFee)
        : resolveAnnualFeeForYear(y, Number(member.defaultAnnualFee), scheduleEntries);
      const paidTotal = existingOb ? Number(existingOb.paidTotal) : 0;
      const computed = computeObligationState(expectedFee, paidTotal);
      yearlyLedger.push({
        year: y,
        frozenAnnualFee: expectedFee,
        paidTotal,
        dueAmount: computed.dueAmount,
        status: existingOb ? existingOb.status : computed.status,
        isFutureYear: y > refYear,
        isPersisted: !!existingOb,
      });
    }

    const pendingSummary = calculatePendingSummary(
      obligations.map((o) => ({
        year: o.year,
        frozenAnnualFee: Number(o.frozenAnnualFee),
        paidTotal: Number(o.paidTotal),
        status: o.status as 'UNPAID' | 'PARTIAL' | 'PAID',
      })),
      refYear
    );

    res.json({
      member: { ...member, defaultAnnualFee: Number(member.defaultAnnualFee) },
      schedules: schedules.map((s) => ({ ...s, annualFee: Number(s.annualFee) })),
      yearlyLedger,
      payments: memberPayments.map((p) => ({
        ...p,
        expectedFee: Number(p.expectedFee),
        paidAmount: Number(p.paidAmount),
        dueAfterPayment: Number(p.dueAfterPayment),
      })),
      pendingSummary,
      referenceYear: refYear,
    });
  } catch (err) {
    return handleRouteError(res, err, 'Failed to load member profile.');
  }
});

// Edit Member & Configure Future Individual Annual Fee (never modifying historical fees!)
apiRouter.put('/members/:id', requireAuth, requirePermission('members:edit'), async (req: AuthRequest, res) => {
  try {
    const memberId = Number(req.params.id);
    if (!Number.isInteger(memberId)) {
      return res.status(400).json({ error: 'Invalid member ID.' });
    }
    if (!isPostgresConfigured()) {
      const member = await updateMemberLocal(memberId, req.body ?? {}, req.authUser!);
      return res.json({ member });
    }
    const {
      name,
      guardianName,
      mobile,
      address,
      status,
      newAnnualFee,
      effectiveFromYear,
      feeNotes,
    } = req.body ?? {};

    const updated = await db.transaction(async (tx) => {
      const existing = await tx.select().from(members).where(eq(members.id, memberId)).limit(1);
      if (existing.length === 0) throw new Error('NOT_FOUND');

      const updateFields: Partial<typeof members.$inferInsert> = {
        updatedAt: new Date(),
      };
      if (name) updateFields.name = String(name).trim();
      if (guardianName) updateFields.guardianName = String(guardianName).trim();
      if (mobile) updateFields.mobile = String(mobile).trim();
      if (address) updateFields.address = String(address).trim();
      if ((status === 'ACTIVE' || status === 'INACTIVE') && req.authUser!.roleName === 'ADMIN') {
        updateFields.status = status;
      }

      if (newAnnualFee !== undefined && Number(newAnnualFee) > 0) {
        const feeVal = roundMoney(Number(newAnnualFee));
        const effYear = Math.max(START_YEAR, Number(effectiveFromYear || new Date().getFullYear()));
        updateFields.defaultAnnualFee = feeVal.toFixed(2);

        await tx
          .insert(annualMembershipFees)
          .values({
            memberId,
            effectiveFromYear: effYear,
            annualFee: feeVal.toFixed(2),
            notes: feeNotes ? String(feeNotes) : `Updated fee from ${effYear}`,
            setByUserId: req.authUser!.id,
          })
          .onConflictDoUpdate({
            target: [annualMembershipFees.memberId, annualMembershipFees.effectiveFromYear],
            set: {
              annualFee: feeVal.toFixed(2),
              notes: feeNotes ? String(feeNotes) : `Updated fee from ${effYear}`,
              setByUserId: req.authUser!.id,
            },
          });

        // Update obligations >= effYear that have 0 payments OR target effYear when fee >= paidTotal;
        // NEVER alter historical (< effYear) frozen obligations!
        const futureObs = await tx
          .select()
          .from(yearlyObligations)
          .where(and(eq(yearlyObligations.memberId, memberId), gte(yearlyObligations.year, effYear)));

        for (const ob of futureObs) {
          const paidNum = Number(ob.paidTotal);
          if (paidNum === 0 || (ob.year === effYear && feeVal >= paidNum)) {
            const nextState = computeObligationState(feeVal, paidNum);
            await tx
              .update(yearlyObligations)
              .set({
                frozenAnnualFee: feeVal.toFixed(2),
                status: nextState.status,
                updatedAt: new Date(),
              })
              .where(eq(yearlyObligations.id, ob.id));
          }
        }
      }

      const [saved] = await tx
        .update(members)
        .set(updateFields)
        .where(eq(members.id, memberId))
        .returning();

      await tx.insert(activityLogs).values({
        actorUserId: req.authUser!.id,
        actorName: req.authUser!.fullName,
        actionType: 'UPDATE_MEMBER',
        entityType: 'MEMBER',
        entityId: saved.memberCode,
        summary: `Updated member ${saved.name} (${saved.memberCode})`,
        metadataJson: JSON.stringify(req.body),
      });

      return saved;
    });

    res.json({ member: updated });
  } catch (err: unknown) {
    if (err instanceof Error && err.message === 'NOT_FOUND') {
      return res.status(404).json({ error: 'Member not found.' });
    }
    return handleRouteError(res, err, 'Failed to update member.');
  }
});

// Delete Member (Admin-Only + Cascading Cleanup + Audit Log)
apiRouter.delete('/members/:id', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    const memberId = Number(req.params.id);
    if (!Number.isInteger(memberId)) {
      return res.status(400).json({ error: 'Invalid member ID.' });
    }
    if (!isPostgresConfigured()) {
      const deleted = await deleteMemberLocal(memberId, req.authUser!);
      return res.json(deleted);
    }

    const deleted = await db.transaction(async (tx) => {
      const [existing] = await tx.select().from(members).where(eq(members.id, memberId)).limit(1);
      if (!existing) throw new Error('NOT_FOUND');

      await tx.delete(members).where(eq(members.id, memberId));

      await tx.insert(activityLogs).values({
        actorUserId: req.authUser!.id,
        actorName: req.authUser!.fullName,
        actionType: 'DELETE_MEMBER',
        entityType: 'MEMBER',
        entityId: existing.memberCode,
        summary: `Deleted member ${existing.name} (${existing.memberCode})`,
        metadataJson: JSON.stringify({
          memberId: existing.id,
          memberCode: existing.memberCode,
          name: existing.name,
          mobile: existing.mobile,
        }),
      });

      return existing;
    });

    res.json({ ok: true, deletedMemberCode: deleted.memberCode, deletedName: deleted.name });
  } catch (err: unknown) {
    if (err instanceof Error && err.message === 'NOT_FOUND') {
      return res.status(404).json({ error: 'Member not found.' });
    }
    return handleRouteError(res, err, 'Failed to delete member.');
  }
});

// Record Payment (Full or Partial, Optional Previous Years' Dues Settlement, Duplicate-Protected, Auto-Generates Receipt, Transactional)
apiRouter.post('/payments', requireAuth, requirePermission('payments:create'), async (req: AuthRequest, res) => {
  try {
    if (!isPostgresConfigured()) {
      const out = await recordPaymentLocal(req.body ?? {}, req.authUser!);
      return res.status(out.duplicateSkipped ? 200 : 201).json(out);
    }
    const {
      memberId,
      paymentYear,
      paidAmount,
      paymentDate,
      paymentTime,
      paymentMethod,
      notes,
      clientTxId,
      includePreviousDues,
    } = req.body ?? {};

    const mId = Number(memberId);
    const yearNum = Number(paymentYear);
    const amountNum = Number(paidAmount);
    const includePrev = Boolean(includePreviousDues);

    if (!Number.isInteger(mId) || !Number.isInteger(yearNum) || !Number.isFinite(amountNum)) {
      return res.status(400).json({ error: 'Member, valid payment year, and amount are required.' });
    }

    // Idempotent check for offline/retry transactions
    if (clientTxId) {
      const existingTx = await db
        .select()
        .from(payments)
        .where(eq(payments.clientTxId, String(clientTxId)))
        .limit(1);
      if (existingTx.length > 0) {
        return res.json({ payment: existingTx[0], duplicateSkipped: true });
      }
    }

    const settings = await getSystemSettingsMap();
    const allowPartialPayments = settings.allowPartialPayments === 'true';

    // Ensure obligations exist from member joining year up to the target paymentYear
    const [memberPreview] = await db.select().from(members).where(eq(members.id, mId)).limit(1);
    if (!memberPreview) {
      return res.status(404).json({ error: 'Member not found.' });
    }
    const joinYear = Math.max(START_YEAR, Number(memberPreview.joiningDate.slice(0, 4)) || START_YEAR);
    const ensureStartYear = includePrev ? Math.min(joinYear, yearNum) : yearNum;
    for (let y = ensureStartYear; y <= yearNum; y++) {
      await ensureMemberObligationForYear(mId, y);
    }

    const result = await db.transaction(async (tx) => {
      const [member] = await tx.select().from(members).where(eq(members.id, mId)).limit(1);
      if (!member) throw new Error('MEMBER_NOT_FOUND');

      // Lock all relevant obligation rows up to yearNum for concurrent safety
      const obRows = await tx
        .select()
        .from(yearlyObligations)
        .where(
          includePrev
            ? and(
                eq(yearlyObligations.memberId, mId),
                gte(yearlyObligations.year, START_YEAR),
                lte(yearlyObligations.year, yearNum)
              )
            : and(eq(yearlyObligations.memberId, mId), eq(yearlyObligations.year, yearNum))
        )
        .orderBy(asc(yearlyObligations.year))
        .for('update');

      if (obRows.length === 0) throw new Error('OBLIGATION_MISSING');

      const plan = allocateMultiYearPayment({
        referenceYear: yearNum,
        obligations: obRows.map((o) => ({
          year: o.year,
          expectedFee: Number(o.frozenAnnualFee),
          alreadyPaid: Number(o.paidTotal),
        })),
        attemptAmount: amountNum,
        includePreviousDues: includePrev,
        allowPartialPayments,
      });

      if (!plan.ok) {
        throw new Error(`VALIDATION:${plan.error}`);
      }

      const now = new Date();
      const dateStr = paymentDate ? String(paymentDate) : now.toISOString().slice(0, 10);
      const monthStr = dateStr.slice(0, 7);
      const timeStr = paymentTime ? String(paymentTime) : now.toTimeString().slice(0, 8);
      const methodStr = paymentMethod ? String(paymentMethod) : 'Cash';

      const receiptNumber = await generateNextReceiptNumber(tx, yearNum);
      const obByYear = new Map(obRows.map((o) => [o.year, o]));
      const primaryAlloc =
        plan.allocations.find((a) => a.year === yearNum) ??
        plan.allocations[plan.allocations.length - 1];

      let primaryPayment: typeof payments.$inferSelect | null = null;
      const insertedPayments: Array<typeof payments.$inferSelect> = [];

      for (const alloc of plan.allocations) {
        const ob = obByYear.get(alloc.year);
        if (!ob) throw new Error('OBLIGATION_MISSING');
        const isPrimaryRow = alloc.year === primaryAlloc.year;
        const rowReceiptNumber = isPrimaryRow ? receiptNumber : `${receiptNumber}/${alloc.year}`;
        const rowNotes =
          plan.allocations.length > 1
            ? [
                notes ? String(notes).trim() : '',
                isPrimaryRow
                  ? `Combined Receipt #${receiptNumber} (Prev: ₹${plan.previousYearsPaidNow}, ${yearNum}: ₹${plan.currentYearPaidNow})`
                  : `Previous year (${alloc.year}) settled in Receipt #${receiptNumber}`,
              ]
                .filter(Boolean)
                .join(' · ')
            : notes
              ? String(notes).trim()
              : null;

        const [insertedPay] = await tx
          .insert(payments)
          .values({
            obligationId: ob.id,
            memberId: mId,
            paymentYear: alloc.year,
            expectedFee: alloc.expectedFee.toFixed(2),
            paidAmount: alloc.paidNow.toFixed(2),
            dueAfterPayment: alloc.dueAfterPayment.toFixed(2),
            paymentDate: dateStr,
            paymentMonth: monthStr,
            paymentTime: timeStr,
            paymentMethod: methodStr,
            receiptNumber: rowReceiptNumber,
            receivedByUserId: req.authUser!.id,
            notes: rowNotes,
            clientTxId: isPrimaryRow && clientTxId ? String(clientTxId) : null,
            isSyncedFromOffline: false,
            isVoided: false,
          })
          .returning();

        insertedPayments.push(insertedPay);
        if (isPrimaryRow) primaryPayment = insertedPay;

        await tx
          .update(yearlyObligations)
          .set({
            paidTotal: alloc.newPaidTotal.toFixed(2),
            status: alloc.status,
            updatedAt: new Date(),
          })
          .where(eq(yearlyObligations.id, ob.id));
      }

      if (!primaryPayment) throw new Error('OBLIGATION_MISSING');

      const hasPreviousContext =
        plan.previousYearsPaidNow > 0 || plan.previousYearsRemainingDue > 0;
      const breakdownObj = hasPreviousContext
        ? {
            isCombinedArrearsReceipt: true,
            referenceYear: yearNum,
            previousYearsPaid: plan.previousYearsPaidNow,
            currentYearPaid: plan.currentYearPaidNow,
            previousYearsRemainingDue: plan.previousYearsRemainingDue,
            currentYearRemainingDue: plan.currentYearRemainingDue,
            totalPaid: plan.totalPaidNow,
            totalRemainingDue: plan.totalRemainingDue,
            yearLines: plan.allocations.map((a) => ({
              year: a.year,
              expectedFee: a.expectedFee,
              paidNow: a.paidNow,
              totalPaidForYear: a.newPaidTotal,
              remainingDue: a.dueAfterPayment,
              isPreviousYear: a.isPreviousYear,
            })),
          }
        : null;

      const [receipt] = await tx
        .insert(receipts)
        .values({
          paymentId: primaryPayment.id,
          receiptNumber,
          memberCode: member.memberCode,
          issuedToName: member.name,
          paymentYear: yearNum,
          amountPaid: plan.totalPaidNow.toFixed(2),
          remainingDue: plan.totalRemainingDue.toFixed(2),
          issuedByName: req.authUser!.fullName,
          verificationHash: sha256Hex(`${receiptNumber}:${member.memberCode}:${plan.totalPaidNow}:${dateStr}`).slice(0, 16),
          breakdownJson: breakdownObj ? JSON.stringify(breakdownObj) : null,
        })
        .returning();

      const summaryNote =
        plan.previousYearsPaidNow > 0
          ? `Received ₹${plan.totalPaidNow} from ${member.name} (${member.memberCode}) [Prev: ₹${plan.previousYearsPaidNow}, ${yearNum}: ₹${plan.currentYearPaidNow}]`
          : `Received ₹${plan.totalPaidNow} from ${member.name} (${member.memberCode}) for ${yearNum}`;

      await tx.insert(activityLogs).values({
        actorUserId: req.authUser!.id,
        actorName: req.authUser!.fullName,
        actionType: 'RECORD_PAYMENT',
        entityType: 'PAYMENT',
        entityId: receiptNumber,
        summary: summaryNote,
        metadataJson: JSON.stringify({
          memberCode: member.memberCode,
          year: yearNum,
          paidAmount: plan.totalPaidNow,
          previousYearsPaid: plan.previousYearsPaidNow,
          currentYearPaid: plan.currentYearPaidNow,
          dueAfterPayment: plan.totalRemainingDue,
          settledYears: plan.allocations.map((a) => a.year),
        }),
      });

      return {
        payment: primaryPayment,
        payments: insertedPayments,
        receipt,
        member,
        breakdown: breakdownObj,
      };
    });

    res.status(201).json(result);
  } catch (err: unknown) {
    if (err instanceof RepoHttpError) {
      return res.status(err.status).json({ error: err.message });
    }
    if (err instanceof Error) {
      if (err.message === 'MEMBER_NOT_FOUND') {
        return res.status(404).json({ error: 'Member not found.' });
      }
      if (err.message.startsWith('VALIDATION:')) {
        return res.status(400).json({ error: err.message.slice('VALIDATION:'.length) });
      }
    }
    console.error('Payment recording failed:', err);
    res.status(500).json({ error: 'Failed to record payment.' });
  }
});

