// Audited Payment Correction (Immutable payment_corrections trail!)
apiRouter.post('/payments/:id/correct', requireAuth, requirePermission('payments:correct'), async (req: AuthRequest, res) => {
  try {
    const paymentId = Number(req.params.id);
    const { newPaidAmount, newPaymentMethod, newNotes, reason } = req.body ?? {};
    if (!Number.isInteger(paymentId)) {
      return res.status(400).json({ error: 'Invalid payment ID.' });
    }
    if (!isPostgresConfigured()) {
      const out = await correctPaymentLocal(
        paymentId,
        { newPaidAmount, newPaymentMethod, newNotes, reason },
        req.authUser!
      );
      return res.json(out);
    }
    if (!reason || String(reason).trim().length < 5) {
      return res.status(400).json({
        error: 'A detailed reason (minimum 5 characters) is mandatory for payment corrections.',
      });
    }

    const updated = await db.transaction(async (tx) => {
      const [pay] = await tx.select().from(payments).where(eq(payments.id, paymentId)).limit(1);
      if (!pay) throw new Error('NOT_FOUND');

      const [ob] = await tx
        .select()
        .from(yearlyObligations)
        .where(eq(yearlyObligations.id, pay.obligationId))
        .for('update');

      const siblingPayments = await tx
        .select()
        .from(payments)
        .where(and(eq(payments.obligationId, ob.id), eq(payments.isVoided, false)));

      const otherPaidTotal = roundMoney(
        siblingPayments
          .filter((p) => p.id !== paymentId)
          .reduce((sum, p) => sum + Number(p.paidAmount), 0)
      );

      const targetAmount =
        newPaidAmount !== undefined ? Number(newPaidAmount) : Number(pay.paidAmount);
      const validation = validateCorrectionRequest({
        originalAmount: Number(pay.paidAmount),
        newAmount: targetAmount,
        reason: String(reason),
        otherPaymentsPaidTotal: otherPaidTotal,
        expectedFee: Number(ob.frozenAnnualFee),
      });

      if (!validation.ok) {
        throw new Error(`VALIDATION:${validation.error}`);
      }

      const auditEntries: Array<{ fieldName: string; originalValue: string; updatedValue: string }> = [];

      if (roundMoney(targetAmount) !== roundMoney(Number(pay.paidAmount))) {
        auditEntries.push({
          fieldName: 'paidAmount',
          originalValue: pay.paidAmount,
          updatedValue: roundMoney(targetAmount).toFixed(2),
        });
      }
      if (newPaymentMethod && String(newPaymentMethod) !== pay.paymentMethod) {
        auditEntries.push({
          fieldName: 'paymentMethod',
          originalValue: pay.paymentMethod,
          updatedValue: String(newPaymentMethod),
        });
      }
      if (newNotes !== undefined && String(newNotes) !== (pay.notes || '')) {
        auditEntries.push({
          fieldName: 'notes',
          originalValue: pay.notes || '(empty)',
          updatedValue: String(newNotes) || '(empty)',
        });
      }

      if (auditEntries.length === 0) {
        throw new Error('VALIDATION:No changes were made to the payment record.');
      }

      const [savedPay] = await tx
        .update(payments)
        .set({
          paidAmount: roundMoney(targetAmount).toFixed(2),
          dueAfterPayment: validation.newObligationDue.toFixed(2),
          paymentMethod: newPaymentMethod ? String(newPaymentMethod) : pay.paymentMethod,
          notes: newNotes !== undefined ? String(newNotes) : pay.notes,
          updatedAt: new Date(),
        })
        .where(eq(payments.id, paymentId))
        .returning();

      await tx
        .update(yearlyObligations)
        .set({
          paidTotal: validation.newObligationPaidTotal.toFixed(2),
          status: validation.newStatus,
          updatedAt: new Date(),
        })
        .where(eq(yearlyObligations.id, ob.id));

      await tx
        .update(receipts)
        .set({
          amountPaid: roundMoney(targetAmount).toFixed(2),
          remainingDue: validation.newObligationDue.toFixed(2),
        })
        .where(eq(receipts.paymentId, paymentId));

      for (const entry of auditEntries) {
        await tx.insert(paymentCorrections).values({
          paymentId,
          fieldName: entry.fieldName,
          originalValue: entry.originalValue,
          updatedValue: entry.updatedValue,
          reason: String(reason).trim(),
          correctedByUserId: req.authUser!.id,
        });
      }

      await tx.insert(activityLogs).values({
        actorUserId: req.authUser!.id,
        actorName: req.authUser!.fullName,
        actionType: 'CORRECT_PAYMENT',
        entityType: 'PAYMENT',
        entityId: pay.receiptNumber,
        summary: `Corrected receipt ${pay.receiptNumber}: ${String(reason).trim()}`,
        metadataJson: JSON.stringify(auditEntries),
      });

      return savedPay;
    });

    res.json({ payment: updated });
  } catch (err: unknown) {
    if (err instanceof RepoHttpError) {
      return res.status(err.status).json({ error: err.message });
    }
    if (err instanceof Error) {
      if (err.message === 'NOT_FOUND') return res.status(404).json({ error: 'Payment not found.' });
      if (err.message.startsWith('VALIDATION:')) {
        return res.status(400).json({ error: err.message.slice('VALIDATION:'.length) });
      }
    }
    console.error('Payment correction failed:', err);
    res.status(500).json({ error: 'Failed to apply payment correction.' });
  }
});

// Get Receipt by Receipt Number (supports both primary ID e.g. "11" and child row e.g. "11/2026")
apiRouter.get('/receipts/:receiptNumber', requireAuth, async (req: AuthRequest, res) => {
  try {
    if (
      req.authUser!.roleName !== 'ADMIN' &&
      !req.authUser!.permissions.includes('payments:view') &&
      !req.authUser!.permissions.includes('payments:create')
    ) {
      return res.status(403).json({ error: 'Permission denied to view or print receipts.' });
    }
    const rawParam = String(req.params.receiptNumber);
    if (!isPostgresConfigured()) {
      const out = await getReceiptLocal(rawParam);
      return res.json(out);
    }
    const primaryNo = rawParam.includes('/') ? rawParam.split('/')[0] : rawParam;

    const queryReceipt = async (rNo: string) =>
      db
        .select({
          receiptNumber: receipts.receiptNumber,
          memberCode: receipts.memberCode,
          issuedToName: receipts.issuedToName,
          paymentYear: receipts.paymentYear,
          amountPaid: receipts.amountPaid,
          remainingDue: receipts.remainingDue,
          issuedByName: receipts.issuedByName,
          issuedByUsername: users.username,
          issuedAt: receipts.issuedAt,
          verificationHash: receipts.verificationHash,
          breakdownJson: receipts.breakdownJson,
          paymentDate: payments.paymentDate,
          paymentTime: payments.paymentTime,
          paymentMethod: payments.paymentMethod,
          expectedFee: payments.expectedFee,
          notes: payments.notes,
          memberId: members.id,
          joiningDate: members.joiningDate,
          defaultAnnualFee: members.defaultAnnualFee,
          guardianName: members.guardianName,
          mobile: members.mobile,
          address: members.address,
        })
        .from(receipts)
        .innerJoin(payments, eq(receipts.paymentId, payments.id))
        .innerJoin(members, eq(payments.memberId, members.id))
        .leftJoin(users, eq(payments.receivedByUserId, users.id))
        .where(eq(receipts.receiptNumber, rNo))
        .limit(1);

    let rows = await queryReceipt(rawParam);
    if (rows.length === 0 && primaryNo !== rawParam) {
      rows = await queryReceipt(primaryNo);
    }

    if (rows.length === 0) {
      return res.status(404).json({ error: 'Receipt not found.' });
    }

    const row = rows[0];
    let parsedBreakdown = null;
    if (row.breakdownJson) {
      try {
        parsedBreakdown = JSON.parse(row.breakdownJson);
      } catch {
        parsedBreakdown = null;
      }
    }

    const settings = await getSystemSettingsMap();
    const activeReferenceYear = Math.max(
      START_YEAR,
      Number(settings.currentActiveYear) || new Date().getFullYear()
    );
    const joinYear = Math.max(START_YEAR, Number(row.joiningDate.slice(0, 4)) || START_YEAR);
    const schedRows = await db
      .select()
      .from(annualMembershipFees)
      .where(eq(annualMembershipFees.memberId, row.memberId));
    const scheds = schedRows.map((s) => ({
      effectiveFromYear: s.effectiveFromYear,
      annualFee: Number(s.annualFee),
    }));
    const obRows = await db
      .select()
      .from(yearlyObligations)
      .where(eq(yearlyObligations.memberId, row.memberId));
    const obByYear = new Map(obRows.map((o) => [o.year, o]));

    const previousPendingDues: Array<{ year: number; dueAmount: number }> = [];
    for (let y = joinYear; y < row.paymentYear; y++) {
      const ob = obByYear.get(y);
      const expFee = ob
        ? Number(ob.frozenAnnualFee)
        : resolveAnnualFeeForYear(y, Number(row.defaultAnnualFee), scheds);
      const paidVal = ob ? Number(ob.paidTotal) : 0;
      const dueVal = roundMoney(Math.max(0, expFee - paidVal));
      if (dueVal > 0) {
        previousPendingDues.push({ year: y, dueAmount: dueVal });
      }
    }
    const totalPreviousDueAmount = roundMoney(
      previousPendingDues.reduce((sum, item) => sum + item.dueAmount, 0)
    );

    res.json({
      receipt: {
        receiptNumber: row.receiptNumber,
        memberCode: row.memberCode,
        issuedToName: row.issuedToName,
        paymentYear: row.paymentYear,
        amountPaid: Number(row.amountPaid),
        remainingDue: Number(row.remainingDue),
        expectedFee: parsedBreakdown ? Number(parsedBreakdown.totalPaid + parsedBreakdown.totalRemainingDue) : Number(row.expectedFee),
        issuedByName: row.issuedByName,
        issuedByUsername: row.issuedByUsername || undefined,
        issuedAt: row.issuedAt,
        verificationHash: row.verificationHash,
        paymentDate: row.paymentDate,
        paymentTime: row.paymentTime,
        paymentMethod: row.paymentMethod,
        notes: row.notes,
        guardianName: row.guardianName,
        mobile: row.mobile,
        address: row.address,
        isAdvanceYearPayment: row.paymentYear > activeReferenceYear,
        activeReferenceYear,
        previousPendingDues,
        totalPreviousDueAmount,
        breakdown: parsedBreakdown,
      },
    });
  } catch (err) {
    return handleRouteError(res, err, 'Failed to load receipt.');
  }
});

// Pending Payments Management (Current Year Pending, Previous Years Pending, Member-wise Pending)
apiRouter.get('/pending', requireAuth, requirePermission('payments:view'), async (req: AuthRequest, res) => {
  try {
    if (!isPostgresConfigured()) {
      const out = await getPendingDuesLocal(req.query.year ? Number(req.query.year) : undefined);
      return res.json(out);
    }
    const settings = await getSystemSettingsMap();
    const referenceYear = Math.max(
      START_YEAR,
      Number(req.query.year || settings.currentActiveYear || START_YEAR)
    );

    const activeMembers = await db
      .select()
      .from(members)
      .where(eq(members.status, 'ACTIVE'))
      .orderBy(asc(members.memberCode));

    for (const m of activeMembers) {
      const joinYear = Math.max(START_YEAR, Number(m.joiningDate.slice(0, 4)) || START_YEAR);
      for (let y = joinYear; y <= referenceYear; y++) {
        await ensureMemberObligationForYear(m.id, y);
      }
    }

    const allObs = await db
      .select()
      .from(yearlyObligations)
      .where(lte(yearlyObligations.year, referenceYear));

    const obsByMember = new Map<number, typeof allObs>();
    for (const o of allObs) {
      const arr = obsByMember.get(o.memberId) || [];
      arr.push(o);
      obsByMember.set(o.memberId, arr);
    }

    const activePayments = await db
      .select({
        memberId: payments.memberId,
        paymentYear: payments.paymentYear,
        receiptNumber: payments.receiptNumber,
      })
      .from(payments)
      .where(eq(payments.isVoided, false))
      .orderBy(desc(payments.id));

    const latestReceiptByMember = new Map<number, string>();
    const yearReceiptByMember = new Map<string, string>();
    for (const p of activePayments) {
      if (!latestReceiptByMember.has(p.memberId)) {
        latestReceiptByMember.set(p.memberId, p.receiptNumber);
      }
      const key = `${p.memberId}:${p.paymentYear}`;
      if (!yearReceiptByMember.has(key)) {
        yearReceiptByMember.set(key, p.receiptNumber);
      }
    }

    let totalCurrentYearPending = 0;
    let totalPreviousYearsPending = 0;

    const memberPendingList = activeMembers.map((m) => {
      const obs = (obsByMember.get(m.id) || []).filter(
        (o) => o.year >= Math.max(START_YEAR, Number(m.joiningDate.slice(0, 4)) || START_YEAR)
      );
      const summary = calculatePendingSummary(
        obs.map((o) => ({
          year: o.year,
          frozenAnnualFee: Number(o.frozenAnnualFee),
          paidTotal: Number(o.paidTotal),
          status: o.status as 'UNPAID' | 'PARTIAL' | 'PAID',
        })),
        referenceYear
      );

      totalCurrentYearPending = roundMoney(totalCurrentYearPending + summary.currentYearPending);
      totalPreviousYearsPending = roundMoney(totalPreviousYearsPending + summary.previousYearsPending);

      const currentYearOb = obs.find((o) => o.year === referenceYear);
      const currentStatus = currentYearOb
        ? (currentYearOb.status as 'UNPAID' | 'PARTIAL' | 'PAID')
        : 'UNPAID';

      return {
        memberId: m.id,
        memberCode: m.memberCode,
        name: m.name,
        guardianName: m.guardianName,
        mobile: m.mobile,
        defaultAnnualFee: Number(m.defaultAnnualFee),
        currentYearStatus: currentStatus,
        currentYearPending: summary.currentYearPending,
        previousYearsPending: summary.previousYearsPending,
        totalOutstanding: summary.totalOutstanding,
        overdueYears: summary.overdueYears,
        currentYearReceiptNumber: yearReceiptByMember.get(`${m.id}:${referenceYear}`) || null,
        latestReceiptNumber: latestReceiptByMember.get(m.id) || null,
      };
    });

    res.json({
      referenceYear,
      summary: {
        currentYearPending: totalCurrentYearPending,
        previousYearsPending: totalPreviousYearsPending,
        totalOutstanding: roundMoney(totalCurrentYearPending + totalPreviousYearsPending),
        pendingMemberCount: memberPendingList.filter((m) => m.totalOutstanding > 0).length,
      },
      items: memberPendingList.filter((m) => m.totalOutstanding > 0),
      allActiveStatus: memberPendingList,
    });
  } catch (err) {
    console.error('Pending dues load failed:', err);
    res.status(500).json({ error: 'Failed to calculate pending dues.' });
  }
});

// 10 Comprehensive Filterable Reports
apiRouter.get('/reports/:reportType', requireAuth, requirePermission('reports:view'), async (req: AuthRequest, res) => {
  try {
    const reportType = String(req.params.reportType);
    const year = req.query.year ? Number(req.query.year) : null;
    const fromDate = req.query.fromDate ? String(req.query.fromDate) : null;
    const toDate = req.query.toDate ? String(req.query.toDate) : null;
    const memberId = req.query.memberId ? Number(req.query.memberId) : null;
    const staffId = req.query.staffId ? Number(req.query.staffId) : null;
    if (!isPostgresConfigured()) {
      const out = await getReportLocal(reportType, { year, fromDate, toDate, memberId, staffId });
      return res.json(out);
    }
    const settings = await getSystemSettingsMap();
    const refYear = year || Math.max(START_YEAR, Number(settings.currentActiveYear || START_YEAR));

    if (reportType === 'all-members' || reportType === 'active-members' || reportType === 'inactive-members') {
      const statusCond =
        reportType === 'active-members'
          ? eq(members.status, 'ACTIVE')
          : reportType === 'inactive-members'
            ? eq(members.status, 'INACTIVE')
            : undefined;
      const rows = await db
        .select()
        .from(members)
        .where(statusCond)
        .orderBy(asc(members.memberCode));
      return res.json({
        reportType,
        rows: rows.map((m) => ({
          memberCode: m.memberCode,
          name: m.name,
          guardianName: m.guardianName,
          mobile: m.mobile,
          address: m.address,
          joiningDate: m.joiningDate,
          annualFee: Number(m.defaultAnnualFee),
          status: m.status,
          registrationDate: m.registrationDate,
        })),
      });
    }

    if (reportType === 'paid-members' || reportType === 'pending-members' || reportType === 'outstanding-dues') {
      const allMembers = await db.select().from(members).orderBy(asc(members.memberCode));
      for (const m of allMembers) {
        if (m.status === 'ACTIVE') {
          await ensureMemberObligationForYear(m.id, refYear);
        }
      }
      const obs = await db
        .select()
        .from(yearlyObligations)
        .where(lte(yearlyObligations.year, refYear));
      const obsMap = new Map<number, typeof obs>();
      for (const o of obs) {
        const list = obsMap.get(o.memberId) || [];
        list.push(o);
        obsMap.set(o.memberId, list);
      }

      const activePayments = await db
        .select({
          memberId: payments.memberId,
          paymentYear: payments.paymentYear,
          receiptNumber: payments.receiptNumber,
        })
        .from(payments)
        .where(eq(payments.isVoided, false))
        .orderBy(desc(payments.id));

      const yearReceiptMap = new Map<string, string>();
      for (const p of activePayments) {
        const key = `${p.memberId}:${p.paymentYear}`;
        if (!yearReceiptMap.has(key)) yearReceiptMap.set(key, p.receiptNumber);
      }

      const rows = allMembers
        .filter((m) => (memberId ? m.id === memberId : true))
        .map((m) => {
          const mObs = obsMap.get(m.id) || [];
          const yearOb = mObs.find((o) => o.year === refYear);
          const pending = calculatePendingSummary(
            mObs.map((o) => ({
              year: o.year,
              frozenAnnualFee: Number(o.frozenAnnualFee),
              paidTotal: Number(o.paidTotal),
              status: o.status as 'UNPAID' | 'PARTIAL' | 'PAID',
            })),
            refYear
          );
          const expected = yearOb ? Number(yearOb.frozenAnnualFee) : Number(m.defaultAnnualFee);
          const paid = yearOb ? Number(yearOb.paidTotal) : 0;
          const status = yearOb ? yearOb.status : 'UNPAID';
          return {
            memberCode: m.memberCode,
            name: m.name,
            mobile: m.mobile,
            memberStatus: m.status,
            year: refYear,
            expectedFee: expected,
            paidAmount: paid,
            currentYearDue: roundMoney(Math.max(0, expected - paid)),
            previousYearsDue: pending.previousYearsPending,
            totalOutstanding: pending.totalOutstanding,
            paymentStatus: status,
            receiptNumber: yearReceiptMap.get(`${m.id}:${refYear}`) || '',
          };
        });

      const filtered =
        reportType === 'paid-members'
          ? rows.filter((r) => r.paymentStatus === 'PAID')
          : rows.filter((r) => r.totalOutstanding > 0 || r.paymentStatus !== 'PAID');

      return res.json({ reportType, year: refYear, rows: filtered });
    }

    if (
      reportType === 'yearly-collection' ||
      reportType === 'total-collection' ||
      reportType === 'member-history'
    ) {
      const conditions = [eq(payments.isVoided, false)];
      if (year && reportType !== 'total-collection') conditions.push(eq(payments.paymentYear, year));
      if (memberId) conditions.push(eq(payments.memberId, memberId));
      if (staffId) conditions.push(eq(payments.receivedByUserId, staffId));
      if (fromDate) conditions.push(gte(payments.paymentDate, fromDate));
      if (toDate) conditions.push(lte(payments.paymentDate, toDate));

      const rows = await db
        .select({
          receiptNumber: payments.receiptNumber,
          memberCode: members.memberCode,
          memberName: members.name,
          mobile: members.mobile,
          paymentYear: payments.paymentYear,
          expectedFee: payments.expectedFee,
          paidAmount: payments.paidAmount,
          dueAfterPayment: payments.dueAfterPayment,
          paymentDate: payments.paymentDate,
          paymentTime: payments.paymentTime,
          paymentMethod: payments.paymentMethod,
          receivedByName: users.fullName,
          notes: payments.notes,
        })
        .from(payments)
        .innerJoin(members, eq(payments.memberId, members.id))
        .innerJoin(users, eq(payments.receivedByUserId, users.id))
        .where(and(...conditions))
        .orderBy(desc(payments.paymentDate), desc(payments.id));

      return res.json({
        reportType,
        rows: rows.map((r) => ({
          ...r,
          expectedFee: Number(r.expectedFee),
          paidAmount: Number(r.paidAmount),
          dueAfterPayment: Number(r.dueAfterPayment),
        })),
      });
    }

    if (reportType === 'staff-activity') {
      const conditions = [];
      if (staffId) conditions.push(eq(activityLogs.actorUserId, staffId));
      const rows = await db
        .select()
        .from(activityLogs)
        .where(conditions.length > 0 ? and(...conditions) : undefined)
        .orderBy(desc(activityLogs.createdAt))
        .limit(300);

      const filtered = rows.filter((r) => {
        const d = r.createdAt.toISOString().slice(0, 10);
        if (fromDate && d < fromDate) return false;
        if (toDate && d > toDate) return false;
        return true;
      });
      return res.json({ reportType, rows: filtered });
    }

    return res.status(400).json({ error: `Unknown report type: ${reportType}` });
  } catch (err) {
    console.error('Report generation failed:', err);
    res.status(500).json({ error: 'Failed to generate report.' });
  }
});

// Staff & Permission Management (Admin only)
apiRouter.get('/staff', requireAuth, async (req: AuthRequest, res) => {
  try {
    // Allow staff list names for filter dropdowns if user has reports:view, full details only for Admin
    const isAdmin = req.authUser!.roleName === 'ADMIN';
    if (!isAdmin && !req.authUser!.permissions.includes('reports:view')) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    if (!isPostgresConfigured()) {
      const out = await listStaffLocal(isAdmin);
      return res.json(out);
    }

    const allPerms = await db.select().from(permissions).orderBy(asc(permissions.id));
    const userRows = await db
      .select({
        id: users.id,
        username: users.username,
        fullName: users.fullName,
        email: users.email,
        phone: users.phone,
        roleName: roles.name,
        isActive: users.isActive,
        canOfflineEntry: users.canOfflineEntry,
        lastLoginAt: users.lastLoginAt,
        createdAt: users.createdAt,
      })
      .from(users)
      .innerJoin(roles, eq(users.roleId, roles.id))
      .orderBy(asc(users.id));

    if (!isAdmin) {
      return res.json({
        staff: userRows.map((u) => ({ id: u.id, fullName: u.fullName, username: u.username, roleName: u.roleName })),
        permissions: [],
      });
    }

    const uPerms = await db
      .select({
        userId: userPermissions.userId,
        code: permissions.code,
      })
      .from(userPermissions)
      .innerJoin(permissions, eq(userPermissions.permissionId, permissions.id));

    const permMap = new Map<number, string[]>();
    for (const up of uPerms) {
      const list = permMap.get(up.userId) || [];
      list.push(up.code);
      permMap.set(up.userId, list);
    }

    res.json({
      staff: userRows.map((u) => ({
        ...u,
        permissions: u.roleName === 'ADMIN' ? allPerms.map((p) => p.code) : permMap.get(u.id) || [],
      })),
      permissions: allPerms,
    });
  } catch (err) {
    console.error('Staff list failed:', err);
    res.status(500).json({ error: 'Failed to load staff list.' });
  }
});

apiRouter.post('/staff', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    if (!isPostgresConfigured()) {
      const out = await createStaffLocal(req.body ?? {}, req.authUser!);
      return res.status(201).json(out);
    }
    const { username, password, fullName, email, phone, roleName, permissionCodes } = req.body ?? {};
    if (!username || !password || !fullName) {
      return res.status(400).json({ error: 'Username, password, and full name are required.' });
    }
    const targetRoleName = roleName === 'ADMIN' ? 'ADMIN' : 'STAFF';
    const [role] = await db.select().from(roles).where(eq(roles.name, targetRoleName)).limit(1);
    if (!role) return res.status(500).json({ error: 'Role configuration missing.' });

    const created = await db.transaction(async (tx) => {
      const [newUser] = await tx
        .insert(users)
        .values({
          username: String(username).trim().toLowerCase(),
          passwordHash: hashPassword(String(password)),
          fullName: String(fullName).trim(),
          email: email ? String(email).trim() : null,
          phone: phone ? String(phone).trim() : null,
          roleId: role.id,
          isActive: true,
          canOfflineEntry: targetRoleName === 'ADMIN',
        })
        .returning();

      if (targetRoleName === 'STAFF' && Array.isArray(permissionCodes)) {
        const allPerms = await tx.select().from(permissions);
        const byCode = new Map(allPerms.map((p) => [p.code, p.id]));
        const allowedCodes = permissionCodes
          .map((c) => String(c))
          .filter((code) => code !== 'members:create' && code !== 'members:delete');
        for (const code of allowedCodes) {
          const pId = byCode.get(code);
          if (pId) {
            await tx
              .insert(userPermissions)
              .values({ userId: newUser.id, permissionId: pId })
              .onConflictDoNothing();
          }
        }
      }

      await tx.insert(activityLogs).values({
        actorUserId: req.authUser!.id,
        actorName: req.authUser!.fullName,
        actionType: 'CREATE_STAFF',
        entityType: 'USER',
        entityId: newUser.username,
        summary: `Created ${targetRoleName} account ${newUser.fullName} (${newUser.username})`,
      });

      return newUser;
    });

    res.status(201).json({ id: created.id, username: created.username, fullName: created.fullName });
  } catch (err: unknown) {
    if (err instanceof RepoHttpError) {
      return res.status(err.status).json({ error: err.message });
    }
    console.error('Create staff failed:', err);
    res.status(400).json({ error: 'Failed to create staff account (username may already exist).' });
  }
});

apiRouter.put('/staff/:id', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    const userId = Number(req.params.id);
    const { username, fullName, email, phone, isActive, newPassword, permissionCodes } = req.body ?? {};
    if (!Number.isInteger(userId)) return res.status(400).json({ error: 'Invalid user ID.' });
    if (!isPostgresConfigured()) {
      const out = await updateStaffLocal(userId, req.body ?? {}, req.authUser!);
      return res.json(out);
    }

    await db.transaction(async (tx) => {
      const [existing] = await tx.select().from(users).where(eq(users.id, userId)).limit(1);
      if (!existing) throw new RepoHttpError(404, 'Staff user not found.');

      const updates: Partial<typeof users.$inferInsert> = { updatedAt: new Date() };
      if (username && String(username).trim().length >= 3) {
        const cleanU = String(username).trim().toLowerCase();
        const dup = await tx.select({ id: users.id }).from(users).where(eq(users.username, cleanU)).limit(1);
        if (dup.length > 0 && dup[0].id !== userId) {
          throw new RepoHttpError(400, 'Username already in use by another account.');
        }
        updates.username = cleanU;
      }
      if (fullName) updates.fullName = String(fullName).trim();
      if (email !== undefined) updates.email = email ? String(email).trim() : null;
      if (phone !== undefined) updates.phone = phone ? String(phone).trim() : null;
      if (typeof isActive === 'boolean') updates.isActive = isActive;
      if (newPassword !== undefined && String(newPassword).length > 0) {
        if (String(newPassword).length < 6) {
          throw new RepoHttpError(400, 'Password must be at least 6 characters.');
        }
        updates.passwordHash = hashPassword(String(newPassword));
      }

      await tx.update(users).set(updates).where(eq(users.id, userId));

      if (Array.isArray(permissionCodes)) {
        const [userRole] = await tx
          .select({ name: roles.name })
          .from(roles)
          .where(eq(roles.id, existing.roleId))
          .limit(1);
        if (userRole?.name === 'STAFF') {
          await tx.delete(userPermissions).where(eq(userPermissions.userId, userId));
          const allPerms = await tx.select().from(permissions);
          const byCode = new Map(allPerms.map((p) => [p.code, p.id]));
          const allowedCodes = permissionCodes
            .map((c) => String(c))
            .filter((code) => code !== 'members:create' && code !== 'members:delete');
          for (const code of allowedCodes) {
            const pId = byCode.get(code);
            if (pId) {
              await tx
                .insert(userPermissions)
                .values({ userId, permissionId: pId })
                .onConflictDoNothing();
            }
          }
        }
      }

      await tx.insert(activityLogs).values({
        actorUserId: req.authUser!.id,
        actorName: req.authUser!.fullName,
        actionType: 'UPDATE_STAFF',
        entityType: 'USER',
        entityId: updates.username || existing.username,
        summary: `Updated staff credentials/permissions for ${existing.fullName} (${updates.username || existing.username})`,
      });
    });

    res.json({ ok: true });
  } catch (err) {
    return handleRouteError(res, err, 'Failed to update staff account.');
  }
});

