// Admin-Only Offline Synchronization Endpoint (Idempotent & Conflict-Safe)
apiRouter.post('/sync/offline', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    const items = Array.isArray(req.body?.items) ? req.body.items : [];
    if (!isPostgresConfigured()) {
      const out = await syncOfflineItemsLocal(items, req.authUser!);
      return res.json(out);
    }
    const settings = await getSystemSettingsMap();
    const allowPartialPayments = settings.allowPartialPayments === 'true';

    const results: Array<{
      clientTxId: string;
      status: 'SYNCED' | 'DUPLICATE_SKIPPED' | 'CONFLICT';
      message: string;
    }> = [];

    for (const item of items) {
      const clientTxId = String(item.clientTxId || '');
      if (!clientTxId) continue;

      const alreadySynced = await db
        .select()
        .from(offlineSyncQueue)
        .where(eq(offlineSyncQueue.clientTxId, clientTxId))
        .limit(1);

      if (alreadySynced.length > 0) {
        results.push({
          clientTxId,
          status: 'DUPLICATE_SKIPPED',
          message: 'Already synchronized previously (duplicate prevented).',
        });
        continue;
      }

      if (item.operationType === 'CREATE_MEMBER') {
        try {
          const p = item.payload ?? {};
          const feeNum = roundMoney(Number(p.defaultAnnualFee || 1000));
          const joinDate = String(p.joiningDate || new Date().toISOString().slice(0, 10));
          const joinYear = Math.max(START_YEAR, Number(joinDate.slice(0, 4)) || START_YEAR);

          await db.transaction(async (tx) => {
            const memberCode = await generateNextMemberCode(tx, joinYear);

            const [member] = await tx
              .insert(members)
              .values({
                memberCode,
                name: String(p.name),
                guardianName: String(p.guardianName || '-'),
                mobile: String(p.mobile),
                address: String(p.address || '-'),
                joiningDate: joinDate,
                defaultAnnualFee: feeNum.toFixed(2),
                status: 'ACTIVE',
                registrationDate: joinDate,
                createdByUserId: req.authUser!.id,
                clientOfflineId: clientTxId,
              })
              .returning();

            await tx.insert(annualMembershipFees).values({
              memberId: member.id,
              effectiveFromYear: joinYear,
              annualFee: feeNum.toFixed(2),
              notes: 'Offline Admin registration synced',
              setByUserId: req.authUser!.id,
            });

            await tx.insert(yearlyObligations).values({
              memberId: member.id,
              year: joinYear,
              frozenAnnualFee: feeNum.toFixed(2),
              paidTotal: '0.00',
              status: 'UNPAID',
            });

            await tx.insert(offlineSyncQueue).values({
              clientTxId,
              adminUserId: req.authUser!.id,
              operationType: 'CREATE_MEMBER',
              payloadJson: JSON.stringify(p),
              syncStatus: 'SYNCED',
              createdOfflineAt: String(item.createdOfflineAt || new Date().toISOString()),
            });
          });

          results.push({ clientTxId, status: 'SYNCED', message: 'Offline member synced to central database.' });
        } catch (err) {
          const existingAfter = await db
            .select()
            .from(offlineSyncQueue)
            .where(eq(offlineSyncQueue.clientTxId, clientTxId))
            .limit(1);
          if (existingAfter.length > 0) {
            results.push({
              clientTxId,
              status: 'DUPLICATE_SKIPPED',
              message: 'Already synchronized previously (duplicate prevented).',
            });
          } else {
            console.error('Offline member sync conflict:', err);
            await db
              .insert(offlineSyncQueue)
              .values({
                clientTxId,
                adminUserId: req.authUser!.id,
                operationType: 'CREATE_MEMBER',
                payloadJson: JSON.stringify(item.payload ?? {}),
                syncStatus: 'CONFLICT',
                conflictReason: err instanceof Error ? err.message : 'Sync failed',
                createdOfflineAt: String(item.createdOfflineAt || new Date().toISOString()),
              })
              .onConflictDoNothing();
            results.push({ clientTxId, status: 'CONFLICT', message: 'Conflict recorded for review.' });
          }
        }
      } else if (item.operationType === 'RECORD_PAYMENT') {
        try {
          const p = item.payload ?? {};
          let mId = Number(p.memberId);
          if ((mId < 0 || !Number.isInteger(mId)) && p.memberTempClientOfflineId) {
            const [resolvedMember] = await db
              .select({ id: members.id })
              .from(members)
              .where(eq(members.clientOfflineId, String(p.memberTempClientOfflineId)))
              .limit(1);
            if (resolvedMember) {
              mId = resolvedMember.id;
            }
          }
          const yearNum = Number(p.paymentYear);
          const amountNum = Number(p.paidAmount);

          await ensureMemberObligationForYear(mId, yearNum);

          await db.transaction(async (tx) => {
            const [member] = await tx.select().from(members).where(eq(members.id, mId)).limit(1);
            if (!member) throw new Error('Target member not found.');

            const [ob] = await tx
              .select()
              .from(yearlyObligations)
              .where(and(eq(yearlyObligations.memberId, mId), eq(yearlyObligations.year, yearNum)))
              .for('update');

            const validation = validatePaymentAttempt({
              paymentYear: yearNum,
              expectedFee: Number(ob.frozenAnnualFee),
              alreadyPaid: Number(ob.paidTotal),
              attemptAmount: amountNum,
              allowPartialPayments,
            });

            if (!validation.ok) {
              throw new Error(validation.error);
            }

            const receiptNumber = await generateNextReceiptNumber(tx, yearNum);
            const dateStr = String(p.paymentDate || new Date().toISOString().slice(0, 10));

            const [pay] = await tx
              .insert(payments)
              .values({
                obligationId: ob.id,
                memberId: mId,
                paymentYear: yearNum,
                expectedFee: Number(ob.frozenAnnualFee).toFixed(2),
                paidAmount: roundMoney(amountNum).toFixed(2),
                dueAfterPayment: validation.dueAfterPayment.toFixed(2),
                paymentDate: dateStr,
                paymentMonth: dateStr.slice(0, 7),
                paymentTime: String(p.paymentTime || '12:00:00'),
                paymentMethod: String(p.paymentMethod || 'Cash'),
                receiptNumber,
                receivedByUserId: req.authUser!.id,
                notes: p.notes ? `${p.notes} [Offline Synced]` : '[Offline Synced]',
                clientTxId,
                isSyncedFromOffline: true,
              })
              .returning();

            await tx
              .update(yearlyObligations)
              .set({
                paidTotal: validation.newPaidTotal.toFixed(2),
                status: validation.status,
                updatedAt: new Date(),
              })
              .where(eq(yearlyObligations.id, ob.id));

            await tx.insert(receipts).values({
              paymentId: pay.id,
              receiptNumber,
              memberCode: member.memberCode,
              issuedToName: member.name,
              paymentYear: yearNum,
              amountPaid: roundMoney(amountNum).toFixed(2),
              remainingDue: validation.dueAfterPayment.toFixed(2),
              issuedByName: req.authUser!.fullName,
              verificationHash: sha256Hex(`${receiptNumber}:${clientTxId}`).slice(0, 16),
            });

            await tx.insert(offlineSyncQueue).values({
              clientTxId,
              adminUserId: req.authUser!.id,
              operationType: 'RECORD_PAYMENT',
              payloadJson: JSON.stringify(p),
              syncStatus: 'SYNCED',
              createdOfflineAt: String(item.createdOfflineAt || new Date().toISOString()),
            });
          });

          results.push({ clientTxId, status: 'SYNCED', message: 'Offline payment synced cleanly.' });
        } catch (err) {
          const existingAfter = await db
            .select()
            .from(offlineSyncQueue)
            .where(eq(offlineSyncQueue.clientTxId, clientTxId))
            .limit(1);
          if (existingAfter.length > 0) {
            results.push({
              clientTxId,
              status: 'DUPLICATE_SKIPPED',
              message: 'Already synchronized previously (duplicate prevented).',
            });
          } else {
            const reason = err instanceof Error ? err.message : 'Payment sync conflict';
            await db
              .insert(offlineSyncQueue)
              .values({
                clientTxId,
                adminUserId: req.authUser!.id,
                operationType: 'RECORD_PAYMENT',
                payloadJson: JSON.stringify(item.payload ?? {}),
                syncStatus: 'CONFLICT',
                conflictReason: reason,
                createdOfflineAt: String(item.createdOfflineAt || new Date().toISOString()),
              })
              .onConflictDoNothing();
            results.push({ clientTxId, status: 'CONFLICT', message: reason });
          }
        }
      } else if (item.operationType === 'UPDATE_MEMBER') {
        try {
          const p = (item.payload ?? {}) as Record<string, unknown>;
          let mId = Number(p.memberId);
          if ((mId < 0 || !Number.isInteger(mId)) && p.memberTempClientOfflineId) {
            const [resolvedMember] = await db
              .select({ id: members.id })
              .from(members)
              .where(eq(members.clientOfflineId, String(p.memberTempClientOfflineId)))
              .limit(1);
            if (resolvedMember) mId = resolvedMember.id;
          }
          await db.transaction(async (tx) => {
            const existing = await tx.select().from(members).where(eq(members.id, mId)).limit(1);
            if (existing.length === 0) throw new Error('Target member not found.');
            const updateFields: Partial<typeof members.$inferInsert> = { updatedAt: new Date() };
            if (p.name) updateFields.name = String(p.name).trim();
            if (p.guardianName) updateFields.guardianName = String(p.guardianName).trim();
            if (p.mobile) updateFields.mobile = String(p.mobile).trim();
            if (p.address) updateFields.address = String(p.address).trim();
            if (p.status === 'ACTIVE' || p.status === 'INACTIVE') updateFields.status = p.status;
            if (p.newAnnualFee !== undefined && Number(p.newAnnualFee) > 0) {
              const feeVal = roundMoney(Number(p.newAnnualFee));
              const effYear = Math.max(START_YEAR, Number(p.effectiveFromYear || new Date().getFullYear()));
              updateFields.defaultAnnualFee = feeVal.toFixed(2);
              await tx
                .insert(annualMembershipFees)
                .values({
                  memberId: mId,
                  effectiveFromYear: effYear,
                  annualFee: feeVal.toFixed(2),
                  notes: `Offline edit fee from ${effYear}`,
                  setByUserId: req.authUser!.id,
                })
                .onConflictDoUpdate({
                  target: [annualMembershipFees.memberId, annualMembershipFees.effectiveFromYear],
                  set: {
                    annualFee: feeVal.toFixed(2),
                    notes: `Offline edit fee from ${effYear}`,
                    setByUserId: req.authUser!.id,
                  },
                });
            }
            await tx.update(members).set(updateFields).where(eq(members.id, mId));
            await tx.insert(offlineSyncQueue).values({
              clientTxId,
              adminUserId: req.authUser!.id,
              operationType: 'UPDATE_MEMBER',
              payloadJson: JSON.stringify(p),
              syncStatus: 'SYNCED',
              createdOfflineAt: String(item.createdOfflineAt || new Date().toISOString()),
            });
          });
          results.push({ clientTxId, status: 'SYNCED', message: 'Offline member update synced.' });
        } catch (err) {
          const reason = err instanceof Error ? err.message : 'Member update conflict';
          await db
            .insert(offlineSyncQueue)
            .values({
              clientTxId,
              adminUserId: req.authUser!.id,
              operationType: 'UPDATE_MEMBER',
              payloadJson: JSON.stringify(item.payload ?? {}),
              syncStatus: 'CONFLICT',
              conflictReason: reason,
              createdOfflineAt: String(item.createdOfflineAt || new Date().toISOString()),
            })
            .onConflictDoNothing();
          results.push({ clientTxId, status: 'CONFLICT', message: reason });
        }
      } else if (item.operationType === 'DELETE_MEMBER') {
        try {
          const p = (item.payload ?? {}) as Record<string, unknown>;
          let mId = Number(p.memberId);
          if ((mId < 0 || !Number.isInteger(mId)) && p.memberTempClientOfflineId) {
            const [resolvedMember] = await db
              .select({ id: members.id })
              .from(members)
              .where(eq(members.clientOfflineId, String(p.memberTempClientOfflineId)))
              .limit(1);
            if (resolvedMember) mId = resolvedMember.id;
          }
          await db.transaction(async (tx) => {
            if (Number.isInteger(mId) && mId > 0) {
              await tx.delete(members).where(eq(members.id, mId));
            }
            await tx.insert(offlineSyncQueue).values({
              clientTxId,
              adminUserId: req.authUser!.id,
              operationType: 'DELETE_MEMBER',
              payloadJson: JSON.stringify(p),
              syncStatus: 'SYNCED',
              createdOfflineAt: String(item.createdOfflineAt || new Date().toISOString()),
            });
          });
          results.push({ clientTxId, status: 'SYNCED', message: 'Offline member deletion synced.' });
        } catch (err) {
          const reason = err instanceof Error ? err.message : 'Member delete conflict';
          results.push({ clientTxId, status: 'CONFLICT', message: reason });
        }
      } else if (item.operationType === 'CREATE_NOTICE') {
        try {
          await ensurePgPublicNoticesTable();
          const p = (item.payload ?? {}) as Record<string, unknown>;
          const rawType = String(p.noticeType || 'NOTICE').toUpperCase();
          const noticeType = rawType === 'PUBLIC_POST' || rawType === 'EVENT' ? rawType : 'NOTICE';
          await db.transaction(async (tx) => {
            const dup = await tx
              .select({ id: publicNotices.id })
              .from(publicNotices)
              .where(eq(publicNotices.clientOfflineId, clientTxId))
              .limit(1);
            if (dup.length === 0) {
              await tx.insert(publicNotices).values({
                title: String(p.title || 'Offline Notice').slice(0, 240),
                content: String(p.content || ''),
                noticeType,
                imageDataUrl: p.imageDataUrl ? String(p.imageDataUrl) : null,
                attachmentDataUrl: p.attachmentDataUrl ? String(p.attachmentDataUrl) : null,
                attachmentName: p.attachmentName ? String(p.attachmentName).slice(0, 180) : null,
                attachmentMime: p.attachmentMime ? String(p.attachmentMime).slice(0, 120) : null,
                isPinned: p.isPinned === undefined ? true : Boolean(p.isPinned),
                isPublished: p.isPublished === undefined ? true : Boolean(p.isPublished),
                createdByUserId: req.authUser!.id,
                createdByName: req.authUser!.fullName || 'Farhan Gazi Admin',
                clientOfflineId: clientTxId,
              });
            }
            await tx.insert(offlineSyncQueue).values({
              clientTxId,
              adminUserId: req.authUser!.id,
              operationType: 'CREATE_NOTICE',
              payloadJson: JSON.stringify({ title: p.title, noticeType }),
              syncStatus: 'SYNCED',
              createdOfflineAt: String(item.createdOfflineAt || new Date().toISOString()),
            });
          });
          results.push({ clientTxId, status: 'SYNCED', message: 'Offline notice synced online.' });
        } catch (err) {
          const reason = err instanceof Error ? err.message : 'Notice sync failed';
          results.push({ clientTxId, status: 'CONFLICT', message: reason });
        }
      } else if (item.operationType === 'UPDATE_NOTICE') {
        try {
          await ensurePgPublicNoticesTable();
          const p = (item.payload ?? {}) as Record<string, unknown>;
          let nId = Number(p.noticeId);
          if ((nId < 0 || !Number.isInteger(nId)) && p.noticeTempClientOfflineId) {
            const [linked] = await db
              .select({ id: publicNotices.id })
              .from(publicNotices)
              .where(eq(publicNotices.clientOfflineId, String(p.noticeTempClientOfflineId)))
              .limit(1);
            if (linked) nId = linked.id;
          }
          await db.transaction(async (tx) => {
            const updates: Partial<typeof publicNotices.$inferInsert> = { updatedAt: new Date() };
            if (p.title !== undefined) updates.title = String(p.title).trim().slice(0, 240);
            if (p.content !== undefined) updates.content = String(p.content).trim();
            if (p.noticeType !== undefined) {
              const nt = String(p.noticeType).toUpperCase();
              updates.noticeType = nt === 'PUBLIC_POST' || nt === 'EVENT' ? nt : 'NOTICE';
            }
            if (p.isPinned !== undefined) updates.isPinned = Boolean(p.isPinned);
            if (p.isPublished !== undefined) updates.isPublished = Boolean(p.isPublished);
            if ('imageDataUrl' in p) updates.imageDataUrl = p.imageDataUrl ? String(p.imageDataUrl) : null;
            if ('attachmentDataUrl' in p) {
              updates.attachmentDataUrl = p.attachmentDataUrl ? String(p.attachmentDataUrl) : null;
              updates.attachmentName = p.attachmentName ? String(p.attachmentName).slice(0, 180) : null;
              updates.attachmentMime = p.attachmentMime ? String(p.attachmentMime).slice(0, 120) : null;
            }
            if (Number.isInteger(nId) && nId > 0) {
              await tx.update(publicNotices).set(updates).where(eq(publicNotices.id, nId));
            }
            await tx.insert(offlineSyncQueue).values({
              clientTxId,
              adminUserId: req.authUser!.id,
              operationType: 'UPDATE_NOTICE',
              payloadJson: JSON.stringify({ noticeId: nId }),
              syncStatus: 'SYNCED',
              createdOfflineAt: String(item.createdOfflineAt || new Date().toISOString()),
            });
          });
          results.push({ clientTxId, status: 'SYNCED', message: 'Offline notice update synced.' });
        } catch (err) {
          const reason = err instanceof Error ? err.message : 'Notice update conflict';
          results.push({ clientTxId, status: 'CONFLICT', message: reason });
        }
      } else if (item.operationType === 'DELETE_NOTICE') {
        try {
          await ensurePgPublicNoticesTable();
          const p = (item.payload ?? {}) as Record<string, unknown>;
          let nId = Number(p.noticeId);
          if ((nId < 0 || !Number.isInteger(nId)) && p.noticeTempClientOfflineId) {
            const [linked] = await db
              .select({ id: publicNotices.id })
              .from(publicNotices)
              .where(eq(publicNotices.clientOfflineId, String(p.noticeTempClientOfflineId)))
              .limit(1);
            if (linked) nId = linked.id;
          }
          await db.transaction(async (tx) => {
            if (Number.isInteger(nId) && nId > 0) {
              await tx.delete(publicNotices).where(eq(publicNotices.id, nId));
            }
            await tx.insert(offlineSyncQueue).values({
              clientTxId,
              adminUserId: req.authUser!.id,
              operationType: 'DELETE_NOTICE',
              payloadJson: JSON.stringify({ noticeId: nId }),
              syncStatus: 'SYNCED',
              createdOfflineAt: String(item.createdOfflineAt || new Date().toISOString()),
            });
          });
          results.push({ clientTxId, status: 'SYNCED', message: 'Offline notice delete synced.' });
        } catch (err) {
          const reason = err instanceof Error ? err.message : 'Notice delete conflict';
          results.push({ clientTxId, status: 'CONFLICT', message: reason });
        }
      }
    }

    if (results.length > 0) {
      await logActivity({
        actorUserId: req.authUser!.id,
        actorName: req.authUser!.fullName,
        actionType: 'OFFLINE_SYNC',
        entityType: 'SYNC',
        entityId: String(results.length),
        summary: `Synchronized ${results.filter((r) => r.status === 'SYNCED').length}/${results.length} offline Admin records`,
      });
    }

    res.json({ results });
  } catch (err) {
    console.error('Offline sync failed:', err);
    res.status(500).json({ error: 'Offline synchronization failed.' });
  }
});

