apiRouter.post('/backups/create', requireAuth, requirePermission('backup:manage'), async (req: AuthRequest, res) => {
  try {
    const { backupType, targetLocation, passphrase } = req.body ?? {};
    if (!isPostgresConfigured()) {
      const out = await createBackupLocal({ backupType, targetLocation, passphrase }, req.authUser!);
      return res.json(out);
    }
    await ensurePgPublicNoticesTable();
    const snapshot = {
      exportedAt: new Date().toISOString(),
      organization: 'Saidpur kudduchiyya madrasah',
      members: await db.select().from(members),
      annualMembershipFees: await db.select().from(annualMembershipFees),
      yearlyObligations: await db.select().from(yearlyObligations),
      payments: await db.select().from(payments),
      paymentCorrections: await db.select().from(paymentCorrections),
      receipts: await db.select().from(receipts),
      systemSettings: await db.select().from(systemSettings),
      publicNotices: await db.select().from(publicNotices),
    };

    const recordCount =
      snapshot.members.length +
      snapshot.yearlyObligations.length +
      snapshot.payments.length +
      snapshot.paymentCorrections.length +
      snapshot.publicNotices.length;

    const encrypted = encryptBackupPayload(snapshot, recordCount, passphrase);
    const serialized = JSON.stringify(encrypted, null, 2);

    const [entry] = await db
      .insert(backupHistory)
      .values({
        backupType: String(backupType || 'MANUAL'),
        targetLocation: String(targetLocation || 'Cloud Encrypted Download'),
        encryptionAlg: encrypted.algorithm,
        checksumSha256: encrypted.checksumSha256,
        recordCount,
        fileSizeBytes: Buffer.byteLength(serialized, 'utf8'),
        status: 'VERIFIED',
        createdByUserId: req.authUser!.id,
      })
      .returning();

    await logActivity({
      actorUserId: req.authUser!.id,
      actorName: req.authUser!.fullName,
      actionType: 'CREATE_BACKUP',
      entityType: 'BACKUP',
      entityId: String(entry.id),
      summary: `Created encrypted ${entry.backupType} backup (${recordCount} records) -> ${entry.targetLocation}`,
    });

    res.json({ backupRecord: entry, encryptedEnvelope: encrypted });
  } catch (err) {
    console.error('Backup creation failed:', err);
    res.status(500).json({ error: 'Failed to create encrypted backup.' });
  }
});

apiRouter.post('/backups/verify-restore', requireAuth, requireAdmin, async (req: AuthRequest, res) => {
  try {
    const { envelope, passphrase, confirmRestore } = req.body ?? {};
    if (!envelope) {
      return res.status(400).json({ error: 'Encrypted backup file payload is required.' });
    }
    if (!isPostgresConfigured()) {
      const out = await verifyOrRestoreBackupLocal(
        { envelope, passphrase, confirmRestore },
        req.authUser!
      );
      return res.json(out);
    }

    const decrypted = decryptBackupPayload<{
      exportedAt: string;
      organization: string;
      members: Array<typeof members.$inferSelect>;
      annualMembershipFees: Array<typeof annualMembershipFees.$inferSelect>;
      yearlyObligations: Array<typeof yearlyObligations.$inferSelect>;
      payments: Array<typeof payments.$inferSelect>;
      paymentCorrections: Array<typeof paymentCorrections.$inferSelect>;
      receipts: Array<typeof receipts.$inferSelect>;
      systemSettings: Array<typeof systemSettings.$inferSelect>;
      publicNotices?: Array<typeof publicNotices.$inferSelect>;
    }>(envelope, passphrase);

    const summary = {
      verified: true,
      exportedAt: decrypted.exportedAt,
      organization: decrypted.organization,
      counts: {
        members: decrypted.members?.length ?? 0,
        obligations: decrypted.yearlyObligations?.length ?? 0,
        payments: decrypted.payments?.length ?? 0,
        corrections: decrypted.paymentCorrections?.length ?? 0,
        notices: decrypted.publicNotices?.length ?? 0,
      },
    };

    if (!confirmRestore) {
      return res.json({ mode: 'VERIFIED_PREVIEW', ...summary });
    }

    await ensurePgPublicNoticesTable();

    // Verified transactional restore (merges missing records cleanly without destroying users)
    await db.transaction(async (tx) => {
      for (const s of decrypted.systemSettings || []) {
        await tx
          .insert(systemSettings)
          .values({ key: s.key, value: s.value, updatedAt: new Date() })
          .onConflictDoUpdate({
            target: systemSettings.key,
            set: { value: s.value, updatedAt: new Date() },
          });
      }
      for (const m of decrypted.members || []) {
        await tx
          .insert(members)
          .values({
            ...m,
            createdAt: new Date(m.createdAt),
            updatedAt: new Date(m.updatedAt),
          })
          .onConflictDoNothing();
      }
      for (const f of decrypted.annualMembershipFees || []) {
        await tx
          .insert(annualMembershipFees)
          .values({
            ...f,
            createdAt: new Date(f.createdAt),
          })
          .onConflictDoNothing();
      }
      for (const o of decrypted.yearlyObligations || []) {
        await tx
          .insert(yearlyObligations)
          .values({
            ...o,
            createdAt: new Date(o.createdAt),
            updatedAt: new Date(o.updatedAt),
          })
          .onConflictDoNothing();
      }
      for (const p of decrypted.payments || []) {
        await tx
          .insert(payments)
          .values({
            ...p,
            createdAt: new Date(p.createdAt),
            updatedAt: new Date(p.updatedAt),
          })
          .onConflictDoNothing();
      }
      for (const c of decrypted.paymentCorrections || []) {
        await tx
          .insert(paymentCorrections)
          .values({
            ...c,
            correctedAt: new Date(c.correctedAt),
          })
          .onConflictDoNothing();
      }
      for (const r of decrypted.receipts || []) {
        await tx
          .insert(receipts)
          .values({
            ...r,
            issuedAt: new Date(r.issuedAt),
          })
          .onConflictDoNothing();
      }
      for (const n of decrypted.publicNotices || []) {
        await tx
          .insert(publicNotices)
          .values({
            ...n,
            createdAt: new Date(n.createdAt),
            updatedAt: new Date(n.updatedAt),
          })
          .onConflictDoNothing();
      }
    });

    await logActivity({
      actorUserId: req.authUser!.id,
      actorName: req.authUser!.fullName,
      actionType: 'RESTORE_BACKUP',
      entityType: 'BACKUP',
      entityId: String(envelope.checksumSha256 || '').slice(0, 12),
      summary: `Restored verified backup (${summary.counts.members} members, ${summary.counts.payments} payments)`,
    });

    res.json({ mode: 'RESTORED', ...summary });
  } catch (err) {
    console.error('Backup restore failed:', err);
    res.status(400).json({
      error: err instanceof Error ? err.message : 'Backup decryption or verification failed.',
    });
  }
});

