async function runSeed(): Promise<void> {
  if (!isPostgresConfigured()) {
    await localStore.ensureReady();
    return;
  }

  // 1. Seed Roles
  const roleCountRes = await db.select({ count: sql<number>`count(*)::int` }).from(roles);
  if ((roleCountRes[0]?.count ?? 0) === 0) {
    await db
      .insert(roles)
      .values([
        { name: 'ADMIN', description: 'Full Madrasa System Administrator' },
        { name: 'STAFF', description: 'Permission-Controlled Madrasa Staff Member' },
      ])
      .onConflictDoNothing();
  }

  // 2. Seed Permissions
  for (const p of PERMISSION_DEFS) {
    await db
      .insert(permissions)
      .values(p)
      .onConflictDoUpdate({
        target: permissions.code,
        set: { label: p.label, labelBn: p.labelBn },
      });
  }

  // 3. Seed System Settings
  const defaultSettings = [
    { key: 'allowPartialPayments', value: 'true' },
    { key: 'autoBackupEnabled', value: 'true' },
    { key: 'autoBackupIntervalHours', value: '24' },
    { key: 'currentActiveYear', value: String(START_YEAR) },
  ];
  for (const s of defaultSettings) {
    await db.insert(systemSettings).values(s).onConflictDoNothing();
  }

  const allRoles = await db.select().from(roles);
  const adminRole = allRoles.find((r) => r.name === 'ADMIN');
  const staffRole = allRoles.find((r) => r.name === 'STAFF');
  if (!adminRole || !staffRole) return;

  const allPerms = await db.select().from(permissions);
  const permByCode = new Map(allPerms.map((p) => [p.code, p.id]));

  // 4. Seed Admin + 22 Staff Accounts (> 20 staff capacity requirement)
  const existingUsers = await db.select({ count: sql<number>`count(*)::int` }).from(users);
  if ((existingUsers[0]?.count ?? 0) === 0) {
    const [adminUser] = await db
      .insert(users)
      .values({
        username: 'admin',
        passwordHash: hashPassword('Admin@1986'),
        fullName: 'Farhan Gazi Admin',
        email: ADMIN_DEFAULT_EMAIL,
        phone: ADMIN_DEFAULT_PHONE,
        roleId: adminRole.id,
        isActive: true,
        canOfflineEntry: true,
      })
      .returning();

    const defaultStaffPermCodes = ['members:view', 'members:edit', 'payments:view', 'payments:create'];
    const collectorPermCodes = ['members:view', 'members:edit', 'payments:view', 'payments:create', 'reports:view'];

    for (let i = 0; i < STAFF_NAMES.length; i++) {
      const num = String(i + 1).padStart(2, '0');
      const [staffUser] = await db
        .insert(users)
        .values({
          username: `staff${num}`,
          passwordHash: hashPassword('Staff@1986'),
          fullName: STAFF_NAMES[i],
          email: `staff${num}@syedpurmadrasa.org`,
          phone: `017000010${num}`,
          roleId: staffRole.id,
          isActive: true,
          canOfflineEntry: false,
        })
        .returning();

      const codes = i % 2 === 0 ? defaultStaffPermCodes : collectorPermCodes;
      for (const code of codes) {
        const permId = permByCode.get(code);
        if (permId) {
          await db
            .insert(userPermissions)
            .values({ userId: staffUser.id, permissionId: permId })
            .onConflictDoNothing();
        }
      }
    }

    // 5. Seed initial Madrasa members if table is empty
    const memberCountRes = await db.select({ count: sql<number>`count(*)::int` }).from(members);
    if ((memberCountRes[0]?.count ?? 0) === 0) {
      let paidReceiptSeq = 0;
      for (let idx = 0; idx < INITIAL_MEMBERS.length; idx++) {
        const item = INITIAL_MEMBERS[idx];
        const code = formatMemberCode(idx + 1, START_YEAR);
        const [member] = await db
          .insert(members)
          .values({
            memberCode: code,
            name: item.name,
            guardianName: item.guardianName,
            mobile: item.mobile,
            address: item.address,
            joiningDate: item.joiningDate,
            defaultAnnualFee: item.defaultAnnualFee.toFixed(2),
            status: 'ACTIVE',
            registrationDate: item.joiningDate,
            createdByUserId: adminUser.id,
          })
          .returning();

        await db.insert(annualMembershipFees).values({
          memberId: member.id,
          effectiveFromYear: START_YEAR,
          annualFee: item.defaultAnnualFee.toFixed(2),
          notes: 'Initial individual annual fee',
          setByUserId: adminUser.id,
        });

        const state2026 = computeObligationState(item.defaultAnnualFee, item.paid2026);
        const [ob2026] = await db
          .insert(yearlyObligations)
          .values({
            memberId: member.id,
            year: START_YEAR,
            frozenAnnualFee: item.defaultAnnualFee.toFixed(2),
            paidTotal: item.paid2026.toFixed(2),
            status: state2026.status,
          })
          .returning();

        // Also ensure 2027 obligation is pre-initialized automatically
        await db.insert(yearlyObligations).values({
          memberId: member.id,
          year: START_YEAR + 1,
          frozenAnnualFee: item.defaultAnnualFee.toFixed(2),
          paidTotal: '0.00',
          status: 'UNPAID',
