        if (item.paid2026 > 0) {
          paidReceiptSeq += 1;
          const receiptNum = formatReceiptNumber(START_YEAR, paidReceiptSeq);
          const [payment] = await db
            .insert(payments)
            .values({
              obligationId: ob2026.id,
              memberId: member.id,
              paymentYear: START_YEAR,
              expectedFee: item.defaultAnnualFee.toFixed(2),
              paidAmount: item.paid2026.toFixed(2),
              dueAfterPayment: state2026.dueAmount.toFixed(2),
              paymentDate: item.joiningDate,
              paymentMonth: item.joiningDate.slice(0, 7),
              paymentTime: '10:30:00',
              paymentMethod: item.method,
              receiptNumber: receiptNum,
              receivedByUserId: adminUser.id,
              notes: 'Membership contribution 2026',
            })
            .returning();

          await db.insert(receipts).values({
            paymentId: payment.id,
            receiptNumber: receiptNum,
            memberCode: member.memberCode,
            issuedToName: member.name,
            paymentYear: START_YEAR,
            amountPaid: item.paid2026.toFixed(2),
            remainingDue: state2026.dueAmount.toFixed(2),
            issuedByName: adminUser.fullName,
            verificationHash: `SKM-${receiptNum}-${member.memberCode}`,
          });
        }
      }

      await db.insert(activityLogs).values({
        actorUserId: adminUser.id,
        actorName: adminUser.fullName,
        actionType: 'SYSTEM_INIT',
        entityType: 'SYSTEM',
        entityId: 'SKM-2026',
        summary: 'Initialized Saidpur kudduchiyya madrasah Membership System (2026+) with 22 staff accounts',
      });
    }
  }

  // 6. One-time idempotent normalization: convert legacy RCP-XXXX-XXXXX receipts to simple 1, 2, 3... IDs
  const legacyPayments = await db
    .select({ id: payments.id, receiptNumber: payments.receiptNumber })
    .from(payments)
    .where(sql`${payments.receiptNumber} LIKE 'RCP-%'`)
    .orderBy(payments.id);

  if (legacyPayments.length > 0) {
    await db.transaction(async (tx) => {
      const [maxNumericRow] = await tx
        .select({
          maxSeq: sql<number>`coalesce(max(case when ${payments.receiptNumber} ~ '^[0-9]+$' then ${payments.receiptNumber}::int else 0 end), 0)::int`,
        })
        .from(payments);

      let nextNum = (maxNumericRow?.maxSeq ?? 0) + 1;
      for (const lp of legacyPayments) {
        const newReceiptNo = String(nextNum++);
        await tx
          .update(payments)
          .set({ receiptNumber: newReceiptNo })
          .where(eq(payments.id, lp.id));
        await tx
          .update(receipts)
          .set({ receiptNumber: newReceiptNo })
          .where(eq(receipts.paymentId, lp.id));
        await tx
          .update(activityLogs)
          .set({ entityId: newReceiptNo })
          .where(sql`${activityLogs.entityType} = 'PAYMENT' AND ${activityLogs.entityId} = ${lp.receiptNumber}`);
      }
    });
  }

  // 7. One-time idempotent normalization: convert legacy SKM-XXXX-XXXX codes to SKM 1, SKM 2...
  const legacyMembers = await db
    .select({ id: members.id, memberCode: members.memberCode })
    .from(members)
    .where(sql`${members.memberCode} LIKE 'SKM-%'`)
    .orderBy(members.id);

  if (legacyMembers.length > 0) {
    await db.transaction(async (tx) => {
      const [maxSkmRow] = await tx
        .select({
          maxSeq: sql<number>`coalesce(max(case when ${members.memberCode} ~ '^SKM [0-9]+$' then substring(${members.memberCode} from '^SKM ([0-9]+)$')::int else 0 end), 0)::int`,
        })
        .from(members);

      let nextNum = (maxSkmRow?.maxSeq ?? 0) + 1;
      for (const lm of legacyMembers) {
        const newCode = `SKM ${nextNum++}`;
        await tx
          .update(members)
          .set({ memberCode: newCode })
          .where(eq(members.id, lm.id));
        await tx
          .update(receipts)
          .set({ memberCode: newCode })
          .where(eq(receipts.memberCode, lm.memberCode));
        await tx
          .update(activityLogs)
          .set({ entityId: newCode })
          .where(sql`${activityLogs.entityType} = 'MEMBER' AND ${activityLogs.entityId} = ${lm.memberCode}`);
      }
    });
  }

  // 8. Enforce Partner (STAFF) permission rules idempotently:
  // Partners CANNOT create or delete members; they CAN view/edit member info & annual fees and collect payments.
  const staffUsers = await db
    .select({ id: users.id })
    .from(users)
    .where(eq(users.roleId, staffRole.id));

  if (staffUsers.length > 0) {
    const staffIds = staffUsers.map((u) => u.id);
    const restrictedPermIds = ['members:create', 'members:delete']
      .map((code) => permByCode.get(code))
      .filter((id): id is number => typeof id === 'number');

    if (restrictedPermIds.length > 0) {
      await db
        .delete(userPermissions)
        .where(
          and(
            inArray(userPermissions.userId, staffIds),
            inArray(userPermissions.permissionId, restrictedPermIds)
          )
        );
    }

    const requiredPartnerCodes = ['members:view', 'members:edit', 'payments:view', 'payments:create'];
    for (const su of staffUsers) {
      for (const code of requiredPartnerCodes) {
        const pId = permByCode.get(code);
        if (pId) {
          await db
            .insert(userPermissions)
            .values({ userId: su.id, permissionId: pId })
            .onConflictDoNothing();
        }
      }
    }
  }

  // 9. Idempotently ensure primary Admin name ('Farhan Gazi Admin'), phone & email reflect configured defaults
  const adminUsers = await db
    .select()
    .from(users)
    .where(eq(users.roleId, adminRole.id));
  for (const au of adminUsers) {
    const nextFullName =
      !au.fullName || au.fullName === 'Madrasa Principal & Admin' ? 'Farhan Gazi Admin' : au.fullName;
    const nextEmail =
      !au.email || au.email === 'rasidg713@gmail.com' ? ADMIN_DEFAULT_EMAIL : au.email;
    const nextPhone =
      !au.phone || au.phone === '01700001986' ? ADMIN_DEFAULT_PHONE : au.phone;
    if (nextFullName !== au.fullName || nextEmail !== au.email || nextPhone !== au.phone) {
      await db
        .update(users)
        .set({ fullName: nextFullName, email: nextEmail, phone: nextPhone, updatedAt: new Date() })
        .where(eq(users.id, au.id));
    }
  }
  await db
    .update(receipts)
    .set({ issuedByName: 'Farhan Gazi Admin' })
    .where(eq(receipts.issuedByName, 'Madrasa Principal & Admin'));
}

export async function ensureSeeded(): Promise<void> {
  if (!seedPromise) {
    seedPromise = runSeed().catch((err) => {
      seedPromise = null;
      throw err;
    });
  }
  return seedPromise;
}

