test('Admin and Staff 2-step Gmail OTP never exposes previewOtp, routes placeholder staff emails to Admin Gmail, verifies valid 6-digit code, locks after 5 attempts, and blocks replay', async () => {
  assert.equal(resolveOtpEmailForUser('staff01@syedpurmadrasa.org', ADMIN_DEFAULT_EMAIL), ADMIN_DEFAULT_EMAIL);
  assert.equal(resolveOtpEmailForUser(null, ADMIN_DEFAULT_EMAIL), ADMIN_DEFAULT_EMAIL);
  assert.equal(resolveOtpEmailForUser('staff.personal@gmail.com', ADMIN_DEFAULT_EMAIL), 'staff.personal@gmail.com');

  const admin = await findUserForLoginLocal('admin');
  const staff01 = await findUserForLoginLocal('staff01');
  assert.ok(admin);
  assert.ok(staff01);

  let capturedOtp = '';
  setOtpTestObserver(({ otp }) => {
    capturedOtp = otp;
  });

  try {
    const ch1 = await issueAdminOtpChallenge({
      userId: admin.id,
      username: admin.username,
      phone: admin.phone || ADMIN_DEFAULT_PHONE,
      email: resolveOtpEmailForUser(admin.email, ADMIN_DEFAULT_EMAIL),
    });
    assert.equal(ch1.requiresOtp, true);
    assert.equal(ch1.maskedPhone, '******3198');
    assert.equal(ch1.maskedEmail, 'fa******@gmail.com');
    assert.equal('previewOtp' in ch1, false);
    assert.match(capturedOtp, /^\d{6}$/);
    const otp1 = capturedOtp;

    // Staff login OTP challenge
    const chStaff = await issueAdminOtpChallenge({
      userId: staff01.id,
      username: staff01.username,
      phone: '',
      email: resolveOtpEmailForUser(staff01.email, ADMIN_DEFAULT_EMAIL),
    });
    assert.equal(chStaff.requiresOtp, true);
    assert.equal(chStaff.maskedEmail, 'fa******@gmail.com');
    assert.equal('previewOtp' in chStaff, false);
    const staffOtp = capturedOtp;
    const goodStaff = verifyAdminOtpChallenge(chStaff.challengeToken, staffOtp);
    assert.equal(goodStaff.ok, true);
    if (goodStaff.ok) {
      assert.equal(goodStaff.userId, staff01.id);
    }

    // Wrong OTP attempt
    const wrongOtp1 = otp1 === '000000' ? '111111' : '000000';
    const bad = verifyAdminOtpChallenge(ch1.challengeToken, wrongOtp1);
    assert.equal(bad.ok, false);
    if (!bad.ok) assert.equal(bad.status, 401);

    // Verify valid OTP
    const good = verifyAdminOtpChallenge(ch1.challengeToken, otp1);
    assert.equal(good.ok, true);
    if (good.ok) {
      assert.equal(good.userId, admin.id);
      const jwt = signSessionToken(good.userId, good.username);
      assert.deepEqual(verifySessionToken(jwt), { sub: admin.id, username: admin.username });
    }

    // Replay attempt must fail
    const replay = verifyAdminOtpChallenge(ch1.challengeToken, otp1);
    assert.equal(replay.ok, false);

    // Brute-force lock after 5 bad attempts
    const ch2 = await issueAdminOtpChallenge({
      userId: admin.id,
      username: admin.username,
      phone: admin.phone || ADMIN_DEFAULT_PHONE,
      email: admin.email || ADMIN_DEFAULT_EMAIL,
    });
    assert.equal('previewOtp' in ch2, false);
    const wrongOtp2 = capturedOtp === '111111' ? '222222' : '111111';
    let lockedStatus = 0;
    for (let i = 0; i < 5; i++) {
      const attempt = verifyAdminOtpChallenge(ch2.challengeToken, wrongOtp2);
      assert.equal(attempt.ok, false);
      if (!attempt.ok) lockedStatus = attempt.status;
    }
    assert.equal(lockedStatus, 429);
  } finally {
    setOtpTestObserver(null);
  }
});

