  assert.equal(y2026?.frozenAnnualFee, 1000);
  assert.equal(y2027?.frozenAnnualFee, 1500);

  // Multi-year combined payment (1000 for 2026 + 500 partial for 2027 = 1500)
  const payRes = await recordPaymentLocal(
