  const sync1 = await syncOfflineItemsLocal(
    [
      {
        clientTxId: txId,
        operationType: 'RECORD_PAYMENT',
        createdOfflineAt: new Date().toISOString(),
        payload: {
          memberId: created.member.id,
          paymentYear: 2027,
          paidAmount: 300,
          paymentMethod: 'Cash',
          includePreviousDues: false,
        },
      },
    ],
    { id: admin.id, fullName: admin.fullName }
  );
  assert.equal(sync1.results[0].status, 'SYNCED');

  const sync2 = await syncOfflineItemsLocal(
    [
      {
        clientTxId: txId,
        operationType: 'RECORD_PAYMENT',
        createdOfflineAt: new Date().toISOString(),
        payload: { memberId: created.member.id, paymentYear: 2027, paidAmount: 300 },
      },
    ],
    { id: admin.id, fullName: admin.fullName }
  );
  assert.equal(sync2.results[0].status, 'DUPLICATE_SKIPPED');

  // Encrypted AES-256-GCM Backup & Verify Preview + Wrong Passphrase rejection
  const backup = await createBackupLocal(
    { backupType: 'MANUAL', targetLocation: 'D:\\', passphrase: 'SecretMadrasaKey' },
    { id: admin.id, fullName: admin.fullName }
  );
