      { envelope: backup.encryptedEnvelope, passphrase: 'WrongPassword', confirmRestore: false },
      { id: admin.id, fullName: admin.fullName }
    )
  );

  const preview = await verifyOrRestoreBackupLocal(
    { envelope: backup.encryptedEnvelope, passphrase: 'SecretMadrasaKey', confirmRestore: false },
    { id: admin.id, fullName: admin.fullName }
  );
  assert.equal(preview.verified, true);
  assert.equal(preview.counts.members, 9);
});

