test('Mobile SMS OTP is unlocked for both Admin and Staff with includePhoneTarget and single-use consumption', async () => {
  const admin = await findUserForLoginLocal('admin');
  const staff02 = await findUserForLoginLocal('staff02');
  assert.ok(admin);
  assert.ok(staff02);

  // Assign mobile number to staff02 and verify unlocked SMS target
  await updateStaffLocal(
    staff02.id,
    { phone: '9876543210' },
    { id: admin.id, fullName: admin.fullName }
  );

  // Authenticated login challenge (includePhoneTarget: true) exposes normalized +91 SMS target
  const staffChallenge = await issueAdminOtpChallenge({
    userId: staff02.id,
    username: staff02.username,
    phone: '9876543210',
    email: ADMIN_DEFAULT_EMAIL,
    includePhoneTarget: true,
  });
  assert.equal(staffChallenge.firebasePhoneReady, true);
  assert.equal(staffChallenge.smsTargetPhone, '+919876543210');
  assert.equal(staffChallenge.maskedPhone, '******3210');

  // Unauthenticated forgot-password challenge omits smsTargetPhone
  const forgotChallenge = await issueAdminOtpChallenge({
    userId: admin.id,
    username: admin.username,
    phone: ADMIN_DEFAULT_PHONE,
    email: ADMIN_DEFAULT_EMAIL,
    includePhoneTarget: false,
  });
  assert.equal(forgotChallenge.firebasePhoneReady, true);
  assert.equal(forgotChallenge.smsTargetPhone, null);

  // Single-use consumeOtpChallenge (Firebase Phone Auth verified flow)
  const firstConsume = consumeOtpChallenge(staffChallenge.challengeToken);
  assert.equal(firstConsume.ok, true);
  if (firstConsume.ok) {
    assert.equal(firstConsume.userId, staff02.id);
    assert.equal(firstConsume.phone, '9876543210');
  }
  const replayConsume = consumeOtpChallenge(staffChallenge.challengeToken);
  assert.equal(replayConsume.ok, false);

  // Gateway status never leaks raw keys
  const gwPublic = getOtpGatewayPublicStatus();
  assert.equal(gwPublic.firebasePhoneEnabled, true);
  assert.equal('fast2SmsApiKey' in gwPublic, false);
  assert.equal('twilioAuthToken' in gwPublic, false);
  assert.equal('smtpPass' in gwPublic, false);
});

// Keep auth token strictly in memory (never in localStorage)
let authTokenInMemory: string | null = null;

export function setAuthToken(token: string | null) {
  authTokenInMemory = token;
}

export function getAuthToken(): string | null {
  return authTokenInMemory;
}

export async function apiFetch<T>(
  path: string,
  options: RequestInit = {}
): Promise<T> {
  const headers = new Headers(options.headers || {});
  if (!headers.has('Content-Type') && options.body) {
    headers.set('Content-Type', 'application/json');
  }
  if (authTokenInMemory) {
    headers.set('Authorization', `Bearer ${authTokenInMemory}`);
  }

  const res = await fetch(path, {
    ...options,
    headers,
  });

  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    throw new Error(data.error || `Request failed (${res.status})`);
  }
  return data as T;
}

