export async function downloadReceiptPdf(
  receipt: ReceiptData,
  paperSize: ReceiptPaperSize = getPreferredPaperSize()
) {
  const formatOpt: 'a6' | [number, number] = paperSize === '4x6' ? [101.6, 152.4] : 'a6';
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: formatOpt });
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const paperLabel = paperSize === '4x6' ? '4"x6"' : 'A6';

  // Header band
  doc.setFillColor(11, 93, 46);
  doc.rect(0, 0, pageWidth, 21, 'F');

  const logoData = await loadLogoAsDataUrl();
  if (logoData) {
    doc.addImage(logoData, 'PNG', 5, 3, 15, 15);
  }

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(10.5);
  doc.text('Saidpur kudduchiyya madrasah', 23, 8.5);
  doc.setFontSize(7.2);
  doc.setTextColor(212, 175, 55);
  doc.text('Official Membership Payment Receipt (Est. 1986)', 23, 13.5);
  doc.setTextColor(255, 255, 255);
  doc.text(`Saidpur, Taki · ${paperLabel} Official Receipt`, 23, 17.8);

  // Receipt Meta
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(8);
  doc.text(`Receipt ID: ${receipt.receiptNumber}`, 7, 26.5);
  doc.text(`${receipt.paymentDate} ${receipt.paymentTime}`, pageWidth - 7, 26.5, { align: 'right' });

  doc.setDrawColor(212, 175, 55);
  doc.line(7, 29, pageWidth - 7, 29);

  const prevYearsSummary = receipt.breakdown?.yearLines
    .filter((l) => l.isPreviousYear)
    .map((l) => `${l.year}: Rs. ${l.paidNow.toFixed(0)}`)
    .join(', ');

  const prevDueList = receipt.previousPendingDues || [];
  const totalPrevDue = Number(receipt.totalPreviousDueAmount || 0);
  const currentDue = receipt.breakdown
    ? receipt.breakdown.totalRemainingDue
    : receipt.remainingDue;
  const combinedTotalDue =
    receipt.breakdown && receipt.breakdown.previousYearsRemainingDue > 0
      ? receipt.breakdown.totalRemainingDue
      : currentDue + totalPrevDue;

  const yearLabel = receipt.isAdvanceYearPayment
    ? `${receipt.paymentYear} (Advance / Upcoming Year)`
    : String(receipt.paymentYear);

  const details: Array<[string, string]> = [
    ['Member ID', receipt.memberCode],
    ['Member Name', receipt.issuedToName],
    ['Guardian Name', receipt.guardianName],
    ['Mobile', receipt.mobile],
    ['Address', receipt.address],
    ...(receipt.breakdown
      ? ([
          [
            'Prev. Years Paid',
            `Rs. ${receipt.breakdown.previousYearsPaid.toFixed(2)}${prevYearsSummary ? ` (${prevYearsSummary})` : ''}`,
          ],
          [
            `Year (${yearLabel}) Paid`,
            `Rs. ${receipt.breakdown.currentYearPaid.toFixed(2)}`,
          ],
          ['Total Paid', `Rs. ${receipt.breakdown.totalPaid.toFixed(2)}`],
          [
            'Due Balance (Bokeya)',
            `Rs. ${combinedTotalDue.toFixed(2)}${
              combinedTotalDue === 0 ? ' (Fully Paid)' : ''
            }`,
          ],
        ] as Array<[string, string]>)
      : ([
          ['Payment Year', yearLabel],
          ['Expected Fee', `Rs. ${receipt.expectedFee.toFixed(2)}`],
          ['Amount Paid', `Rs. ${receipt.amountPaid.toFixed(2)}`],
          ...(totalPrevDue > 0
            ? ([
                [
                  'Previous Years Due (Bokeya)',
                  `Rs. ${totalPrevDue.toFixed(2)} (${prevDueList
                    .map((d) => `${d.year}: Rs. ${d.dueAmount.toFixed(0)}`)
                    .join(', ')})`,
                ],
              ] as Array<[string, string]>)
            : []),
          [
            totalPrevDue > 0 ? 'Total Due (Bokeya)' : 'Due Balance (Bokeya)',
            `Rs. ${combinedTotalDue.toFixed(2)}${
              combinedTotalDue === 0 ? ' (Fully Paid)' : ''
            }`,
          ],
        ] as Array<[string, string]>)),
    ['Payment Method', receipt.paymentMethod],
    ['Received By', receipt.issuedByName],
    ['Verification Ref', receipt.verificationHash],
  ];

  if (receipt.notes) {
    details.push(['Notes', receipt.notes]);
  }

  autoTable(doc, {
    startY: 31.5,
    margin: { left: 7, right: 7 },
    body: details,
    theme: 'grid',
    styles: {
      fontSize: 7.2,
      cellPadding: 1.3,
      lineWidth: 0.18,
    },
    columnStyles: {
      0: { fontStyle: 'bold', cellWidth: 34, fillColor: [246, 248, 247] },
      1: { cellWidth: 57 },
    },
  });

  const finalY = (doc as unknown as { lastAutoTable?: { finalY: number } }).lastAutoTable?.finalY ?? 110;
  const sigLineY = Math.min(Math.max(finalY + 10, 122), pageHeight - 16);

  doc.setDrawColor(100, 116, 139);
  doc.line(7, sigLineY, 42, sigLineY);
  doc.line(pageWidth - 44, sigLineY, pageWidth - 7, sigLineY);

  doc.setFontSize(7);
  doc.setTextColor(71, 85, 105);
  doc.text('Member / Payer Signature', 7, sigLineY + 4);
  doc.text('Authorized Signature & Seal', pageWidth - 7, sigLineY + 4, { align: 'right' });

  doc.setFontSize(6.5);
  doc.setTextColor(148, 163, 184);
  doc.text(`Saidpur kudduchiyya madrasah · ${paperLabel} Official Receipt`, pageWidth / 2, pageHeight - 5, {
    align: 'center',
  });

  doc.save(`Receipt-${receipt.receiptNumber}-${paperSize}.pdf`);
}

export async function fetchAndDownloadReceiptPdf(
  receiptNumber: string,
  paperSize: ReceiptPaperSize = getPreferredPaperSize()
): Promise<void> {
  const cached = await getOfflineSnapshot<ReceiptData>(`receipt:${receiptNumber}`);
  if (typeof navigator !== 'undefined' && !navigator.onLine && cached) {
    await downloadReceiptPdf(cached, paperSize);
    return;
  }
  try {
    const res = await apiFetch<{ receipt: ReceiptData }>(
      `/api/receipts/${encodeURIComponent(receiptNumber)}`
    );
    await saveOfflineSnapshot(`receipt:${receiptNumber}`, res.receipt);
    await downloadReceiptPdf(res.receipt, paperSize);
  } catch (err) {
    if (cached) {
      await downloadReceiptPdf(cached, paperSize);
      return;
    }
    throw err;
  }
}

import type { AuthUser, MemberListItem, OfflineQueueItem, SystemSettings } from '../types/app';

const DB_NAME = 'skm-admin-offline-db';
const DB_VERSION = 2;
const QUEUE_STORE = 'offline_queue';
const CACHE_STORE = 'cached_members';
const SNAPSHOT_STORE = 'kv_snapshots';
const PROFILE_STORE = 'offline_profile';

const AUTO_RESUME_KEY = 'active_offline_username';

export interface TrustedOfflineProfile {
  username: string;
  user: AuthUser;
  settings: SystemSettings;
  saltHex: string;
  passwordHashHex: string;
  savedAt: string;
}

function openOfflineDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(QUEUE_STORE)) {
        db.createObjectStore(QUEUE_STORE, { keyPath: 'clientTxId' });
      }
      if (!db.objectStoreNames.contains(CACHE_STORE)) {
        db.createObjectStore(CACHE_STORE, { keyPath: 'id' });
      }
      if (!db.objectStoreNames.contains(SNAPSHOT_STORE)) {
        db.createObjectStore(SNAPSHOT_STORE, { keyPath: 'key' });
      }
      if (!db.objectStoreNames.contains(PROFILE_STORE)) {
        db.createObjectStore(PROFILE_STORE, { keyPath: 'username' });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function generateSaltHex(): string {
  const bytes = new Uint8Array(16);
  if (globalThis.crypto?.getRandomValues) {
    globalThis.crypto.getRandomValues(bytes);
  } else {
    for (let i = 0; i < bytes.length; i++) {
      bytes[i] = Math.floor(Math.random() * 256);
    }
  }
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

async function hashSaltedPassword(saltHex: string, passwordPlain: string): Promise<string> {
  const input = `${saltHex}:${passwordPlain}`;
  if (globalThis.crypto?.subtle) {
    const encoded = new TextEncoder().encode(input);
    const digest = await globalThis.crypto.subtle.digest('SHA-256', encoded);
    return Array.from(new Uint8Array(digest))
      .map((b) => b.toString(16).padStart(2, '0'))
      .join('');
  }
  // Fallback deterministic mixing hash for non-secure HTTP LAN contexts
  let h1 = 0x811c9dc5;
  let h2 = 0x9e3779b9;
  for (let i = 0; i < input.length; i++) {
    const c = input.charCodeAt(i);
    h1 ^= c;
    h1 = Math.imul(h1, 0x01000193);
    h2 ^= c + (i << 3);
    h2 = Math.imul(h2, 0x85ebca6b);
  }
  return `${(h1 >>> 0).toString(16).padStart(8, '0')}${(h2 >>> 0).toString(16).padStart(8, '0')}`;
}

export async function enqueueAdminOfflineItem(item: OfflineQueueItem): Promise<void> {
  const db = await openOfflineDb();
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE, 'readwrite');
    tx.objectStore(QUEUE_STORE).put(item);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function getAdminOfflineQueue(): Promise<OfflineQueueItem[]> {
  const db = await openOfflineDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE, 'readonly');
    const req = tx.objectStore(QUEUE_STORE).getAll();
    req.onsuccess = () => {
      const items = (req.result as OfflineQueueItem[]) || [];
      items.sort((a, b) => b.createdOfflineAt.localeCompare(a.createdOfflineAt));
      resolve(items);
    };
    req.onerror = () => reject(req.error);
  });
}

export async function updateOfflineItemStatus(
  clientTxId: string,
  syncStatus: 'UNSYNCED' | 'SYNCED' | 'CONFLICT',
  errorMessage?: string
): Promise<void> {
  const db = await openOfflineDb();
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE, 'readwrite');
    const store = tx.objectStore(QUEUE_STORE);
    const getReq = store.get(clientTxId);
    getReq.onsuccess = () => {
      const record = getReq.result as OfflineQueueItem | undefined;
      if (record) {
        record.syncStatus = syncStatus;
        record.errorMessage = errorMessage;
        store.put(record);
      }
    };
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function clearSyncedOfflineItems(): Promise<void> {
  const items = await getAdminOfflineQueue();
  const db = await openOfflineDb();
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE, 'readwrite');
    const store = tx.objectStore(QUEUE_STORE);
    for (const item of items) {
      if (item.syncStatus === 'SYNCED') {
        store.delete(item.clientTxId);
      }
    }
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function cacheMembersSnapshot(members: MemberListItem[]): Promise<void> {
  const db = await openOfflineDb();
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(CACHE_STORE, 'readwrite');
    const store = tx.objectStore(CACHE_STORE);
    store.clear();
    for (const m of members) {
      store.put(m);
    }
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function getCachedMembersSnapshot(): Promise<MemberListItem[]> {
  const db = await openOfflineDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(CACHE_STORE, 'readonly');
    const req = tx.objectStore(CACHE_STORE).getAll();
    req.onsuccess = () => resolve((req.result as MemberListItem[]) || []);
    req.onerror = () => reject(req.error);
  });
}

export async function saveOfflineSnapshot<T>(key: string, value: T): Promise<void> {
  try {
    const db = await openOfflineDb();
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(SNAPSHOT_STORE, 'readwrite');
      tx.objectStore(SNAPSHOT_STORE).put({
        key,
        value,
        updatedAt: new Date().toISOString(),
      });
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  } catch {
    // ignore storage errors in restricted contexts
  }
}

export async function getOfflineSnapshot<T>(key: string): Promise<T | null> {
  try {
    const db = await openOfflineDb();
    return await new Promise<T | null>((resolve, reject) => {
      const tx = db.transaction(SNAPSHOT_STORE, 'readonly');
      const req = tx.objectStore(SNAPSHOT_STORE).get(key);
      req.onsuccess = () => {
        const rec = req.result as { key: string; value: T } | undefined;
        resolve(rec ? rec.value : null);
      };
      req.onerror = () => reject(req.error);
    });
  } catch {
    return null;
  }
}

export async function saveTrustedOfflineProfile(params: {
  username: string;
  passwordPlain?: string;
  user: AuthUser;
  settings: SystemSettings;
}): Promise<void> {
  // Security Rule: ONLY Admin account is permitted for offline mode on installed devices
  if (params.user.roleName !== 'ADMIN') {
    return;
  }
  try {
    const db = await openOfflineDb();
    const existing = await new Promise<TrustedOfflineProfile | undefined>((resolve) => {
      const tx = db.transaction(PROFILE_STORE, 'readonly');
      const req = tx.objectStore(PROFILE_STORE).get(params.user.username.toLowerCase());
      req.onsuccess = () => resolve(req.result as TrustedOfflineProfile | undefined);
      req.onerror = () => resolve(undefined);
    });

    let saltHex = existing?.saltHex || generateSaltHex();
    let passwordHashHex = existing?.passwordHashHex || '';
    if (params.passwordPlain) {
      saltHex = generateSaltHex();
      passwordHashHex = await hashSaltedPassword(saltHex, params.passwordPlain);
    }

    const record: TrustedOfflineProfile = {
      username: params.user.username.toLowerCase(),
      user: params.user,
      settings: params.settings,
      saltHex,
      passwordHashHex,
      savedAt: new Date().toISOString(),
    };

    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction([PROFILE_STORE, SNAPSHOT_STORE], 'readwrite');
      tx.objectStore(PROFILE_STORE).put(record);
      tx.objectStore(SNAPSHOT_STORE).put({
        key: AUTO_RESUME_KEY,
        value: record.username,
        updatedAt: record.savedAt,
      });
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  } catch {
    // ignore IndexedDB unavailability
  }
}

export async function verifyOfflineCredentials(
  identifier: string,
  passwordPlain: string
): Promise<{ user: AuthUser; settings: SystemSettings } | null> {
  try {
    const clean = identifier.trim().toLowerCase();
    const cleanDigits = clean.replace(/\D/g, '');
    if (!clean || !passwordPlain) return null;

    const db = await openOfflineDb();
    const allProfiles = await new Promise<TrustedOfflineProfile[]>((resolve) => {
      const tx = db.transaction(PROFILE_STORE, 'readonly');
      const req = tx.objectStore(PROFILE_STORE).getAll();
      req.onsuccess = () => resolve((req.result as TrustedOfflineProfile[]) || []);
      req.onerror = () => resolve([]);
    });

    const match = allProfiles.find((p) => {
      if (p.user.roleName !== 'ADMIN') return false;
      if (p.username === clean) return true;
      if (p.user.email && p.user.email.toLowerCase() === clean) return true;
      if (cleanDigits.length >= 10 && p.user.phone) {
        const uDigits = p.user.phone.replace(/\D/g, '');
        return uDigits === cleanDigits || uDigits.endsWith(cleanDigits) || cleanDigits.endsWith(uDigits);
      }
      return false;
    });

    if (!match || !match.passwordHashHex) return null;
    const computed = await hashSaltedPassword(match.saltHex, passwordPlain);
    if (computed !== match.passwordHashHex) return null;

    await saveOfflineSnapshot(AUTO_RESUME_KEY, match.username);
    return { user: match.user, settings: match.settings };
  } catch {
    return null;
  }
}

