 * Admin Gmail or Mobile Number unlocks the offline Admin session directly.
 */
export async function verifyOfflineAdminRecovery(
  emailOrMobile: string
): Promise<{ user: AuthUser; settings: SystemSettings } | null> {
  try {
    const clean = emailOrMobile.trim().toLowerCase();
    const cleanDigits = clean.replace(/\D/g, '');
    if (!clean) return null;

    const db = await openOfflineDb();
    const allProfiles = await new Promise<TrustedOfflineProfile[]>((resolve) => {
      const tx = db.transaction(PROFILE_STORE, 'readonly');
      const req = tx.objectStore(PROFILE_STORE).getAll();
      req.onsuccess = () => resolve((req.result as TrustedOfflineProfile[]) || []);
      req.onerror = () => resolve([]);
    });

    const match = allProfiles.find((p) => {
      if (p.user.roleName !== 'ADMIN') return false;
      if (p.user.email && p.user.email.toLowerCase() === clean) return true;
      if (cleanDigits.length >= 10 && p.user.phone) {
        const uDigits = p.user.phone.replace(/\D/g, '');
        return uDigits === cleanDigits || uDigits.endsWith(cleanDigits) || cleanDigits.endsWith(uDigits);
      }
