export async function getLastOfflineProfile(): Promise<TrustedOfflineProfile | null> {
  try {
    const activeUsername = await getOfflineSnapshot<string | null>(AUTO_RESUME_KEY);
    const db = await openOfflineDb();
    const allProfiles = await new Promise<TrustedOfflineProfile[]>((resolve) => {
      const tx = db.transaction(PROFILE_STORE, 'readonly');
      const req = tx.objectStore(PROFILE_STORE).getAll();
      req.onsuccess = () => resolve((req.result as TrustedOfflineProfile[]) || []);
      req.onerror = () => resolve([]);
    });
    const adminProfiles = allProfiles.filter((p) => p.user.roleName === 'ADMIN');
    if (adminProfiles.length === 0) return null;
    if (activeUsername) {
      const found = adminProfiles.find((p) => p.username === activeUsername.toLowerCase());
      if (found) return found;
    }
    return null;
  } catch {
    return null;
  }
}

export async function hasAnySavedOfflineProfile(): Promise<TrustedOfflineProfile | null> {
  try {
    const db = await openOfflineDb();
    const allProfiles = await new Promise<TrustedOfflineProfile[]>((resolve) => {
      const tx = db.transaction(PROFILE_STORE, 'readonly');
      const req = tx.objectStore(PROFILE_STORE).getAll();
      req.onsuccess = () => resolve((req.result as TrustedOfflineProfile[]) || []);
      req.onerror = () => resolve([]);
    });
    const adminProfiles = allProfiles.filter((p) => p.user.roleName === 'ADMIN');
    if (adminProfiles.length === 0) return null;
    adminProfiles.sort((a, b) => b.savedAt.localeCompare(a.savedAt));
    return adminProfiles[0];
  } catch {
    return null;
  }
}

