import { START_YEAR, roundMoney } from '../domain/membershipRules';
import type {
  AuthUser,
  DashboardData,
  MemberListItem,
  OfflineQueueItem,
  PaymentItem,
  PendingMemberItem,
  PublicNoticeItem,
  ReceiptData,
} from '../types/app';

export interface PendingApiResponse {
  referenceYear: number;
  summary: {
    currentYearPending: number;
    previousYearsPending: number;
    totalOutstanding: number;
    pendingMemberCount: number;
  };
  items: PendingMemberItem[];
  allActiveStatus: PendingMemberItem[];
}

export function offlineTempMemberId(clientTxId: string): number {
  let hash = 0;
  for (let i = 0; i < clientTxId.length; i++) {
    hash = (hash * 31 + clientTxId.charCodeAt(i)) | 0;
  }
  const abs = Math.abs(hash % 900000) + 10000;
  return -abs;
}

export function offlineTempNoticeId(clientTxId: string): number {
  let hash = 0;
  for (let i = 0; i < clientTxId.length; i++) {
    hash = (hash * 33 + clientTxId.charCodeAt(i)) | 0;
  }
  const abs = Math.abs(hash % 900000) + 100000;
  return -abs;
}

export function sortQueueChronological(items: OfflineQueueItem[]): OfflineQueueItem[] {
  return [...items].sort((a, b) => a.createdOfflineAt.localeCompare(b.createdOfflineAt));
}

function resolveMemberInList(
  list: MemberListItem[],
  idByClientOfflineId: Map<string, number>,
  rawId: unknown,
  tempClientOfflineId: unknown
): number {
  const numId = Number(rawId);
  if (tempClientOfflineId) {
    const tempKey = String(tempClientOfflineId);
    const mapped = idByClientOfflineId.get(tempKey);
    if (mapped !== undefined) {
      const idx = list.findIndex((m) => m.id === mapped || m.tempClientOfflineId === tempKey);
      if (idx !== -1) return idx;
    }
    const idxByKey = list.findIndex((m) => m.tempClientOfflineId === tempKey);
    if (idxByKey !== -1) return idxByKey;
  }
  if (Number.isInteger(numId)) {
    return list.findIndex((m) => m.id === numId);
  }
  return -1;
}

export function mergeMembersWithOfflineQueue(
  cachedMembers: MemberListItem[],
  queue: OfflineQueueItem[],
  referenceYear: number,
  creatorName = 'Farhan Gazi Admin'
): MemberListItem[] {
  const unsynced = sortQueueChronological(queue.filter((q) => q.syncStatus === 'UNSYNCED'));
  const list = cachedMembers.map((m) => ({ ...m }));
  const idByClientOfflineId = new Map<string, number>();

  for (const item of unsynced) {
    const p = (item.payload || {}) as Record<string, unknown>;

    if (item.operationType === 'CREATE_MEMBER') {
      const tempId = offlineTempMemberId(item.clientTxId);
      idByClientOfflineId.set(item.clientTxId, tempId);
      if (list.some((m) => m.id === tempId || m.tempClientOfflineId === item.clientTxId)) continue;

      const fee = roundMoney(Number(p.defaultAnnualFee || 1200));
      const joinDate = String(p.joiningDate || item.createdOfflineAt.slice(0, 10));
      const status = String(p.status || 'ACTIVE') === 'INACTIVE' ? 'INACTIVE' : 'ACTIVE';
      const newMember: MemberListItem = {
        id: tempId,
        memberCode: `OFFLINE-${Math.abs(tempId).toString().slice(0, 4)}`,
        name: String(p.name || 'Offline Member'),
        guardianName: String(p.guardianName || '-'),
        mobile: String(p.mobile || '-'),
        address: String(p.address || '-'),
        joiningDate: joinDate,
        defaultAnnualFee: fee,
        status,
        registrationDate: joinDate,
        createdByName: creatorName,
        currentYearStatus: 'UNPAID',
        currentYearPaid: 0,
        currentYearExpected: fee,
        totalOutstanding: status === 'ACTIVE' ? fee : 0,
        currentYearReceiptNumber: null,
        latestReceiptNumber: null,
        tempClientOfflineId: item.clientTxId,
      };
      list.unshift(newMember);
    } else if (item.operationType === 'UPDATE_MEMBER') {
      const idx = resolveMemberInList(list, idByClientOfflineId, p.memberId, p.memberTempClientOfflineId);
      if (idx === -1) continue;
      const member = list[idx];
      if (p.name) member.name = String(p.name).trim();
      if (p.guardianName) member.guardianName = String(p.guardianName).trim();
      if (p.mobile) member.mobile = String(p.mobile).trim();
      if (p.address) member.address = String(p.address).trim();
      if (p.status === 'ACTIVE' || p.status === 'INACTIVE') {
        member.status = p.status;
      }
      if (p.newAnnualFee !== undefined && Number(p.newAnnualFee) > 0) {
        const feeVal = roundMoney(Number(p.newAnnualFee));
        const effYear = Math.max(START_YEAR, Number(p.effectiveFromYear || referenceYear));
        member.defaultAnnualFee = feeVal;
        if (effYear <= referenceYear && (member.currentYearPaid === 0 || feeVal >= member.currentYearPaid)) {
          const diff = roundMoney(feeVal - member.currentYearExpected);
          member.currentYearExpected = feeVal;
          member.totalOutstanding = roundMoney(Math.max(0, member.totalOutstanding + diff));
          member.currentYearStatus =
            member.currentYearPaid >= feeVal
              ? 'PAID'
              : member.currentYearPaid > 0
                ? 'PARTIAL'
                : 'UNPAID';
        }
      }
    } else if (item.operationType === 'DELETE_MEMBER') {
      const idx = resolveMemberInList(list, idByClientOfflineId, p.memberId, p.memberTempClientOfflineId);
      if (idx !== -1) {
        list.splice(idx, 1);
      }
    } else if (item.operationType === 'RECORD_PAYMENT') {
      const idx = resolveMemberInList(list, idByClientOfflineId, p.memberId, p.memberTempClientOfflineId);
      if (idx === -1) continue;

      const member = list[idx];
      const payYear = Number(p.paymentYear || referenceYear);
      const paidAmount = roundMoney(Number(p.paidAmount || 0));
      const receiptNo = String(p.offlineReceiptNumber || `OFF-${item.clientTxId.slice(-6).toUpperCase()}`);

      if (payYear === referenceYear) {
        const nextPaid = roundMoney(member.currentYearPaid + paidAmount);
        member.currentYearPaid = nextPaid;
        member.currentYearStatus =
          nextPaid >= member.currentYearExpected
            ? 'PAID'
            : nextPaid > 0
              ? 'PARTIAL'
              : 'UNPAID';
        member.currentYearReceiptNumber = receiptNo;
      }
      member.totalOutstanding = roundMoney(Math.max(0, member.totalOutstanding - paidAmount));
      member.latestReceiptNumber = receiptNo;
    }
  }

  return list;
}

export function mergePaymentsWithOfflineQueue(
  cachedPayments: PaymentItem[],
  mergedMembers: MemberListItem[],
  queue: OfflineQueueItem[],
  actorUser?: Pick<AuthUser, 'fullName' | 'username'>
): PaymentItem[] {
  const memberById = new Map(mergedMembers.map((m) => [m.id, m]));
  const unsynced = sortQueueChronological(queue.filter((q) => q.syncStatus === 'UNSYNCED'));

  const deletedIds = new Set<number>();
  const deletedTempIds = new Set<string>();
  for (const item of unsynced) {
    if (item.operationType === 'DELETE_MEMBER') {
      const p = (item.payload || {}) as Record<string, unknown>;
      if (Number.isInteger(Number(p.memberId))) deletedIds.add(Number(p.memberId));
      if (p.memberTempClientOfflineId) deletedTempIds.add(String(p.memberTempClientOfflineId));
    }
  }

  const offlinePayments: PaymentItem[] = [];
  let seq = 1;
  for (const item of unsynced) {
    if (item.operationType !== 'RECORD_PAYMENT') continue;
    const p = item.payload as Record<string, unknown>;
    const rawMemberId = Number(p.memberId);
    const tempKey = p.memberTempClientOfflineId ? String(p.memberTempClientOfflineId) : '';
    if (deletedIds.has(rawMemberId) || (tempKey && deletedTempIds.has(tempKey))) {
      continue;
    }

    const member =
      memberById.get(rawMemberId) ||
      (tempKey ? memberById.get(offlineTempMemberId(tempKey)) : undefined);

    const paidAmount = roundMoney(Number(p.paidAmount || 0));
    const expectedFee = roundMoney(
      Number(p.expectedFeeSnapshot || member?.currentYearExpected || member?.defaultAnnualFee || paidAmount)
    );
    const dueAfter = roundMoney(
      p.dueAfterSnapshot !== undefined
        ? Number(p.dueAfterSnapshot)
        : Math.max(0, expectedFee - paidAmount)
    );
    const dateStr = String(p.paymentDate || item.createdOfflineAt.slice(0, 10));
    const receiptNumber = String(
      p.offlineReceiptNumber || `OFF-${item.clientTxId.slice(-6).toUpperCase()}`
    );

    offlinePayments.push({
      id: -seq++,
      obligationId: -seq,
      memberId: member?.id ?? rawMemberId,
      memberCode: member?.memberCode || String(p.memberCodeSnapshot || 'OFFLINE'),
      memberName: member?.name || String(p.memberNameSnapshot || `Member #${rawMemberId}`),
      memberMobile: member?.mobile || String(p.memberMobileSnapshot || ''),
      memberAddress: member?.address || String(p.memberAddressSnapshot || ''),
      paymentYear: Number(p.paymentYear || START_YEAR),
      expectedFee,
      paidAmount,
      dueAfterPayment: dueAfter,
      paymentDate: dateStr,
      paymentMonth: dateStr.slice(0, 7),
      paymentTime: String(p.paymentTime || item.createdOfflineAt.slice(11, 19) || '12:00:00'),
      paymentMethod: String(p.paymentMethod || 'Cash'),
      receiptNumber,
      receivedByName: actorUser?.fullName || 'Farhan Gazi Admin',
      receivedByUsername: actorUser?.username || 'admin',
      notes: p.notes ? `${String(p.notes)} [Offline Pending Sync]` : '[Offline Pending Sync]',
      isSyncedFromOffline: true,
      isVoided: false,
      corrections: [],
    });
  }

  return [...offlinePayments.reverse(), ...cachedPayments];
}

export function mergeDashboardWithOfflineQueue(
  cachedDashboard: DashboardData,
  mergedMembers: MemberListItem[],
  queue: OfflineQueueItem[],
  actorUser?: Pick<AuthUser, 'fullName' | 'username'>
): DashboardData {
  const unsynced = sortQueueChronological(queue.filter((q) => q.syncStatus === 'UNSYNCED'));
  if (unsynced.length === 0) return cachedDashboard;

  const memberById = new Map(mergedMembers.map((m) => [m.id, m]));
  let addedMembersTotal = 0;
  let addedActiveMembers = 0;
  let addedInactiveMembers = 0;
  let addedTotalCollection = 0;
  let addedCurrentYearCollection = 0;

  const chartMap = new Map(cachedDashboard.yearlyChart.map((c) => [c.year, c.amount]));
  const addedPayments: DashboardData['recentPayments'] = [];
  const addedActivities: DashboardData['recentActivities'] = [];
  let synthId = 1;

  for (const item of unsynced) {
    const p = (item.payload || {}) as Record<string, unknown>;
    if (item.operationType === 'CREATE_MEMBER') {
      addedMembersTotal += 1;
      if (String(p.status || 'ACTIVE') === 'INACTIVE') {
        addedInactiveMembers += 1;
      } else {
        addedActiveMembers += 1;
      }
      addedActivities.push({
        id: -(synthId++),
        actorName: actorUser?.fullName || 'Farhan Gazi Admin',
        actorUsername: actorUser?.username || 'admin',
        actionType: 'OFFLINE_CREATE_MEMBER',
        entityType: 'MEMBER',
        entityId: item.clientTxId,
        summary: `[Offline] Registered member ${String(p.name || '')}`,
        createdAt: item.createdOfflineAt,
      });
    } else if (item.operationType === 'UPDATE_MEMBER') {
      addedActivities.push({
        id: -(synthId++),
        actorName: actorUser?.fullName || 'Farhan Gazi Admin',
        actorUsername: actorUser?.username || 'admin',
        actionType: 'OFFLINE_UPDATE_MEMBER',
        entityType: 'MEMBER',
        entityId: String(p.memberCodeSnapshot || p.memberId || item.clientTxId),
        summary: `[Offline] Edited member ${String(p.name || p.memberCodeSnapshot || '')}`,
        createdAt: item.createdOfflineAt,
      });
    } else if (item.operationType === 'DELETE_MEMBER') {
      addedMembersTotal -= 1;
      if (String(p.memberStatusSnapshot || 'ACTIVE') === 'INACTIVE') {
        addedInactiveMembers -= 1;
      } else {
        addedActiveMembers -= 1;
      }
      addedActivities.push({
        id: -(synthId++),
        actorName: actorUser?.fullName || 'Farhan Gazi Admin',
        actorUsername: actorUser?.username || 'admin',
        actionType: 'OFFLINE_DELETE_MEMBER',
        entityType: 'MEMBER',
        entityId: String(p.memberCodeSnapshot || p.memberId || item.clientTxId),
        summary: `[Offline] Deleted member ${String(p.memberNameSnapshot || '')}`,
        createdAt: item.createdOfflineAt,
      });
    } else if (item.operationType === 'CREATE_NOTICE' || item.operationType === 'UPDATE_NOTICE' || item.operationType === 'DELETE_NOTICE') {
      addedActivities.push({
        id: -(synthId++),
        actorName: actorUser?.fullName || 'Farhan Gazi Admin',
        actorUsername: actorUser?.username || 'admin',
        actionType: `OFFLINE_${item.operationType}`,
        entityType: 'NOTICE',
        entityId: item.clientTxId,
        summary: `[Offline] ${item.summary}`,
        createdAt: item.createdOfflineAt,
      });
    } else if (item.operationType === 'RECORD_PAYMENT') {
      const amountNum = roundMoney(Number(p.paidAmount || 0));
      const payYear = Number(p.paymentYear || cachedDashboard.referenceYear);
      const rawMemberId = Number(p.memberId);
      const member =
        memberById.get(rawMemberId) ||
        (p.memberTempClientOfflineId
          ? memberById.get(offlineTempMemberId(String(p.memberTempClientOfflineId)))
          : undefined);
      const receiptNumber = String(
        p.offlineReceiptNumber || `OFF-${item.clientTxId.slice(-6).toUpperCase()}`
      );
      const expectedFee = roundMoney(
        Number(p.expectedFeeSnapshot || member?.currentYearExpected || member?.defaultAnnualFee || amountNum)
      );
      const dueAfter = roundMoney(
        p.dueAfterSnapshot !== undefined
          ? Number(p.dueAfterSnapshot)
          : Math.max(0, expectedFee - amountNum)
      );

      addedTotalCollection = roundMoney(addedTotalCollection + amountNum);
      if (payYear === cachedDashboard.referenceYear) {
        addedCurrentYearCollection = roundMoney(addedCurrentYearCollection + amountNum);
      }
      chartMap.set(payYear, roundMoney((chartMap.get(payYear) || 0) + amountNum));

      addedPayments.push({
        id: -(synthId++),
        memberId: member?.id ?? rawMemberId,
        memberName: member?.name || String(p.memberNameSnapshot || `Member #${rawMemberId}`),
        memberCode: member?.memberCode || String(p.memberCodeSnapshot || 'OFFLINE'),
        paymentYear: payYear,
        paidAmount: amountNum,
        dueAfterPayment: dueAfter,
        paymentDate: String(p.paymentDate || item.createdOfflineAt.slice(0, 10)),
        paymentTime: String(p.paymentTime || item.createdOfflineAt.slice(11, 19) || '12:00:00'),
        paymentMethod: String(p.paymentMethod || 'Cash'),
        receiptNumber,
        receivedByName: actorUser?.fullName || 'Farhan Gazi Admin',
        receivedByUsername: actorUser?.username || 'admin',
        isSyncedFromOffline: true,
      });

      addedActivities.push({
        id: -(synthId++),
        actorName: actorUser?.fullName || 'Farhan Gazi Admin',
        actorUsername: actorUser?.username || 'admin',
        actionType: 'OFFLINE_RECORD_PAYMENT',
        entityType: 'PAYMENT',
        entityId: receiptNumber,
        summary: `[Offline] Received ₹${amountNum} from ${member?.name || `Member #${rawMemberId}`} (${payYear})`,
        createdAt: item.createdOfflineAt,
      });
    }
  }

  const paidMembersCount =
    mergedMembers.length > 0
      ? mergedMembers.filter((m) => m.status === 'ACTIVE' && m.currentYearStatus === 'PAID').length
      : cachedDashboard.stats.paidMembers;
  const pendingMembersCount =
    mergedMembers.length > 0
      ? mergedMembers.filter((m) => m.status === 'ACTIVE' && m.totalOutstanding > 0).length
      : cachedDashboard.stats.pendingMembers;

  const computedTotal = Math.max(0, cachedDashboard.stats.totalMembers + addedMembersTotal);
  const computedActive = Math.max(0, cachedDashboard.stats.activeMembers + addedActiveMembers);
  const computedInactive = Math.max(0, cachedDashboard.stats.inactiveMembers + addedInactiveMembers);

  return {
    ...cachedDashboard,
    stats: {
      totalMembers: mergedMembers.length > 0 ? mergedMembers.length : computedTotal,
      activeMembers:
        mergedMembers.length > 0
          ? mergedMembers.filter((m) => m.status === 'ACTIVE').length
          : computedActive,
      inactiveMembers:
        mergedMembers.length > 0
          ? mergedMembers.filter((m) => m.status !== 'ACTIVE').length
          : computedInactive,
      totalCollection: roundMoney(cachedDashboard.stats.totalCollection + addedTotalCollection),
      paidMembers: paidMembersCount,
      pendingMembers: pendingMembersCount,
      currentYearCollection: roundMoney(
        cachedDashboard.stats.currentYearCollection + addedCurrentYearCollection
      ),
    },
    yearlyChart: cachedDashboard.yearlyChart.map((c) => ({
      year: c.year,
      amount: chartMap.get(c.year) ?? c.amount,
    })),
    recentPayments: [...addedPayments.reverse(), ...cachedDashboard.recentPayments].slice(0, 12),
    recentActivities: [...addedActivities.reverse(), ...cachedDashboard.recentActivities].slice(0, 10),
  };
}

export function mergeNoticesWithOfflineQueue(
  cachedNotices: PublicNoticeItem[],
  queue: OfflineQueueItem[],
  creatorName = 'Farhan Gazi Admin',
  options?: { publicOnly?: boolean }
): PublicNoticeItem[] {
  const unsynced = sortQueueChronological(queue.filter((q) => q.syncStatus === 'UNSYNCED'));
  const list = cachedNotices.map((n) => ({ ...n }));
  const idByClientOfflineId = new Map<string, number>();

  const findIdx = (rawId: unknown, tempKeyRaw: unknown): number => {
    const numId = Number(rawId);
    if (tempKeyRaw) {
      const tempKey = String(tempKeyRaw);
      const mapped = idByClientOfflineId.get(tempKey);
      const idx = list.findIndex(
        (n) => (mapped !== undefined && n.id === mapped) || n.tempClientOfflineId === tempKey
      );
      if (idx !== -1) return idx;
    }
    if (Number.isInteger(numId)) {
      return list.findIndex((n) => n.id === numId);
    }
    return -1;
  };

  for (const item of unsynced) {
    const p = (item.payload || {}) as Record<string, unknown>;
    if (item.operationType === 'CREATE_NOTICE') {
      const tempId = offlineTempNoticeId(item.clientTxId);
      idByClientOfflineId.set(item.clientTxId, tempId);
      if (list.some((n) => n.id === tempId || n.tempClientOfflineId === item.clientTxId)) continue;

      const noticeTypeRaw = String(p.noticeType || 'NOTICE').toUpperCase();
      const noticeType: PublicNoticeItem['noticeType'] =
        noticeTypeRaw === 'PUBLIC_POST' || noticeTypeRaw === 'EVENT' ? noticeTypeRaw : 'NOTICE';
      const nowIso = String(p.createdAt || item.createdOfflineAt);
      const attName = p.attachmentName ? String(p.attachmentName) : null;
      const attMime = p.attachmentMime ? String(p.attachmentMime) : null;
      const hasAtt = Boolean(p.attachmentDataUrl && attName);

      list.unshift({
        id: tempId,
        title: String(p.title || 'Offline Notice'),
        content: String(p.content || ''),
        noticeType,
        imageDataUrl: p.imageDataUrl ? String(p.imageDataUrl) : null,
        attachmentName: attName,
        attachmentMime: attMime,
        hasAttachment: hasAtt,
        isPinned: p.isPinned === undefined ? true : Boolean(p.isPinned),
        isPublished: p.isPublished === undefined ? true : Boolean(p.isPublished),
        createdByName: creatorName,
        createdAt: nowIso,
        updatedAt: nowIso,
        isSyncedFromOffline: true,
        tempClientOfflineId: item.clientTxId,
      });
    } else if (item.operationType === 'UPDATE_NOTICE') {
      const idx = findIdx(p.noticeId, p.noticeTempClientOfflineId);
      if (idx === -1) continue;
      const n = list[idx];
      if (p.title !== undefined) n.title = String(p.title).trim();
      if (p.content !== undefined) n.content = String(p.content).trim();
      if (p.noticeType !== undefined) {
        const nt = String(p.noticeType).toUpperCase();
        n.noticeType = nt === 'PUBLIC_POST' || nt === 'EVENT' ? nt : 'NOTICE';
      }
      if (p.isPinned !== undefined) n.isPinned = Boolean(p.isPinned);
      if (p.isPublished !== undefined) n.isPublished = Boolean(p.isPublished);
      if ('imageDataUrl' in p) {
        n.imageDataUrl = p.imageDataUrl ? String(p.imageDataUrl) : null;
      }
      if ('attachmentDataUrl' in p) {
        n.attachmentName = p.attachmentName ? String(p.attachmentName) : null;
        n.attachmentMime = p.attachmentMime ? String(p.attachmentMime) : null;
        n.hasAttachment = Boolean(p.attachmentDataUrl && n.attachmentName);
      }
      n.updatedAt = item.createdOfflineAt;
      n.isSyncedFromOffline = true;
    } else if (item.operationType === 'DELETE_NOTICE') {
      const idx = findIdx(p.noticeId, p.noticeTempClientOfflineId);
      if (idx !== -1) {
        list.splice(idx, 1);
      }
    }
  }

  if (options?.publicOnly) {
    return list
      .filter((n) => n.isPublished)
      .sort(
        (a, b) =>
          Number(b.isPinned) - Number(a.isPinned) || b.createdAt.localeCompare(a.createdAt) || b.id - a.id
      );
  }
  return list.sort((a, b) => b.createdAt.localeCompare(a.createdAt) || b.id - a.id);
}

export function mergePendingWithOfflineQueue(
  cachedPending: PendingApiResponse,
  queue: OfflineQueueItem[]
): PendingApiResponse {
  const unsynced = sortQueueChronological(queue.filter((q) => q.syncStatus === 'UNSYNCED'));
  if (unsynced.length === 0) return cachedPending;

  const allActiveStatus = cachedPending.allActiveStatus.map((row) => ({ ...row }));
  const deletedIds = new Set<number>();
  for (const item of unsynced) {
    if (item.operationType === 'DELETE_MEMBER') {
      const p = (item.payload || {}) as Record<string, unknown>;
      if (Number.isInteger(Number(p.memberId))) deletedIds.add(Number(p.memberId));
    }
  }
  const activeFiltered = allActiveStatus.filter((r) => !deletedIds.has(r.memberId));
  const rowByMemberId = new Map(activeFiltered.map((r) => [r.memberId, r]));

  for (const item of unsynced) {
    if (item.operationType !== 'RECORD_PAYMENT') continue;
    const p = item.payload as Record<string, unknown>;
    const row = rowByMemberId.get(Number(p.memberId));
    if (!row) continue;

    const paidAmount = roundMoney(Number(p.paidAmount || 0));
    const payYear = Number(p.paymentYear || cachedPending.referenceYear);
    const receiptNo = String(p.offlineReceiptNumber || `OFF-${item.clientTxId.slice(-6).toUpperCase()}`);

    if (payYear === cachedPending.referenceYear) {
      const prevCurr = row.currentYearPending;
      const newCurr = roundMoney(Math.max(0, prevCurr - paidAmount));
      const leftover = roundMoney(Math.max(0, paidAmount - prevCurr));
      row.currentYearPending = newCurr;
      row.previousYearsPending = roundMoney(Math.max(0, row.previousYearsPending - leftover));
      row.currentYearStatus =
        newCurr <= 0 ? 'PAID' : paidAmount > 0 ? 'PARTIAL' : row.currentYearStatus;
      row.currentYearReceiptNumber = receiptNo;
    } else if (payYear < cachedPending.referenceYear) {
      row.previousYearsPending = roundMoney(Math.max(0, row.previousYearsPending - paidAmount));
    }

    row.totalOutstanding = roundMoney(Math.max(0, row.totalOutstanding - paidAmount));
    row.latestReceiptNumber = receiptNo;
  }

  const pendingItems = activeFiltered.filter((r) => r.totalOutstanding > 0);
  const currentYearPending = roundMoney(
    activeFiltered.reduce((sum, r) => sum + r.currentYearPending, 0)
  );
  const previousYearsPending = roundMoney(
    activeFiltered.reduce((sum, r) => sum + r.previousYearsPending, 0)
  );
  const totalOutstanding = roundMoney(
    activeFiltered.reduce((sum, r) => sum + r.totalOutstanding, 0)
  );

  return {
    referenceYear: cachedPending.referenceYear,
    summary: {
      currentYearPending,
      previousYearsPending,
      totalOutstanding,
      pendingMemberCount: pendingItems.length,
    },
    items: pendingItems,
    allActiveStatus: activeFiltered,
  };
}

