export type PackageAssetKind = 'zip' | 'bat' | 'guideline' | 'formula' | 'source';

interface PackageAssetMeta {
  apiUrl: string;
  staticUrl?: string;
  filename: string;
}

const PACKAGE_ASSETS: Record<PackageAssetKind, PackageAssetMeta> = {
  zip: {
    apiUrl: '/api/package/download-zip',
    staticUrl: '/downloads/syedpur-kuddusia-madrasa-software.zip',
    filename: 'syedpur-kuddusia-madrasa-software.zip',
  },
  bat: {
    apiUrl: '/api/package/download-bat',
    filename: 'setup-and-run-windows.bat',
  },
  guideline: {
    apiUrl: '/api/package/download-guideline',
    staticUrl: '/downloads/SKM_Online_Offline_Guideline.pdf',
    filename: 'SKM_Online_Offline_Guideline.pdf',
  },
  formula: {
    apiUrl: '/api/package/download-formula',
    staticUrl: '/downloads/SKM_REPLICATION_FORMULA.md',
    filename: 'SKM_REPLICATION_FORMULA.md',
  },
  source: {
    apiUrl: '/api/package/download-source',
    staticUrl: '/downloads/skm-source-bundle.json',
    filename: 'skm-source-bundle.json',
  },
};

const OFFLINE_BUNDLE_CACHE = 'skm-offline-bundles-v1';

async function readFromBundleCache(url: string): Promise<Blob | null> {
  if (typeof caches === 'undefined') return null;
  try {
    const cache = await caches.open(OFFLINE_BUNDLE_CACHE);
    const hit = await cache.match(url);
    if (hit && hit.ok) {
      return await hit.blob();
    }
  } catch {
    // ignore cache errors
  }
  return null;
}

async function saveToBundleCache(urls: string[], response: Response): Promise<void> {
  if (typeof caches === 'undefined' || !response.ok) return;
  try {
    const cache = await caches.open(OFFLINE_BUNDLE_CACHE);
    for (const u of urls) {
      await cache.put(u, response.clone());
    }
  } catch {
    // ignore quota/cache errors
  }
}

export async function isPackageCachedOffline(kind: PackageAssetKind): Promise<boolean> {
  const meta = PACKAGE_ASSETS[kind];
  if (typeof caches === 'undefined') return false;
  try {
    const cache = await caches.open(OFFLINE_BUNDLE_CACHE);
    if (await cache.match(meta.apiUrl)) return true;
    if (meta.staticUrl && (await cache.match(meta.staticUrl))) return true;
  } catch {
    return false;
  }
  return false;
}

async function fetchPackageBlob(kind: PackageAssetKind): Promise<Blob> {
  const meta = PACKAGE_ASSETS[kind];
  const candidateUrls = [meta.apiUrl, ...(meta.staticUrl ? [meta.staticUrl] : [])];

  // Try live fetch first when online so latest version is always served and cached
  if (typeof navigator === 'undefined' || navigator.onLine) {
    for (const url of candidateUrls) {
      try {
        const res = await fetch(url, { cache: 'no-store' });
        if (res.ok) {
          await saveToBundleCache(candidateUrls, res);
          return await res.blob();
        }
      } catch {
        // try next url or offline cache
      }
    }
  }

  // Fallback to browser Cache Storage (works completely offline!)
  for (const url of candidateUrls) {
    const cachedBlob = await readFromBundleCache(url);
    if (cachedBlob && cachedBlob.size > 0) {
      return cachedBlob;
    }
  }

  throw new Error(
    kind === 'zip'
      ? 'সফটওয়্যার ZIP ফাইলটি পাওয়া যায়নি। ইন্টারনেট সংযোগ থাকা অবস্থায় একবার "অফলাইনের জন্য সেভ" বা ডাউনলোড করুন।'
      : `Failed to download ${meta.filename}.`
  );
}

export async function cacheZipBundleOffline(): Promise<number> {
  const blob = await fetchPackageBlob('zip');
  return blob.size;
}

export async function downloadPackageAsset(kind: PackageAssetKind): Promise<void> {
  const meta = PACKAGE_ASSETS[kind];
  const blob = await fetchPackageBlob(kind);
  const blobUrl = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = blobUrl;
  link.download = meta.filename;
  link.rel = 'noopener';
  link.style.display = 'none';
  document.body.appendChild(link);
  link.click();
  setTimeout(() => {
    try {
      document.body.removeChild(link);
    } catch {
      // ignore
    }
    URL.revokeObjectURL(blobUrl);
  }, 4000);
}

