const PAPER_SIZE_STORAGE_KEY = 'skm_print_paper_size';

export function getPreferredPaperSize(): ReceiptPaperSize {
  try {
    const val = localStorage.getItem(PAPER_SIZE_STORAGE_KEY);
    return val === 'A6' ? 'A6' : '4x6';
  } catch {
    return '4x6';
  }
}

export function setPreferredPaperSize(size: ReceiptPaperSize): void {
  try {
    localStorage.setItem(PAPER_SIZE_STORAGE_KEY, size);
  } catch {
    // ignore storage errors
  }
}

let cachedLogoDataUrl: string | null = null;
let logoPreloadPromise: Promise<string> | null = null;

async function getLogoSrc(): Promise<string> {
  if (cachedLogoDataUrl) return cachedLogoDataUrl;
  if (logoPreloadPromise) return logoPreloadPromise;
  logoPreloadPromise = (async () => {
    try {
      const res = await fetch('/assets/madrasa-logo.png');
      if (!res.ok) throw new Error('Logo fetch failed');
      const blob = await res.blob();
      const dataUrl = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(String(reader.result || '/assets/madrasa-logo.png'));
        reader.onerror = () => resolve('/assets/madrasa-logo.png');
        reader.readAsDataURL(blob);
      });
      if (dataUrl.startsWith('data:')) {
        cachedLogoDataUrl = dataUrl;
      }
      return dataUrl;
    } catch {
      return typeof window !== 'undefined'
        ? `${window.location.origin}/assets/madrasa-logo.png`
        : '/assets/madrasa-logo.png';
    }
  })();
  return logoPreloadPromise;
}

if (typeof window !== 'undefined') {
  void getLogoSrc();
}

function escapeHtml(raw: unknown): string {
  return String(raw ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function extractBodyContent(fullHtml: string): { styles: string; body: string } {
  const styleMatches = Array.from(fullHtml.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/gi));
  const styles = styleMatches.map((m) => m[1]).join('\n');
  const bodyMatch = fullHtml.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  const body = bodyMatch ? bodyMatch[1] : fullHtml;
  return { styles, body };
}

function mountDirectPrintRoot(fullHtml: string, paperSize: ReceiptPaperSize | 'A4'): void {
  if (typeof document === 'undefined') return;

  const { styles, body } = extractBodyContent(fullHtml);
  let printRoot = document.getElementById('skm-print-root');
  if (!printRoot) {
    printRoot = document.createElement('div');
    printRoot.id = 'skm-print-root';
    printRoot.style.display = 'none';
    document.body.appendChild(printRoot);
  }

  const pageCss =
    paperSize === '4x6'
      ? '@page { size: 4in 6in; margin: 4mm; }'
      : paperSize === 'A6'
        ? '@page { size: A6 portrait; margin: 4mm; }'
        : '@page { size: A4 portrait; margin: 12mm; }';

  let pageStyleEl = document.getElementById('skm-dynamic-page-style') as HTMLStyleElement | null;
  if (!pageStyleEl) {
    pageStyleEl = document.createElement('style');
    pageStyleEl.id = 'skm-dynamic-page-style';
    document.head.appendChild(pageStyleEl);
  }
  pageStyleEl.textContent = `
    @media print {
      ${pageCss}
    }
    #skm-print-root {
      display: none;
    }
    @media print {
      body[data-skm-printing="true"] > *:not(#skm-print-root) {
        display: none !important;
      }
      body[data-skm-printing="true"] > #skm-print-root {
        display: block !important;
      }
    }
  `;

  printRoot.innerHTML = `<style>${styles}</style><div class="skm-print-surface">${body}</div>`;
}

export function triggerNativePrintNow(fullHtml: string, paperSize: ReceiptPaperSize | 'A4'): void {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;

  mountDirectPrintRoot(fullHtml, paperSize);
  document.body.setAttribute('data-skm-printing', 'true');

  const cleanup = () => {
    document.body.removeAttribute('data-skm-printing');
    window.removeEventListener('afterprint', cleanup);
  };
  window.addEventListener('afterprint', cleanup, { once: true });

  if (window.skmDesktop?.isElectron && window.skmDesktop.printA6) {
    // Also populate legacy A6 iframe for Electron IPC printA6 compatibility
    const oldFrame = document.getElementById('skm-a6-print-iframe');
    if (oldFrame && oldFrame.parentNode) oldFrame.parentNode.removeChild(oldFrame);
    const iframe = document.createElement('iframe');
    iframe.id = 'skm-a6-print-iframe';
    iframe.style.position = 'fixed';
    iframe.style.left = '-9999px';
    iframe.style.top = '0';
    iframe.style.width = paperSize === '4x6' ? '4in' : paperSize === 'A6' ? '105mm' : '210mm';
    iframe.style.height = paperSize === '4x6' ? '6in' : paperSize === 'A6' ? '148mm' : '297mm';
    iframe.style.border = '0';
    document.body.appendChild(iframe);
    const doc = iframe.contentDocument || iframe.contentWindow?.document;
    if (doc) {
      doc.open();
      doc.write(fullHtml);
      doc.close();
    }
    void window.skmDesktop.printA6().finally(() => {
      setTimeout(cleanup, 1200);
    });
    return;
  }

  try {
    window.focus();
    window.print();
  } catch {
    // Print preview modal remains visible on screen with Save PDF fallback
  } finally {
    setTimeout(cleanup, 4000);
  }
}

type PreviewListener = (payload: PrintPreviewPayload | null) => void;
const previewListeners = new Set<PreviewListener>();

export function subscribePrintPreview(listener: PreviewListener): () => void {
  previewListeners.add(listener);
  return () => {
    previewListeners.delete(listener);
  };
}

export function dispatchPrintPreview(payload: PrintPreviewPayload | null): void {
  previewListeners.forEach((fn) => {
    try {
      fn(payload);
    } catch {
      // ignore listener errors
    }
  });
}

export function closePrintPreview(): void {
  if (typeof document !== 'undefined') {
    document.body.removeAttribute('data-skm-printing');
  }
  dispatchPrintPreview(null);
}

