  const prevPaidYearsText = receipt.breakdown?.yearLines
    .filter((l) => l.isPreviousYear)
    .map((l) => `${l.year}: ${formatCurrency(l.paidNow)}`)
    .join(', ');

  const is4x6 = paperSize === '4x6';
  const pageSizeCss = is4x6 ? '4in 6in' : 'A6 portrait';
  const bodyWidthCss = is4x6 ? '93mm' : '96mm';
  const paperBadge = is4x6 ? '4"×6"' : 'A6';

  const rowsHtml = receipt.breakdown
    ? `
      <tr>
        <td class="lbl">${lang === 'bn' ? 'বিগত বছরের চাঁদা পরিশোধ' : 'Previous Years Paid'}${
          prevPaidYearsText ? `<div class="sub">${escapeHtml(prevPaidYearsText)}</div>` : ''
