      <tr>
        <td class="lbl">${
          lang === 'bn'
            ? `${isAdvanceYear ? 'আগত' : 'চলতি'} বছরের চাঁদা (${receipt.breakdown.referenceYear})`
            : `${isAdvanceYear ? 'Upcoming' : 'Current'} Year (${receipt.breakdown.referenceYear})`
        }</td>
        <td class="amt green">${escapeHtml(formatCurrency(receipt.breakdown.currentYearPaid))}</td>
      </tr>
      <tr class="paid-row">
        <td class="lbl bold">${lang === 'bn' ? 'মোট পরিশোধিত টাকা' : 'Total Amount Paid'}</td>
        <td class="amt bold green">${escapeHtml(formatCurrency(receipt.breakdown.totalPaid))}</td>
      </tr>
      ${
        receipt.breakdown.previousYearsRemainingDue > 0
          ? `<tr class="prev-due-row">
              <td class="lbl bold amber">${lang === 'bn' ? 'পূর্বের বছরের বকেয়া' : 'Previous Years Due (Bokeya)'}</td>
