                  : `Due for ${receipt.paymentYear}`
              }</td>
              <td class="amt bold red">${escapeHtml(formatCurrency(currentSelectedDue))}</td>
            </tr>`
          : ''
      }
      <tr class="due-row">
        <td class="lbl bold">${
          lang === 'bn' ? 'বকেয়া টাকার পরিমাণ (মোট বকেয়া)' : 'Remaining Due (Bokeya)'
