export async function printReceiptA6(
  receipt: ReceiptData,
  lang: Language,
  paperSize: ReceiptPaperSize = getPreferredPaperSize()
): Promise<void> {
  const logoSrc = await getLogoSrc();
  const html = buildA6ReceiptHtml(receipt, lang, logoSrc, paperSize);
  const title =
    lang === 'bn'
      ? `রসিদ #${receipt.receiptNumber} — ${receipt.issuedToName}`
      : `Receipt #${receipt.receiptNumber} — ${receipt.issuedToName}`;

  dispatchPrintPreview({
    id: `receipt-${receipt.receiptNumber}-${Date.now()}`,
    kind: 'RECEIPT',
    title,
    paperSize,
    supportsPaperToggle: true,
    html,
    lang,
    receipt,
  });

  triggerNativePrintNow(html, paperSize);
}

