export async function printReceiptByNumber(
  receiptNumber: string,
  lang: Language,
  paperSize: ReceiptPaperSize = getPreferredPaperSize()
): Promise<void> {
  const cacheKey = `receipt:${receiptNumber}`;
  let receipt: ReceiptData | null = null;

  if (typeof navigator !== 'undefined' && !navigator.onLine) {
    receipt = await getOfflineSnapshot<ReceiptData>(cacheKey);
  }

  if (!receipt) {
    try {
      const res = await apiFetch<{ receipt: ReceiptData }>(
        `/api/receipts/${encodeURIComponent(receiptNumber)}`
      );
      receipt = res.receipt;
      await saveOfflineSnapshot(cacheKey, receipt);
    } catch (err) {
      receipt = await getOfflineSnapshot<ReceiptData>(cacheKey);
      if (!receipt) {
        throw err instanceof Error ? err : new Error(`Receipt ${receiptNumber} not found.`);
      }
    }
  }

  await printReceiptA6(receipt, lang, paperSize);
}

