export async function regeneratePreviewForPaperSize(
  payload: PrintPreviewPayload,
  nextSize: ReceiptPaperSize
): Promise<PrintPreviewPayload> {
  const logoSrc = await getLogoSrc();
  setPreferredPaperSize(nextSize);
  if (payload.kind === 'RECEIPT' && payload.receipt) {
    return {
      ...payload,
      paperSize: nextSize,
      html: buildA6ReceiptHtml(payload.receipt, payload.lang, logoSrc, nextSize),
    };
  }
  if (payload.kind === 'DUE_SLIP' && payload.dueItem) {
    return {
      ...payload,
      paperSize: nextSize,
      html: buildPendingDueSlipHtml(
        payload.dueItem,
        payload.referenceYear || new Date().getFullYear(),
        payload.lang,
        logoSrc,
        nextSize
      ),
    };
  }
  return payload;
}

