    )
    .join('');

  const bodyHtml = `
    <table>
      <thead><tr>${headersHtml}</tr></thead>
      <tbody>${bodyRowsHtml}</tbody>
    </table>
  `;

  const html = buildA4PrintShell(
    title,
    `${rows.length} ${lang === 'bn' ? 'টি রেকর্ড' : 'records'}`,
    logoSrc,
    bodyHtml,
    lang
  );
  dispatchPrintPreview({
    id: `report-${Date.now()}`,
    kind: 'REPORT_TABLE',
    title,
    paperSize: 'A4',
    html,
    lang,
    reportTitle: title,
    reportColumns: columns,
    reportRows: rows,
  });
  triggerNativePrintNow(html, 'A4');
}

export async function downloadPrintPreviewPdf(payload: PrintPreviewPayload): Promise<void> {
  if (payload.kind === 'RECEIPT' && payload.receipt) {
    const { downloadReceiptPdf } = await import('./exportUtils');
    await downloadReceiptPdf(
      payload.receipt,
      payload.paperSize === 'A6' ? 'A6' : '4x6'
    );
    return;
  }

  const logoSrc = await getLogoSrc();
  const hasLogoDataUrl = logoSrc.startsWith('data:');

  if (payload.kind === 'DUE_SLIP' && payload.dueItem) {
    const pSize = payload.paperSize === 'A6' ? 'a6' : ([101.6, 152.4] as [number, number]);
    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: pSize });
    const w = doc.internal.pageSize.getWidth();
    doc.setFillColor(180, 30, 30);
    doc.rect(0, 0, w, 19, 'F');
    if (hasLogoDataUrl) doc.addImage(logoSrc, 'PNG', 4, 2.5, 14, 14);
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(10);
    doc.text('Saidpur kudduchiyya madrasah', 21, 8.5);
    doc.setFontSize(7.5);
    doc.text(`Pending Due Slip (Up to ${payload.referenceYear || new Date().getFullYear()})`, 21, 14);

    autoTable(doc, {
      startY: 24,
      margin: { left: 6, right: 6 },
      body: [
        ['Member ID', payload.dueItem.memberCode],
        ['Name', payload.dueItem.name],
        ['Guardian', payload.dueItem.guardianName],
        ['Mobile', payload.dueItem.mobile],
        ['Current Year Due', `Rs. ${Number(payload.dueItem.currentYearPending).toFixed(2)}`],
        ['Previous Years Due', `Rs. ${Number(payload.dueItem.previousYearsPending).toFixed(2)}`],
        ['Total Outstanding Due', `Rs. ${Number(payload.dueItem.totalOutstanding).toFixed(2)}`],
      ],
      styles: { fontSize: 8, cellPadding: 2 },
      columnStyles: { 0: { fontStyle: 'bold' } },
    });
    doc.save(`SKM-DueSlip-${payload.dueItem.memberCode}.pdf`);
    return;
  }

  if (payload.kind === 'NOTICE' && payload.notice) {
    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    const w = doc.internal.pageSize.getWidth();
    doc.setFillColor(11, 93, 46);
    doc.rect(0, 0, w, 24, 'F');
    if (hasLogoDataUrl) doc.addImage(logoSrc, 'PNG', 10, 4, 16, 16);
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(14);
    doc.text('Saidpur kudduchiyya madrasah', 30, 11);
    doc.setFontSize(9);
    doc.text('Saidpur, Taki · Est. 1986 · Official Notice Board', 30, 17.5);

    doc.setTextColor(15, 23, 42);
    doc.setFontSize(13);
    const titleLines = doc.splitTextToSize(payload.notice.title, w - 28);
    doc.text(titleLines, 14, 34);
    let cursorY = 34 + titleLines.length * 6.5;

    if (payload.notice.imageDataUrl?.startsWith('data:image/')) {
      try {
        const mime = payload.notice.imageDataUrl.includes('png') ? 'PNG' : 'JPEG';
        doc.addImage(payload.notice.imageDataUrl, mime, 14, cursorY, 80, 50);
        cursorY += 56;
      } catch {
        // skip unsupported image format
      }
    }

    doc.setFontSize(10.5);
    const contentLines = doc.splitTextToSize(payload.notice.content, w - 28);
    doc.text(contentLines, 14, cursorY);
    doc.save(`SKM-Notice-${payload.notice.id}.pdf`);
    return;
  }

  if (payload.kind === 'MEMBER_HISTORY' && payload.memberProfile) {
    const p = payload.memberProfile;
    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    doc.setFillColor(11, 93, 46);
    doc.rect(0, 0, doc.internal.pageSize.getWidth(), 22, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(13);
    doc.text(`Member History - ${p.member.memberCode} (${p.member.name})`, 14, 13);
    autoTable(doc, {
      startY: 28,
      head: [['Receipt', 'Year', 'Date', 'Method', 'Paid (Rs.)', 'Due (Rs.)']],
      body: p.payments.map((pay) => [
        `#${pay.receiptNumber}`,
        String(pay.paymentYear),
        pay.paymentDate,
        pay.paymentMethod,
        `Rs. ${Number(pay.paidAmount).toFixed(2)}`,
        `Rs. ${Number(pay.dueAfterPayment).toFixed(2)}`,
      ]),
      headStyles: { fillColor: [11, 93, 46], textColor: 255 },
    });
    doc.save(`SKM-History-${p.member.memberCode}.pdf`);
    return;
  }

  if (payload.kind === 'PAYMENT_LIST' && payload.paymentsList) {
    const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
    doc.setFillColor(11, 93, 46);
    doc.rect(0, 0, doc.internal.pageSize.getWidth(), 20, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(13);
    doc.text(`Payment History (${payload.yearLabel || ''})`, 14, 12.5);
    autoTable(doc, {
      startY: 26,
      head: [['Receipt', 'ID', 'Member', 'Year', 'Date', 'Method', 'Paid (Rs.)', 'Due (Rs.)', 'By']],
      body: payload.paymentsList.map((p) => [
        `#${p.receiptNumber}`,
        p.memberCode || '',
        p.memberName || '',
        String(p.paymentYear),
        p.paymentDate,
        p.paymentMethod,
        `Rs. ${Number(p.paidAmount).toFixed(2)}`,
        `Rs. ${Number(p.dueAfterPayment).toFixed(2)}`,
        p.receivedByName,
      ]),
      headStyles: { fillColor: [11, 93, 46], textColor: 255 },
    });
    doc.save(`SKM-Payments-${Date.now()}.pdf`);
    return;
  }

  if (payload.kind === 'PENDING_LIST' && payload.pendingRows) {
    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    doc.setFillColor(11, 93, 46);
    doc.rect(0, 0, doc.internal.pageSize.getWidth(), 20, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(13);
    doc.text(`Pending Dues (${payload.referenceYear || 2026})`, 14, 12.5);
    autoTable(doc, {
      startY: 26,
      head: [['ID', 'Member', 'Mobile', 'Status', 'Current Due', 'Prev Due', 'Total Due']],
      body: payload.pendingRows.map((r) => [
        r.memberCode,
        r.name,
        r.mobile,
        r.currentYearStatus,
        `Rs. ${Number(r.currentYearPending).toFixed(2)}`,
        `Rs. ${Number(r.previousYearsPending).toFixed(2)}`,
        `Rs. ${Number(r.totalOutstanding).toFixed(2)}`,
      ]),
      headStyles: { fillColor: [11, 93, 46], textColor: 255 },
    });
    doc.save(`SKM-Pending-Dues-${Date.now()}.pdf`);
    return;
  }

  if (payload.kind === 'REPORT_TABLE' && payload.reportColumns && payload.reportRows) {
    const { exportReportToPdf } = await import('./exportUtils');
    exportReportToPdf(
      `SKM-Report-${Date.now()}`,
      payload.reportTitle || payload.title,
      payload.reportColumns,
      payload.reportRows.map((r) => payload.reportColumns!.map((c) => String(r[c] ?? '—')))
    );
  }
}

